-- CFG.HOUSE_UNIT dang la Hmkg -- Mountain King -- mot unit HERO co chan,
-- va no thuoc mot slot may (CFG.HOUSE_SLOT). Unit co chan cua slot may
-- thi tu di loanh quanh: do la AI mac dinh cua Warcraft, khong phai loi
