  -- DA MO KHOA -- 2026-09-19. Cay ky nang xong: xem CFG.SKILLS[H002].
  { id = id('H002'), title = "Lac Vu", name = "Hvwd", role = "Shooter - Carry", abilities = {}, skills = nil,
