-- da du.
--
-- Doi lai: ESC gio BAT/TAT chu khong chi tat. Nghia la moi lan bam ESC
-- de huy chon quan hay dong menu deu mo bang len -- neu thay phien thi
-- dat lai mot chu cai o day, luc do ESC tu quay ve chi-tat.
