--#region 1_core/2_state.lua
do
-- ============================================================
--  2_state.lua  --  Trang thai chay & tien ich dung chung
--
--  S   : moi thu thay doi trong luc choi.
--  API : ban dang ky ham dung chung giua cac module.
--        Goi cheo module PHAI di qua API -- Lua bat upvalue luc dinh
--        nghia ham, nen local cua file sau khong nhin thay duoc tu
--        file truoc. Xem docs/05-quyet-dinh/0002.
-- ============================================================

S = {}

S.running = false
S.grid    = nil     -- so do luoi, do 03_geometry dung
S.p       = {}      -- [pid] = { active = true }
S.pids    = {}      -- danh sach pid dang choi, theo thu tu
S.enemy   = nil     -- player phe dich

-- Nha chinh & vung, do 06_core dung
S.house      = nil  -- unit nha chinh
S.houseX     = nil
S.houseY     = nil
S.houseHpSet    = false  -- dat duoc HP khong (can patch 1.31+)
S.houseSightVia = nil    -- dat tam nhin bang cach nao
S.houseNoAttack = false  -- tat duoc don danh khong
S.houseOwner    = nil    -- player so huu nha chinh
S.houseRgnName  = nil    -- ten vung thuc su khop duoc
S.enemyRgnName  = nil

-- Chon hero, do 07_heropick dung
S.heroTaken   = {}     -- [unit type id] = true khi da co nguoi lay
S.pick        = {}     -- [pid] = { dlg = dialog, map = { [button] = uid } }
S.pickTrigger = nil
S.skillPick   = {}     -- [pid] = { dlg, map, slot }
S.skillTrigger= nil
S.sframe      = {}     -- giao dien ky nang, do 07b_skillframe dung
S.hframe      = {}     -- the chon hero,   do 07c_heroframe dung
S.panel       = { tabs = {}, byPid = {}, trig = nil }  -- bang phim R
S.cultTabIndex  = nil    -- so thu tu the Linh Can trong bang
S.skillMax    = {}     -- [abilId] = so bac THAT doc tu unit, do 4_skill dung
-- S.sync do 3_sync.lua dung, khai bao ngay trong file do.
S.fct         = { pending = {}, count = 0 }   -- chu bay, 08b
S.fctTimer    = nil
S.keyBound    = false  -- gan duoc phim E khong
S.xpTimer     = nil    -- bo quet khoa hero

-- Dot quai, do 05_wave dung
S.stage      = 0       -- 1..100, MOT bien duy nhat
S.mobs       = {}      -- [unit] = "mob" | "elite" | "boss"
S.mobStage   = {}      -- [unit] = stage luc SINH, de tra thuong dung gia
S.alive      = 0
S.wave       = {}      -- { players, spawnFail } cua wave hien tai
S.waveTimer  = nil
-- nil = dong ho dang chay. "boss" = da don sach tang 10, cho -next goi
-- boss. "realm" = da ha boss, cho -next sang canh gioi sau.
S.waitNext   = nil
S.waveDlg    = nil
S.waveHold   = false   -- dang hoan dot sau vi wave cu chua sach
S.tickTimer  = nil
S.dumped      = {}     -- [unit] = true, da do danh sach ability chua
S.spReported  = {}     -- [unit] = true, da bao so diem ky nang chua
S.abilReported= {}     -- [unit] = true, da bao ket qua go ability chua

API = {}

-- Frame chi de NHIN thi phai tat tuong tac.
--
-- Frame con nam de len nut se NUOT cu bam: bam dung vao chu tren nut thi
-- khong an, lech ra vai pixel moi an. Chu cang dai thi vung chet cang
-- rong -- nen loi nay luc co luc khong, rat de tuong la may.
--
-- Ap cho MOI frame khong phai nut: chu, icon, vach ke, nen.
local function frameDead(f)
  if f ~= nil and BlzFrameSetEnable ~= nil then BlzFrameSetEnable(f, false) end
  return f
end
API.frameDead = frameDead

-- Nen co vien that, thay cho mot o mau phang.
--
-- BlzCreateFrameByType("BACKDROP", ...) chi cho mot hinh chu nhat tron,
-- phai tu dap texture vao. Ma texture chac chan ton tai o moi ban
-- (TeamColor) lai la mot o mau DAC 1x1 pixel -- nen ket qua luon la mot
-- hinh chu nhat phang, khong vien, canh cung.
--
-- BlzCreateFrame dung TEMPLATE co san trong giao dien game, nen no keo
-- theo ca vien, bo goc va hoa tiet. Doi lai: ten template khong co that
-- thi tra ve nil, nen phai thu lan luot roi moi lui ve cach cu.
--
-- Tra ve ca frame LAN TEN da dung -- khong ghi lai duoc thi khong co
-- cach nao biet no dang ve bang duong nao, dung kieu im lang cua
-- ADR 0012.
local function backdrop(names, parent, pid, fallbackTex)
  if BlzCreateFrame ~= nil and names ~= nil then
    for i = 1, #names do
      local f = BlzCreateFrame(names[i], parent, 0, pid)
      if f ~= nil then return f, names[i] end
    end
  end
  if BlzCreateFrameByType == nil then return nil, "thieu native" end
  local f = BlzCreateFrameByType("BACKDROP", "FlatBackdrop", parent, "", pid)
  if f ~= nil and fallbackTex ~= nil and BlzFrameSetTexture ~= nil then
    BlzFrameSetTexture(f, fallbackTex, 0, true)
  end
  return f, "o mau phang (lui ve)"
end
API.backdrop = backdrop

-- Co chu. Khong co native thi bo qua -- chu ve co mac dinh, van doc duoc.
local function frameScale(f, s)
  if f ~= nil and s ~= nil and BlzFrameSetScale ~= nil then
    BlzFrameSetScale(f, s)
  end
end
API.frameScale = frameScale

-- ---------- Tien ich ----------

-- Duong RA man hinh, khong dan nhan gi. Moi kenh ben duoi deu di qua
-- day; chi khac nhau o cai dan TRUOC khi goi.
local function raw(pid, text)
  if pid == nil then
    for i = 0, bj_MAX_PLAYERS - 1 do
      DisplayTimedTextToPlayer(Player(i), 0, 0, CFG.MSG_TIME, text)
    end
  else
    DisplayTimedTextToPlayer(Player(pid), 0, 0, CFG.MSG_TIME, text)
  end
end

-- NHAN "[He Thong]".
--
-- API.t o day phai tra MUON: 2_state.lua nap TRUOC 6_i18n.lua, nen luc
-- file nay chay thi bang chuoi chua ton tai. Tra luc GOI thi khong sao
-- -- tru vai dong bao rat som truoc khi i18n san sang, va do la ly do
-- co nhanh lui.
local function sysTag()
  local t = (API.t ~= nil) and API.t("sys_tag") or nil
  if t == nil or t == "sys_tag" then t = "System" end
  return (CFG.C_SYS or CFG.C_GREY) .. "[" .. t .. "]" .. CFG.C_END .. " "
end

-- CHU CUA NGUOI CHOI. Luon co nhan.
--
-- Vi sao dan nhan o DAY chu khong sua ~100 cho goi: mot cho sua, khong
-- cho nao sot, va khong co duong nao lo ra mot dong khong nhan. Dong
-- nao la cua mot NGUOI thi di qua say() va mang ten nguoi do thay vi
-- "[He Thong]".
--
-- warn/info/dbg KHONG di qua day: chung la chan doan cua nguoi lam map,
-- dan nhan "He Thong" vao la noi doi ve doi tuong doc.
local function msg(pid, text)
  raw(pid, sysTag() .. text)
end

-- CHAN DOAN CHO NGUOI LAM MAP -- khong phai chu cua nguoi choi.
--
-- Hai kenh, hai doi tuong doc, hai luat khac nhau:
--
--   API.msg   nguoi CHOI doc   -> BAT BUOC qua API.t(), co en/vi
--   API.warn  nguoi LAM MAP doc -> tieng Viet khong dau, KHONG dich
--
-- Vi sao khong dich phan warn: noi dung cua no la ten khoa CFG, ten
-- native, ten file. "Kiem tra CFG.HOUSE_UNIT" dich sang tieng Anh van
-- la mot cau nguoi choi khong lam gi duoc -- dich chi ton hai bang
-- chuoi cho mot doc gia duy nhat la chinh minh.
--
-- Tach thanh HAI HAM chu khong phai mot quy uoc, de i18n_hardcode.py
-- kiem duoc chinh xac: chuoi cung trong API.msg la LOI, trong API.warn
-- la binh thuong.
local function warn(pid, text)
  raw(pid, CFG.C_RED .. text .. CFG.C_END)
end

-- Bao cao cho nguoi lam map: KHONG mau, nhieu dong, doc nhu mot bang.
-- Y het msg() ve hanh vi -- ton tai chi de i18n_hardcode.py phan biet
-- duoc "chu cua nguoi choi" voi "bao cao cua cong cu".
local function info(pid, text)
  raw(pid, text)
end

-- TIN NHAN CHUNG -- viec mot nguoi lam ma ca ban do nen biet.
--
--   [Ten nguoi choi] noi dung
--
-- Dung cho hanh dong co the so sanh duoc giua nguoi choi: nang ky nang,
-- nang trang bi, mua do, di chuyen bang bang R. Muc dich la de mot van
-- nhieu nguoi co nhip -- thay nguoi khac len tay thi minh biet minh dang
-- o dau.
--
-- PHAI goi trong handler cua API.syncOn, KHONG phai trong callback cua
-- frame. Frame click chi chay tren may nguoi bam; goi o do thi "tin
-- chung" chi mot minh nguoi do doc duoc, va loi nay khong bao gio hien
-- ra khi test mot minh.
--
-- Phan noi dung van phai qua API.t() nhu moi chu cua nguoi choi -- chi
-- cai ngoac vuong la ky hieu.
local function say(pid, text)
  raw(nil, CFG.C_GOLD .. "[" .. GetPlayerName(Player(pid)) .. "]" ..
    CFG.C_END .. " " .. text)
end

local function dbg(text)
  if CFG.DEBUG then raw(nil, CFG.C_GREY .. "[dbg] " .. text .. CFG.C_END) end
end

local function clamp(v, lo, hi)
  if v < lo then return lo end
  if v > hi then return hi end
  return v
end

local function round(v)
  return math.floor(v + 0.5)
end

-- 12345 -> "12,345"
local function num(n)
  local s = tostring(math.floor(n))
  local out, neg = "", false
  if s:sub(1, 1) == "-" then neg = true; s = s:sub(2) end
  while #s > 3 do
    out = "," .. s:sub(-3) .. out
    s = s:sub(1, -4)
  end
  out = s .. out
  if neg then out = "-" .. out end
  return out
end

-- UnitAlive la native 1.31+; lui ve nguong 0.405 cua Warcraft III.
local function alive(u)
  if u == nil then return false end
  if UnitAlive ~= nil then return UnitAlive(u) end
  return GetUnitState(u, UNIT_STATE_LIFE) > 0.405
end

-- Chay f sau delay giay (mot lan).
local function after(delay, f)
  local t = CreateTimer()
  TimerStart(t, delay, false, function()
    local d = GetExpiredTimer()
    f()
    DestroyTimer(d)
  end)
  return t
end

-- ---------- Vet khoi dong ----------
-- PreloadGenEnd ghi mot file text vao Documents\Warcraft III\. Moi
-- buoc ta ghi lai TOAN BO danh sach, nen sau khi game sap, dong cuoi
-- trong file chinh la buoc cuoi cung da chay xong.
local traceSteps = {}

local function trace(step)
  if not CFG.TRACE then return end
  traceSteps[#traceSteps + 1] = step
  PreloadGenClear()
  PreloadGenStart()
  for i = 1, #traceSteps do
    Preload(traceSteps[i])
  end
  PreloadGenEnd(CFG.TRACE_FILE)
end

-- Doi mot unit/ability id tro lai chuoi bon ky tu. Dung phep chia chu
-- khong dung toan tu bit -- khong phai ban Lua nao cua WC3 cung co.
local function idToStr(v)
  if type(v) ~= "number" then return "?" end
  local a = math.floor(v / 16777216) % 256
  local b = math.floor(v / 65536) % 256
  local c = math.floor(v / 256) % 256
  local d = v % 256
  return string.char(a, b, c, d)
end

API.idToStr = idToStr
API.trace = trace
API.msg   = msg
API.dbg   = dbg
API.warn  = warn
API.info  = info
API.say   = say
-- Hieu ung roi tu huy sau khi dien xong.
local function fx(model, x, y)
  if model == nil then return end
  DestroyEffect(AddSpecialEffect(model, x, y))
end

API.fx    = fx
API.alive = alive
API.clamp = clamp
API.round = round
API.num   = num
API.after = after
end
--#endregion 1_core/2_state.lua

--#region 1_core/3_sync.lua
do
-- ============================================================
--  3_sync.lua  --  Kenh dong bo: mot may bam, moi may cung lam
--
--  VAN DE. Su kien bam frame chi no tren may nguoi bam. Warcraft III
--  chay lockstep: moi may mo phong cung mot van co, cung mot nhip. Doi
--  trang thai game ngay trong su kien do thi may day di truoc hai may
--  kia -- lech nhip la bi da ra khoi tran.
--
--  Nen: bam KHONG doi gi. No gui mot con so. Moi may nhan duoc con so
--  do cung mot nhip roi MOI doi trang thai.
--
--  BA DUONG GUI, chon bang CFG.SYNC_MODE:
--
--  "blz"   -- BlzSendSyncData + BlzTriggerRegisterPlayerSyncEvent.
--             Co tu 1.31. La su kien, khong phai quet, nen khong co khe
--             thoi gian nao mo ho. Duong tot nhat neu ban nay co.
--
--  "cache" -- StoreInteger + SyncStoredInteger tren game cache. Co tu
--             ban 1.00 nen chac chan ton tai. Khong co su kien bao tin
--             den, phai quet bang timer.
--
--  "local" -- khong dong bo, chay thang. CHI DUNG KHI CHOI MOT MINH.
--
--  "auto" (mac dinh) uu tien blz, roi cache, roi local.
--
--  Duong nao dang chay ghi ro trong file vet, va xem duoc trong game
--  bang lenh -sync.
--
--  KHUON TIN. Moi tin la MOT so nguyen 32 bit:
--
--      packed = op * 10^7  +  seq * 10^5  +  arg
--               op  1..200      seq 0..99     arg 0..99999
--
--  seq co mat chi de phan biet hai tin GIONG HET NHAU gui lien tiep
--  (bam "Dot pha" hai lan). Khong co no thi duong cache -- von so sanh
--  gia tri cu voi moi -- se nuot tin thu hai.
--
--  arg chi 5 chu so, nen KHONG gui duoc id kieu FourCC (H001 la hon 1,2
--  ti). Gui SO THU TU trong bang tinh (CFG.HEROES, danh sach choices)
--  roi tra nguoc ra id o dau ben kia.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local OP_MUL  = 10000000
local SEQ_MUL = 100000
local ARG_MAX = 99999
local OP_MAX  = 200
local MISSION = "d"
local PREFIX  = "DTT"

S.sync = {
  mode     = "local",
  handlers = {},      -- [op] = f(pid, arg)
  seen     = {},      -- [pid] = so doc duoc lan cuoi (duong cache)
  seq      = 0,       -- CUC BO: moi may dem rieng, khong phai trang thai game
  cache    = nil,
  timer    = nil,
  trig     = nil,
  pingSeen = {},
  native   = {},
}

local function keyOf(pid) return "p" .. pid end

local function pack(op, seq, arg)
  return op * OP_MUL + (seq % 100) * SEQ_MUL + arg
end

local function unpackMsg(v)
  local op   = math.floor(v / OP_MUL)
  local rest = v - op * OP_MUL
  local seq  = math.floor(rest / SEQ_MUL)
  return op, seq, rest - seq * SEQ_MUL
end

-- ---------- Do xem ban nay co gi ----------

local function probe()
  local t = {}
  t.blzSend = (BlzSendSyncData ~= nil)
  t.blzData = (BlzGetTriggerSyncData ~= nil)
  -- HAI ten. Ban 1.31 dat ten native la BlzTriggerRegisterPlayerSyncEvent;
  -- tai lieu tren mang hay viet thieu tien to Blz. Do ca hai roi hay ket
  -- luan la ban nay khong co dong bo.
  t.blzRegBlz = (BlzTriggerRegisterPlayerSyncEvent ~= nil)
  t.blzRegOld = (TriggerRegisterPlayerSyncEvent ~= nil)
  t.gc = (InitGameCache ~= nil and StoreInteger ~= nil
      and SyncStoredInteger ~= nil and GetStoredInteger ~= nil
      and HaveStoredInteger ~= nil and FlushGameCache ~= nil
      and FlushStoredInteger ~= nil)
  return t
end

local function blzUsable(t)
  return t.blzSend and t.blzData and (t.blzRegBlz or t.blzRegOld)
end

local function chooseMode(t)
  local m = CFG.SYNC_MODE
  if m == "local" then return "local" end
  if m == "blz"   then return blzUsable(t) and "blz" or "local" end
  if m == "cache" then return t.gc and "cache" or "local" end
  if blzUsable(t) then return "blz" end
  if t.gc         then return "cache" end
  return "local"
end

-- ---------- Nhan tin ----------

local function dispatch(pid, packed)
  local op, _, arg = unpackMsg(packed)
  local f = S.sync.handlers[op]
  if f == nil then
    API.trace("sync: tin la op=" .. op .. " tu pid " .. pid)
    return
  end
  f(pid, arg)
end

-- ---------- Duong blz ----------

local function blzStart()
  local reg = BlzTriggerRegisterPlayerSyncEvent or TriggerRegisterPlayerSyncEvent
  S.sync.trig = CreateTrigger()
  for i = 1, #S.pids do
    reg(S.sync.trig, Player(S.pids[i]), PREFIX, false)
  end
  TriggerAddAction(S.sync.trig, function()
    local v = tonumber(BlzGetTriggerSyncData())
    if v == nil then return end
    dispatch(GetPlayerId(GetTriggerPlayer()), v)
  end)
  return true
end

local function blzSendRaw(packed)
  BlzSendSyncData(PREFIX, tostring(packed))
end

-- ---------- Duong cache ----------

local function cachePoll()
  local sy = S.sync
  if sy.cache == nil then return end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local k = keyOf(pid)
    if HaveStoredInteger(sy.cache, MISSION, k) then
      local v = GetStoredInteger(sy.cache, MISSION, k)
      if v > 0 and v ~= sy.seen[pid] then
        sy.seen[pid] = v
        dispatch(pid, v)
      end
    end
  end
end

local function cacheStart()
  local c = InitGameCache(CFG.SYNC_CACHE)
  if c == nil then return false end

  -- Game cache SONG QUA nhieu van trong cung mot phien Warcraft III, va
  -- no nam tren dia TUNG MAY. Khong xoa thi vao van moi may nay con tin
  -- cu cua van truoc, may kia thi khong -- lech ngay tu giay dau.
  FlushGameCache(c)
  c = InitGameCache(CFG.SYNC_CACHE)
  if c == nil then return false end

  S.sync.cache = c
  for i = 1, #S.pids do S.sync.seen[S.pids[i]] = 0 end

  S.sync.timer = CreateTimer()
  TimerStart(S.sync.timer, CFG.SYNC_POLL, true, cachePoll)
  return true
end

local function cacheSendRaw(pid, packed)
  local sy = S.sync
  if sy.cache == nil then return end
  local k = keyOf(pid)
  StoreInteger(sy.cache, MISSION, k, packed)
  SyncStoredInteger(sy.cache, MISSION, k)

  -- XOA BAN CUC BO NGAY SAU KHI GUI.
  -- StoreInteger ghi thang vao cache cua may nay. Neu de nguyen, bo quet
  -- cua chinh may nguoi gui thay tin o nhip ke tiep (0.1 giay), trong khi
  -- hai may kia phai doi goi tin qua mang. Nguoi gui lam truoc mot nhip
  -- -- lech tran. Xoa di thi may nguoi gui cung phai doi goi tin quay ve
  -- nhu moi nguoi.
  --
  -- Dua tren mot gia dinh CHUA DO DUOC TREN 1.31.1: SyncStoredInteger
  -- dong goi gia tri ngay luc goi, nen xoa sau khong huy duoc no. Neu
  -- gia dinh sai thi tin khong bao gio ve -- nut chet, KHONG lech tran.
  -- Hong kieu do thay duoc ngay khi test; lech tran thi khong. Bo tu
  -- kiem ben duoi do dung viec nay va ghi ket qua vao file vet.
  FlushStoredInteger(sy.cache, MISSION, k)
end

-- ---------- Gui ----------

-- CHI may cua chinh nguoi choi do moi gui. Goi duoc tu su kien cuc bo
-- (bam frame) lan su kien dong bo (chat) deu an toan.
local function send(pid, op, arg)
  arg = math.floor(arg or 0)
  if op < 1 or op > OP_MAX then
    API.trace("sync: op ngoai khoang: " .. tostring(op))
    return
  end
  if arg < 0 or arg > ARG_MAX then
    API.trace("sync: arg ngoai khoang: " .. tostring(arg))
    return
  end
  if GetLocalPlayer() ~= Player(pid) then return end

  local sy = S.sync
  sy.seq = (sy.seq + 1) % 100
  local packed = pack(op, sy.seq, arg)

  if sy.mode == "blz" then
    blzSendRaw(packed)
  elseif sy.mode == "cache" then
    cacheSendRaw(pid, packed)
  else
    dispatch(pid, packed)   -- mot nguoi choi
  end
end

local function on(op, f)
  S.sync.handlers[op] = f
end

-- ---------- Tu kiem ----------
-- Moi nguoi gui mot tin PING luc vao map. Tin ve duoc nghia la duong
-- dang chon that su chay. Ket qua vao file vet, khong lam phien ai.

local function selfTest()
  on(CFG.OP_PING, function(pid, arg)
    S.sync.pingSeen[pid] = true
    API.trace("sync: ping ve tu pid " .. pid .. " (arg " .. arg .. ")")
  end)

  for i = 1, #S.pids do
    send(S.pids[i], CFG.OP_PING, S.pids[i])
  end

  API.after(CFG.SYNC_TEST_WAIT, function()
    local here, gone = {}, {}
    for i = 1, #S.pids do
      local pid = S.pids[i]
      if S.sync.pingSeen[pid] then here[#here + 1] = pid else gone[#gone + 1] = pid end
    end
    API.trace("sync: tu kiem [" .. S.sync.mode .. "] ping ve tu " ..
      #here .. "/" .. #S.pids .. " nguoi" ..
      (#here > 0 and (" (player " .. table.concat(here, ",") .. ")") or "") ..
      (#gone > 0 and (" -- MAT player " .. table.concat(gone, ",")) or ""))
    -- KHONG tu doi duong o day. Neu hai may ket luan khac nhau thi moi
    -- may chay mot kieu -- dung cai muon tranh ngay tu dau. Bao ra roi
    -- de nguoi sua CFG.SYNC_MODE, build lai.
    if #gone > 0 and S.sync.mode ~= "local" then
      API.warn(nil, "Dong bo [" .. S.sync.mode ..
        "] khong nhan duoc tin cua player " .. table.concat(gone, ",") ..
        " -- nut trong bang se khong an.")
      API.info(nil, CFG.C_GOLD .. "Doi CFG.SYNC_MODE trong 1_config.lua sang " ..
        (S.sync.mode == "cache" and "\"blz\"" or "\"cache\"") ..
        " roi build lai. Go -sync de xem chi tiet." .. CFG.C_END)
    end
  end)
end

-- ---------- Bao cao ----------

local function statusLines()
  local t = S.sync.native
  local out = {}
  out[#out + 1] = "Duong dang chay: " .. CFG.C_GOLD .. S.sync.mode .. CFG.C_END ..
                  "   (CFG.SYNC_MODE = " .. tostring(CFG.SYNC_MODE) .. ")"
  out[#out + 1] = "BlzSendSyncData .................. " .. tostring(t.blzSend)
  out[#out + 1] = "BlzGetTriggerSyncData ............ " .. tostring(t.blzData)
  out[#out + 1] = "BlzTriggerRegisterPlayerSyncEvent  " .. tostring(t.blzRegBlz)
  out[#out + 1] = "TriggerRegisterPlayerSyncEvent ... " .. tostring(t.blzRegOld)
  out[#out + 1] = "Game cache (Store/Sync/Flush) .... " .. tostring(t.gc)

  -- Ghi ro tung nguoi mot. Truoc day gop thanh mot danh sach so, nen
  -- "Ping ve tu player: 0" doc ra hai nghia trai nguoc nhau: player so 0
  -- da ve, hay khong ai ve. Bang chan doan ma doc nham duoc thi te hon
  -- la khong co.
  for i = 1, #S.pids do
    local pid = S.pids[i]
    out[#out + 1] = "Ping player " .. pid .. ": " ..
      (S.sync.pingSeen[pid] and (CFG.C_JADE .. "da ve" .. CFG.C_END)
                            or (CFG.C_RED .. "CHUA VE" .. CFG.C_END))
  end
  return out
end

local function onChat(pid)
  local lines = statusLines()
  API.info(pid, CFG.C_GOLD .. "=== Dong bo ===" .. CFG.C_END)
  for i = 1, #lines do API.msg(pid, lines[i]) end
  send(pid, CFG.OP_PING, pid)
  API.msg(pid, CFG.C_GREY ..
    "Da gui mot ping. Go -sync lai sau 1 giay de xem no ve chua." .. CFG.C_END)
end

local function startSync()
  local t = probe()
  S.sync.native = t
  S.sync.mode   = chooseMode(t)

  if S.sync.mode == "blz" then
    if not blzStart() then S.sync.mode = "local" end
  elseif S.sync.mode == "cache" then
    if not cacheStart() then S.sync.mode = "local" end
  end

  API.trace("sync: mode=" .. S.sync.mode ..
    " blzSend=" .. tostring(t.blzSend) ..
    " blzReg=" .. tostring(t.blzRegBlz) ..
    " regCu=" .. tostring(t.blzRegOld) ..
    " cache=" .. tostring(t.gc))

  if S.sync.mode == "local" then
    API.warn(nil, "Khong co kenh dong bo nao -- bang chi dung duoc " ..
      "khi choi MOT MINH. Go -sync de xem chi tiet.")
  end

  selfTest()
end

API.syncSend   = send
API.syncOn     = on
API.syncMode   = function() return S.sync.mode end
API.syncChat   = onChat
API.syncStatus = statusLines
API.startSync  = startSync
end
--#endregion 1_core/3_sync.lua

--#region 1_core/4_geometry.lua
do
-- ============================================================
--  4_geometry.lua  --  Luoi 25 o va cac dong song ngan cach
--
--  Mot truc (vd truc X, 5 cot) duoc chia nhu sau:
--
--    |<-le->|block|song|block|song|block|song|block|song|block|<-le->|
--
--  Kich thuoc block suy ra tu vung choi duoc that su cua map luc chay,
--  khong hard-code. Phan du sau khi chia deu duoc day ra hai bien lam
--  le, nen luoi luon nam chinh giua vung choi duoc.
--
--  Module nay chi tinh TOA DO. No khong ve dia hinh -- Lua cua WC3
--  khong tao duoc nuoc luc chay. Xem docs/04-map/luoi-25-o.md.
-- ============================================================

-- ---------- Toa do co ban ----------

local function polarX(x, dist, angDeg) return x + dist * Cos(angDeg * bj_DEGTORAD) end
local function polarY(y, dist, angDeg) return y + dist * Sin(angDeg * bj_DEGTORAD) end

local function angleXY(x1, y1, x2, y2)
  return bj_RADTODEG * Atan2(y2 - y1, x2 - x1)
end

local function distXY(x1, y1, x2, y2)
  local dx, dy = x2 - x1, y2 - y1
  return SquareRoot(dx * dx + dy * dy)
end

local function playableRect()
  local r = bj_mapInitialPlayableArea
  return GetRectMinX(r), GetRectMinY(r), GetRectMaxX(r), GetRectMaxY(r)
end

-- Chia totalTiles thanh n block ngan cach boi (n-1) con song.
-- Tra ve: so o moi block, so o le moi ben.
local function splitAxis(totalTiles, n, riverTiles)
  local block = CFG.BLOCK_TILES_OVERRIDE
  if block <= 0 then
    block = math.floor((totalTiles - (n - 1) * riverTiles) / n)
  end
  if block < 1 then block = 1 end
  local used = n * block + (n - 1) * riverTiles
  -- Lam tron xuong: goc luoi phai roi dung ranh gioi o dia hinh, neu
  -- khong thi khong con dem o trong World Editor duoc. Nua o du neu co
  -- bi day sang bien phai/tren.
  local margin = math.floor((totalTiles - used) / 2)
  return block, margin
end

local function buildGrid()
  local minX, minY, maxX, maxY = playableRect()
  local T     = CFG.TILE
  local cols  = CFG.GRID_COLS
  local rows  = CFG.GRID_ROWS
  local river = CFG.RIVER_TILES

  local tilesW = API.round((maxX - minX) / T)
  local tilesH = API.round((maxY - minY) / T)

  local bw, marginX = splitAxis(tilesW, cols, river)
  local bh, marginY = splitAxis(tilesH, rows, river)

  S.grid = {
    cols = cols, rows = rows,

    -- don vi the gioi
    blockW  = bw * T,
    blockH  = bh * T,
    river   = river * T,
    originX = minX + marginX * T,
    originY = minY + marginY * T,

    -- don vi o dia hinh, de doi chieu voi World Editor
    tilesW = tilesW, tilesH = tilesH,
    blockTilesW = bw, blockTilesH = bh,
    riverTiles = river,
    marginTilesX = marginX, marginTilesY = marginY,

    playMinX = minX, playMinY = minY, playMaxX = maxX, playMaxY = maxY,
  }

  -- pitch = tu mep trai block nay toi mep trai block ke tiep
  S.grid.pitchX = S.grid.blockW + S.grid.river
  S.grid.pitchY = S.grid.blockH + S.grid.river
  S.grid.spanX  = cols * S.grid.blockW + (cols - 1) * S.grid.river
  S.grid.spanY  = rows * S.grid.blockH + (rows - 1) * S.grid.river

  return S.grid
end

-- Keo mot diem ve trong vung choi duoc cua map.
local function clampToMap(x, y)
  local r = bj_mapInitialPlayableArea
  if r == nil then return x, y end
  local pad = 256.0
  return API.clamp(x, GetRectMinX(r) + pad, GetRectMaxX(r) - pad),
         API.clamp(y, GetRectMinY(r) + pad, GetRectMaxY(r) - pad)
end

-- Block dem tu 1, goc duoi-trai la (1,1) -- cung chieu voi toa do WC3.
local function blockIndex(col, row)
  return (row - 1) * S.grid.cols + col
end

local function blockBounds(col, row)
  local g = S.grid
  local x0 = g.originX + (col - 1) * g.pitchX
  local y0 = g.originY + (row - 1) * g.pitchY
  return x0, y0, x0 + g.blockW, y0 + g.blockH
end

local function blockCenter(col, row)
  local x0, y0, x1, y1 = blockBounds(col, row)
  return (x0 + x1) * 0.5, (y0 + y1) * 0.5
end

-- Tra ve col, row neu diem nam trong mot block.
-- Tra ve nil neu diem nam duoi song hoac ngoai luoi.
local function blockAt(x, y)
  local g = S.grid
  local dx, dy = x - g.originX, y - g.originY
  if dx < 0 or dy < 0 or dx >= g.spanX or dy >= g.spanY then return nil end

  local col = math.floor(dx / g.pitchX) + 1
  local row = math.floor(dy / g.pitchY) + 1
  if col > g.cols then col = g.cols end
  if row > g.rows then row = g.rows end

  -- Phan du sau mep phai block chinh la long song.
  if dx - (col - 1) * g.pitchX > g.blockW then return nil end
  if dy - (row - 1) * g.pitchY > g.blockH then return nil end
  return col, row
end

local function inRiver(x, y)
  local g = S.grid
  local dx, dy = x - g.originX, y - g.originY
  if dx < 0 or dy < 0 or dx >= g.spanX or dy >= g.spanY then return false end
  return blockAt(x, y) == nil
end

-- Cac long song doc: { {x0, x1}, ... }, tu trai sang phai.
local function riverColumns()
  local g, out = S.grid, {}
  for i = 1, g.cols - 1 do
    local x0 = g.originX + (i - 1) * g.pitchX + g.blockW
    out[#out + 1] = { x0 = x0, x1 = x0 + g.river }
  end
  return out
end

-- Cac long song ngang: { {y0, y1}, ... }, tu duoi len tren.
local function riverRows()
  local g, out = S.grid, {}
  for i = 1, g.rows - 1 do
    local y0 = g.originY + (i - 1) * g.pitchY + g.blockH
    out[#out + 1] = { y0 = y0, y1 = y0 + g.river }
  end
  return out
end

local function forEachBlock(f)
  for row = 1, S.grid.rows do
    for col = 1, S.grid.cols do
      local x0, y0, x1, y1 = blockBounds(col, row)
      f(col, row, blockIndex(col, row), x0, y0, x1, y1)
    end
  end
end

-- Doi toa do the gioi sang chi so o dia hinh cua World Editor.
-- Tien khi can go toa do vao WE de ve song cho khop.
local function worldToTile(x, y)
  local g = S.grid
  return API.round((x - g.playMinX) / CFG.TILE), API.round((y - g.playMinY) / CFG.TILE)
end

-- ---------- Vung tao trong World Editor ----------
-- WE sinh moi vung thanh mot bien toan cuc ten gg_rct_<Ten>, tao trong
-- CreateRegions() do main() goi. Bootstrap chay sau khi main() xong nen
-- luc do chung da ton tai.

local function region(name)
  if name == nil then return nil end
  local r = _G["gg_rct_" .. name]
  if r ~= nil then return r end
  -- World Editor cho dat ten co KHOANG TRANG ("Region 004 Copy") nhung
  -- bien toan cuc thi khong the co khoang trang -- no thay bang gach
  -- duoi. Thu ca hai de trong CFG viet duoc dung cai ten nhin thay
  -- trong World Editor, khong phai tu dich sang dang bien.
  return _G["gg_rct_" .. name:gsub("[^%w]", "_")]
end

local function regionCenter(r)
  if r == nil then return nil, nil end
  return GetRectCenterX(r), GetRectCenterY(r)
end

-- Liet ke moi vung WE nhin thay duoc. Dung khi ten trong CFG khong khop.
local function listRegions()
  local out = {}
  for k, _ in pairs(_G) do
    if type(k) == "string" and k:sub(1, 7) == "gg_rct_" then
      out[#out + 1] = k:sub(8)
    end
  end
  table.sort(out)
  return out
end

-- Ten vung: mot chuoi, hoac mot danh sach ung vien thu lan luot.
local function regionNames(names)
  if type(names) == "string" then return { names } end
  return names
end

-- Nhan mot ten hoac danh sach ten. Thu khop chinh xac truoc, roi moi
-- khop khong phan biet hoa thuong.
local function findRegion(names)
  local list = regionNames(names)

  for i = 1, #list do
    local r = region(list[i])
    if r ~= nil then return r, list[i] end
  end

  local have = listRegions()
  for i = 1, #list do
    local lower = list[i]:lower()
    for j = 1, #have do
      if have[j]:lower() == lower then return region(have[j]), have[j] end
    end
  end
  return nil, nil
end

-- Ten de hien trong thong bao.
local function regionLabel(names)
  return table.concat(regionNames(names), " / ")
end

-- Bao khong tim thay vung, KEM danh sach vung World Editor that su co.
-- Khong phu thuoc CFG.DEBUG: go sai ten vung la loi rat kho doan neu
-- chi bao "khong thay".
local function regionMissing(cfgKey, name)
  API.warn(nil, "Khong tim thay vung " .. name ..
    "  (" .. cfgKey .. ")")
  local rgns = listRegions()
  if #rgns == 0 then
    API.info(nil, "  World Editor chua co vung nao. Tao vung, Save, roi chay lai build.py.")
  else
    API.info(nil, "  Vung dang co: " .. table.concat(rgns, ", "))
  end
end

-- ---------- Vai tro cua tung block ----------
--
-- Block khong khai bao trong CFG.BLOCKS thi la "hoang" -- chua giao
-- viec. Tra ve "hoang" chu khong tra nil: goi ben ngoai khong phai kiem
-- nil truoc moi lan dung.
local function blockRole(idx)
  local b = CFG.BLOCKS[idx]
  return (b ~= nil and b.role) or "wilds"
end

local function blockRoleDef(idx)
  return CFG.BLOCK_ROLE[blockRole(idx)] or CFG.BLOCK_ROLE.wilds
end

local function blockRoleName(idx)
  return API.pick(blockRoleDef(idx))
end

-- Vung World Editor cua mot block: gg_rct_Blk07. Tra ve nil neu chua
-- chay w3region.py -- goi ben ngoai phai chiu duoc chuyen do.
local function blockRegion(idx)
  return region(string.format("%s%02d", CFG.BLOCK_RGN_PREFIX, idx))
end

API.blockRole     = blockRole
API.blockRoleDef  = blockRoleDef
API.blockRoleName = blockRoleName
API.blockRegion   = blockRegion

API.regionNames   = regionNames
API.regionLabel   = regionLabel
API.regionMissing = regionMissing
API.region       = region
API.regionCenter = regionCenter
API.listRegions  = listRegions
API.findRegion   = findRegion

API.polarX       = polarX
API.polarY       = polarY
API.angleXY      = angleXY
API.distXY       = distXY
API.clampToMap   = clampToMap
API.playableRect = playableRect
API.buildGrid    = buildGrid
API.blockIndex   = blockIndex
API.blockBounds  = blockBounds
API.blockCenter  = blockCenter
API.blockAt      = blockAt
API.inRiver      = inRiver
API.riverColumns = riverColumns
API.riverRows    = riverRows
API.forEachBlock = forEachBlock
API.worldToTile  = worldToTile
end
--#endregion 1_core/4_geometry.lua

--#region 1_core/5_natives.lua
do
-- ============================================================
--  5_natives.lua  --  Ban 1.31.1 nay co nhung gi
--
--  Moi lan doan xem mot native co ton tai hay khong, du an nay deu doan
--  sai. Lan dat nhat: doan "1.31.1 khong co dong bo" trong khi chi la
--  viet thieu tien to Blz -- ba bang giao dien am tham lui ve che do mot
--  nguoi choi suot may ngay ma khong ai biet (ADR 0012).
--
--  Nen: khong doan nua. Do mot lan luc vao map, ghi vao file vet, va cho
--  xem lai bang lenh -nat.
--
--  Goi mot ten toan cuc chua dinh nghia trong Lua tra ve nil chu khong
--  no loi -- nen chi can so sanh voi nil la do duoc.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Moi muc: { ten hien thi, gia tri, giai thich neu THIEU }
local function groups()
  return {
    { name = "Su kien sat thuong", entries = {
      { "EVENT_PLAYER_UNIT_DAMAGED",  EVENT_PLAYER_UNIT_DAMAGED,
