local function lang()
  return T[CFG.LANG] and CFG.LANG or "en"
end

-- Thieu cau thi tra ve chinh cai key. Mot chuoi la tren man hinh de
-- thay ngay va sua sau duoc; nil thi no giua tran.
local function t(key, ...)
  local s = T[lang()][key]
  if s == nil then
    API.trace("i18n: THIEU cau [" .. tostring(key) .. "] tieng " .. lang())
    return tostring(key)
  end
  if select("#", ...) == 0 then return s end
  return string.format(s, ...)
end

-- Ten nam trong bang du lieu: { ten = "Pham Nhan", en = "Mortal" }
-- Tieng Viet giu o khoa "ten" vi bang du lieu viet bang tieng Viet truoc.
local function pick(tbl)
  if tbl == nil then return "?" end
  if lang() == "en" then return tbl.en or tbl.vi or "?" end
  return tbl.vi or tbl.en or "?"
end

-- Doi chieu hai bang: thieu cau nao thi bao ngay luc vao map, dung de
-- tinh co mo dung the do moi phat hien.
local function checkAll()
  local missing = {}
  for k, _ in pairs(T.en) do
    if T.vi[k] == nil then missing[#missing + 1] = "vi:" .. k end
  end
  for k, _ in pairs(T.vi) do
    if T.en[k] == nil then missing[#missing + 1] = "en:" .. k end
  end
  if #missing > 0 then
    API.trace("i18n: LECH BANG -- " .. table.concat(missing, " "))
  else
    API.trace("i18n: " .. lang() .. ", hai bang khop nhau")
  end
end

API.t         = t
API.pick      = pick
API.lang      = lang
API.langCheck = checkAll
end
--#endregion 1_core/6_i18n.lua

--#region 2_player/1_player.lua
do
-- ============================================================
--  1_player.lua  --  Dang ky nguoi choi va quan he dong minh
--
--  Buoc 1 chi lam dung hai viec: biet ai dang choi, va dat quan he
--  ba nguoi choi <-> phe dich. Chua co hero, chua co chi so.
-- ============================================================

local function initPlayers()
  S.pids = {}
  S.p = {}

  for i = 1, #CFG.PLAYER_SLOTS do
    local pid = CFG.PLAYER_SLOTS[i]
    local p = Player(pid)
    -- Slot trong hoac do may giu deu bi bo qua, nen choi mot minh van vao duoc.
    if GetPlayerSlotState(p) == PLAYER_SLOT_STATE_PLAYING
       and GetPlayerController(p) == MAP_CONTROL_USER then
      S.p[pid] = { active = true, hero = nil, heroCount = 0,
                   slots = {},
                   qi = 0, qiTotal = 0,
                   cultRank = 1, fctGold = 0,

                   iron = 0,        -- Da Huyen Thiet
                   gear = {},       -- [so thu tu mon] = { canh, cap }
                   relic = {} }      -- [ma phap khi] = true
      S.pids[#S.pids + 1] = pid
    end
  end

  -- Ba nguoi choi la dong minh, chung tam nhin.
  for i = 1, #S.pids do
    for j = 1, #S.pids do
      if i ~= j then
        SetPlayerAllianceStateBJ(Player(S.pids[i]), Player(S.pids[j]), bj_ALLIANCE_ALLIED_VISION)
      end
    end
  end

  -- Phe dich doi dau voi tat ca.
  S.enemy = Player(CFG.ENEMY_SLOT)
  for i = 1, #S.pids do
    SetPlayerAllianceStateBJ(S.enemy, Player(S.pids[i]), bj_ALLIANCE_UNALLIED)
    SetPlayerAllianceStateBJ(Player(S.pids[i]), S.enemy, bj_ALLIANCE_UNALLIED)
  end

  -- Nha chinh dung slot rieng, khong thuoc ve rieng ai. No la dong minh
  -- cua ca ba nguoi choi va CHUNG TAM NHIN -- nho vay tam nhin 1500 cua
  -- no moi co ich cho ho. Va no doi dau voi phe dich de bi nham lam
  -- muc tieu.
  S.houseOwner = Player(CFG.HOUSE_SLOT)
  for i = 1, #S.pids do
    SetPlayerAllianceStateBJ(Player(S.pids[i]), S.houseOwner, bj_ALLIANCE_ALLIED_VISION)
    SetPlayerAllianceStateBJ(S.houseOwner, Player(S.pids[i]), bj_ALLIANCE_ALLIED_VISION)
  end
  SetPlayerAllianceStateBJ(S.houseOwner, S.enemy, bj_ALLIANCE_UNALLIED)
  SetPlayerAllianceStateBJ(S.enemy, S.houseOwner, bj_ALLIANCE_UNALLIED)

  -- Tat quyen dieu khien chung mot cach TUONG MINH.
  -- bj_ALLIANCE_ALLIED_VISION o tren da tat san, nhung dat lai ro rang
  -- thi doc code khong phai tra xem hang so BJ do bat/tat nhung gi.
  if SetPlayerAlliance ~= nil and ALLIANCE_SHARED_CONTROL ~= nil then
    for i = 1, #S.pids do
      local p = Player(S.pids[i])
      SetPlayerAlliance(p, S.houseOwner, ALLIANCE_SHARED_CONTROL, false)
      SetPlayerAlliance(S.houseOwner, p, ALLIANCE_SHARED_CONTROL, false)
      if ALLIANCE_SHARED_ADVANCED_CONTROL ~= nil then
        SetPlayerAlliance(p, S.houseOwner, ALLIANCE_SHARED_ADVANCED_CONTROL, false)
        SetPlayerAlliance(S.houseOwner, p, ALLIANCE_SHARED_ADVANCED_CONTROL, false)
      end
    end
  end

  -- Slot nha chinh trung slot nguoi choi hoac slot dich thi quan he
  -- dong minh o tren se da nhau. Bao ngay thay vi de no hong am tham.
  if CFG.HOUSE_SLOT == CFG.ENEMY_SLOT then
    API.warn(nil, "CFG.HOUSE_SLOT trung ENEMY_SLOT -- nha chinh dang"
      .. " thuoc phe dich.")
  end
  for i = 1, #CFG.PLAYER_SLOTS do
    if CFG.PLAYER_SLOTS[i] == CFG.HOUSE_SLOT then
      API.warn(nil, "CFG.HOUSE_SLOT trung slot nguoi choi "
        .. CFG.HOUSE_SLOT .. ".")
    end
  end

  return #S.pids
end

-- ---------- Khoa hero: kinh nghiem & ky nang ----------
--
-- SuspendHeroXP chan viec NHAN kinh nghiem, nen hero dung yen o cap
-- hien tai. Goi nhieu lan len cung mot unit la vo hai, nen bo quet co
-- the chay lai thoai mai.

-- Rut sach diem ky nang.
--
-- Warcraft III khong co native doc so diem ky nang hien co, nen tru dan
-- tung diem toi khi native bao khong tru duoc nua. Chan 20 vong de
-- khong bao gio treo du native co tra ve gi.
local function stripSkillPoints(u)
  if not CFG.STRIP_SKILL_POINTS then return 0, "tat" end
  if UnitModifySkillPoints == nil then return 0, "native khong ton tai" end

  local n = 0
  for _ = 1, 20 do
    if not UnitModifySkillPoints(u, -1) then break end
    n = n + 1
  end
  return n, "ok"
end

-- Phat diem ky nang. Dung o che do "learn" -- goi luc tao hero, hoac
-- bat cu khi nao ban muon thuong (don sach dot quai, moc thoi gian...).
local function grantSkillPoints(u, n)
  if u == nil or n == nil or n <= 0 then return false end
  if UnitModifySkillPoints == nil then return false end
  if CFG.STRIP_SKILL_POINTS then
    API.warn(nil, "Phat diem ky nang khi STRIP_SKILL_POINTS con bat" ..
      " -- bo quet se an mat ngay.")
  end
  return UnitModifySkillPoints(u, n)
end

-- Do danh sach ability THAT cua hero ra file vet. Moi unit chi do mot
-- lan de khong lam ngap file.
--
-- Day la cach lay ID that thay vi doan: danh sach ID hero skill tren
-- mang khong dang tin, va doan sai thi UnitRemoveAbility im lang khong
-- lam gi -- kieu that bai kho phat hien nhat.
local function dumpAbilities(u)
  if not CFG.TRACE or S.dumped[u] then return end
  if BlzGetUnitAbilityByIndex == nil or BlzGetAbilityId == nil then
    API.trace("abil: khong co BlzGetUnitAbilityByIndex de liet ke")
    S.dumped[u] = true
    return
  end
  S.dumped[u] = true

  local list = {}
  for i = 0, 40 do
    local ab = BlzGetUnitAbilityByIndex(u, i)
    if ab == nil then break end
    list[#list + 1] = API.idToStr(BlzGetAbilityId(ab))
  end
  API.trace("abil " .. GetUnitName(u) .. " (" .. #list .. "): " ..
            table.concat(list, " "))
end

-- Go ky nang goc, va GHI LAI ket qua tung id.
--
-- UnitRemoveAbility tra ve boolean: true nghia la unit CO ability do va
-- da go duoc, false nghia la unit khong he co no. Day la cach duy nhat
-- con lai de biet id doan dung hay sai, vi 1.31.1 khong co
-- BlzGetUnitAbilityByIndex de liet ke truc tiep.
local function removeStockAbilities(u)
  local report = (CFG.TRACE and not S.abilReported[u])
  if report then S.abilReported[u] = true end

  local hits = {}
  for i = 1, #CFG.HERO_REMOVE_ABILITIES do
    local aid = CFG.HERO_REMOVE_ABILITIES[i]
    local ok = UnitRemoveAbility(u, aid)
    if report and ok then hits[#hits + 1] = API.idToStr(aid) end
  end

  if report then
    if #hits == 0 then
      API.trace("remove " .. GetUnitName(u) .. ": KHONG id nao trung " ..
                "(" .. #CFG.HERO_REMOVE_ABILITIES .. " id da thu)")
    else
      API.trace("remove " .. GetUnitName(u) .. ": go duoc " ..
                table.concat(hits, " "))
    end
  end
end

local function lockHero(u)
  if u == nil then return false end
  if not IsUnitType(u, UNIT_TYPE_HERO) then return false end

  if CFG.LOCK_HERO_XP then SuspendHeroXP(u, true) end

  local n, how = stripSkillPoints(u)
  if not S.spReported[u] then
    S.spReported[u] = true
    API.trace("skillpoint " .. GetUnitName(u) .. ": rut " .. n .. " diem (" .. how .. ")")
  end

  dumpAbilities(u)
  removeStockAbilities(u)
  return true
end

-- Quet moi unit trong vung choi duoc. Bat duoc ca nhung hero sinh ra o
-- cho code nay khong goi toi.
local function sweepHeroes()
  if not (CFG.LOCK_HERO_XP or CFG.STRIP_SKILL_POINTS) then return 0 end
  local g = CreateGroup()
  GroupEnumUnitsInRect(g, bj_mapInitialPlayableArea, nil)

  local n = 0
  local u = FirstOfGroup(g)
  while u ~= nil do
    GroupRemoveUnit(g, u)
    if lockHero(u) then n = n + 1 end
    u = FirstOfGroup(g)
  end

  DestroyGroup(g)
  return n
end

local function startHeroLock()
  local n = sweepHeroes()
  API.trace("lockHero: quet dau tien khoa " .. n .. " hero")
  if CFG.HERO_XP_SWEEP > 0 then
    S.xpTimer = CreateTimer()
    TimerStart(S.xpTimer, CFG.HERO_XP_SWEEP, true, sweepHeroes)
  end
end

-- ---------- BA DONG TIEN ----------
--
--   Linh Khi   bien rieng, hien o bang phim R   <- quai thuong, 1/con
--   Vang       thanh tai nguyen VANG cua Warcraft <- quai thuong, 1/con
--   Go         thanh tai nguyen GO cua Warcraft   <- tinh anh 1, boss 5
--
-- Vi sao Linh Khi khong con nam tren thanh tai nguyen: thanh do chi co
-- HAI o ma gio co BA dong tien. Vang va Go duoc uu tien vi chung la thu
-- nguoi choi tieu lien tuc (shop moi wave, ky nang moi tinh anh); Linh
-- Khi chi tieu o DUNG MOT cho (Linh Can), nen nam trong bang la du.
--
-- Hai dong tien cu, Ngo Tinh va Tinh Thach, da bo: Ngo Tinh thanh Go,
-- con Tinh Thach khong con he nao tieu sau khi Phap Khi bi khoa -- giu
-- lai la de nguoi choi nhin mot con so tang mai ma khong bao gio dung
-- duoc. Xem docs/02-he-thong/kinh-te.md

-- ---------- Linh Khi ----------
local function addQi(pid, amount)
  if amount == nil or amount == 0 then return end
  local d = S.p[pid]
  if d == nil then return end
  d.qi = (d.qi or 0) + amount
  if d.qi < 0 then d.qi = 0 end
  if amount > 0 then
    d.qiTotal = (d.qiTotal or 0) + amount
    API.fctOnQi(pid, amount)
  end
end

local function getQi(pid)
  local d = S.p[pid]
  return (d ~= nil) and (d.qi or 0) or 0
end

local function spendQi(pid, amount)
  if getQi(pid) < amount then return false end
  addQi(pid, -amount)
  return true
end

-- ---------- Vang (thanh tai nguyen) ----------
local function addGold(pid, amount)
  if amount == nil or amount == 0 then return end
  local p = Player(pid)
  local cur = GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD)
  local newVal = cur + amount
  if newVal < 0 then newVal = 0 end
  SetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD, newVal)
  -- Ghi so cai NGAY SAU khi ghi that. Ghi truoc thi so cai giu con
  -- so cu va nhip kiem ngay sau se to oan nguoi choi.
  -- Xem 13_cheatguard.lua.
  if API.cheatNote ~= nil then API.cheatNote(pid, "gold", newVal) end
end

local function getGold(pid)
  return GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD)
end

local function spendGold(pid, amount)
  if getGold(pid) < amount then return false end
  addGold(pid, -amount)
  return true
end

-- ---------- Da Huyen Thiet ----------
--
-- KHONG nam tren thanh tai nguyen: thanh do chi co HAI o (vang, go)
-- ma map co ba dong tien cong them da. Nen da song trong S.p[pid].da
-- va hien o bang phim ESC, giong Linh Khi.
--
-- Truoc 2026-09-17 ba cho tu cong thang vao d.da. Gom lai mot cua de
-- them cho tieu khong phai nho sua may noi.
local function addIron(pid, amount)
  if amount == nil or amount == 0 then return end
  local d = S.p[pid]
  if d == nil then return end
  local newVal = (d.iron or 0) + amount
  if newVal < 0 then newVal = 0 end
  d.iron = newVal
end

local function getIron(pid)
  local d = S.p[pid]
  return (d ~= nil) and (d.iron or 0) or 0
end

local function spendIron(pid, amount)
  if getIron(pid) < amount then return false end
  addIron(pid, -amount)
  return true
end

-- ---------- Go (thanh tai nguyen) ----------
local function addLumber(pid, amount)
  if amount == nil or amount == 0 then return end
  local p = Player(pid)
  local cur = GetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER)
  local newVal = cur + amount
  if newVal < 0 then newVal = 0 end
  SetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER, newVal)
  if API.cheatNote ~= nil then API.cheatNote(pid, "lumber", newVal) end
end

local function getLumber(pid)
  return GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER)
end

local function spendLumber(pid, amount)
  if getLumber(pid) < amount then return false end
  addLumber(pid, -amount)
  return true
end

local function activeCount()
  local n = 0
  for i = 1, #S.pids do
    if S.p[S.pids[i]].active then n = n + 1 end
  end
  return n
end

API.addQi       = addQi
API.getQi       = getQi
API.spendQi     = spendQi
API.addGold          = addGold
API.getGold          = getGold
API.spendGold        = spendGold
API.addIron            = addIron
API.getIron            = getIron
API.spendIron          = spendIron
API.addLumber            = addLumber
API.getLumber            = getLumber
API.spendLumber          = spendLumber
API.grantSkillPoints = grantSkillPoints
API.lockHero      = lockHero
API.sweepHeroes   = sweepHeroes
API.startHeroLock = startHeroLock
API.initPlayers = initPlayers
API.activeCount = activeCount
end
--#endregion 2_player/1_player.lua

--#region 2_player/2_heropick.lua
do
-- ============================================================
--  2_heropick.lua  --  Chon hero bang popup
--
--  Thay cho Tavern. Ly do: CreateUnit bo qua toan bo techtree --
--  khong requirement Altar, khong gia vang/go, khong luong thuc,
--  khong quay hang, khong dong ho hoi hang. Ban Tavern phai chong do
--  ca nam thu do bang nam cho va tam; popup thi khong can cai nao.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nhung hero chua ai lay.
-- Hero mo khoa: bo cac con dang 'locked' (cay ky nang chua thiet ke).
local function unlockedCount()
  local n = 0
  for i = 1, #CFG.HEROES do
    if not CFG.HEROES[i].locked then n = n + 1 end
  end
  return n
end

-- Luat "moi nguoi mot con" chi co nghia khi con NHIEU HON MOT con.
--
-- Con mot con ma van ep duy nhat thi nguoi thu hai khong co hero nao,
-- va khong co thao tac nao cuu duoc -- ho chi ngoi nhin. Suy tu so hero
-- mo khoa chu khong doc thang CFG.HERO_UNIQUE, de mo khoa lai la luat
-- tu bat ma khong phai nho sua cho nao.
local function uniqueOn()
  return CFG.HERO_UNIQUE and unlockedCount() > 1
end

local function available()
  local out = {}
  for i = 1, #CFG.HEROES do
    local h = CFG.HEROES[i]
    if not h.locked and not (uniqueOn() and S.heroTaken[h.id]) then
      out[#out + 1] = h
    end
  end
  return out
end

local function heroDef(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return CFG.HEROES[i] end
  end
  return nil
end

-- So thu tu trong CFG.HEROES. Kenh dong bo chi cho gui so duoi 100000,
-- ma id kieu FourCC thi hon mot ti -- nen gui so thu tu roi tra nguoc
-- ra id o dau ben kia. Xem src/1_core/3_sync.lua.
local function heroIndex(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return i end
  end
  return nil
end

-- Gan ky nang luc tao. Ghi lai id nao gan that bai -- UnitAddAbility
-- tra ve false khi id khong ton tai, va that bai im lang kieu do la
-- thu kho phat hien nhat.
local function giveAbilities(u, uid)
  local def = heroDef(uid)
  local list = {}

  for i = 1, #CFG.HERO_COMMON_ABILITIES do
    list[#list + 1] = CFG.HERO_COMMON_ABILITIES[i]
  end
  if def ~= nil and def.abilities ~= nil then
    for i = 1, #def.abilities do list[#list + 1] = def.abilities[i] end
  end

  -- Ky nang hero: CHI nhung cai da mo khoa. Khong hoc bang diem, mua
  -- bang Linh Khi trong bang phim E. Xem
  -- docs/03-du-lieu/nang-cap-ky-nang.md
  local sk = CFG.SKILLS[uid]
  if sk ~= nil then
    local n = CFG.SKILL_START_COUNT
    if n > #sk then n = #sk end
    for i = 1, n do list[#list + 1] = sk[i].id end
  end

  local bad = {}
  for i = 1, #list do
    if UnitAddAbility(u, list[i]) then
      -- Ability nhan ban tu HERO ability ra o cap 0: nut hien nhung bam
      -- khong duoc. Ability thuong von da cap 1, goi them la vo hai.
      SetUnitAbilityLevel(u, list[i], 1)
    else
      bad[#bad + 1] = API.idToStr(list[i])
    end
  end

  if #bad > 0 then
    API.warn(nil, "Khong gan duoc ability: " ..
      table.concat(bad, " "))
  end
  API.trace("abil gan cho " .. GetUnitName(u) .. ": " .. (#list - #bad) ..
            "/" .. #list)
end

local function heroNameOf(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return CFG.HEROES[i].name end
  end
  return "?"
end

local function slotIndex(pid)
  for i = 1, #S.pids do
    if S.pids[i] == pid then return i end
  end
  return 1
end

-- Hero sinh quanh nha chinh, moi nguoi mot huong de khong chong len nhau.
-- Xoe quanh mot diem theo slot nguoi choi: ba hero cung sinh mot cho
-- thi chong len nhau va Warcraft day chung ra lung tung.
--
-- Dung chung cho CA hai cho -- luc pick, va luc cong dich chuyen dua ve
-- nha chinh (xem startHeroGate o 1_house.lua). Hai cho mot cong thuc,
-- nen khoang cach giua cac hero luon giong nhau.
local function fanPoint(pid, cx, cy, radius)
  local n = #S.pids
  if n < 1 then n = 1 end
  local ang = (360.0 / n) * (slotIndex(pid) - 1)
  local x, y = API.clampToMap(API.polarX(cx, radius, ang),
                              API.polarY(cy, radius, ang))
  return x, y, ang
end

local function spawnHero(pid, uid)
  -- Hero ra o HeroStartRegion, khong phai quanh nha chinh. Thieu vung
  -- thi BAO RA roi lui ve nha chinh -- khong im lang sinh nham cho.
  local cx, cy
  local r, realName = API.findRegion(CFG.RGN_HERO_START)
  if r ~= nil then
    cx, cy = API.regionCenter(r)
    S.heroStartRgnName = realName
  else
    API.regionMissing("CFG.RGN_HERO_START", API.regionLabel(CFG.RGN_HERO_START))
    cx, cy = S.houseX, S.houseY
  end
  if cx == nil then cx, cy = API.blockCenter(3, 3) end

  local x, y, ang = fanPoint(pid, cx, cy, CFG.HERO_SPAWN_OFFSET)

  local u = CreateUnit(Player(pid), uid, x, y, ang + 180.0)
  if u ~= nil then
    API.lockHero(u)
    giveAbilities(u, uid)
    -- THU TU QUAN TRONG. Doc chi so NEN cua hero moi TRUOC khi bat cu
    -- he nao cong vao -- doc sau la doc phai con so da cong roi, va moi
    -- lan doi hero se nhan chong them mot lan.
    API.heroBaseCapture(pid)
    API.skillApply(pid)          -- dat lai bac cho dung bang da mua
    API.heroRecomputeAll()       -- Linh Can + Trang Bi + bi dong + aura
    if CFG.SKILL_MODE == "learn" then
      API.grantSkillPoints(u, CFG.SKILL_POINTS_START)
    end
    SelectUnitAddForPlayer(u, Player(pid))
    PanCameraToTimedForPlayer(Player(pid), x, y, 0.0)
  end
  return u
end

local function hidePicker(pid)
  local slot = S.pick[pid]
  if slot ~= nil and slot.dlg ~= nil then
    DialogDisplay(Player(pid), slot.dlg, false)
  end
end

-- Dung lai popup cho mot nguoi. Goi lai moi khi danh sach doi -- nguoi
-- khac vua lay mat mot con thi con do phai bien khoi popup cua ta.
local function showPicker(pid)
  local d = S.p[pid]
  if d == nil or not d.active then return end
  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    hidePicker(pid)
    return
  end

  local list = available()
  if #list == 0 then
    hidePicker(pid)
    API.msg(pid, CFG.C_RED .. API.t("pick_none") .. CFG.C_END)
    return
  end

  local slot = S.pick[pid]
  if slot == nil then
    slot = { dlg = DialogCreate(), map = {} }
    S.pick[pid] = slot
    TriggerRegisterDialogEvent(S.pickTrigger, slot.dlg)
  end

  -- DialogClear huy cac nut cu, nen bang anh xa phai dung lai tu dau.
  DialogClear(slot.dlg)
  slot.map = {}
  DialogSetMessage(slot.dlg, API.t("pick_title"))
  for i = 1, #list do
    local btn = DialogAddButton(slot.dlg, list[i].name, 0)
    slot.map[btn] = list[i].id
  end

  DialogDisplay(Player(pid), slot.dlg, true)
end

-- ---------- Dieu huong: popup chu hay giao dien card ----------
-- Hai duong cung dung mot logic chon hero ben duoi; chi khac cach ve.

local function pickerShow(pid)
  if CFG.HERO_PICK_MODE == "frame" and API.showHeroFrame ~= nil then
    return API.showHeroFrame(pid)
  end
  return showPicker(pid)
end

local function pickerHide(pid)
  if API.hideHeroFrame ~= nil then API.hideHeroFrame(pid) end
  hidePicker(pid)
end

-- Hien lai cho nhung nguoi chua chon, sau khi danh sach thay doi -- ai
-- do vua lay mat mot con thi con do phai bien khoi man hinh nguoi khac.
local function refreshOthers(exceptPid)
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if pid ~= exceptPid and d ~= nil and d.hero == nil then
      pickerShow(pid)
    end
  end
end

-- Ap dung mot lua chon hero.
--
-- Day la NOI DUY NHAT doi trang thai khi chon hero. Ca popup dialog lan
-- giao dien card deu goi vao day, nen luat "moi nguoi mot con, khong ai
-- lay trung" chi ton tai o mot cho.
--
-- Voi giao dien card, ham nay duoc goi tu su kien DONG BO nen no chay
-- tren moi may. Voi dialog thi su kien von da dong bo san.
local function applyHeroPick(pid, uid)
  local d = S.p[pid]
  if d == nil then return false end

  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    pickerHide(pid)
    return false
  end

  -- Hai nguoi bam cung mot con: nguoi den sau roi vao day.
  if uniqueOn() and S.heroTaken[uid] then
    API.msg(pid, CFG.C_RED .. API.t("pick_taken", heroNameOf(uid)) .. CFG.C_END)
    pickerShow(pid)
    return false
  end

  local u = spawnHero(pid, uid)
  if u == nil then
    API.msg(pid, CFG.C_RED .. API.t("pick_failed") .. CFG.C_END)
    pickerShow(pid)
    return false
  end

  d.hero = u
  d.heroCount = d.heroCount + 1
  -- Pet sinh SAU khi co hero, vi no lay toa do tu hero. Doi hero thi
  -- petSpawn tu bo con cu -- neu khong moi lan doi la them mot con.
  if API.petSpawn ~= nil then API.petSpawn(pid) end
  -- Nhac ngay pho ban nao da mo. Moc dau la Pham Nhan nen it nhat mot
  -- con luon mo san tu giay dau tien -- khong nhac thi nguoi choi khong
  -- co ly do nao de mo the Nhiem Vu Phu.
  if API.sideQuestCheck ~= nil then API.sideQuestCheck(pid) end
  -- Hero MOI thi chua co canh tren nguoi, du canh gioi da cao (doi
  -- hero giua van). check() quet ca bang chu khong so voi bac vua qua.
  if API.wingCheck ~= nil then API.wingCheck(pid) end
  -- Hai dong chu tren bang hero: ten nhan vat + cap/canh gioi.
  -- Dat o day chu khong trong spawnHero(): luc do d.hero chua gan.
  if API.heroNameRefresh ~= nil then API.heroNameRefresh(pid) end
  if uniqueOn() then S.heroTaken[uid] = true end
  pickerHide(pid)

  -- Qua khoi dau, phat SAU KHI CO HERO chu khong luc vao map.
  --
  -- Truoc day Go phat trong initPlayers, tuc truoc khi ai kip chon hero.
  -- Do la sai thu tu: qua la cua HERO, ma luc do hero chua ton tai --
  -- lo do voi vat pham thi khong co tui nao de bo vao.
  --
  -- Chi phat cho lan pick DAU TIEN. Doi hero (heroCount > 1) ma phat
  -- lai la mot duong de nhan qua vo han.
  --
  -- KHONG phat qua o day nua -- CA go LAN vat pham deu doi den cong.
  -- Xem startHeroGate() trong 3_battle/1_house.lua.
  --
  -- Hero hien ra o HeroStartRegion chu khong phai trong nha. De tron bo
  -- qua o cong la cho nguoi choi mot ly do de di doan duong do, thay vi
  -- mot doan duong trong di cho het.
  if d.heroCount == 1 then
    API.msg(pid, CFG.C_JADE .. API.t("gate_hint") .. CFG.C_END)
  end

  API.msg(nil, API.t("pick_done",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. heroNameOf(uid) .. CFG.C_END))

  refreshOthers(pid)
  return true
end

local function onPick()
  local pid  = GetPlayerId(GetTriggerPlayer())
  local slot = S.pick[pid]
  if slot == nil then return end

  local uid = slot.map[GetClickedButton()]
  if uid == nil then return end

  applyHeroPick(pid, uid)
end

local function startPicking()
  S.pickTrigger = CreateTrigger()
  TriggerAddAction(S.pickTrigger, onPick)

  API.after(CFG.PICK_DELAY, function()
    for i = 1, #S.pids do pickerShow(S.pids[i]) end
    API.trace("heropick: da hien bang chon cho " .. #S.pids .. " nguoi (che do " ..
              tostring(CFG.HERO_PICK_MODE) .. ")")
  end)
end


-- ============================================================
--  Chon ky nang theo slot
--
--  Moi slot la mot o trong command card. Nguoi choi chon mot ability
--  trong so ung vien cua slot do, va no duoc gan thang bang
--  UnitAddAbility -- khong ton diem ky nang, khong can Techtree.
--
--  Han che phai biet: nut popup cua Warcraft III chi hien CHU, khong
--  hien icon. Muon co icon thi phai dung nut + goc (Techtree - Hero
--  Abilities), va luc do slot do vi tri nut cua ability quyet dinh chu
--  khong phai nguoi choi chon.
-- ============================================================

-- Cay skill cua hero nguoi choi dang cam, lui ve cay chung neu hero do
-- khong khai bao rieng.
local function slotsFor(pid)
  local d = S.p[pid]
  if d ~= nil and d.hero ~= nil then
    local def = heroDef(GetUnitTypeId(d.hero))
    if def ~= nil and def.skills ~= nil and #def.skills > 0 then
      return def.skills
    end
  end
  return CFG.SKILL_SLOTS
end

local function slotDone(d, i)
  return d.slots ~= nil and d.slots[i] ~= nil
end

local function nextEmptySlot(d, slots)
  for i = 1, #slots do
    if not slotDone(d, i) then return i end
  end
  return nil
end

local function hideSkillPicker(pid)
  local sp = S.skillPick[pid]
  if sp ~= nil and sp.dlg ~= nil then
    DialogDisplay(Player(pid), sp.dlg, false)
  end
end

local function showSkillPicker(pid)
  local d = S.p[pid]
  if d == nil or not d.active then return false end

  if d.hero == nil then
    API.msg(pid, CFG.C_RED .. API.t("skill_nohero") .. CFG.C_END)
    return false
  end
  local slots = slotsFor(pid)
  if #slots == 0 then
    API.msg(pid, CFG.C_RED .. API.t("skill_notree") .. CFG.C_END)
    return false
  end

  local si = nextEmptySlot(d, slots)
  if si == nil then
    hideSkillPicker(pid)
    API.msg(pid, CFG.C_GOLD .. API.t("skill_full", #slots)
      .. CFG.C_END)
    return false
  end

  local slot = slots[si]
  local sp = S.skillPick[pid]
  if sp == nil then
    sp = { dlg = DialogCreate(), map = {}, slot = si }
    S.skillPick[pid] = sp
    TriggerRegisterDialogEvent(S.skillTrigger, sp.dlg)
  end
  sp.slot = si

  DialogClear(sp.dlg)
  sp.map = {}
  DialogSetMessage(sp.dlg, slot.name or ("Slot " .. si))
  for i = 1, #slot.choices do
    local c = slot.choices[i]
    local btn = DialogAddButton(sp.dlg, c.name, 0)
    sp.map[btn] = c.id
  end

  DialogDisplay(Player(pid), sp.dlg, true)
  return true
end

local function onSkillPick()
  local p   = GetTriggerPlayer()
  local pid = GetPlayerId(p)
  local sp  = S.skillPick[pid]
  if sp == nil then return end

  local aid = sp.map[GetClickedButton()]
  if aid == nil then return end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  if not UnitAddAbility(d.hero, aid) then
    API.warn(pid, "Khong gan duoc ability " .. API.idToStr(aid) ..
      " -- id sai, hoac unit khong nhan duoc ability nay.")
    showSkillPicker(pid)
    return
  end

  -- HERO ability gan thang bang UnitAddAbility ra o CAP 0: nut hien
  -- nhung bam khong duoc. Phai nang len cap 1 moi dung duoc.
  -- Ability thuong von da o cap 1, goi them la vo hai.
  SetUnitAbilityLevel(d.hero, aid, 1)

  d.slots[sp.slot] = aid
  hideSkillPicker(pid)
  API.msg(pid, CFG.C_GOLD .. API.t("skill_learned",
    CFG.C_JADE .. (slotsFor(pid)[sp.slot].name or "?") .. CFG.C_GOLD) ..
    CFG.C_END)

  if CFG.SKILL_PICK_CHAIN then showSkillPicker(pid) end
end

local function startSkillPicking()
  S.skillTrigger = CreateTrigger()
  TriggerAddAction(S.skillTrigger, onSkillPick)
end

-- ---------- Nap truoc model hero ----------
--
-- Warcraft nap model cua nhung LOAI unit co mat tren map luc vao game.
-- Loai nao khong xuat hien o dau thi model nap theo yeu cau -- va model
-- tu import nap kieu do thi hong: unit hien ra den si, khong loi nao bao.
--
-- Do duoc: cung mot H001, con dat san trong World Editor thi co mau, con
-- tao bang CreateUnit luc chay thi den.
--
-- Cach chua: tao mot con moi loai luc khoi dong roi xoa ngay. Engine da
-- nap model roi thi lan tao sau khong con phai nap theo yeu cau nua.
local function preloadHeroes()
  local x, y = API.blockCenter(3, 3)
  local n = 0
  for i = 1, #CFG.HEROES do
    local u = CreateUnit(Player(bj_PLAYER_NEUTRAL_EXTRA), CFG.HEROES[i].id,
                         x, y, 270.0)
    if u ~= nil then
      ShowUnit(u, false)
      RemoveUnit(u)
      n = n + 1
    end
  end
  API.trace("heropick: nap truoc model cho " .. n .. "/" .. #CFG.HEROES .. " hero")
end

API.preloadHeroes     = preloadHeroes
API.heroesAvailable   = available
API.heroNameOf        = heroNameOf
API.heroDef           = heroDef
API.heroIndex         = heroIndex
API.applyHeroPick     = applyHeroPick
API.pickerShow        = pickerShow
API.slotsFor          = slotsFor
API.showSkillPicker   = showSkillPicker
API.startSkillPicking = startSkillPicking

local function report()
  API.info(nil, CFG.C_GOLD .. "=== Chon hero ===" .. CFG.C_END)
  API.info(nil, #CFG.HEROES .. " hero  |  moi nguoi toi da " ..
    CFG.HERO_MAX_PER_PLAYER .. "  |  " ..
    (uniqueOn() and "khong trung nhau" or "duoc trung nhau"))
  API.info(nil, "Popup hien sau " .. CFG.PICK_DELAY .. "s, hero sinh cach nha chinh " ..
    API.num(CFG.HERO_SPAWN_OFFSET))
end

API.showPicker    = showPicker
API.startPicking  = startPicking
API.heroFanPoint   = fanPoint
API.heroPickReport = report
end
--#endregion 2_player/2_heropick.lua

--#region 2_player/3_cultivation.lua
do
-- ============================================================
--  3_cultivation.lua  --  Tu Vi (bac tu luyen cua nguoi choi)
--
--  Ten cu la "Linh Can". Doi vi sai nghia: "Linh Can" la TU CHAT bam
--  sinh, thu khong doi duoc; he nay thi nguoc lai, no len tung nac
--  theo canh gioi. Nhan doi truoc (T.panel_cult), dinh danh doi sau
--  (cultRank / CFG.CULT_*) nen gio khong con cho nao lech nhau.
--
--  Nguon suc manh CHINH: EHP quai bam theo chinh he so cua no
--  (docs/03-du-lieu/duong-cong-suc-manh.md). 20 bac, dung chung thang
--  ten voi 20 canh gioi cua phe dich.
--
--  File nay KHONG ve bang. No dang ky mot the vao bang nhan vat
--  (1_panel.lua) va chi lo phan noi dung. Nho vay bon he dung chung
--  mot khung, khong the lech nhau ve giao dien.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- The nay dung kieu "focus" cua bang: MOT the lon, MOT hanh dong.
--
-- Truoc day no la mot cai thang 7 dong. Nhung trong 7 dong do chi co
-- DUNG MOT dong bam duoc -- bac ke tiep. Sau dong con lai la thong tin
-- tham khao chen cho dung mot viec lam duoc, va nguoi choi phai do mat
-- tim xem dong nao moi la dong cua minh.
--
-- Bang 20 bac van con, nhung no thuoc ve tai lieu
-- (docs/03-du-lieu/canh-gioi.md) chu khong phai giao dien.

-- ---------- Toan ----------

local function maxRank() return #CFG.REALMS end

local function rankName(r)
  return API.pick(CFG.REALMS[r])
end

-- CONG THEM, khong nhan. Moi lan dot pha cong mot cuc chi so, va cuc do
-- gap doi moi bac: +50, +100, +200, ...
--
-- Ban truoc nhan ca chi so len CULT_STEP^(r-1) roi giai nguoc de bu
-- phan sat thuong nen. Bo vi mot ly do giao dien chu khong phai toan:
-- nguoi choi khong doc duoc "x1.17", ho doc duoc "+50 chi so". Con so
-- cong them la thu nhin thay ngay tren bang hero sau khi bam.
--
-- statBonusAt(r) = tong cong don sau (r-1) lan dot pha
--                = GAIN x (STEP^(r-1) - 1) / (STEP - 1)
local function statBonusAt(r)
  local g, s = CFG.CULT_STAT_GAIN, CFG.CULT_STAT_STEP
  if r <= 1 then return 0.0 end
  if s == 1.0 then return g * (r - 1) end     -- tranh chia cho 0
  return g * (s ^ (r - 1) - 1) / (s - 1)
end

local function statAt(r)
  return CFG.CULT_STAT_BASE + statBonusAt(r)
end

-- He so suc manh HIEN RA cho nguoi choi. Suy TU chi so chu khong phai
-- mot duong cong rieng: sat thuong = factor x (DMG_BASE + chi so), nen
-- day dung la ti le sat thuong giua bac r va bac 1. Ban truoc no la mot
-- hang so rieng (CULT_STEP) va co the noi khac voi chi so that.
local function powerAt(r)
  local b = CFG.CULT_DMG_BASE
  return (b + statAt(r)) / (b + statAt(1))
end

-- He so suy ra thanh chu. "x2.85" doc duoc, nhung bac 20 la
-- x970,903 -- in no bang %.2f ra "x970903.00", dai va thua hai chu so
-- le khong ai can.
local function powerText(r)
  local p = powerAt(r)
  if p < 1000.0 then return string.format("x%.2f", p) end
  return "x" .. API.num(math.floor(p + 0.5))
end

-- PHANG: CFG.CULT_COST_STEP = 1.0 nen moi bac deu 500. Van giu cong
-- thuc mu de doi lai duong cong chi bang mot so.
local function costOf(r)
  return math.floor(CFG.CULT_COST_BASE * CFG.CULT_COST_STEP ^ (r - 1) + 0.5)
end

-- Linh Can KHONG tu ghi chi so nua. No chi tra loi mot cau: "tu vi cong
-- them bao nhieu diem so voi bac 1?"
--
-- API.heroRecompute trong 7_effect.lua la cho DUY NHAT ghi chi so hero
-- -- no cong nen + so nay, roi nhan % cua bi dong, roi ghi mot lan. Truoc
-- day moi he tu cong vao, va hai he cung ghi mot thuoc tinh thi lech.
--
-- CFG.CULT_STAT_MODE quyet dinh cong vao chi so nao; phan do do
-- recompute lo.
local function statBonus(pid)
  local d = S.p[pid]
  if d == nil then return 0 end
  return math.floor(statBonusAt(d.cultRank) + 0.5)
end

-- ---------- Noi dung the ----------
--
-- Cai nguoi choi can biet la TRUOC -> SAU va GIA. Khong phai ca bang.
-- Duong dan anh cua mot canh gioi. Chua ve toi thi dung anh CAO NHAT
-- da co -- cung cach iconFor() cua 5_gear.lua, va cung ly do: thieu anh
-- thi ra o trong, ma o trong nhin nhu giao dien hong.
local function realmIcon(r)
  if CFG.REALM_ICON_PATH == nil or r == nil then return nil end
  local mx = CFG.REALM_ICON_MAX or 0
  if r > mx then r = mx end
  if r < 1 then return nil end
  return string.format(CFG.REALM_ICON_PATH, r)
end


local function tabInfo(pid)
  local d = S.p[pid]
  if d == nil then return {} end

  local cur = d.cultRank
  local top = maxRank()
  local out = {
    title  = API.t("cult_rank", cur, top),
    sub    = rankName(cur),
    progress = cur / top,
  }

  if cur >= top then
    out.row = {
      { API.t("cult_power"), powerText(cur), "" },
      { API.t("cult_stat"),
        "+" .. API.num(statAt(cur) - CFG.CULT_STAT_BASE), "" },
    }
    out.note = API.t("cult_peak")
    -- Het thang: mot buc, khong mui ten -- khong con "sau" de tro toi.
    out.art = { { icon = realmIcon(cur), name = rankName(cur) } }
    -- Da o bac cao nhat: van ve mot nut, khoa. Khong co nut thi the
    -- Tu Vi bong dung trong rong o cuoi van, trong nhu bang hong.
    out.btn    = API.t("cult_btn_peak")
    out.btnOn  = false
    out.btnWhy = "locked" 
    return out
  end

  local price = costOf(cur)
  out.row = {
    { API.t("cult_power"),
      powerText(cur), powerText(cur + 1) },
    { API.t("cult_stat"),
      "+" .. API.num(statAt(cur)     - CFG.CULT_STAT_BASE),
      "+" .. API.num(statAt(cur + 1) - CFG.CULT_STAT_BASE) },
    { API.t("col_realm"), rankName(cur), rankName(cur + 1) },
  }
  -- Cung nhip voi ba dong tren: trai la DANG O, phai la SAU KHI DOT PHA.
  -- Buc phai mo di (dim) vi no chua thuoc ve nguoi choi.
  out.art = {
    { icon = realmIcon(cur),     name = rankName(cur) },
    { icon = realmIcon(cur + 1), name = rankName(cur + 1), dim = true },
  }

  out.btn    = API.t("cult_next", rankName(cur + 1)) .. "     " ..
               API.num(price) .. " " .. API.t("cur_qi")
  out.btnOn = (API.getQi(pid) >= price)
  if not out.btnOn then
    out.btn = out.btn .. API.t("gear_btn_have", API.num(API.getQi(pid)))
  end
  out.note = API.t("cult_have", API.num(API.getQi(pid)))
  return out
end

-- ---------- Dot pha ----------
-- setRank/breakthrough chay tren MOI may, tu su kien dong bo.

local function setRank(pid, newR, dev)
  local d = S.p[pid]
  if d == nil then return end
  if newR < 1 then newR = 1 end
  if newR > maxRank() then newR = maxRank() end

  local old = d.cultRank
  if newR == old then return end

  d.cultRank = newR
  API.heroRecompute(pid)
  API.panelRefresh(pid)
  -- Bang hero hien canh gioi o dong hai. setRank la cho DUY NHAT bac
  -- doi, nen goi o day la du cho moi duong (dot pha, lenh dev).
  if API.heroNameRefresh ~= nil then API.heroNameRefresh(pid) end

  if dev then
    API.info(pid, CFG.C_GREY .. "[dev] Linh Can -> " .. rankName(newR) ..
      " (bac " .. newR .. ", " .. powerText(newR) .. ")" .. CFG.C_END)
  end
end

local function breakthrough(pid)
  local d = S.p[pid]
  if d == nil then return end

  local r = d.cultRank
  if r >= maxRank() then
    API.msg(pid, CFG.C_GREY .. API.t("cult_peak") .. CFG.C_END)
    return
  end

  local c = costOf(r)
  if not API.spendQi(pid, c) then
    API.msg(pid, CFG.C_RED .. API.t("no_qi") .. CFG.C_END ..
      API.t("need_have", API.num(c), API.num(API.getQi(pid))))
    API.panelRefresh(pid)
    return
  end

  setRank(pid, r + 1, false)
  API.msg(nil, API.t("cult_broke",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. rankName(r + 1) .. CFG.C_END) ..
    " (" .. powerText(r + 1) .. ")")

  if d.hero ~= nil then
    API.fx([[Abilities\Spells\Human\Resurrect\ResurrectTarget.mdl]],
           GetUnitX(d.hero), GetUnitY(d.hero))
  end

  -- Canh gioi vua tang -- co the vua mo mot pho ban. Kiem o day chu
  -- khong bat nguoi choi tu nho moc nao la moc nao.
  if API.sideQuestCheck ~= nil then API.sideQuestCheck(pid) end
  -- Canh gioi vua tang -- co the vua cham mot moc canh.
  if API.wingCheck ~= nil then API.wingCheck(pid) end
end

-- Nut "Dot pha" tren bang: KHONG doi trang thai o day. Su kien bam frame
-- chi no tren may nguoi bam, nen chi gui mot tin -- 02b_sync lo phan con
-- lai. breakthrough() ben duoi chay tren MOI may, cung mot nhip.
local function tabAction(pid)
  API.syncSend(pid, CFG.OP_CULT_UP, 0)
end

-- "-lc" mo the Linh Can | "-lc up" dot pha | "-lc <so>" nhay bac (dev)
--
-- Lenh chat KHONG can di qua 02b_sync: su kien chat von da no tren moi
-- may cung luc. Goi thang la dung, va do la ly do lenh chat luon chay
-- duoc ke ca khi khong con duong dong bo nao.
local function onChat(pid, raw)
  if raw ~= nil and raw:match("^%s*%-lc%s+up") then
    breakthrough(pid)
    return
  end

  if raw ~= nil then
    local n = tonumber(raw:match("^%s*%-lc%s+(%d+)"))
    if n ~= nil then
      if not CFG.DEV_COMMANDS then
        API.warn(pid, "Lenh dev dang tat (CFG.DEV_COMMANDS).")
        return
      end
      setRank(pid, n, true)
      return
    end
  end

  API.panelOpenTab(pid, S.cultTabIndex or 1)
end

local function startCult()
  S.cultTabIndex = API.panelAddTab({
    name    = API.t("panel_cult"),
    kind   = "focus",
    info   = tabInfo,
    action = tabAction,
  })

  API.syncOn(CFG.OP_CULT_UP,  function(pid) breakthrough(pid) end)
  API.syncOn(CFG.OP_CULT_SET, function(pid, arg) setRank(pid, arg, true) end)

  API.trace("cult: the so " .. S.cultTabIndex .. ", dong bo=" .. API.syncMode())
end

-- Goi khi hero vua duoc tao. Khong con lam gi rieng: recompute doc
-- statBonus roi tu ap. Giu ten de cho goi cu khong gay.
local function applyToHero(pid, hero)
  API.heroRecompute(pid)
end

API.cultRank   = function(pid) return S.p[pid] and S.p[pid].cultRank or 1 end
API.cultPower  = function(pid) return powerAt(API.cultRank(pid)) end
API.cultCost   = costOf
API.cultStatAt = statAt
API.cultStatBonus = statBonus
API.cultChat   = onChat
API.cultApply  = applyToHero
API.startCult  = startCult
end
--#endregion 2_player/3_cultivation.lua

--#region 2_player/4_skill.lua
do
-- ============================================================
--  4_skill.lua  --  Bay ky nang: bac, gia nang, suc manh moi bac
--
--  MOI so lieu ky nang o day, khong o Object Editor. war3map.w3a chi
--  giu VO: ten, icon, o nut, so bac. Nho vay chinh can bang khong phai
--  build lai file nhi phan nao -- va so lieu voi tooltip ra tu cung mot
--  bang nen khong the lech nhau.
--
--  HAI QUY TAC, ca hai deu tu do ma ra:
--
--  1. Sat thuong an theo CHI SO CAO NHAT cua hero, khong phai so co dinh.
--     Linh Can cong +1075 moi chi so o bac 20; skill gay so co dinh thi
--     cuoi game thanh vo nghia.
--
--  2. Ky nang bi dong tinh theo PHAN TRAM. Cung ly do: cong thang +20
--     chi so nghe to luc dau (+100%) nhung chi con +5% o Linh Can bac 20.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function listOf(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return {} end
  return CFG.SKILLS[GetUnitTypeId(d.hero)] or {}
end

-- ---------- So bac THAT cua ability ----------
--
-- Object Editor moi la nguoi quyet dinh mot ability co bao nhieu bac.
-- Ability hero mac dinh 3 bac, ability unit thuong 1 bac. Goi
-- SetUnitAbilityLevel(u, aid, 10) len mot ability 3 bac thi no KEP
-- xuong 3 va KHONG bao loi gi.
--
-- Da can mot lan: nang skill len bac 10, tra du tien, bang bao 10/10,
-- ma trong game chi len bac 3. Nen gio do that roi moi cho nang.
local function probeMax(u, aid)
  local cur = GetUnitAbilityLevel(u, aid)
  if cur == 0 then return 0 end
  SetUnitAbilityLevel(u, aid, CFG.SKILL_MAX_LEVEL)
  local hi = GetUnitAbilityLevel(u, aid)
  SetUnitAbilityLevel(u, aid, cur)
  return hi
end

-- Tran that: nho hon giua "thiet ke muon" va "Object Editor cho".
local function maxOf(aid)
  local m = S.skillMax[aid]
  if m == nil or m <= 0 then return CFG.SKILL_MAX_LEVEL end
  if m < CFG.SKILL_MAX_LEVEL then return m end
  return CFG.SKILL_MAX_LEVEL
end

-- Bac 0 = CHUA MO KHOA. Bac 1..10 = da co.
local function levelOf(pid, aid, index)
  local d = S.p[pid]
  if d ~= nil and d.skill ~= nil and d.skill[aid] ~= nil then
    return d.skill[aid]
  end
  -- Chua mua gi: nhung cai dau tien co san, con lai khoa.
  if index ~= nil and index <= CFG.SKILL_START_COUNT then return 1 end
  return 0
end

-- Gia mo khoa theo SO CAI DA MO, khong theo cai nao. Thich mo cai nao
-- truoc thi mo -- ep thu tu la lay mat mot lua chon ma chang duoc gi.
-- Gia tinh bang NGO TINH, va la MOT diem cho moi lan.
--
-- Ky nang bi chan boi "da giet du tinh anh chua", khong phai "da gom du
-- tien chua" -- ma tien thi Linh Can va Trang Bi da tranh nhau roi.
-- Xem docs/02-he-thong/kinh-te.md
--
-- Gia phang nen khong con ham unlockCost: mo khoa cai thu nhat hay cai
-- thu bay deu 1 diem. Nguoi choi khong phai tinh toan gi, chi phai chon
-- THU TU -- mo cai nao truoc, don bac cai nao.
local function costOf(pid, level, aid)
  if level <= 0 then return CFG.SKILL_LUMBER_UNLOCK end
  if level >= (aid and maxOf(aid) or CFG.SKILL_MAX_LEVEL) then return nil end
  return CFG.SKILL_LUMBER_UP
end

-- ---------- Suc manh theo bac ----------
-- Ngan sach ca he nang cap la x2, va x2 do la TICH cua moi nut chinh.
-- Chu dong: he so x1.33 va hoi chieu x0.667 (tan suat x1.5) = x2.
-- Bi dong khong co hoi chieu nen an tron x2.

local function factorAt(sk, level)
  return (sk.factor or 0) * CFG.SKILL_DMG_STEP ^ (level - 1)
end

local function cdAt(sk, level)
  return (sk.cd or 0) * CFG.SKILL_CD_STEP ^ (level - 1)
end

local function pctAt(sk, level)
  return (sk.pct or 0) * CFG.SKILL_PASSIVE_STEP ^ (level - 1)
end

-- Giap PHANG cua aura. Dung buoc bi dong nhu pct: 3.0 -> 6.0 sau 9 lan.
--
-- Rieng mot ham chu khong dung pctAt vi day la GIAP, khong phai phan
-- tram. Warcraft dung giap phang; "+15% giap" tren hero co 3 giap la
-- +0.45 -- gan nhu bang khong.
local function armorAt(sk, level)
  return (sk.armor or 0) * CFG.SKILL_PASSIVE_STEP ^ (level - 1)
end

-- Chi so PHANG cua bi dong "stat" (Luyen The). Bam theo CA hai truc:
-- bac ky nang va bac Tu Vi. Xem chu thich o CFG.SKILLS A004.
local function statAt(sk, level, rank)
  if sk == nil or sk.statVal == nil then return 0.0 end
  return sk.statVal * CFG.SKILL_PASSIVE_STEP ^ (level - 1)
                  * CFG.CULT_STAT_STEP ^ ((rank or 1) - 1)
end

local function manaAt(sk, level)
  if sk.mana == nil or sk.mana <= 0 then return 0 end
  return math.floor(sk.mana * CFG.SKILL_MANA_STEP ^ (level - 1) + 0.5)
end

-- Chi so cao nhat cua hero. Dung CHUNG cho moi skill, nen doi hero hay
-- doi trang bi deu khong lam skill nao bi bo lai.
local function topStat(u)
  if u == nil then return 0 end
  local s, a, i = GetHeroStr(u, true), GetHeroAgi(u, true), GetHeroInt(u, true)
  if s >= a and s >= i then return s, "str" end
  if a >= i then return a, "agi" end
  return i, "int"
end

-- Sat thuong/hoi mau cua mot skill. Day la ham ma cac skill se goi khi
-- co hieu ung that.
-- Sat thuong PHEP, va luong HOI MAU cua ky nang.
--
-- %Kiem nhan O DAY chu khong o cho khac: ca fxLine lan fxHeal deu di qua
-- ham nay, nen mot cho la du cho "phep + hoi mau". Don THUONG thi khong
-- di qua day -- no duoc nhan trong onDamaged.
--
-- Hai cho KHONG chong nhau: sat thuong ky nang ban ra bang hit(), ma
-- hit() bat co 'busy' nen onDamaged return ngay dong dau.
local function skillDamage(u, factor)
  local base = factor * (CFG.CULT_DMG_BASE + topStat(u))
  local pid  = (API.heroPidOf ~= nil) and API.heroPidOf(u) or nil
  if pid ~= nil and API.gearDmgPct ~= nil then
    base = base * (1.0 + API.gearDmgPct(pid))
  end
  return base
end

-- ---------- Nang bac ----------
-- Chay tren MOI may, tu kenh dong bo.

local function applyLevel(pid, sk, level)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if GetUnitAbilityLevel(d.hero, sk.id) <= 0 then return end

  SetUnitAbilityLevel(d.hero, sk.id, level)

  -- Mana va hoi chieu dat TU LUA, de o Object Editor thi chinh can bang
  -- phai mo World Editor. Ca hai native nay deu co tren 1.31.1 (-nat).
  -- Dat cho MOI bac, khong chi bac hien tai: unit nho bac nao thi doc
  -- bac do, va ta khong biet no se nhay len bac nao truoc khi ta kip
  -- goi lai.
  local ceil = maxOf(sk.id)

  -- TAT hieu ung GOC. Xem CFG.SKILL_ZERO_BASE.
  --
  -- Dat cho MOI bac, cung ly do voi mana/hoi chieu ben duoi. Hang so nao
  -- khong co trong ban nay thi GHI VET chu khong lang le bo qua -- mot
  -- cai ten go sai tra ve nil va khong lam gi ca (ADR 0012).
  local ab = (BlzGetUnitAbility ~= nil) and BlzGetUnitAbility(d.hero, sk.id) or nil

  local function zeroField(fields, setter)
    local zero = fields and fields[sk.id] or nil
    if zero == nil or ab == nil or setter == nil then return end
    for k = 1, #zero do
      local F = _G[zero[k]]
      if F == nil then
        API.trace("skill: KHONG co hang so " .. zero[k] ..
                  " -- hieu ung goc VAN CHAY")
      else
        for lv = 1, ceil do setter(ab, F, lv - 1, 0) end
      end
    end
  end

  zeroField(CFG.SKILL_ZERO_BASE,     BlzSetAbilityRealLevelField)
  zeroField(CFG.SKILL_ZERO_BASE_INT, BlzSetAbilityIntegerLevelField)

  -- GHI so can bang vao truong goc, de Warcraft tu cong. Xem
  -- CFG.SKILL_CARRY_BASE -- day la duong thay cho BlzSetUnitArmor, thu da
  -- dong bang phan chi so vao giap.
  local carry = CFG.SKILL_CARRY_BASE and CFG.SKILL_CARRY_BASE[sk.id] or nil
  if carry ~= nil and ab ~= nil and BlzSetAbilityRealLevelField ~= nil then
    local F = _G[carry.field]
    if F == nil then
      API.trace("skill: KHONG co hang so " .. carry.field ..
                " -- " .. API.idToStr(sk.id) .. " khong cong duoc giap")
    else
      for lv = 1, ceil do
        local v = 0.0
        if carry.source == "armor" then
          v = armorAt(sk, lv)
        elseif carry.source == "buffarmor" then
          v = CFG.FX_BUFF_ARMOR * (1 + 0.1 * (lv - 1))
        end
        BlzSetAbilityRealLevelField(ab, F, lv - 1, v)
      end
    end
  end

  for lv = 1, ceil do
    if BlzSetUnitAbilityManaCost ~= nil and sk.mana ~= nil then
      BlzSetUnitAbilityManaCost(d.hero, sk.id, lv - 1, manaAt(sk, lv))
    end
    if BlzSetUnitAbilityCooldown ~= nil and sk.cd ~= nil and sk.cd > 0 then
      BlzSetUnitAbilityCooldown(d.hero, sk.id, lv - 1, cdAt(sk, lv))
    end
  end
end

local function upgrade(pid, index)
  local list = listOf(pid)
  local sk = list[index]
  if sk == nil then return end

  local d = S.p[pid]
  if d.skill == nil then d.skill = {} end

  local cur = levelOf(pid, sk.id, index)
  local ceil = maxOf(sk.id)
  local price = costOf(pid, cur, sk.id)
  if price == nil then
    if ceil < CFG.SKILL_MAX_LEVEL then
      -- Khong tru tien. Bao dung cho phai sua, dung de nguoi choi doan.
      API.msg(pid, CFG.C_RED ..
        API.t("skill_oemissing", API.pick(sk), ceil) .. CFG.C_END ..
        API.t("skill_oefix", CFG.SKILL_MAX_LEVEL, CFG.SKILL_MAX_LEVEL,
              API.idToStr(sk.id)))
    else
      API.msg(pid, CFG.C_GREY .. API.t("skill_atmax", API.pick(sk)) .. CFG.C_END)
    end
    return
  end
  if not API.spendLumber(pid, price) then
    API.msg(pid, CFG.C_RED .. API.t("no_lumber") .. CFG.C_END ..
      API.t("need_have", API.num(price), API.num(API.getLumber(pid))) ..
      CFG.C_GREY .. " " .. API.t("lumber_note") .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  d.skill[sk.id] = cur + 1

  -- Tu bac 0 len 1 la MO KHOA: phai gan ability vao unit truoc da.
  if cur == 0 then
    if UnitAddAbility(d.hero, sk.id) then
      SetUnitAbilityLevel(d.hero, sk.id, 1)
      S.skillMax[sk.id] = probeMax(d.hero, sk.id)
      SetUnitAbilityLevel(d.hero, sk.id, 1)
      -- PHAI goi applyLevel o day nua. Truoc day nhanh mo khoa return
      -- thang, nen mana va hoi chieu cua ability giu nguyen so cua
      -- Object Editor -- Chuong la ban sao cua Shockwave nen no doi 100
      -- mana trong khi bang ghi 25, va hero chi co 75 mana. Bang noi mot
      -- dang, game lam mot neo.
      applyLevel(pid, sk, 1)
      API.skillFxRecompute(pid)   -- vua mo khoa mot bi dong
    else
      API.info(pid, CFG.C_RED .. "Khong gan duoc " .. API.idToStr(sk.id) ..
        CFG.C_END)
    end
    API.say(pid, API.t("skill_unlocked",
      CFG.C_JADE .. API.pick(sk) .. CFG.C_END))
    API.panelRefresh(pid)
    return
  end

  applyLevel(pid, sk, cur + 1)
  API.skillFxRecompute(pid)   -- bi dong "stat"/"aura" tinh lai theo bac moi

  -- Doc lai bac THAT tren unit. Neu no khong bang bac vua mua thi bang
  -- dang noi doi, va tha nguoi choi biet ngay con hon phat hien sau
  -- muoi lan nang nua.
  local real = (d.hero ~= nil) and GetUnitAbilityLevel(d.hero, sk.id) or (cur + 1)
  if real ~= cur + 1 then
    API.msg(pid, CFG.C_RED ..
      API.t("skill_warn", API.pick(sk), real, cur + 1) .. CFG.C_END)
  end
  -- Tin CHUNG: ca ban do thay ai dang len tay. Cung ly do voi
  -- skill_unlocked o nhanh tren.
  API.say(pid, API.t("skill_up", CFG.C_JADE .. API.pick(sk) .. CFG.C_END,
                     cur + 1, ceil))
  API.panelRefresh(pid)
end

-- ---------- The "Ky Nang" trong bang phim E ----------

-- DOC so tu chinh ability, khong tu tinh.
--
-- Hai ky nang (A003 Endurance Aura, A006 Hoi Sinh) co bang so nam tron
-- trong war3map.w3a do World Editor dat. Tu tinh lai o day la co HAI
-- noi cung khai mot con so, va hai noi thi som muon lech -- nguoi choi
-- doc mot dang, danh ra mot dang.
--
-- Hang so co the vang mat o ban nay: TRACE roi lui ve hien bac, khong
-- nuot. Do ten that bang lenh "-nat oae".
local function fromAbility(pid, sk, level)
  if sk.fromCooldown then
    if BlzGetAbilityCooldown == nil then
      API.trace("skill: khong co BlzGetAbilityCooldown -- " ..
                API.idToStr(sk.id) .. " hien bac thay vi hoi chieu")
      return nil
    end
    return string.format("%.0fs", BlzGetAbilityCooldown(sk.id, level - 1))
  end

  if sk.fromAbil == nil then return nil end
  -- BlzGetAbilityRealLevelField nhan HANDLE ability, ma handle chi lay
  -- duoc tu mot unit dang mang no. Chua co hero thi chiu.
  local h = (S.p[pid] or {}).hero
  if h == nil or BlzGetUnitAbility == nil
     or BlzGetAbilityRealLevelField == nil then
    return nil
  end
  local F = _G[sk.fromAbil]

  -- DUONG VONG khi hang so vang mat.
  --
  -- Do duoc o 1.31.1 (dong "-nat" trong file vet): THIEU ca
  -- ABILITY_RLF_ATTACK_SPEED_INCREASE_OAE1 lan
  -- ABILITY_RLF_MOVEMENT_SPEED_INCREASE_OAE2 -- tuc bang ky nang cua
  -- A003 chi hien duoc "bac N". Rieng BlzGetAbilityRealLevelField thi
  -- CO, no chi thieu cai handle truong de dua vao.
  --
  -- ConvertAbilityRealLevelField dung ma truong 4 ky tu, nen dung duoc
  -- ma khong can hang so co ten. Co ban co ham nay, co ban khong --
  -- tra truoc khi goi, va van lui ve "bac N" neu khong co.
  if F == nil and sk.fromField ~= nil then
    local conv = _G["ConvertAbilityRealLevelField"]
    if conv ~= nil then F = conv(FourCC(sk.fromField)) end
  end

  if F == nil then
    API.trace("skill: khong co hang so " .. tostring(sk.fromAbil) ..
              " (va khong chuyen duoc tu ma truong " ..
              tostring(sk.fromField) .. ") -- " .. API.idToStr(sk.id) ..
              " hien bac thay vi so that")
    return nil
  end
  local ab = BlzGetUnitAbility(h, sk.id)
  if ab == nil then return nil end
  local v = BlzGetAbilityRealLevelField(ab, F, level - 1)
  if v == nil then return nil end
  return sk.fromPct and string.format("%.0f%%", v * 100.0)
                     or string.format("%.2f", v)
end

local function fmt(pid, sk, level, rank)
  -- 'noNumber': ky nang KHONG CO con so nao de hien, va do la co y.
  --
  -- Moon Glaive (A012) la vi du: ca co che nay do Warcraft lo, Lua
  -- khong tinh gi ca. Neu khong co nhanh nay thi no roi xuong nhanh
  -- cuoi va hien "0%" -- mot con so BIA, te hon la khong co so.
  --
  -- Khong dung cach "khai mot pct chi de hien": nhu the la hai noi cung
  -- khai mot con so, va mot ngay se chi sua mot noi.
  if sk.noNumber then return API.t("skill_always") end

  local fromA = fromAbility(pid, sk, level)
  if fromA ~= nil then return fromA end
  -- Doc khong ra thi noi RO la bac may, chu khong bia mot con so.
  if sk.fromAbil ~= nil or sk.fromCooldown then
    return API.t("skill_rank_n", level)
  end
  if sk.statVal ~= nil then
    return "+" .. API.num(math.floor(statAt(sk, level, rank) + 0.5))
  end
  if sk.armor ~= nil then
    return "+" .. string.format("%.0f", armorAt(sk, level))
  end
  if sk.kind == "aura" or sk.kind == "passive" then
    return string.format("%.0f%%", pctAt(sk, level) * 100)
  end
  return "x" .. string.format("%.2f", factorAt(sk, level))
end

-- Icon lay THANG tu ability, khong go duong dan trong bang. Go tay thi
-- sai mot chu la hien o xanh la, ma khong ai biet sai o dau.
local function iconOf(sk)
  if sk.icon ~= nil then return sk.icon end
  if BlzGetAbilityIcon == nil then return nil end
  local p = BlzGetAbilityIcon(sk.id)
  if p == nil or p == "" then return nil end
  return p
end

-- Mot dong mo ta: hieu luc, roi hoi chieu / mana neu co.
local function subOf(pid, sk, lv)
  local s = fmt(pid, sk, lv, API.cultRank and API.cultRank(pid) or 1)
  if sk.factor ~= nil and sk.factor > 0 then
    -- Ghi ro dang an theo chi so nao. Cong thuc lay chi so CAO NHAT, ma
    -- nguoi choi khong co cach nao biet do la cai nao neu khong noi.
    local _, name = topStat(S.p[pid] and S.p[pid].hero)
    s = s .. " (" .. API.t("stat_" .. name) .. ")"
  end
  if sk.cd ~= nil and sk.cd > 0 then
    s = s .. "   " .. string.format("%.1fs", cdAt(sk, lv))
    if manaAt(sk, lv) > 0 then s = s .. " / " .. manaAt(sk, lv) .. " mana" end
  end
  return s
end

local function tabItems(pid)
  local list = listOf(pid)
  if #list == 0 then return {} end

  local lumber = API.getLumber(pid)
  local out = {}
  for i = 1, #list do
    local sk   = list[i]
    local lv   = levelOf(pid, sk.id, i)
    local ceil = maxOf(sk.id)
    local price  = costOf(pid, lv, sk.id)

    local it = { icon = iconOf(sk), name = API.pick(sk) }

    if lv <= 0 then
      -- Ky nang chua mo: KHONG hien so lieu cua no. Lo het thi chang
      -- con gi de mong khi bo tien ra mo.
      it.name       = CFG.C_GREY .. API.pick(sk) .. CFG.C_END
      it.status = CFG.C_GREY .. API.t("skill_locked") .. CFG.C_END
      it.desc      = ""
      if price ~= nil then
        it.btn    = API.t("btn_unlock") .. "  " .. price .. " " .. API.t("cur_lumber")
        it.btnOn = (lumber >= price)
        if not it.btnOn then
          it.btn = it.btn .. API.t("gear_btn_have", API.num(lumber))
        end
      end
    else
      -- Hien TRAN THAT, khong hien tran thiet ke. Bang bao 10/10 trong
      -- khi unit chi len duoc bac 3 la bang noi doi.
      local rank = lv .. "/" .. ceil
      if ceil < CFG.SKILL_MAX_LEVEL then
        rank = CFG.C_RED .. rank .. " !" .. CFG.C_END
      else
        rank = CFG.C_JADE .. rank .. CFG.C_END
      end
      it.status = rank
      it.desc      = subOf(pid, sk, lv)
      if price ~= nil then
        it.btn    = API.t("btn_up") .. "  " .. price .. " " .. API.t("cur_lumber")
        it.btnOn = (lumber >= price)
        if not it.btnOn then
          it.btn = it.btn .. API.t("gear_btn_have", API.num(lumber))
        end
      else
        it.status = CFG.C_GREY .. API.t("st_max") .. CFG.C_END
      end
    end
    out[i] = it
  end

  -- Mot dong su that o cuoi: con so mau ngoc o tren la THIET KE, chua
  -- phai thu dang chay. Chung chi thanh that khi bo sinh ghi so vao
  -- war3map.w3a va cac skill bi dong duoc viet bang Lua.
  --
  -- Giu lai sau khi doi bo cuc: bang ma hien so dep nhung sai thi te
  -- hon la khong hien gi.
  if not CFG.SKILL_DATA_LIVE then
    out[#out + 1] = {
      name  = CFG.C_RED .. API.t("skill_notlive") .. CFG.C_END,
      desc = API.t("skill_notlive2"),
    }
  end
  return out
end

local function tabItemAction(pid, i)
  if listOf(pid)[i] == nil then return end
  API.syncSend(pid, CFG.OP_SKILL_UP, i)
end

local function startSkills()
  API.panelAddTab({
    name        = API.t("panel_skill"),
    kind       = "list",
    -- Dong canh bao SKILL_DATA_LIVE chi hien khi co la false, nen chi
    -- dat cho no khi do. Mot hang thua = 0.048 chieu cao khung, ma
    -- chieu cao dang tranh nhau voi thanh giao dien duoi.
    rows      = 7 + (CFG.SKILL_DATA_LIVE and 0 or 1),
    items      = tabItems,
    itemAction = tabItemAction,
    empty      = API.t("skill_none"),
  })
  API.syncOn(CFG.OP_SKILL_UP, upgrade)
  API.trace("skill: the Ky Nang san sang (Go)")
end

-- Goi khi hero vua duoc tao: dat lai bac cho dung voi bang da mua.
local function applyToHero(pid)
  local d = S.p[pid]
  local list = listOf(pid)
  local missing = {}

  local have = 0
  for i = 1, #list do
    local sk = list[i]
    local lv = levelOf(pid, sk.id, i)

    -- Chi do va dat bac cho ky nang DA MO KHOA. Ky nang con khoa chua
    -- nam tren unit, do no chi tra ve 0 va lam ban bao cao.
    if lv > 0 and d ~= nil and d.hero ~= nil then
      have = have + 1
      local m = probeMax(d.hero, sk.id)
      S.skillMax[sk.id] = m
      if m > 0 and m < CFG.SKILL_MAX_LEVEL then
        missing[#missing + 1] = API.idToStr(sk.id) .. "=" .. m
      end
      applyLevel(pid, sk, lv)
    end
  end

  if #missing > 0 then
    API.trace("skill: OE thieu bac -- " .. table.concat(missing, " "))
    API.warn(pid, #missing .. "/" .. have ..
      " ky nang chua du " .. CFG.SKILL_MAX_LEVEL .. " bac trong Object Editor" ..
      CFG.C_END .. CFG.C_GREY .. " (" .. table.concat(missing, " ") ..
      "). Dat Stats - Levels = " .. CFG.SKILL_MAX_LEVEL .. ".")
  end
end

API.skillList    = listOf
API.skillLevel   = levelOf
API.skillCost    = costOf
API.skillDamage  = skillDamage
API.skillFactor    = factorAt
API.skillCd      = cdAt
API.skillPct     = pctAt
API.skillStat   = statAt
API.skillArmor    = armorAt
API.skillMana    = manaAt
API.skillTopStat = topStat
API.skillApply   = applyToHero
API.startSkills  = startSkills
end
--#endregion 2_player/4_skill.lua

--#region 2_player/5_gear.lua
do
-- ============================================================
--  5_gear.lua  --  Sau mon, moi mon tien hoa 100 bac
--
--  Moi mon di 20 canh gioi x 5 cap. TRAN la TU VI cua nguoi choi.
--  Luat day du: docs/02-he-thong/trang-bi-kiem.md  |  ADR 0021
--
--    (0,0)  "Kiem"                      <- tho, chua luyen
--      LUYEN  1 da, 100%
--    (1,1)  "Kiem Pham Nhan - So Cap"
--      LUYEN  1 da, 75% / 50% / 25% / 15%
--    (1,5)  "Kiem Pham Nhan - Hoan Hao"
--      TIEN GIAI  10 da, 100%, doi Tu Vi >= canh gioi 2
--    (2,1)  "Kiem Luyen Khi - So Cap"
--      ...
--
--  BAY MON, MOI MON MOT VAI -- 2026-09-18:
--    Mu    Int           Day Chuyen  ca ba      Ao   Str
--    Giay  Agi           Kiem  %sat thuong gay ra (ke ca hoi mau)
--    Khien %giam don danh nhan vao   Ao Choang %giam phep nhan vao
--  Bon mon cong diem thi LEO theo Tu Vi, ba mon nhan % thi PHANG.
--  Xem muc "CHI SO" ben duoi va CFG.GEAR_STAT_BASE.
--
--  NGAU NHIEN PHAI NAM TRONG HAM NHAN TU KENH DONG BO. Bam frame chi no
--  tren may nguoi bam; goi GetRandomInt o do la moi may tieu mot so khac
--  nhau tu chuoi ngau nhien, va TU GIAY DO moi so ngau nhien cua ca van
--  deu lech -- ke ca the Co Duyen. Xem dau 10_fortune.lua.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function itemCount() return #CFG.GEAR end
local function levelMax()   return #CFG.GEAR_CAP end
local function tierMax()  return #CFG.REALMS end

-- Trang thai mot mon: { canh = 0..20, cap = 0..5 }.
-- canh = 0 nghia la chua luyen lan nao.
local function stOf(pid, i)
  local d = S.p[pid]
  if d == nil then return nil end
  if d.gear == nil then d.gear = {} end
  if d.gear[i] == nil then d.gear[i] = { tier = 0, level = 0 } end
  return d.gear[i]
end

-- ---------- Ten ----------

local function levelNameOf(c)
  local t = CFG.GEAR_CAP[c]
  return (t ~= nil) and API.pick(t) or tostring(c)
end

-- Ten canh gioi, cho dong "can canh gioi X" cua o Canh.
local function realmNameOf(r)
  local t = CFG.REALMS[r]
  return (t ~= nil) and API.pick(t) or tostring(r)
end

local function tierNameOf(r)
  local t = CFG.REALMS[r]
  return (t ~= nil) and API.pick(t) or tostring(r)
end

-- "Kiem"  hoac  "Kiem Pham Nhan - So Cap"
local function fullName(pid, i)
  local item = CFG.GEAR[i]
  if item == nil then return "?" end
  local base = API.pick(item)
  local st = stOf(pid, i)
  if st == nil or st.tier <= 0 then return base end
  -- CANH GIOI DUNG TRUOC: "Pham Nhan Kiem - So Cap", khong phai
  -- "Kiem Pham Nhan - So Cap". Tieng Viet dat dinh ngu canh gioi len
  -- dau moi ra ten do tu tien; ban tieng Anh cung dung the ("Mortal
  -- Sword - Basic").
  return tierNameOf(st.tier) .. " " .. base .. " - " .. levelNameOf(st.level)
end

-- ---------- Hoi trang thai ----------

-- Luyen duoc khong: chua toi Hoan Hao la duoc.
local function canRefine(pid, i)
  local st = stOf(pid, i)
  return (st ~= nil) and (st.level < levelMax())
end

-- Tien Giai duoc khong. BA dieu kien, va dieu kien thu ba la cho cai
-- tran Tu Vi thuc su co hieu luc.
local function canEvolve(pid, i)
  local st = stOf(pid, i)
  if st == nil then return false end
  if st.level < levelMax() then return false end          -- chua Hoan Hao
  if st.tier >= tierMax() then return false end       -- da het canh gioi
  local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
  return rank >= st.tier + 1                            -- Tu Vi da toi chua
end

-- Xac suat cua lan luyen KE TIEP, dang 0..1.
local function nextOdds(pid, i)
  local st = stOf(pid, i)
  if st == nil then return 0.0 end
  return CFG.GEAR_ODDS[st.level + 1] or 0.0
end

-- Chi phi KY VONG tu cap hien tai len Hoan Hao: tong 1/p cua cac cap
-- con lai. Ghi len nut de nguoi choi biet minh dat bao nhieu TRUOC khi
-- bam -- mot cu bam gio tieu nhieu vien chu khong mot vien.
local function expectedCost(pid, i)
  local st = stOf(pid, i)
  if st == nil then return 0 end
  local sum = 0.0
  for k = st.level + 1, levelMax() do
    local p = CFG.GEAR_ODDS[k]
    -- Odds thieu hoac bang 0 la CFG hong, khong phai "kho". Bao ra chu
    -- khong tra mot con so doan.
    if p == nil or p <= 0.0 then
      API.trace("gear: GEAR_ODDS[" .. k .. "] = " .. tostring(p) ..
                " -- khong tinh duoc chi phi ky vong")
      return 0
    end
    sum = sum + 1.0 / p
  end
  return math.floor(sum * CFG.GEAR_PRICE + 0.5)
end

-- ---------- O tich "luyen gop / luyen le" ----------
--
-- CUC BO, khong dong bo, va khong duoc phep dong bo: no chi doi (a) chu
-- tren nut o may nay va (b) op nao duoc gui di. Ca hai deu la viec cuc
-- bo -- click frame chi no o may nguoi bam, va ben NHAN op moi la cho
-- doi trang thai that.
--
-- Vi the no khong nam trong S.p: mot truong trong trang thai da dong bo
-- ma chi dung o mot may la cai bay cho nguoi doc sau.
local allIn = {}

-- BAT san. Nguoi choi bao moi tay truoc khi bao thieu da, nen gop phai
-- la mac dinh; tick la de TAT, khong phai de bat.
local function isAllIn(pid)
  return allIn[pid] ~= false
end

-- ---------- Luyen ----------
-- Chay tren MOI may, tu kenh dong bo.
--
-- MOT lan bam = luyen LIEN TIEP toi Hoan Hao, hoac toi khi het da.
--
-- Vi sao gop chu khong de bam le: bam le KHONG phai mot quyet dinh.
-- That bai khong phat gi ngoai vien da va ti le thi co dinh -- nen nhin
-- mot lan that bai khong cho nguoi choi thong tin nao de doi y. 15 lan
-- bam chi la 15 lan bam. Quyet dinh that la DON DA VAO MON NAO, va cho
-- do van con nguyen.
--
-- Dung o Hoan Hao vi do la ranh gioi CO SAN trong thiet ke: qua no phai
-- Tien Giai, mot cua 10 da gac boi Tu Vi. Tuc la dung dung cho nguoi
-- choi buoc phai quyet dinh lai.
--
-- Do duoc: 99% so lan bam ton <= 39 vien, trung binh 15 -- tren ngan
-- sach ~420 vien ca van thi mot cu bam xau nhat an 9%. Co tran, va tran
-- do la cai canh gioi chu khong phai cai kho da.
local function refine(pid, i, once)
  local item = CFG.GEAR[i]
  if item == nil then return end
  if not canRefine(pid, i) then return end

  local st = stOf(pid, i)

  -- Phan hoi nam tren CAI O VUA BAM, khong o con hero.
  --
  -- Ban truoc ve mot hieu ung duoi chan hero: luc bam LUYEN mat nguoi
  -- choi dang o bang, ma con hero thi dang bi chinh cai bang che -- ve
  -- o do la ve vao cho khong ai nhin.
  local function flash(kind)
    if API.panelGearFlash ~= nil then API.panelGearFlash(pid, i, kind) end
  end

  local from, tries, spent, poor = st.level, 0, 0, false
  local lastPct = 0

  -- Chan vong lap. Da la huu han nen vong nay tu het, nhung mot
  -- CFG.GEAR_ODDS go sai se bien no thanh cai bom hut sach kho da ma
  -- khong bao gi. Chan cung, va TRACE khi cham -- khong nuot.
  local GUARD = 1000

  while canRefine(pid, i) do
    if tries >= GUARD then
      API.trace("gear: refine cham tran " .. GUARD .. " lan (pid " .. pid ..
                ", mon " .. i .. ") -- kiem lai CFG.GEAR_ODDS")
      break
    end
    if not API.spendIron(pid, CFG.GEAR_PRICE) then
      poor = true
      break
    end
    spent = spent + CFG.GEAR_PRICE
    tries = tries + 1

    -- GetRandomInt o DAY moi dung: ham nay chay tren MOI may, va ca so
    -- da lan cap deu la trang thai da dong bo -- nen vong lap quay dung
    -- bay nhieu lan, dung thu tu, o moi may.
    local pct = math.floor(nextOdds(pid, i) * 100.0 + 0.5)
    lastPct = pct
    if GetRandomInt(1, 100) <= pct then
      st.level = st.level + 1
      if st.tier <= 0 then st.tier = 1 end   -- lan dau: vao canh gioi 1
    end

    if once then break end
  end

  local name = CFG.C_JADE .. fullName(pid, i) .. CFG.C_END

  if tries == 0 then
    API.msg(pid, CFG.C_RED .. API.t("no_iron") .. CFG.C_END ..
      API.t("need_have", API.num(CFG.GEAR_PRICE), API.num(API.getIron(pid))))
    flash("fail")
  else
    local up  = (st.level > from)
    local top = (st.level >= levelMax())
    if once then
      -- Bam le: bao y NHU CU -- mot lan quay, mot cau. Doi sang dong
      -- tong ket o day thi "Luyen 1 lan, ton 1 da" khong noi duoc rang
      -- no THAT BAI.
      if up then
        API.say(pid, API.t("gear_became", name))
      else
        API.msg(pid, CFG.C_RED .. API.t("gear_failed", lastPct) .. CFG.C_END)
      end
    else
      -- Bam gop: MOT dong tong ket thay cho 15 dong "that bai". Nguoi
      -- choi can biet CAI GIA da tra, khong can nhat ky tung lan quay.
      --
      -- Dong nay di CHUNG ca doi. Truoc day chi cham Hoan Hao moi bao
      -- chung, con lai bao rieng -- nhung mot van nhieu nguoi thi viec
      -- so nhau chinh la noi dung, va gear_batch da noi ket qua cuoi
      -- ("gio la %s") nen khong can them dong moc rieng nua.
      API.say(pid, API.t("gear_batch", tries, API.num(spent), name))
    end

    flash((not up) and "fail" or (top and "big" or "ok"))

    if poor then
      API.msg(pid, CFG.C_RED .. API.t("no_iron") .. CFG.C_END)
    end
  end

  if API.heroRecompute ~= nil then API.heroRecompute(pid) end
  API.panelRefresh(pid)
end

-- ---------- Tien Giai ----------
-- Chay tren MOI may. KHONG co xac suat: no la mot CUA, khong phai canh
-- bac chong len canh bac. Va no bao gom luon lan len "So Cap" cua canh
-- gioi moi (von 100%), de khong co mot cu bam chac chan thua.

local function dismantle(pid, i)
  local item = CFG.GEAR[i]
  if item == nil then return end
  if not canEvolve(pid, i) then return end

  if not API.spendIron(pid, CFG.GEAR_DISMANTLE) then
    API.msg(pid, CFG.C_RED .. API.t("no_iron") .. CFG.C_END ..
      API.t("need_have", API.num(CFG.GEAR_DISMANTLE), API.num(API.getIron(pid))))
    API.panelRefresh(pid)
    return
  end

  local st = stOf(pid, i)
  st.tier = st.tier + 1
  st.level  = 1

  API.say(pid, API.t("gear_dismantled",
    CFG.C_JADE .. fullName(pid, i) .. CFG.C_END))

  if S.p[pid] ~= nil and S.p[pid].hero ~= nil then
    API.fx([[Abilities\Spells\Human\Resurrect\ResurrectTarget.mdl]],
           GetUnitX(S.p[pid].hero), GetUnitY(S.p[pid].hero))
  end

  if API.heroRecompute ~= nil then API.heroRecompute(pid) end
  API.panelRefresh(pid)
end

-- ---------- CHI SO ----------
--
-- HAI LOAI VAI, va chung khac nhau ve BAN CHAT chu khong chi ve con so:
--
--   cong diem  (str/agi/int/all)      -- KHONG tu leo, phai nhan
--                                        CULT_STAT_STEP^(canh gioi-1)
--   nhan %     (dmgpct/mitig_phys/
--               mitig_magic)             -- TU leo san, nen phai de PHANG
--
-- Cho ca hai cung mot duong cong la hai mon nhan chay mat -- xem chu
-- thich CFG.GEAR_STAT_BASE. Day la ADR 0010 lap lai o tang nguoi choi.

-- Tong so bac da di cua mot mon: 0 .. tierMax x levelMax.
local function stepsOf(pid, i)
  local st = stOf(pid, i)
  if st == nil or st.tier <= 0 then return 0 end
  return (st.tier - 1) * levelMax() + st.level
end

local function stepsMax()
  return tierMax() * levelMax()
end

-- Diem chi so CONG DON cua mot mon "cong diem".
--
--   value(T,L) = BASE x [ N x (STEP^(T-1) - 1)/(STEP-1) + L x STEP^(T-1) ]
--                         \_ N canh gioi truoc, tron _/   \_ canh gioi nay _/
--
-- Dung CHINH CULT_STAT_STEP chu khong go 1.30: doi duong cong Tu Vi thi
-- trang bi tu di theo, giong cach the "stat" cua Co Duyen lam.
local function addPoints(pid, i)
  local st = stOf(pid, i)
  if st == nil or st.tier <= 0 then return 0.0 end
  local s, n, T = CFG.CULT_STAT_STEP, levelMax(), st.tier
  local prev
  if s == 1.0 then prev = n * (T - 1)
  else               prev = n * (s ^ (T - 1) - 1) / (s - 1) end
  return CFG.GEAR_STAT_BASE * (prev + st.level * s ^ (T - 1))
end

-- Phan tram cua mot mon "nhan": TUYEN TINH theo so bac, khong leo.
local function pctOf(pid, i, maxPct)
  local m = stepsMax()
  if m <= 0 then return 0.0 end
  return (maxPct or 0.0) * stepsOf(pid, i) / m
end

-- Tong chi so tu CA SAU mon. Tra ve BA so, dung thu tu str/agi/int --
-- 7_effect cong thang vao mot cong thuc duy nhat, khong doc-cong-ghi.
local function statOf(pid)
  local str, agi, int = 0.0, 0.0, 0.0
  for i = 1, itemCount() do
    local role = CFG.GEAR[i].role
    if role == "str" or role == "agi" or role == "int" or role == "all" then
      local v = addPoints(pid, i)
      if     role == "str" then str = str + v
      elseif role == "agi" then agi = agi + v
      elseif role == "int" then int = int + v
      else
        -- Nhan: chia deu ba phan. Tong bang dung mot mon don chi so --
        -- doi lai chia ba thi sat thuong ky nang chi an mot phan ba, vi
        -- no tra theo chi so CAO NHAT chu khong theo tong.
        local third = v / 3.0
        str, agi, int = str + third, agi + third, int + third
      end
    end
  end
  return str, agi, int
end

-- % sat thuong GAY RA. An vao don thuong, sat thuong phep va hoi mau.
local function dmgPctOf(pid)
  local out = 0.0
  for i = 1, itemCount() do
    if CFG.GEAR[i].role == "dmgpct" then
      out = out + pctOf(pid, i, CFG.GEAR_DMG_MAX)
    end
  end
  return out
end

-- % sat thuong NHAN VAO duoc giam, theo LOAI don:
--   Khien ("mitig_phys")  cham don danh
--   Ao Choang ("mitig_magic") cham phep
--
-- Nguoi goi noi ro dang hoi loai nao. Khong doan tu dau goi: onDamaged
-- co BlzGetEventDamageType de hoi that.
local function mitigPctOf(pid, role)
  local out = 0.0
  for i = 1, itemCount() do
    if CFG.GEAR[i].role == role then
      out = out + pctOf(pid, i, CFG.GEAR_MITIG_MAX)
    end
  end
  return out
end

-- Duong dan icon cua mot mon o canh gioi hien tai.
--
-- Dung san theo CFG.GEAR_ICON_PATH chu khong go tung cai: them mot canh
-- gioi la tha anh vao roi chay w3gear_icons.py, khong sua dong Lua nao.
--
-- Chua luyen (tier 0) thi coi nhu canh gioi 1 -- phai co hinh de nguoi
-- choi biet mon do la gi truoc khi bo da vao.
--
-- Vuot qua GEAR_ICON_MAX thi dung anh cua muc cao nhat DA CO. Khong ke
-- thua thi mon o canh gioi 7 se mat icon, va o trong giua luoi trong
-- nhu bang hong.
--
-- Thieu ca bang duong dan thi lui ve item.icon -- duong do tu item that
-- luc vao map (probeIcons), da chung minh ve ra hinh.
local function iconFor(pid, i)
  local item = CFG.GEAR[i]
  if item == nil then return nil end
  if item.key == nil or CFG.GEAR_ICON_PATH == nil then return item.icon end
  local st = stOf(pid, i)
  local t  = (st ~= nil and st.tier > 0) and st.tier or 1
  local mx = CFG.GEAR_ICON_MAX or 1
  if t > mx then t = mx end
  return string.format(CFG.GEAR_ICON_PATH, item.key, t)
end

-- Nhan: % sat thuong gay ra hoi thanh mau. Cung khuon voi dmgPctOf.
local function lifestealPctOf(pid)
  local out = 0.0
  for i = 1, itemCount() do
    if CFG.GEAR[i].role == "lifesteal" then
      out = out + pctOf(pid, i, CFG.GEAR_LIFESTEAL_MAX)
    end
  end
  return out
end

-- Hoi mau cho hero theo sat thuong VUA GAY RA. Goi tu hai duong danh:
-- don thuong (onDamaged) va sat thuong ky nang (hit). Khong co Nhan thi
-- tra ve ngay, khong dung toi GetUnitState.
local function lifestealHeal(pid, amount)
  if amount == nil or amount <= 0.0 then return end
  local pct = lifestealPctOf(pid)
  if pct <= 0.0 then return end
  local d = S.p[pid]
  local h = d and d.hero or nil
  if h == nil or not API.alive(h) then return end
  local hp = GetUnitState(h, UNIT_STATE_LIFE) + amount * pct
  local mx = GetUnitState(h, UNIT_STATE_MAX_LIFE)
  SetUnitState(h, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
end

-- Chu mo ta phan mon nay DANG cong, de len the trong bang. Khong co no
-- thi nguoi choi bo da ma khong thay minh mua duoc gi.
local function bonusLabel(pid, i)
  local item = CFG.GEAR[i]
  if item == nil then return "" end
  local role = item.role
  -- API.num lam TRON XUONG, ma o bac dau % con duoi 1 -- no se hien
  -- "+0%" trong khi mon do that su co cong. Phan tram phai co mot chu so
  -- thap phan.
  if role == "dmgpct" then
    return API.t("gear_bonus_dmg",
      string.format("%.1f", pctOf(pid, i, CFG.GEAR_DMG_MAX) * 100.0))
  elseif role == "lifesteal" then
    return API.t("gear_bonus_lifesteal",
      string.format("%.1f", pctOf(pid, i, CFG.GEAR_LIFESTEAL_MAX) * 100.0))
  elseif role == "mitig_phys" or role == "mitig_magic" then
    local pct = string.format("%.1f", pctOf(pid, i, CFG.GEAR_MITIG_MAX) * 100.0)
    return API.t((role == "mitig_phys") and "gear_bonus_mitig_phys"
                                         or "gear_bonus_mitig_magic", pct)
  end
  local v = addPoints(pid, i)
  if role == "all" then
    return API.t("gear_bonus_all", API.num(v / 3.0))
  end
  return "+" .. API.num(v) .. " " .. API.t("stat_" .. role)
end

-- ---------- The trong bang ----------

local function tabItems(pid)
  local iron  = API.getIron(pid)
  local out = {}
  for i = 1, itemCount() do
    local item = CFG.GEAR[i]
    local st  = stOf(pid, i)
    local it  = { icon = iconFor(pid, i), name = fullName(pid, i) }

    -- 'short' + 'stat' la cua bang thong ke ben phai luoi; 'status' la
    -- cua kieu than "list" cu. Giu ca hai de doi kieu bay khong phai
    -- sua lai cho nay.
    -- NHAN tren icon (luoi). Xem chu thich o 1_panel.lua ve cho dat.
    --
    -- Ghi TONG BAC DA DI tren tong bac ("33/100"), khong ghi "3/5".
    -- Ba ly do:
    --   - "3/5" khong phan biet duoc Pham Nhan cap 3 voi Tien De cap 3,
    --     ma hai cai do cach nhau ca mot van choi.
    --   - Mot con so duy nhat thi TAM MON SO SANH DUOC VOI NHAU bang
    --     mot cai liec -- do dung la cau hoi "mon nao dang tut lai".
    --   - Ten cap ("Trung Cap" / "Exalted") khong vua be ngang icon
    --     0.036, va cot ten ben phai thi da chat san.
    local steps, smax = stepsOf(pid, i), stepsMax()
    it.tag = ((steps <= 0) and CFG.C_GREY
              or (steps >= smax) and CFG.C_GOLD or CFG.C_JADE) ..
             steps .. "/" .. smax .. CFG.C_END

    if st.tier <= 0 then
      it.status = CFG.C_GREY .. API.t("gear_not_refined") .. CFG.C_END
      it.short  = API.pick(item)
      it.stat   = CFG.C_GREY .. "--" .. CFG.C_END
    else
      -- Cap hien tai VA phan mon nay dang cong. Khong co ve sau thi
      -- nguoi choi bo mot van da ma khong bao gio thay minh mua duoc gi.
      it.status = CFG.C_GREY .. st.level .. "/" .. levelMax() .. CFG.C_END ..
                  "   " .. CFG.C_JADE .. bonusLabel(pid, i) .. CFG.C_END
      -- Bang thong ke ben phai luoi: cot hep nen KHONG nhet ca canh
      -- gioi vao. Ghi TEN CAP chu khong ghi "1-4" -- con so do khong
      -- noi len gi, ma nguoi choi thi doc "So Cap / Trung Cap".
      -- KHONG nhet canh gioi vao day. Da do: cot nay rong sw*0.58 va
      -- "Necklace - Exalted" da chiem 164px; them "Sang The Than " nua
      -- la tran sang cot chi so. Canh gioi doc o nhan icon (tong bac)
      -- va o nhan nut khi cham tran.
      it.short  = API.pick(item) .. " - " .. levelNameOf(st.level)
      it.stat   = CFG.C_JADE .. bonusLabel(pid, i) .. CFG.C_END
    end

    if canRefine(pid, i) then
      local pct = math.floor(nextOdds(pid, i) * 100.0 + 0.5)
      local exp = expectedCost(pid, i)
      it.desc   = API.t("gear_up", levelNameOf(levelMax()), pct, API.num(exp))
      -- O LUOI, 'note' chi hien KHI KHONG CO NUT (xem panel.lua:387) --
      -- nghia la chu giai thich bi chinh cai nut che. Nen NHAN NUT phai
      -- gom du ba y: lam gi, toi dau, het bao nhieu.
      --
      -- Nut rong 0.132 = 238 px, chu co mac dinh ~10,7 px/ky tu -> 22 ky
      -- tu. "LUYEN Hoan Hao  ~15" = 19. Vua, con du le.
      -- Nhan nut NOI RA che do dang bat. Do la thu bien o tich tu mot
      -- che do AN thanh mot che do NHIN THAY DUOC: bat len thi ca tam
      -- nut cung doi chu, khong phai nho cai tick be ti o giua.
      if isAllIn(pid) then
        -- KHONG dung "~". Font cua Warcraft ve dau nga NHAC CAO gan ngang
        -- dinh chu, nhin ra dau phu cua mot ky tu chu khong ra "khoang
        -- chung" -- da thu tren man hinh that. Con so dung mot minh, va
        -- "(co N)" ben canh da noi ro no dem DA.
        it.btn  = API.t("gear_btn_upto", levelNameOf(levelMax()))
                  .. "  " .. API.num(exp)
      else
        it.btn  = API.t("gear_btn_up") .. "  " .. API.num(CFG.GEAR_PRICE)
      end
      -- Chi can MOT vien la bam duoc: no se tieu het cho co roi dung.
      -- Khoa nut theo 'exp' la khoa theo mot con so DU DOAN -- nguoi
      -- choi con 8 vien van luyen duoc, khong co ly do chan.
      it.btnOn = (iron >= CFG.GEAR_PRICE)
      if not it.btnOn then
        it.btn = it.btn .. API.t("gear_btn_have", API.num(iron))
      end

    elseif st.tier >= tierMax() then
      it.desc   = CFG.C_JADE .. API.t("gear_max") .. CFG.C_END
      it.note   = API.t("gear_note_max")

    elseif canEvolve(pid, i) then
      it.desc   = API.t("gear_need_iron")
      it.btn    = API.t("gear_btn_dismantle") .. "  " .. API.num(CFG.GEAR_DISMANTLE)
      it.btnOn = (iron >= CFG.GEAR_DISMANTLE)
      if not it.btnOn then
        it.btn = it.btn .. API.t("gear_btn_have", API.num(iron))
      end

    else
      -- Hoan Hao roi nhung Tu Vi chua toi. Day la luc cai TRAN hien ra,
      -- va no phai noi RO dang cho gi -- khong co nut ma khong giai
      -- thich thi nguoi choi tuong giao dien hong.
      -- 'desc' la cau day du cho kieu than "list"; 'note' la ban ngan
      -- dat vua mot o cua luoi. Hai cho hien, mot y.
      it.desc = CFG.C_GREY .. API.t("gear_cap", tierNameOf(st.tier + 1)) .. CFG.C_END
      it.note = API.t("gear_note_cap")
      -- CO nut, nhung khoa. Truoc day cho nay khong co nut nao ca, nen
      -- no trong y HET o dang thieu da -- ma hai cai bao nguoi choi lam
      -- hai viec trai nguoc: thieu da thi di cay, cho Tu Vi thi di dot
      -- pha. btnWhy = "locked" cho bang ve no khac di.
      it.btn    = API.t("gear_btn_wait", tierNameOf(st.tier + 1))
      it.btnOn  = false
      it.btnWhy = "locked" 
    end

    out[i] = it
  end

  -- ----- HAI O KHONG PHAI TRANG BI, o cuoi danh sach -----
  --
  -- Di qua dung may moc o luoi (icon + nhan + nut) thay vi ve khung
  -- rieng. Chi so cua chung la #CFG.GEAR+1 va +2, khop voi hai o
  -- { 1, 5 } va { 3, 5 } them vao CFG.GEAR_SLOTS.
  --
  -- tabItemAction() dinh tuyen chung sang OP_WING / OP_PET.
  local n = itemCount()

  local wn = (API.wingOwned ~= nil) and API.wingOwned(pid) or 0
  local wl = (API.wingLabel ~= nil) and API.wingLabel(pid) or nil
  -- Anh theo bo DANG DEO, y het o Thanh Thu ben duoi. CFG.GEAR_WING_ICON
  -- gio chi con la duong LUI cho luc chua mo bo nao.
  local wIcon = (API.wingIcon ~= nil) and API.wingIcon(pid) or nil
  local wi = { icon = wIcon or CFG.GEAR_WING_ICON, name = API.t("gear_wing") }
  if wn <= 0 then
    -- Chua co bo nao: noi RO can canh gioi may, khong de o trong.
    local need = (API.wingNext ~= nil) and API.wingNext(pid) or nil
    wi.status = CFG.C_GREY .. API.t("st_locked") .. CFG.C_END
    wi.desc   = (need ~= nil) and API.t("wing_need", realmNameOf(need)) or ""
    wi.btn    = API.t("wing_need_short")
    wi.btnOn  = false
    wi.btnWhy = "locked"
  else
    wi.status = CFG.C_GREY .. wn .. "/" .. #(CFG.WINGS or {}) .. CFG.C_END
    wi.desc   = CFG.C_JADE .. (wl or "--") .. CFG.C_END
    wi.btn    = API.t("btn_swap")
    wi.btnOn  = (wn > 1)
  end
  out[n + 1] = wi

  local pn = (API.petOwned ~= nil) and API.petOwned(pid) or 0
  local pl = (API.petLabel ~= nil) and API.petLabel(pid) or nil
  -- CHAN DUNG THEO CON DANG DEO, khong phai mot duong dan co dinh.
  --
  -- Truoc day day la CFG.GEAR_PET_ICON thang, nen bam DOI thi ten doi ma
  -- anh van la Chu Tuoc -- nut nhin nhu hong. CFG.GEAR_PET_ICON gio chi
  -- con la duong LUI cho luc chua thu phuc con nao.
  local pIcon = (API.petIcon ~= nil) and API.petIcon(pid) or nil
  local pi = { icon = pIcon or CFG.GEAR_PET_ICON, name = API.t("gear_pet") }
  if pn <= 0 then
    pi.status = CFG.C_GREY .. API.t("st_locked") .. CFG.C_END
    pi.desc   = API.t("pet_need")
    pi.btn    = API.t("pet_need_short")
    pi.btnOn  = false
    pi.btnWhy = "locked"
  else
    pi.status = CFG.C_GREY .. pn .. "/" .. #(CFG.SIDE_QUESTS or {}) .. CFG.C_END
    pi.desc   = CFG.C_JADE .. (pl or "--") .. CFG.C_END
    pi.btn    = API.t("btn_swap")
    pi.btnOn  = (pn > 1)
  end
  out[n + 2] = pi

  return out
end

-- Mot nut, hai viec: truoc Hoan Hao thi Luyen, den Hoan Hao thi Tien
-- Giai. Quyet dinh o day la CUC BO nhung an toan, vi trang thai dua vao
-- (st.cap) da dong bo san -- va ca hai nhanh deu kiem lai dieu kien o
-- ben nhan.
-- O tich chi doi CHO NAY: op nao duoc gui. Ben nhan van kiem lai du
-- dieu kien, nen mot may go trang thai tich cung khong lam gi duoc hon
-- ngoai viec tu luyen le.
local function tabToggleText(pid)
  return isAllIn(pid) and API.t("gear_allin_on") or API.t("gear_allin_off")
end

local function tabToggleAction(pid)
  allIn[pid] = not isAllIn(pid)
end

local function tabItemAction(pid, i)
  -- Hai o cuoi khong phai trang bi -- xem tabItems().
  local n = itemCount()
  if i == n + 1 then API.syncSend(pid, CFG.OP_WING, 0); return end
  if i == n + 2 then API.syncSend(pid, CFG.OP_PET,  0); return end

  if CFG.GEAR[i] == nil then return end
  if canRefine(pid, i) then
    API.syncSend(pid, isAllIn(pid) and CFG.OP_GEAR_UP
                                    or CFG.OP_GEAR_UP_ONE, i)
  elseif canEvolve(pid, i) then
    API.syncSend(pid, CFG.OP_GEAR_DISMANTLE, i)
  end
end

-- Doc icon THAT tu item cua game. Cung cach probeItems() cua 8_shop.lua
-- va probeIcons() cua 10_fortune.lua -- ba cho cung mot bai hoc.
local function probeIcons()
  if CreateItem == nil or BlzGetItemIconPath == nil then
    API.trace("gear: khong do duoc icon (thieu CreateItem/BlzGetItemIconPath)")
    return
  end
  for i = 1, #CFG.GEAR do
    local item = CFG.GEAR[i]
    local hit = nil
    if item.probe ~= nil then
      for k = 1, #item.probe do
        local code = item.probe[k]
        local it = CreateItem(FourCC(code), 0.0, 0.0)
        if it ~= nil then
          local path = BlzGetItemIconPath(it)
          if path ~= nil and path ~= "" then
            item.icon = path
            hit = code
          end
          RemoveItem(it)
        end
        if hit ~= nil then break end
      end
    end
    if hit ~= nil then
      API.trace("gear: " .. item.en .. " <- " .. hit .. " (icon " .. item.icon .. ")")
    else
      API.trace("gear: " .. item.en .. " GIU DUONG LUI (" .. tostring(item.icon) .. ")")
    end
  end
end

local function startGear()
  probeIcons()
  -- Kieu "grid": bay o xep quanh cho hinh nguoi, nut Upgrade ngay duoi
  -- moi o, bang thong ke ben phai. Bo cuc o nam trong CFG.GEAR_SLOTS --
  -- bang chi doc, no khong biet mon nao la mon nao.
  API.panelAddTab({
    name        = API.t("panel_gear"),
    kind       = "grid",
    slots      = CFG.GEAR_SLOTS,
    statHead   = API.t("gear_stat_head"),
    items      = tabItems,
    itemAction = tabItemAction,
    toggleSlot   = CFG.GEAR_TOGGLE_SLOT,
    toggleText   = tabToggleText,
    toggleAction = tabToggleAction,
  })
  -- Lech so o va so mon thi bang se VE THIEU mot mon ma khong bao gi --
  -- dung kieu sai im lang cua ADR 0012. Bat o day, luc vao map.
  -- +2 cho hai o Canh va Thanh Thu o hang 5 (xem tabItems).
  local nslot = (CFG.GEAR_SLOTS ~= nil) and #CFG.GEAR_SLOTS or 0
  if nslot ~= itemCount() + 2 then
    API.trace("gear: LECH -- " .. itemCount() .. " mon + 2 o rieng nhung " ..
              nslot .. " o trong CFG.GEAR_SLOTS; bang se ve thieu")
  end

  API.syncOn(CFG.OP_GEAR_UP,   refine)
  API.syncOn(CFG.OP_GEAR_UP_ONE,
             function(p2, i2) refine(p2, i2, true) end)
  API.syncOn(CFG.OP_GEAR_DISMANTLE, dismantle)
  API.trace("gear: " .. itemCount() .. " mon x " .. tierMax() .. " canh gioi x " ..
            levelMax() .. " cap, the san sang (chi so con rong)")
end

API.gearName     = fullName
API.gearTier    = function(pid, i) local st = stOf(pid, i); return st and st.tier or 0 end
API.gearLevel     = function(pid, i) local st = stOf(pid, i); return st and st.level  or 0 end
API.gearStat    = statOf      -- tra ve str, agi, int
API.gearDmgPct  = dmgPctOf
API.gearMitigPct = mitigPctOf  -- (pid, "mitig_phys" | "mitig_magic")
API.gearLifesteal    = lifestealHeal  -- (pid, sat thuong vua gay ra)
API.gearBonus   = bonusLabel
API.startGear   = startGear
end
--#endregion 2_player/5_gear.lua

--#region 2_player/6_relic.lua
do
-- ============================================================
--  6_relic.lua  --  Mua MOT lan, khong co cap
--
--  BANG DANG RONG (CFG.RELIC = {}) -- 2026-09-16. Nam mon cu da xoa:
--  chung mua bang Tinh Thach, mot dong tien gio da xoa han. He nay
--  tra bang GO.
--
--  NGAN SACH DANH SAN: ca van kiem 260 Go, ky nang tieu 70, nen con
--  190 diem cho day. Do la rang buoc khi thiet ke lai.
--
--  Code chay duoc voi bang rong: the hien mot dong "chua co gi", khong
--  mua duoc gi, va moi hieu ung tra ve false -- nen 2_wave.lua goi
--  API.relicHas / relicAnyHas / relicOnClear van an toan.
--
--  KHI THEM MON MOI. Moi mon phai DOC-LUC-DUNG: khong dang ky trigger
--  rieng, ma cho can biet thi hoi API.relicHas. Mot mon can bo bat su
--  kien rieng la mot mon co the hong am tham, ma ca van chi mua duoc
--  vai lan. Them mon la them dong vao CFG.RELIC VA viet cho doc 'ma'
--  cua no -- khong co bang dieu phoi tu dong nao ca.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nguoi nay co mon do khong.
local function has(pid, code)
  local d = S.p[pid]
  return (d ~= nil) and (d.relic ~= nil) and (d.relic[code] == true)
end

-- CO AI trong doi co mon do khong.
--
-- Dung cho hai mon cong vao NHA CHINH: nha la cua chung, nen mot nguoi
-- mua la ca doi duoc huong. Do cung la ly do hai mon do dat hon hai mon
-- ca nhan.
local function anyHas(code)
  for i = 1, #S.pids do
    if has(S.pids[i], code) then return true end
  end
  return false
end

-- So cua mot mon, hoac 0 neu nguoi do chua mua.
--
-- Cho nao can thi goi cai nay, khong ai dang ky trigger rieng -- xem
-- luat "doc-luc-dung" o dau file. Tra 0 chu khong nil de ben goi khong
-- phai chot nil moi cho.
-- Mon nay da mo khoa chua.
--
-- Mo bang cach HA THANH THU tuong ung, khong phai bang tien. Con thu
-- la cai CONG, Go la cai BE TIEU -- tang thang mon do thi 222 Go lai
-- roi vao canh khong co gi de mua, dung cai lo cu chi doi cho.
--
-- 'unlock' vang mat nghia la ban tu dau (khong dung cho mon nao hien
-- tai, nhung de bang khong vo neu sau nay them mon mua tu do).
local function unlocked(item)
  if item == nil then return false end
  if item.unlock == nil then return true end
  return (S.sideDone or {})[item.unlock] == true
end

-- Ten con thu phai ha, de bao cho nguoi choi biet DI DAU.
local function gateName(item)
  local q = (CFG.SIDE_QUESTS or {})[item.unlock or 0]
  return (q ~= nil) and API.pick(q) or "?"
end

local function valOf(pid, code, field)
  local d = S.p[pid]
  if d == nil or d.relic == nil or not d.relic[code] then return 0.0 end
  for i = 1, #CFG.RELIC do
    local r = CFG.RELIC[i]
    if r.code == code then return r[field] or 0.0 end
  end
  return 0.0
end

local function defOf(code)
  for i = 1, #CFG.RELIC do
    if CFG.RELIC[i].code == code then return CFG.RELIC[i] end
  end
  return nil
end

-- ---------- Mua ----------
-- Chay tren MOI may, tu kenh dong bo.

local function buy(pid, i)
  local item = CFG.RELIC[i]
  if item == nil then return end
  -- Kiem lai o BEN NHAN, khong tin cu bam: ben gui la cuc bo.
  if not unlocked(item) then
    API.msg(pid, CFG.C_RED .. API.t("relic_need", gateName(item)) .. CFG.C_END)
    return
  end

  local d = S.p[pid]
  if d == nil then return end
  if d.relic == nil then d.relic = {} end
  if d.relic[item.code] then return end

  if CFG.RELIC_LOCKED then return end
  if not API.spendLumber(pid, item.price) then
    API.msg(pid, CFG.C_RED .. API.t("no_lumber") .. CFG.C_END ..
      API.t("need_have", API.num(item.price), API.num(API.getLumber(pid))) ..
      CFG.C_GREY .. " " .. API.t("lumber_note") .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  d.relic[item.code] = true
  API.msg(nil, API.t("relic_bought",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. API.pick(item) .. CFG.C_END))

  if d.hero ~= nil then
    API.fx([[Abilities\Spells\Items\AIem\AIemTarget.mdl]],
           GetUnitX(d.hero), GetUnitY(d.hero))
  end
  API.panelRefresh(pid)
end

-- ---------- Hieu ung "mana": don sach mot dot thi ca doi hoi day ----------
--
-- Goi tu onMobDeath luc con cuoi cung chet. Mot nguoi mua thi ca doi
-- duoc -- cung nguyen tac voi hai mon cong vao nha.
local function onClear()
  if not anyHas("mana") then return end
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    if d ~= nil and d.hero ~= nil and API.alive(d.hero) then
      SetUnitState(d.hero, UNIT_STATE_MANA,
                   GetUnitState(d.hero, UNIT_STATE_MAX_MANA))
    end
  end
end

-- ---------- The trong bang phim E ----------

local function descOf(item)
  if API.lang() == "en" then return item.desc_en or item.desc end
  return item.desc or item.desc_en
end

local function tabItems(pid)
  -- KHOA TAM THOI: khong ban gi ca. Tra ve rong de bang hien dong
  -- "chua co gi" + ly do, thay vi hien mon mua khong duoc.
  if CFG.RELIC_LOCKED then return {} end
  local lumber = API.getLumber(pid)
  local out = {}
  for i = 1, #CFG.RELIC do
    local item = CFG.RELIC[i]
    local it  = { icon = item.icon, name = API.pick(item), desc = descOf(item) }

    if has(pid, item.code) then
      it.status = CFG.C_JADE .. API.t("st_owned") .. CFG.C_END
    elseif not unlocked(item) then
      -- CO NUT nhung khoa, khong phai bo trong.
      --
      -- O trong thi nguoi choi tuong giao dien hong; co nut khoa kem
      -- ten con thu thi no thanh mot CAI DICH -- va do chinh la ly do
      -- di giet bon con thu.
      it.status = CFG.C_GREY .. API.t("st_locked") .. CFG.C_END
      it.btn    = API.t("relic_need", gateName(item))
      it.btnOn  = false
      it.btnWhy = "locked"
    else
      it.status = CFG.C_GREY .. API.num(item.price) .. CFG.C_END
      -- GO: buy() goi API.spendLumber. Nhan sai tien tren nut la noi doi voi
      -- nguoi choi ve thu ho dang de danh.
      it.btn       = API.t("btn_buy") .. "  " .. API.num(item.price) .. " " .. API.t("cur_lumber")
      it.btnOn    = (lumber >= item.price)
    end
    out[i] = it
  end
  return out
end

local function tabItemAction(pid, i)
  if CFG.RELIC[i] == nil then return end
  API.syncSend(pid, CFG.OP_RELIC_BUY, i)
end

local function startRelic()
  API.panelAddTab({
    name        = API.t("panel_relic"),
    kind       = "list",
    rows      = #CFG.RELIC,
    items      = tabItems,
    itemAction = tabItemAction,
    empty      = CFG.RELIC_LOCKED and API.t("relic_locked") or API.t("relic_empty"),
  })
  API.syncOn(CFG.OP_RELIC_BUY, buy)
  API.trace("relic: " .. #CFG.RELIC .. " mon, the san sang")
end

-- Goi tu 4_sidequest.lua khi mot con thu nga xuong.
local function announceUnlock(idx)
  for i = 1, #CFG.RELIC do
    local r = CFG.RELIC[i]
    if r.unlock == idx then
      API.msg(nil, CFG.C_GOLD ..
        API.t("relic_open", API.pick(r), API.num(r.price)) .. CFG.C_END)
    end
  end
  API.panelRefreshAll()
end

API.relicUnlocked = announceUnlock
API.relicVal      = valOf
API.relicHas      = has
API.relicAnyHas    = anyHas
API.relicDef     = defOf
API.relicOnClear = onClear
API.startRelic   = startRelic
end
--#endregion 2_player/6_relic.lua

--#region 2_player/7_effect.lua
do
-- ============================================================
--  7_effect.lua  --  Ky nang co hieu luc that
--
--  Truoc file nay, bay ky nang cua Hart la bay ability GOC cua Warcraft
--  duoc nhan ban: Shockwave, Holy Light, Devotion Aura, Avatar... Chung
--  gay dung so sat thuong ma Blizzard dat, va KHONG an theo bat cu thu
--  gi nguoi choi mua. Linh Can bac 20 cong +1075 moi chi so; Chuong van
--  gay dung ngan ay sat thuong nhu wave 1.
--
--  Do la ly do CFG.SKILL_DATA_LIVE ton tai, va vi sao no tung la false.
--
--  VI SAO KHONG SUA TRUONG TRONG war3map.w3a
--
--  Cach "chinh thong" la ghi so vao truong Data cua Shockwave. Khong lam
--  duoc: ma truong cua AOsh / AHhb / AHad CHUA AI DO
--  (docs/06-object-editor/sua-va-clone-ability.md), ma du an nay co luat
--  khong doan -- doan sai mot ma truong bon ky tu la file hong am tham,
--  kieu te nhat.
--
--  Nen file nay bat su kien va TU gay sat thuong. Khong can biet ma
--  truong nao ca. Sat thuong goc cua Warcraft van con, nhung o bac 10
--  voi Linh Can bac 20 thi no la sai so lam tron.
--
--  MUOI MOT LOAI HIEU UNG, khai bao bang truong 'fx':
--    line chain nova           chu dong, sat thuong
--    heal hot wave buff        chu dong, hoi mau / tu buff
--    cleave burn reduce        bi dong, bat qua su kien sat thuong
--    stat                      bi dong, tinh lai khi bac ky nang doi
--
--  'heal' hoi MOT CUC ngay; 'hot' rai deu trong thoi luong cua chinh
--  ability. Hai cai khac nhau that, va A010 tung dung nham 'heal' --
--  nguoi lam map dat 6 giay trong World Editor ma trong game no hoi
--  tuc thi, nhin ra nhu loi.
--
--  ('aura' KHONG con la hieu ung o day -- con so cua no nam trong chinh
--  ability va Warcraft tu cong. No chi con la nhan de bang phim R loc.)
--
--  Moi hero moi thuong keo theo vai loai moi, roi tu do hero sau dung
--  lai duoc: Hvwd (2026-09-19) them 'chain' va 'burn', Hkal cung ngay
--  them 'nova' va 'wave'. Den hero thu tu thi kha nang chi con khai
--  bao them dong trong CFG.SKILLS.
--
--  VI SAO 'burn' TINH THEO % DON DANH, KHONG PHAI % MAU MUC TIEU
--
--  Ban thao dau la "+1% mau toi da cua muc tieu". Khong dung duoc: mau
--  moi thu trong map nay DINH NGHIA theo DPS nguoi choi (ADR 0020, va
--  armStats() dat mau Thanh Thu = dps x seconds). Nen "% mau dich" that
--  ra la "% TRAN DAU" -- 1% thanh dung 100 mui ten giet MOI thu, va bo
--  so 45/85/150/240 giay cua bon Thanh Thu mat sach y nghia.
--
--  Do lai con nguoc: cung 100 mui do voi Chu Tuoc (thiet ke 45 giay) la
--  CHAM hon danh thuong, con voi Thanh Long (240 giay) la nhanh gap 3,6
--  lan. Con de nhat khong doi gi, con kho nhat boc hoi.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Chan de quy: sat thuong do CHINH file nay gay ra cung ban su kien
-- EVENT_PLAYER_UNIT_DAMAGED. Khong chan thi Chem Lan van lan nhau vo han
-- va game treo ngay wave dau.
local busy = false

-- Bao THIEU BlzGetEventDamageType dung mot lan, khong phai moi don --
-- mot dong moi cu danh la file vet khong con doc duoc.
local dmgTypeWarned = false
local hotWarned     = false

-- ---------- Tra cuu ----------

-- Tra ve (sk, bac) cua mot ability tren hero cua nguoi nay. Bac 0 hoac
-- khong tim thay thi tra nil -- goi ben ngoai chi can kiem mot lan.
local function skillOf(pid, abilId)
  local list = API.skillList(pid)
  for i = 1, #list do
    if list[i].id == abilId then
      local lv = API.skillLevel(pid, abilId, i)
      if lv > 0 then return list[i], lv end
      return nil
    end
  end
  return nil
end

-- Tim ky nang theo LOAI hieu ung. Dung cho bi dong: luc bi danh thi ta
-- khong biet ability nao, chi biet "nguoi nay co Da Sat khong".
local function skillByFx(pid, fx)
  local list = API.skillList(pid)
  for i = 1, #list do
    if list[i].fx == fx then
      local lv = API.skillLevel(pid, list[i].id, i)
      if lv > 0 then return list[i], lv end
      return nil
    end
  end
  return nil
end

local function heroPid(u)
  if u == nil then return nil end
  local pid = GetPlayerId(GetOwningPlayer(u))
  local d = S.p[pid]
  if d == nil or d.hero ~= u then return nil end
  return pid
end

-- ---------- Nhat muc tieu ----------

local function enemiesNear(x, y, radius, f)
  local g = CreateGroup()
  GroupEnumUnitsInRange(g, x, y, radius, nil)
  local u = FirstOfGroup(g)
  while u ~= nil do
    GroupRemoveUnit(g, u)
    -- Chi quai cua phe dich. Khong dung IsUnitEnemy: no hoi "dich voi
    -- AI", ma o day ta luon muon dung mot phe duy nhat.
    if API.alive(u) and GetOwningPlayer(u) == S.enemy then f(u) end
    u = FirstOfGroup(g)
  end
  DestroyGroup(g)
end

-- Gay sat thuong, co co chan de quy.
local function hit(src, tgt, amount, model)
  if amount <= 0 or not API.alive(tgt) then return end
  busy = true
  UnitDamageTarget(src, tgt, amount, true, false,
                   ATTACK_TYPE_NORMAL, DAMAGE_TYPE_MAGIC, WEAPON_TYPE_WHOKNOWS)
  busy = false
  if model ~= nil then API.fx(model, GetUnitX(tgt), GetUnitY(tgt)) end

  -- NHAN an ca o duong ky nang. 'busy' lam onDamaged() return ngay dong
  -- dau, nen neu khong goi o day thi hut mau chi chay tren don thuong --
  -- kieu sai im lang, va hero danh phep thi khong hieu vi sao khong hoi.
  if API.gearLifesteal ~= nil and API.heroPidOf ~= nil then
    local sp = API.heroPidOf(src)
    if sp ~= nil then API.gearLifesteal(sp, amount) end
  end
end

-- ---------- Ky nang chu dong ----------

-- "line": danh tren mot duong thang truoc mat.
--
-- Khoang cach tu mot diem toi DUONG THANG, khong phai toi diem cuoi --
-- neu khong thi con dung sat ben canh hero se khong an don du no nam
-- ngay tren duong danh.
local function fxLine(pid, u, sk, lv)
  local x, y = GetUnitX(u), GetUnitY(u)
  local tx, ty = x, y
  if GetSpellTargetX ~= nil then tx, ty = GetSpellTargetX(), GetSpellTargetY() end
  if tx == x and ty == y then
    -- Khong co diem nham thi danh theo huong dang quay.
    tx = API.polarX(x, CFG.FX_LINE_LEN, GetUnitFacing(u))
    ty = API.polarY(y, CFG.FX_LINE_LEN, GetUnitFacing(u))
  end

  local ang = API.angleXY(x, y, tx, ty)
  local L   = CFG.FX_LINE_LEN
  local cx  = API.polarX(x, L * 0.5, ang)
  local cy  = API.polarY(y, L * 0.5, ang)
  local dmg = API.skillDamage(u, API.skillFactor(sk, lv))

  local ux, uy = Cos(ang * bj_DEGTORAD), Sin(ang * bj_DEGTORAD)
  enemiesNear(cx, cy, L * 0.5 + CFG.FX_LINE_WIDTH, function(e)
    local dx, dy = GetUnitX(e) - x, GetUnitY(e) - y
    local along = dx * ux + dy * uy                 -- chieu len duong danh
    if along < 0.0 or along > L then return end
    local perp = dx * (-uy) + dy * ux            -- khoang cach toi duong
    if perp < 0 then perp = -perp end
    if perp > CFG.FX_LINE_WIDTH then return end
    hit(u, e, dmg, CFG.FX_HIT_LINE)
  end)
end

-- Hoi mau, chan o tran. MOT cho duy nhat lam viec nay -- ba duong
-- (heal, hot, wave) deu goi vao day chu khong ai tu viet lai phep kep.
local function healUnit(t, amount)
  if t == nil or amount <= 0.0 or not API.alive(t) then return end
  local hp = GetUnitState(t, UNIT_STATE_LIFE) + amount
  local mx = GetUnitState(t, UNIT_STATE_MAX_LIFE)
  SetUnitState(t, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
end

-- "heal": hoi mau mot muc tieu. Khong co muc tieu thi hoi chinh minh.
local function fxHeal(pid, u, sk, lv)
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t == nil then t = u end
  healUnit(t, API.skillDamage(u, API.skillFactor(sk, lv)))
  API.fx(CFG.FX_HIT_HEAL, GetUnitX(t), GetUnitY(t))
end

-- "nova": no mot vong quanh MUC TIEU, khong phai quanh minh (A013).
--
-- Frost Nova goc nham vao mot unit roi van ra; giu dung kieu do. Khong
-- co muc tieu thi lay diem nham -- ban sao co the duoc dat lai thanh
-- nham diem trong Object Editor, va luc do ham nay van chay.
local function fxNova(pid, u, sk, lv)
  local tx, ty
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t ~= nil then
    tx, ty = GetUnitX(t), GetUnitY(t)
  elseif GetSpellTargetX ~= nil then
    tx, ty = GetSpellTargetX(), GetSpellTargetY()
  end
  if tx == nil then return end

  local dmg = API.skillDamage(u, API.skillFactor(sk, lv))
  enemiesNear(tx, ty, CFG.FX_NOVA_AOE or 300.0, function(e)
    hit(u, e, dmg, CFG.FX_HIT_NOVA)
  end)
end

-- Duyet HERO CUA NGUOI CHOI trong ban kinh. Doi cua enemiesNear.
--
-- Khong dung GroupEnumUnitsInRange roi loc theo phe: pet va thap canh
-- cung thuoc ve nguoi choi, ma hoi mau cho mot cai thap thi vo nghia.
-- Duyet thang S.pids la chac chan lay dung hero.
local function heroesNear(x, y, radius, f)
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h)
       and API.distXY(x, y, GetUnitX(h), GetUnitY(h)) <= radius then
      f(h)
    end
  end
end

-- "wave": hoi mau nay qua dong doi, moi lan nhay yeu di (A014).
--
-- CHON NGUOI THIEU MAU NHAT, khong phai nguoi gan nhat. Day la khac
-- biet that: hoi mau nay sang mot nguoi day mau la vut di mot nhip,
-- ma so nhip thi co han. Sat thuong thi nguoc lai -- "gan nhat" moi
-- dung, vi muc tieu nao cung an du.
local function fxWave(pid, u, sk, lv)
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t == nil then t = u end

  local amount = API.skillDamage(u, API.skillFactor(sk, lv))
  local hops  = CFG.FX_WAVE_MAX or 3
  local fall  = CFG.FX_WAVE_FALLOFF or 0.75
  local reach = CFG.FX_WAVE_HOP or 500.0

  local seen, cur = {}, t
  for _ = 1, hops do
    if cur == nil or amount < 1.0 then break end
    seen[GetHandleId(cur)] = true
    local cx, cy = GetUnitX(cur), GetUnitY(cur)
    healUnit(cur, amount)
    API.fx(CFG.FX_HIT_HEAL, cx, cy)
    amount = amount * fall

    local best, worst = nil, nil
    heroesNear(cx, cy, reach, function(h)
      if seen[GetHandleId(h)] then return end
      local frac = GetUnitState(h, UNIT_STATE_LIFE)
                 / GetUnitState(h, UNIT_STATE_MAX_LIFE)
      if worst == nil or frac < worst then best, worst = h, frac end
    end)
    cur = best
  end
end

-- "buff" KHONG con ham Lua nao.
--
-- Bat Hoai la ban sao cua Avatar, va Avatar tu co buff co thoi luong.
-- Giap cua no lay tu ABILITY_RLF_DEFENSE_BONUS_HAV1 -- truong ma
-- applyLevel() ghi so can bang cua ta vao (CFG.SKILL_CARRY_BASE). Nen
-- khong con gi de lam bang Lua: bam la Warcraft lo het.
--
-- Thoi luong gio la thoi luong goc cua Avatar, khong phai
-- CFG.FX_BUFF_TIME. Muon doi thi dat truong 'adur'/'ahdu' trong
-- war3map.w3a.
--
-- HAV2 (mau toi da) van chay: ban 1.31.1 khong phoi ra hang so nao cho
-- no nen khong tat duoc -- xem chu thich o CFG.SKILL_ZERO_BASE.

-- "chain": nay tu muc tieu sang con gan nhat chua bi danh (A008, Hvwd).
--
-- Warcraft CO san co che nay, nhung sat thuong cua no la so PHANG trong
-- Object Editor -- tuc teo thanh khong o canh gioi cao (ADR 0024). Nen
-- ta muon cai VO (icon, tia set, hoi chieu, mana, tam) va tu tinh sat
-- thuong bang skillDamage() nhu moi ky nang khac.
--
-- Tia set GOC van ve ra, va no chon muc tieu theo bang so cua WE chu
-- khong theo vong lap nay. Hai ben co the lech mot con -- FX_HIT_CHAIN
-- danh dau nhung con LUA that su danh, de nhin ra do lech neu co.
local function fxChain(pid, u, sk, lv)
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t == nil then return end

  local dmg  = API.skillDamage(u, API.skillFactor(sk, lv))
  local hops = CFG.FX_CHAIN_MAX or 4
  local fall = CFG.FX_CHAIN_FALLOFF or 0.80
  local reach = CFG.FX_CHAIN_HOP or 400.0

  -- 'seen' chan tia set quay lai con vua danh. Khong co no thi hai con
  -- dung canh nhau se chuyen qua chuyen lai va an tron ca bon lan nhay.
  local seen, cur = {}, t
  for _ = 1, hops do
    if cur == nil or dmg < 1.0 then break end
    seen[GetHandleId(cur)] = true
    -- Nho toa do TRUOC khi danh: hit() co the giet no, va enemiesNear
    -- loc theo API.alive nen tu bo qua xac.
    local cx, cy = GetUnitX(cur), GetUnitY(cur)
    hit(u, cur, dmg, CFG.FX_HIT_CHAIN)
    dmg = dmg * fall

    local best, bestD = nil, nil
    enemiesNear(cx, cy, reach, function(e)
      if seen[GetHandleId(e)] then return end
      local dd = API.distXY(cx, cy, GetUnitX(e), GetUnitY(e))
      if bestD == nil or dd < bestD then best, bestD = e, dd end
    end)
    cur = best
  end
end

-- ---------- "burn": lop thieu dot (A011, Hvwd) ----------
--
-- MOT bang va MOT dong ho cho ca map, khong phai mot dong ho moi lan
-- danh. Xa thu cuoi van danh rat nhanh, ma moi TimerStart la mot handle:
-- vai nghin cai trong mot wave thi Warcraft can handle va nhung he KHAC
-- bat dau hong -- kieu loi khong bao gio truy nguoc duoc ve day.
--
-- Nho 'pid' chu khong nho unit hero: doi hero thi handle cu treo lai, va
-- UnitDamageTarget voi mot nguon da bi xoa la vung khong xac dinh. Tra
-- lai S.p[pid].hero moi nhip thi luon la con dang song.
local function burnApply(pid, tgt, total)
  if total < 1.0 or tgt == nil or not API.alive(tgt) then return end
  if S.burn == nil then S.burn = {} end

  local time  = CFG.FX_BURN_TIME or 3.0
  local step  = CFG.FX_BURN_TICK or 0.5
  local ticks = math.floor(time / step + 0.5)
  if ticks < 1 then ticks = 1 end

  local k = GetHandleId(tgt)
  local b = S.burn[k]
  if b ~= nil and CFG.FX_BURN_STACK then
    b.per  = b.per + total / ticks
    b.left = time
    b.pid  = pid
  else
    -- LAM MOI chu khong cong don (CFG.FX_BURN_STACK = false). Cong don
    -- thi toc danh tu nhan voi chinh no.
    S.burn[k] = { u = tgt, pid = pid, per = total / ticks, left = time }
    API.fx(CFG.FX_HIT_BURN, GetUnitX(tgt), GetUnitY(tgt))
  end
end

-- ---------- "hot": hoi mau keo dai (A010, Hvwd) ----------
--
-- BANG RIENG voi burn chu khong chung mot bang. Khoa la GetHandleId
-- cua muc tieu; burn bam vao QUAI con hot bam vao HERO nen chung
-- "khong bao gio" dam nhau -- nhung do la mot gia dinh ve luat choi,
-- khong phai ve ma nguon. Hai bang thi khong ai phai nho gia dinh do.
--
-- Dung chung MOT dong ho voi burn, vi cung mot nhip.
local function hotApply(pid, tgt, total, secs)
  if total < 1.0 or tgt == nil or not API.alive(tgt) then return end
  if S.hot == nil then S.hot = {} end

  local step  = CFG.FX_BURN_TICK or 0.5
  local ticks = math.floor(secs / step + 0.5)
  if ticks < 1 then ticks = 1 end

  S.hot[GetHandleId(tgt)] = { u = tgt, per = total / ticks, left = secs }
  API.fx(CFG.FX_HIT_HEAL, GetUnitX(tgt), GetUnitY(tgt))
end

-- Doc mot truong REAL cua ability bang MA TRUONG 4 ky tu.
--
-- Ma truong chu khong ten hang so, va day la do chu khong phai so
-- thich: ban 1.31.1 THIEU rat nhieu ABILITY_RLF_* -- file vet ghi ro
-- OCL1, OCL2, CR21 deu khong co. ConvertAbilityRealLevelField nhan
-- FourCC nen di duong vong duoc; day cung la duong A003 da phai di.
local function abilReal(pid, abilId, code, level)
  local h = (S.p[pid] or {}).hero
  if h == nil or BlzGetUnitAbility == nil
     or BlzGetAbilityRealLevelField == nil then return nil end
  local conv = _G["ConvertAbilityRealLevelField"]
  if conv == nil then return nil end
  local ab = BlzGetUnitAbility(h, abilId)
  if ab == nil then return nil end
  return BlzGetAbilityRealLevelField(ab, conv(FourCC(code)), (level or 1) - 1)
end

-- "hot": hoi mau RAI DEU, khong phai mot cuc.
--
-- Thoi luong lay tu CHINH ability ('adur' -- doc duoc trong w3obj.py
-- dump, 6.0 cho A010). World Editor giu con so do; khai them mot
-- CFG.FX_HOT_TIME co dinh la hai noi cung khai mot thu, va mot ngay se
-- chi sua mot noi. CFG chi la duong lui khi doc khong ra.
local function fxHot(pid, u, sk, lv)
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t == nil then t = u end

  local secs = abilReal(pid, sk.id, sk.durField or "adur", lv)
  if secs == nil or secs <= 0.0 then
    secs = CFG.FX_HOT_TIME or 6.0
    if not hotWarned then
      hotWarned = true
      API.trace("effect: khong doc duoc thoi luong '" ..
                tostring(sk.durField or "adur") .. "' cua " ..
                API.idToStr(sk.id) .. " -- lui ve " .. secs .. "s")
    end
  end
  hotApply(pid, t, API.skillDamage(u, API.skillFactor(sk, lv)), secs)
end

-- Mot nhip cho CA HAI bang. Gan nil cho chinh khoa dang duyet la hop
-- le trong Lua; them khoa moi thi khong, va vong nay khong them.
local function overTick()
  local step = CFG.FX_BURN_TICK or 0.5

  if S.burn ~= nil then
    for k, b in pairs(S.burn) do
      local d   = S.p[b.pid]
      local src = d and d.hero or nil
      if b.u == nil or not API.alive(b.u) or b.left <= 0.0
         or src == nil or not API.alive(src) then
        S.burn[k] = nil
      else
        hit(src, b.u, b.per, nil)
        b.left = b.left - step
        if b.left <= 0.0 then S.burn[k] = nil end
      end
    end
  end

  if S.hot ~= nil then
    for k, b in pairs(S.hot) do
      if b.u == nil or not API.alive(b.u) or b.left <= 0.0 then
        S.hot[k] = nil
      else
        -- Khong di qua hit(): day la HOI MAU, va no phai dung o mau
        -- toi da chu khong tran qua.
        local hp = GetUnitState(b.u, UNIT_STATE_LIFE) + b.per
        local mx = GetUnitState(b.u, UNIT_STATE_MAX_LIFE)
        SetUnitState(b.u, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
        b.left = b.left - step
        if b.left <= 0.0 then S.hot[k] = nil end
      end
    end
  end
end

-- ---------- Autocast cua Searing Arrows ----------
--
-- A011 la ban sao cua AHfa -- mot ability AUTOCAST, tuc co nut bat/tat
-- that tren command card (phim E). Neu Lua cu dot bat ke nut do thi tat
-- di la vua khoi ton mana vua giu nguyen sat thuong: nut thanh cai bay.
--
-- Warcraft 1.31.1 khong phoi ra native nao hoi "autocast dang bat
-- khong". Nhung LENH thi bat duoc, va OrderId() tra ve 0 cho ten sai --
-- nen day la do duoc, khong phai doan.
local BURN_ON, BURN_OFF = nil, nil

local function probeBurnOrder()
  -- Da DO roi thi dung so do, khong tim nua. CFG.BURN_ORDER = { bat,
  -- tat } -- lay tu dong "order: pid N phat lenh X" trong file vet.
  local fixed = CFG.BURN_ORDER
  if fixed ~= nil and fixed[1] ~= nil and fixed[2] ~= nil then
    BURN_ON, BURN_OFF = fixed[1], fixed[2]
    API.trace("effect: burn autocast = CFG.BURN_ORDER " ..
              BURN_ON .. "/" .. BURN_OFF)
    return
  end

  if OrderId == nil then
    API.trace("effect: khong co OrderId -- burn coi nhu LUON BAT")
    return
  end
  -- OrderId KHAC 0 CHI CHUNG MINH "ten nay la mot lenh co that",
  -- KHONG chung minh "no la lenh cua ability nay".
  --
  -- LOI DA SHIP: danh sach dau co "blackarrow" o cuoi, va no trung --
  -- file vet ghi 'blackarrow' 852577/852579. Nhung blackarrow la lenh
  -- cua Black Arrow, mot ability khac han; nut E cua Thieu Thien khong
  -- bao gio phat lenh do, nen bo theo doi im lang khong chay.
  --
  -- Cung lop loi voi AddWeatherEffect nhan ma rac: ham tra ve mot gia
  -- tri "hop le" cho mot dau vao sai.
  --
  -- Gio chi giu hai ten CO LIEN QUAN toi AHfa. Trung thi dung; truot
  -- thi onOrder() ghi vet moi lenh la de nguoi choi bam E mot cai va
  -- doc ra so that -- do, khong doan.
  local cands = { "searingarrows", "flamingarrows" }
  for i = 1, #cands do
    local on  = OrderId(cands[i])
    local off = OrderId(cands[i] .. "off")
    if on ~= nil and on ~= 0 and off ~= nil and off ~= 0 then
      BURN_ON, BURN_OFF = on, off
      API.trace("effect: burn autocast = '" .. cands[i] .. "' " ..
                on .. "/" .. off)
      return
    end
  end
  -- Khong do duoc thi LUON BAT, khong phai luon tat: mot ky nang im
  -- lang khong lam gi la kieu hong te nhat (ADR 0012).
  API.trace("effect: KHONG do duoc lenh autocast cua Searing Arrows -- " ..
            "burn coi nhu LUON BAT")
end

-- Mac dinh BAT khi chua ai bam.
--
-- Nguoc voi mac dinh cua Object Editor (Searing Arrows goc tat san),
-- va do la co y: nguoi choi khong bam gi ma thay ky nang chay la hieu
-- duoc, con bo Go ra mo khoa roi khong thay gi thi tuong la hong.
local function burnOn(pid)
  if BURN_ON == nil then return true end
  local d = S.p[pid]
  return d == nil or d.burnOn ~= false
end

local function onOrder()
  local o = GetIssuedOrderId and GetIssuedOrderId() or nil
  if o == nil then return end
  local pid = heroPid(GetTriggerUnit())
  if pid == nil or S.p[pid] == nil then return end

  if BURN_ON ~= nil and (o == BURN_ON or o == BURN_OFF) then
    S.p[pid].burnOn = (o == BURN_ON)
    return
  end

  -- GHI VET LENH LA, mot lan moi ma.
  --
  -- Day la cach DO ra so that thay vi doan tiep mot cai ten: nguoi
  -- choi bam E mot cai, file vet in ra hai so, va ta ghi thang chung
  -- vao CFG.BURN_ORDER. Loc bo lenh di chuyen/danh thuong -- chung
  -- phat lien tuc va se lam ngap file vet.
  if not CFG.DEV_COMMANDS then return end
  if S.orderSeen == nil then S.orderSeen = {} end
  if S.orderSeen[o] then return end
  S.orderSeen[o] = true
  -- 851971..851999 la vung lenh co ban (move/stop/attack/hold/patrol).
  if o >= 851970 and o <= 851999 then return end
  API.trace("order: pid " .. pid .. " phat lenh " .. o)
end

local FX_CAST = { line = fxLine, chain = fxChain, nova = fxNova,
                  heal = fxHeal, hot = fxHot, wave = fxWave }

local function onSpell()
  local u = GetTriggerUnit()
  if u == nil then return end
  local pid = heroPid(u)
  if pid == nil then return end

  local sk, lv = skillOf(pid, GetSpellAbilityId())
  if sk == nil or sk.fx == nil then return end

  local f = FX_CAST[sk.fx]
  if f ~= nil then f(pid, u, sk, lv) end
end

-- ---------- Ky nang bi dong bat qua su kien sat thuong ----------

local function onDamaged()
  if busy then return end                -- sat thuong cua chinh ta

  local amount = GetEventDamage()
  if amount <= 0.0 then return end

  local tgt = (BlzGetEventDamageTarget ~= nil) and BlzGetEventDamageTarget()
              or GetTriggerUnit()
  local src = GetEventDamageSource()

  -- hero NHAN don. HAI nguon giam sat thuong: bi dong "reduce" va mon
  -- Khien (%chong chiu).
  --
  -- Chung NHAN voi nhau chu khong cong. Cong thi hai nguon du manh se
  -- cham 100% va hero thanh bat tu; nhan thi khong bao gio toi, va ti le
  -- moi nguon dong gop van doc ra duoc.
  --
  -- MOT lan ghi duy nhat, dung luat cua recompute ben duoi: gom het roi
  -- ghi, khong doc-cong-ghi-lai.
  local tp = heroPid(tgt)
  if tp ~= nil and BlzSetEventDamage ~= nil then
    local keep = 1.0

    local sk, lv = skillByFx(tp, "reduce")
    if sk ~= nil then
      local pct = API.skillPct(sk, lv)
      if pct > CFG.FX_REDUCE_CAP then pct = CFG.FX_REDUCE_CAP end
      keep = keep * (1.0 - pct)
    end

    -- Khien chan DON DANH, Ao Choang chan PHEP -- nen phai hoi engine day
    -- don loai gi.
    --
    -- Thieu BlzGetEventDamageType thi KHONG nuot im: coi la don danh
    -- (loai pho bien nhat) va GHI VET mot lan, de "Ao Choang khong an gi"
    -- khong bi tuong la loi can bang. ADR 0012.
    if API.gearMitigPct ~= nil then
      local spell = false
      if BlzGetEventDamageType ~= nil then
        spell = (BlzGetEventDamageType() ~= DAMAGE_TYPE_NORMAL)
      elseif not dmgTypeWarned then
        dmgTypeWarned = true
        API.trace("effect: THIEU BlzGetEventDamageType -- moi don deu tinh la " ..
                  "don danh, mon Ao Choang se khong an gi")
      end
      keep = keep * (1.0 - API.gearMitigPct(tp,
                       spell and "mitig_magic" or "mitig_phys"))
    end

    -- Phap Khi "Huyen Quy Giap": -20% sat thuong nhan, CA HAI loai.
    --
    -- Nhan vao 'keep' chu khong tru thang: no phai chong len Khien/Ao
    -- Choang theo kieu NHAN, neu khong hai nguon giam cong lai se vuot
    -- tran va bien hero thanh bat tu.
    if API.relicVal ~= nil then
      local rv = API.relicVal(tp, "huyenquy", "mitig")
      if rv > 0.0 then keep = keep * (1.0 - rv) end
    end

    -- Tran cung mot lan nua, de mot lan chinh so tay khong bien hero
    -- thanh bat tu ma khong ai nhan ra.
    local least = 1.0 - (CFG.GEAR_MITIG_CAP or 1.0)
    if keep < least then keep = least end

    if keep < 1.0 then BlzSetEventDamage(amount * keep) end
  end

  local sp = heroPid(src)

  -- "Kiem": %sat thuong GAY RA -- phan DON THUONG.
  --
  -- Sat thuong ky nang khong toi day (hit() bat 'busy', ham nay da return
  -- o dong dau); no duoc nhan trong skillDamage(). Hai duong, hai cho,
  -- khong chong nhau.
  --
  -- Ghi de len 'amount' luon, de "cleave" ben duoi van % sang muc tieu
  -- canh theo con so DA nhan -- chem lan cua mot cu danh manh thi phan
  -- van sang cung phai manh theo.
  --
  -- Dieu kien 'tp == nil' de hai nhanh khong dam nhau: neu ca nguon lan
  -- muc tieu deu la hero (ban minh -- map nay dong minh nen khong xay ra,
  -- nhung dung de no am tham sai) thi nhanh nay se ghi de len con so da
  -- giam o tren.
  if sp ~= nil and tp == nil and BlzSetEventDamage ~= nil
     and API.gearDmgPct ~= nil then
    local pct = API.gearDmgPct(sp)
    -- Phap Khi "Hoa Vu Linh Chau": +25% sat thuong gay ra.
    --
    -- CONG vao cung mot 'pct' roi nhan MOT lan, khong nhan hai lan noi
    -- tiep: hai lan nhan thi Kiem va Phap Khi tu khuech dai nhau, va
    -- duong cong x967 khong con dung o cuoi van.
    if API.relicVal ~= nil then
      pct = pct + API.relicVal(sp, "hoavu", "dmgUp")
    end
    if pct > 0.0 then
      amount = amount * (1.0 + pct)
      BlzSetEventDamage(amount)
    end
  end

  -- NHAN: hut mau theo con so CUOI CUNG, tuc sau khi Kiem da cong %.
  -- Dat sau khoi tren chu khong truoc: hai mon nhan voi nhau, va thu tu
  -- nay la cho quyet dinh dieu do.
  if sp ~= nil and tp == nil and API.gearLifesteal ~= nil then
    API.gearLifesteal(sp, amount)
  end

  -- "cleave": hero GAY don. Van % sat thuong sang muc tieu ben canh.
  if sp ~= nil and tgt ~= nil then
    local sk, lv = skillByFx(sp, "cleave")
    if sk ~= nil then
      local splash = amount * API.skillPct(sk, lv)
      if splash >= 1.0 then
        enemiesNear(GetUnitX(tgt), GetUnitY(tgt), CFG.FX_CLEAVE_AOE,
          function(e)
            if e ~= tgt then hit(src, e, splash, CFG.FX_HIT_CLEAVE) end
          end)
      end
    end
  end

  -- "bounce": don danh NAY sang muc tieu ben canh, moi lan yeu di.
  --
  -- VI SAO LAM BANG LUA CHU KHONG DE ENGINE LO. Ban dau A012 la ban
  -- sao Moon Glaive va KHONG co dong Lua nao -- de Warcraft tu nay.
  -- No khong nay. Do lai thi ro:
  --
  --   war3map.w3a  A012 khong co MOT truong du lieu nao -- so muc tieu
  --                va do hao deu thua ke tu Amgl goc, ma goc chi co 3
  --                bac trong khi ta vua dat alev = 10
  --   war3map.w3u  H002 khong khai 'ua1w' -- kieu vu khi thua ke tu
  --                unit goc, va Moon Glaive chi nay duoc khi vu khi la
  --                Missile (Bounce)
  --
  -- Sua o Object Editor thi phai dung ca hai cho, va cho thu hai la
  -- mot gia thuyet chua chung minh. Lam o day thi:
  --   chay voi MOI hero, khong phu thuoc unit goc
  --   la PHAN TRAM cua don danh that -> tu scale, khong teo
  --   dung lai dung bo may ma cleave da chay hang tram wave
  --
  -- Doi lai: mat hoat anh glaive bay vong cua Warcraft. Neu mai nay
  -- dat 'ua1w = mbounce' trong World Editor de lay lai hoat anh do thi
  -- PHAI bo 'fx = "bounce"' khoi CFG.SKILLS -- de ca hai la sat thuong
  -- nhan doi.
  if sp ~= nil and tgt ~= nil and tp == nil then
    local sk, lv = skillByFx(sp, "bounce")

    -- GHI VET MOT LAN cho moi nguoi, ngay don danh dau tien.
    --
    -- "Khong thay no nay" co HAI nguyen nhan rat khac nhau va nhin
    -- giong het nhau tu ngoai: ky nang CHUA MO KHOA (bac 0), hay da mo
    -- ma vong lap khong tim ra muc tieu nao trong tam. Mot dong vet
    -- tach duoc hai cai do; doan thi khong.
    local d = S.p[sp]
    if d ~= nil and not d.bounceLogged then
      d.bounceLogged = true
      if sk == nil then
        API.trace("bounce: pid " .. sp ..
                  " KHONG co ky nang 'bounce' dang mo -- chua mua Nguyet Nhan?")
      else
        API.trace("bounce: pid " .. sp .. " co Nguyet Nhan bac " .. lv ..
                  ", " .. string.format("%.0f%%", API.skillPct(sk, lv) * 100) ..
                  " moi cu nay, tam " .. (CFG.FX_BOUNCE_HOP or 350.0))
      end
    end

    if sk ~= nil then
      local share = amount * API.skillPct(sk, lv)
      local hops  = CFG.FX_BOUNCE_MAX or 3
      local fall  = CFG.FX_BOUNCE_FALLOFF or 0.70
      local reach = CFG.FX_BOUNCE_HOP or 350.0

      -- 'seen' phai chua CA muc tieu dau: khong thi cu nay dau tien
      -- quay nguoc lai chinh con vua an don thuong.
      local seen, cx, cy = { [GetHandleId(tgt)] = true }, GetUnitX(tgt), GetUnitY(tgt)
      local landed = 0
      for _ = 1, hops do
        if share < 1.0 then break end
        local best, bestD = nil, nil
        enemiesNear(cx, cy, reach, function(e)
          if seen[GetHandleId(e)] then return end
          local dd = API.distXY(cx, cy, GetUnitX(e), GetUnitY(e))
          if bestD == nil or dd < bestD then best, bestD = e, dd end
        end)
        if best == nil then break end
        seen[GetHandleId(best)] = true
        cx, cy = GetUnitX(best), GetUnitY(best)
        hit(src, best, share, CFG.FX_HIT_BOUNCE)
        share = share * fall
        landed = landed + 1
      end

      -- Lan dau NAY TRUNG duoc it nhat mot con thi ghi mot dong. Khong
      -- co dong nay thi "da mo khoa ma van khong thay" khong phan biet
      -- duoc voi "danh mot con dung mot minh" -- ma truong hop sau la
      -- binh thuong, khong phai loi.
      if landed > 0 and d ~= nil and not d.bounceHit then
        d.bounceHit = true
        API.trace("bounce: pid " .. sp .. " nay trung " .. landed .. " con")
      end
    end
  end

  -- "burn": hero GAY don. De lai mot lop dot tren chinh muc tieu do.
  --
  -- Tinh theo % DON DANH THAT ('amount' da qua Kiem va Phap Khi o tren),
  -- y het cleave. Do la ly do no khong bao gio teo: no khong co con so
  -- rieng nao de bi bo lai.
  --
  -- 'tp == nil' de khong dot dong doi neu mai nay map co sat thuong
  -- cheo phe. overTick() goi hit(), ma hit() bat 'busy' nen lop dot
  -- khong tu de ra lop dot moi.
  if sp ~= nil and tgt ~= nil and tp == nil and burnOn(sp) then
    local sk, lv = skillByFx(sp, "burn")
    if sk ~= nil then
      burnApply(sp, tgt, amount * API.skillPct(sk, lv))
    end
  end
end

-- ============================================================
--  MOT cho duy nhat ghi chi so hero
--
--  LUAT. Moi nguon chi KHAI BAO no dong gop bao nhieu; ham recompute
--  cong het lai roi ghi MOT lan. Khong cho nao duoc doc-cong-ghi-lai.
--
--  Vi sao phai co luat nay -- day la loi that da xay ra:
--
--    Bat Hoai va Hieu Lenh truoc day deu ghi giap kieu doc-cong-ghi.
--    Nang Hieu Lenh trong luc Bat Hoai dang bat thi "giap nen" bi doc
--    nham la giap DA CONG buff, nen luc buff het tru ra khong khop.
--    Lan vet voi giap nen 5: sau mot chu ky hero con 9.05 thay vi 5.81,
--    va no cong don moi lan lap.
--
--  Bon nguon hien co, va se con them khi Hvwd/Hkal co ky nang:
--    chi so       nen + Linh Can, roi nhan % cua bi dong "stat"
--    sat thuong   nen x Trang Bi
--    giap         nen + aura "Hieu Lenh" + buff "Bat Hoai"
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Doc chi so NEN cua hero. Goi DUNG MOT LAN, ngay sau khi tao hero va
-- truoc khi bat cu he nao cong vao.
--
-- Doc lai lan hai la nhan chong: lan do se doc ra con so da cong roi.
local function baseCapture(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  local h = d.hero
  d.base = {
    str   = GetHeroStr(h, false),
    agi   = GetHeroAgi(h, false),
    int   = GetHeroInt(h, false),
    dmg   = (BlzGetUnitBaseDamage ~= nil) and BlzGetUnitBaseDamage(h, 0) or 0,
    armor  = (BlzGetUnitArmor ~= nil) and BlzGetUnitArmor(h) or 0.0,
  }
end

-- Giap cua Hieu Lenh va Bat Hoai khong con tinh o file nay.
--
-- Hai ham cu -- auraGiap() va buffGiap() -- da xoa. Chung ton tai de
-- cong giap vao BlzSetUnitArmor, ma dong do chinh la thu dong bang phan
-- chi so. Gio giap nam trong truong cua chinh hai ability do
-- (CFG.SKILL_CARRY_BASE) va Warcraft cong.
--
-- DOI HANH VI: aura cua Warcraft co BAN KINH, ban Lua cu thi khong --
-- no cong cho ca doi du dung dau tren map. Map nay ba nguoi gan nhu
-- luon dung chung mot cho nen khac biet nho, nhung day la thu can nhin
-- lai neu doi hinh tach xa nhau.

local function recompute(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  local h = d.hero
  if d.base == nil then baseCapture(pid) end
  local n = d.base

  -- ---------- Chi so ----------
  -- nen + Linh Can, roi nhan % cua bi dong "stat" (Luyen The).
  local cultAdd = API.cultStatBonus(pid)
  -- Luyen The cong PHANG, khong nhan phan tram -- xem CFG.SKILLS A004.
  local sk, lv = skillByFx(pid, "stat")
  local bonus = 0.0
  if sk ~= nil and API.skillStat ~= nil then
    bonus = API.skillStat(sk, lv, API.cultRank and API.cultRank(pid) or 1)
  end

  -- Chi so tu QUAY cong vao truoc khi nhan %: mot cong thuc duy nhat,
  -- khong phai nho thu tu.
  local q = d.rollStats or {}
  local qStr, qAgi, qInt = q.str or 0, q.agi or 0, q.int or 0

  -- Trang Bi: bon mon cong diem (Ao/Giay/Mu/Nhan). MOT loi goi tra ve ba
  -- so -- khong cho nao doc chi so hien tai roi cong vao.
  local gStr, gAgi, gInt = 0.0, 0.0, 0.0
  if API.gearStat ~= nil then gStr, gAgi, gInt = API.gearStat(pid) end

  if CFG.CULT_STAT_MODE == "primary" then
    -- Cong vao chi so cao nhat cua NEN, khong phai cua hien tai -- chi
    -- so hien tai doi theo chinh phep cong nay thi no se nhay qua nhay
    -- lai giua hai chi so.
    local s, a, i = n.str + qStr + gStr + bonus,
                    n.agi + qAgi + gAgi + bonus,
                    n.int + qInt + gInt + bonus
    if s >= a and s >= i then s = s + cultAdd
    elseif a >= i then a = a + cultAdd
    else i = i + cultAdd end
    SetHeroStr(h, math.floor(s + 0.5), true)
    SetHeroAgi(h, math.floor(a + 0.5), true)
    SetHeroInt(h, math.floor(i + 0.5), true)
  else
    SetHeroStr(h, math.floor(n.str + qStr + gStr + cultAdd + bonus + 0.5), true)
    SetHeroAgi(h, math.floor(n.agi + qAgi + gAgi + cultAdd + bonus + 0.5), true)
    SetHeroInt(h, math.floor(n.int + qInt + gInt + cultAdd + bonus + 0.5), true)
  end

  -- ---------- Mau / mana toi da: KHONG dong vao ----------
  --
  -- The 3 cua he quay tung dinh cong mau/mana toi da. Bo, vi ban 1.31.1
  -- KHONG phoi ra truong nao cong THEM mau toi da ("-nat ilf": co
  -- STRENGTH_BONUS_ISTR, DEFENSE_BONUS_IDEF, nhung khong co MAX LIFE).
  -- Chi con BlzSetUnitMaxHP, ma ham do GHI DE -- dung cai da dong bang
  -- giap suot may ngay.
  --
  -- The 3 gio ra VANG. Mau/mana van hoan toan cua engine, suy tu Str va
  -- Int nhu Warcraft van lam.

  -- ---------- Sat thuong va giap: DE WARCRAFT TU TINH ----------
  --
  -- Ham nay KHONG con ghi BlzSetUnitBaseDamage hay BlzSetUnitArmor.
  --
  -- Ban truoc ghi ca hai, va do la ly do chi so len ma don thuong voi
  -- giap dung yen: n.giap la BlzGetUnitArmor() chup luc TAO HERO (giap
  -- tong hoi Agi con bang 5), nen moi lan tinh lai deu dong bang phan
  -- Agi vao con so do. Agi 511 ma giap van bang 2.
  --
  -- Phan cong them cua Hieu Lenh va Bat Hoai gio nam trong CHINH TRUONG
  -- cua hai ability do (CFG.SKILL_CARRY_BASE), nen Warcraft cong -- khong
  -- con ai phai so huu cong thuc giap nua.
  --
  -- Sat thuong cua Trang Bi KHONG can vat mang, va do la ly do mon Kiem
  -- cong % chu khong cong diem: % thi nhan duoc ngay trong onDamaged va
  -- skillDamage, khong phai muon truong cua mot ability nao ca.
  -- (API.gearMult da bo -- khong file nao doc no.)
end

-- Aura cham toi NGUOI KHAC, nen doi bac cua mot nguoi la ca doi phai
-- tinh lai.
local function recomputeAll()
  for i = 1, #S.pids do recompute(S.pids[i]) end
end

-- ---------- Khoi dong ----------

local function startSkillFx()
  local tSpell = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tSpell, EVENT_PLAYER_UNIT_SPELL_EFFECT)
  TriggerAddAction(tSpell, onSpell)

  if EVENT_PLAYER_UNIT_DAMAGED ~= nil then
    local tDmg = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(tDmg, EVENT_PLAYER_UNIT_DAMAGED)
    TriggerAddAction(tDmg, onDamaged)
  else
    API.warn(nil, "Khong co EVENT_PLAYER_UNIT_DAMAGED -- " ..
      "Chem Lan, Thieu Thien va Da Sat se khong chay.")
  end

  -- Nut bat/tat cua Thieu Thien (A011). Do ten lenh TRUOC khi dang ky:
  -- khong do duoc thi khong can trigger nao, burn se luon bat.
  probeBurnOrder()
  -- Dang ky KE CA khi do khong ra: luc do onOrder() lam viec khac --
  -- ghi vet moi lenh la, de nguoi choi bam E mot cai la doc duoc so
  -- that. Do, khong doan tiep mot cai ten.
  if EVENT_PLAYER_UNIT_ISSUED_ORDER ~= nil then
    local tOrd = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(tOrd, EVENT_PLAYER_UNIT_ISSUED_ORDER)
    TriggerAddAction(tOrd, onOrder)
  end

  -- MOT dong ho cho moi lop dot cua ca map -- xem burnApply().
  S.burn, S.hot = {}, {}
  S.burnTimer = CreateTimer()
  TimerStart(S.burnTimer, CFG.FX_BURN_TICK or 0.5, true, overTick)

  API.trace("effect: san sang (cast + damage + burn)")
end

API.heroBaseCapture  = baseCapture
API.heroPidOf       = heroPid
API.heroRecompute    = recompute
API.heroRecomputeAll = recomputeAll
API.skillFxRecompute = recomputeAll   -- ten cu, giu cho cho goi san co
API.startSkillFx     = startSkillFx
end
--#endregion 2_player/7_effect.lua

--#region 2_player/8_shop.lua
do
-- ============================================================
--  8_shop.lua  --  The V: Shop
--
--  He DUY NHAT tieu VANG, va he duy nhat ban do TIEU HAO. Ba the kia
--  ban thu vinh vien; the nay ban mot lan dung.
--
--  Mua la HANH DONG -> phai qua kenh dong bo, khong duoc lam cuc bo.
--  Chi viec mo bang va doi the moi la UI thuan.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Cung khuon voi 6_relic.lua: API.pick lo phan TEN, mo ta thi tung he
-- tu lay vi ten truong khac nhau.
local function descOf(item)
  if API.lang() == "en" then return item.desc_en or item.desc end
  return item.desc or item.desc_en
end

-- Con o trong tui khong? Warcraft cho 6 o; mua khi day tui thi item roi
-- xuong dat ngay duoi chan hero, va nguoi choi mat vang vi mot cai o ma
-- khong hieu tai sao.
-- Tim o dang giu item CUNG LOAI va con cho gop. Tra ve chinh item do.
local function stackSlot(u, itemId)
  if u == nil or UnitInventorySize == nil or UnitItemInSlot == nil then return nil end
  if GetItemTypeId == nil or GetItemCharges == nil then return nil end
  local stackMax = CFG.SHOP_STACK_MAX or 1
  if stackMax <= 1 then return nil end
  local n = UnitInventorySize(u)
  for i = 0, (n or 0) - 1 do
    local it = UnitItemInSlot(u, i)
    if it ~= nil and GetItemTypeId(it) == itemId then
      local c = GetItemCharges(it)
      -- 0 luot = item khong dung he luot. Gop vao la dem duoc nhung con
      -- so hien ra co the khong dung voi so lan dung duoc -- nen bo qua,
      -- de no chiem o rieng cho that.
      if c ~= nil and c >= 1 and c < stackMax then return it end
    end
  end
  return nil
end

-- Con cho de NHAN them mot lo khong: hoac con o trong, hoac co mot o
-- cung loai chua day luot.
-- Mon cong thang vao bo dem (da Huyen Thiet) thay vi bo item vao tui.
local function isIronItem(item)
  return (item ~= nil) and (item.iron ~= nil) and (item.iron > 0)
end

local function hasRoom(u, itemId)
  -- maItem = nil nghia la mon nay khong dung tui do -- luon con cho.
  if itemId == nil then return true end
  if not CFG.SHOP_CHECK_BAG then return true end
  if u == nil then return false end
  if stackSlot(u, itemId) ~= nil then return true end
  if UnitInventorySize == nil or UnitItemInSlot == nil then return true end

  -- KHONG CO TUI = KHONG CO CHO, chu khong phai "khong biet nen cho qua".
  --
  -- Ban truoc tra ve true o day, va do la mot loi im lang dat dung cho
  -- te nhat: UnitAddItemById tren mot unit khong co tui van tra ve
  -- HANDLE ITEM -- no tao item roi tha xuong DAT duoi chan. Nen
  -- give() dem "phat 10/10 thanh cong" trong khi ca 20 lo nam duoi
  -- san, va UnitItemInSlot() thi bao o trong.
  --
  -- Unit muon cam do phai co ability "Inventory (Hero)" (AInv) trong
  -- Object Editor. Xem CFG.HERO_COMMON_ABILITIES.
  local n = UnitInventorySize(u)
  if n == nil or n <= 0 then return false end

  for i = 0, n - 1 do
    if UnitItemInSlot(u, i) == nil then return true end
  end
  return false
end

-- Chay tren MOI may, tu kenh dong bo.
-- Mua THANH CONG thi bao CA DOI ("[Ten] da mua ..."), that bai thi bao
-- RIENG. Loi la chuyen cua tui tien mot nguoi; con mon vua mua la thu
-- ca doi nen thay, vi no noi len doi phuong dang manh len theo huong
-- nao. Ham nay chay trong syncOn nen API.say hien o moi may.
local function buy(pid, i)
  local item = CFG.SHOP[i]
  if item == nil then return end
  -- Mon phat cung khong mua duoc, ke ca khi op toi bang duong khac.
  -- Ben NHAN kiem lai, khong tin cu bam: ben gui la cuc bo.
  if item.forSale == false then return end

  local d = S.p[pid]
  if d == nil then return end

  -- Phan hoi nam tren DONG VUA BAM. Mot dong chat thi troi di, ma nguoi
  -- choi luc do dang nhin vao bang chu khong nhin o chat.
  local function flash(kind)
    if API.panelFlash ~= nil then API.panelFlash(pid, i, kind) end
  end

  -- Da: khong dung tui do, nen khong can hero va khong can kiem o.
  if isIronItem(item) then
    if not API.spendGold(pid, item.price) then
      API.msg(pid, CFG.C_RED .. API.t("no_gold") .. CFG.C_END ..
        API.t("need_have", API.num(item.price), API.num(API.getGold(pid))))
      flash("fail")
      API.panelRefresh(pid)
      return
    end
    d.iron = (d.iron or 0) + item.iron
    API.say(pid, API.t("shop_bought",
      CFG.C_JADE .. API.pick(item) .. CFG.C_END, API.num(item.price)))
    flash("ok")
    API.panelRefresh(pid)
    return
  end

  if d.hero == nil then return end

  if not hasRoom(d.hero, item.item) then
    API.msg(pid, CFG.C_RED .. API.t("shop_full") .. CFG.C_END)
    flash("fail")
    return
  end

  if not API.spendGold(pid, item.price) then
    API.msg(pid, CFG.C_RED .. API.t("no_gold") .. CFG.C_END ..
      API.t("need_have", API.num(item.price), API.num(API.getGold(pid))))
    flash("fail")
    API.panelRefresh(pid)
    return
  end

  -- Da co mot o cung loai chua day: cong them mot luot, khong chiem o
  -- moi. Lam truoc khi tao item moi, neu khong thi lan nao cung ra o moi
  -- va gop thanh vo nghia.
  local old = stackSlot(d.hero, item.item)
  if old ~= nil then
    local c = GetItemCharges(old) + 1
    SetItemCharges(old, c)
    API.say(pid, API.t("shop_stack",
      CFG.C_JADE .. API.pick(item) .. CFG.C_END, c, API.num(item.price)))
    flash("ok")
    API.panelRefresh(pid)
    return
  end

  -- UnitAddItemById tra ve nil khi ma item khong ton tai. Hoan tien va
  -- BAO RO -- mot ma sai ma nuot im la nguoi choi mat vang khong hieu vi
  -- sao, va ta khong biet minh go sai ma nao (ADR 0012).
  local it = UnitAddItemById(d.hero, item.item)
  if it == nil then
    API.addGold(pid, item.price)
    API.warn(pid, "Khong tao duoc item " ..
      API.idToStr(item.item) .. " -- da hoan " .. API.num(item.price) ..
      " vang. Kiem CFG.SHOP.")
    flash("fail")
    API.panelRefresh(pid)
    return
  end

  API.say(pid, API.t("shop_bought",
    CFG.C_JADE .. API.pick(item) .. CFG.C_END, API.num(item.price)))
  flash("ok")
  API.panelRefresh(pid)
end

-- Phat item khong tinh tien. Dung cho qua khoi dau (CFG.START_ITEMS).
--
-- Di qua CUNG duong voi buy(): gop vao o cu neu co, khong thi tao o
-- moi. Nho vay qua khoi dau va do mua deu nam chung mot o, va luat gop
-- chi viet mot lan.
local function give(pid, code, count)
  local d = S.p[pid]
  if d == nil or d.hero == nil or count == nil or count <= 0 then return 0 end

  local item
  for i = 1, #CFG.SHOP do
    if CFG.SHOP[i].code == code then item = CFG.SHOP[i] end
  end
  if item == nil then
    API.warn(pid, "shopGive: khong co mon '" .. tostring(code) ..
      "' trong CFG.SHOP.")
    return 0
  end

  -- Bao RO khi unit khong co tui, thay vi tha do xuong dat roi bao
  -- thanh cong.
  if UnitInventorySize ~= nil then
    local n = UnitInventorySize(d.hero)
    if n == nil or n <= 0 then
      API.warn(nil, "Hero khong co tui do (thieu ability " ..
        "Inventory/AInv) -- khong phat duoc " .. tostring(code))
      API.trace("shop: hero KHONG CO TUI, bo qua " .. tostring(code))
      return 0
    end
  end

  local done = 0
  for _ = 1, count do
    local old = stackSlot(d.hero, item.item)
    if old ~= nil then
      SetItemCharges(old, GetItemCharges(old) + 1)
      done = done + 1
    elseif hasRoom(d.hero, item.item) then
      local it = UnitAddItemById(d.hero, item.item)
      if it == nil then break end
      done = done + 1
    else
      break   -- het cho, dung han chu khong lam roi item xuong dat
    end
  end

  API.trace("shop: phat " .. done .. "/" .. count .. " " .. code .. " cho pid " .. pid)
  return done
end

-- ---------- The trong bang ----------

local function tabItems(pid)
  local gold = API.getGold(pid)
  local hero = (S.p[pid] or {}).hero
  local out  = {}
  for i = 1, #CFG.SHOP do
    local item = CFG.SHOP[i]
    -- Mon phat cung (thap thu) khong bay ban.
    --
    -- BO TRONG o do chu KHONG don danh sach lai: buy(pid, i) tra
    -- CFG.SHOP[i] bang chinh chi so nay. Don lai thi chi so lech mot va
    -- moi cu bam mua nham mon ben canh -- kieu sai im lang, nguoi choi
    -- chi biet khi thay minh mua phai thu khac.
    --
    -- Than kieu "list" tu an dong nao out[i] == nil (xem refreshList).
    if item.forSale ~= false then
      local room = hasRoom(hero, item.item)
      -- Icon da: lay cai 10_fortune.lua DO DUOC luc vao map, khong go
      -- tay. Doc o day chu khong o startShop vi shop khoi dong TRUOC quay.
      local ic = item.icon
      if isIronItem(item) and API.fortuneIcon ~= nil then
        ic = API.fortuneIcon("iron") or ic
      end
      out[i] = {
        icon      = ic,
        name       = API.pick(item),
        desc      = descOf(item),
        -- Trang thai la CHO TRONG TUI, khong phai gia: gia da nam tren
        -- nut roi, in hai lan la thua.
        status = room and "" or (CFG.C_RED .. API.t("shop_full") .. CFG.C_END),
        btn       = API.t("btn_buy") .. "  " .. API.num(item.price) .. " " ..
                    API.t("cur_gold"),
        btnOn    = (gold >= item.price) and room,
      }
    end
  end
  return out
end

local function tabItemAction(pid, i)
  if CFG.SHOP[i] == nil then return end
  API.syncSend(pid, CFG.OP_SHOP, i)
end

-- Do ma item va icon NGAY LUC VAO MAP, khong doi toi luc ai do bam mua.
--
-- Hai thu trong CFG.SHOP deu la phong doan: ma item ('phea', 'pman') va
-- duong dan icon. Doan sai ma thi nguoi choi bam mua moi biet; doan sai
-- icon thi o icon ra XANH LA -- dung loi ma BTNRingViolet da dinh.
--
-- CreateItem tra ve nil khi ma khong ton tai, nen tao thu mot cai roi
-- xoa ngay la do duoc ca hai: ma co that khong, va icon THAT cua no la
-- gi. Icon doc duoc thi ghi de len duong dan trong CFG -- lay so do
-- duoc thay cho so go tay.
local function probeItems()
  if CreateItem == nil then return end
  local bad = {}
  for i = 1, #CFG.SHOP do
    local item = CFG.SHOP[i]
    local it = (item.item ~= nil) and CreateItem(item.item, 0.0, 0.0) or nil
    if item.item == nil then
      -- Mon khong dung tui do (da Huyen Thiet): khong co gi de do.
    elseif it == nil then
      bad[#bad + 1] = API.idToStr(item.item)
    else
      if BlzGetItemIconPath ~= nil then
        local p = BlzGetItemIconPath(it)
        if p ~= nil and p ~= "" then item.icon = p end
      end
      -- So luot GOC. Bang 0 nghia la item nay khong dung he luot, va
      -- luc do gop lo khong chay -- phai biet truoc chu khong doi toi
      -- luc nguoi choi mua cai thu hai moi phat hien.
      local c = (GetItemCharges ~= nil) and GetItemCharges(it) or -1
      API.trace("shop: " .. item.code .. " = " .. API.idToStr(item.item) ..
                ", luot goc " .. c .. ", icon " .. tostring(item.icon))
      if c == 0 then
        API.info(nil, CFG.C_GREY .. "[shop] " .. API.pick(item) ..
          " co 0 luot -- khong gop o duoc, moi lo se chiem mot o." .. CFG.C_END)
      end
      RemoveItem(it)
    end
  end
  if #bad > 0 then
    API.warn(nil, "Shop: khong co item " ..
      table.concat(bad, " ") .. " -- sua CFG.SHOP.")
  end
end

local function startShop()
  probeItems()
  API.panelAddTab({
    name        = API.t("panel_shop"),
    kind       = "list",
    rows      = #CFG.SHOP,
    items      = tabItems,
    itemAction = tabItemAction,
    empty      = API.t("shop_empty"),
  })
  API.syncOn(CFG.OP_SHOP, buy)
  API.trace("shop: " .. #CFG.SHOP .. " mon, the san sang")
end

API.shopBuy   = buy
API.shopGive  = give
API.startShop = startShop
end
--#endregion 2_player/8_shop.lua

--#region 2_player/9_useitem.lua
do
-- ============================================================
--  9_useitem.lua  --  Dung do trong tui bang HANG SO TREN (canh Esc)
--
--  Warcraft chi gan san san tui do vao numpad (7/8/4/5/1/2). May
--  khong co numpad, va tay phai roi chuot de voi sang numpad, nen
--  gan them hang so 1..6 o tren.
--
--  Day la THEM, khong phai thay: numpad van chay nhu cu.
--
--  VI SAO PHAI QUA KENH DONG BO.
--
--  Su kien phim la DAU VAO CUC BO -- no chi no tren may cua nguoi bam.
--  Bang phim R goi UnitUseItem thang o day thi may do dung mot lo thuoc
--  ma hai may kia khong biet -> lech ban game. Bang chi bat/tat khung
--  hinh nen lam cuc bo duoc; dung do thi doi TRANG THAI, nen phai di
--  qua API.syncSend nhu moi hanh dong khac (ADR 0012).
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Chay tren MOI may, tu kenh dong bo. o = 0..5.
local function use(pid, o)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if UnitItemInSlot == nil or UnitUseItem == nil then return end

  local it = UnitItemInSlot(d.hero, o)
  if it == nil then return end
  UnitUseItem(d.hero, it)
end

local function startUseItem()
  if CFG.ITEM_KEYS == nil or #CFG.ITEM_KEYS == 0 then return end
  if BlzTriggerRegisterPlayerKeyEvent == nil then
    API.trace("useitem: KHONG co BlzTriggerRegisterPlayerKeyEvent")
    return
  end

  API.syncOn(CFG.OP_ITEM, use)

  local missing, done = {}, 0
  for k = 1, #CFG.ITEM_KEYS do
    local name = CFG.ITEM_KEYS[k]
    local key = _G["OSKEY_" .. name]
    if key == nil then
      -- Go sai ten hang la tra ve nil roi im lang khong lam gi ca --
      -- ghi ra chu khong nuot (ADR 0012). "-nat oskey" liet ke ten that.
      missing[#missing + 1] = "OSKEY_" .. name
    else
      local t = CreateTrigger()
      for i = 1, #S.pids do
        BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), key, 0, true)
      end
      -- Bien k cua vong for so hoc la RIENG cho tung vong trong Lua,
      -- nen moi closure bat dung o cua no.
      TriggerAddAction(t, function()
        API.syncSend(GetPlayerId(GetTriggerPlayer()), CFG.OP_ITEM, k - 1)
      end)
      done = done + 1
    end
  end

  if #missing > 0 then
    API.trace("useitem: THIEU hang so " .. table.concat(missing, " ") ..
              " -- go '-nat oskey' de tim ten dung")
  end
  API.trace("useitem: gan " .. done .. "/" .. #CFG.ITEM_KEYS .. " phim")
end

API.useItem      = use
API.startUseItem = startUseItem
end
--#endregion 2_player/9_useitem.lua

--#region 2_player/10_fortune.lua
do
-- ============================================================
--  10_fortune.lua  --  The VI: Quay thuong
--
--  Giet tinh anh 1 luot, boss 3 luot. Moi luot mo CFG.FORTUNE_KINDS
--  the, chon MOT.
--
--    "gold"    vang, PHANG, ngau nhien FORTUNE_GOLD_MIN..MAX
--    "stat"    +V vao MOT chi so ngau nhien trong ba
--    "lumber"  Go, PHANG va CO DINH -- xem CFG.FORTUNE_LUMBER
--
--  V = CFG.FORTUNE_VALUE x CULT_STAT_STEP^(bac-1), ngau nhien +-30%.
--  CHI the "stat" dung V. Dung CHINH buoc cua Tu Vi nen no tu bam theo
--  -- doi duong cong Tu Vi thi the nay tu co theo.
--
--  The "gold" KHONG dung V: no la TIEN, ma tien thi phang. Nhung no van
--  song song voi the "stat", vi thu no mua (bac Trang Bi) moi la thu
--  leo -- xem chu thich CFG.FORTUNE_KINDS.
--
--  SO THE DOC TU CFG, khong go cung. Them mot the la them mot dong vao
--  CFG.FORTUNE_KINDS va mot nhanh trong take(); khung tu co theo.
--
--  THE SINH O DAU, va vi sao cho do.
--
--  GetRandomInt cua Warcraft da dong bo san giua cac may, VOI DIEU KIEN
--  moi may goi cung so lan va cung thu tu. Goi no trong mot nhanh
--  GetLocalPlayer() la moi may tieu mot so khac nhau tu chuoi ngau
--  nhien, va tu giay do MOI so ngau nhien cua ca van deu lech.
--
--  Nen the duoc sinh trong addRolls() -- ham do chay tu su kien quai
--  chet, tuc chay tren MOI may. Mo bang la UI thuan, khong sinh gi ca.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Gia tri mot the o bac hien tai, da nhan he so ngau nhien.
local function rollValue(pid)
  local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
  local v = CFG.FORTUNE_VALUE * CFG.CULT_STAT_STEP ^ (rank - 1)
  local lo = math.floor(v * CFG.FORTUNE_RANGE_MIN * 100.0 + 0.5)
  local hi = math.floor(v * CFG.FORTUNE_RANGE_MAX * 100.0 + 0.5)
  if hi < lo then hi = lo end
  return GetRandomInt(lo, hi) / 100.0
end

-- Sinh mot the theo LOAI. Tach rieng de them loai moi la them mot
-- nhanh, khong phai sua vong lap.
--
-- Moi nhanh goi GetRandomInt DUNG SO LAN NHU NHAU tren moi may -- do la
-- dieu kien duy nhat de chuoi ngau nhien khong lech (xem dau file).
local function makeCard(pid, kind, v)
  if kind == "gold" then
    return { kind = kind,
             amount = GetRandomInt(CFG.FORTUNE_GOLD_MIN, CFG.FORTUNE_GOLD_MAX) }
  elseif kind == "stat" then
    return { kind = kind, amount = math.floor(v + 0.5),
             stat = CFG.FORTUNE_STATS[GetRandomInt(1, #CFG.FORTUNE_STATS)] }
  elseif kind == "lumber" then
    -- CO DINH, khong goi GetRandomInt. Xem CFG.FORTUNE_LUMBER.
    return { kind = kind, amount = CFG.FORTUNE_LUMBER or 1 }
  elseif kind == "iron" then
    -- The da da bo khoi CFG.FORTUNE_KINDS, nhanh nay giu de bat lai
    -- bang mot dong CFG neu can. Khong co CFG.FORTUNE_IRON nua thi coi
    -- nhu 0 chu khong sap.
    return { kind = kind, amount = CFG.FORTUNE_IRON or 0 }
  end
  API.trace("fortune: khong biet loai the '" .. tostring(kind) .. "'")
  return nil
end

-- Rut mot luot the moi. Chay tren MOI may -- xem chu thich dau file.
--
-- RUT CFG.FORTUNE_DRAW TRONG SO CFG.FORTUNE_KINDS. Mo ca ba the thi
-- no thanh "chon cai to nhat", ma cai to nhat thi tinh ra duoc -- tuc
-- khong con la lua chon. Rut hai trong ba thi moi luot la mot cau hoi
-- khac: Go/Chi So, Go/Vang, hay Chi So/Vang.
--
-- DONG BO: ham nay chay tu addRolls(), tuc tu su kien quai chet, tuc
-- tren MOI may. Moi may boc cung thu tu tu cung chuoi ngau nhien nen
-- ra cung bo the. Tuyet doi khong goi tu callback frame (ADR 0012).
--
-- Boc kieu "rut khong hoan lai": sao chep danh sach roi nhat ra, de
-- khong bao gio ra hai the trung loai.
local function drawCards(pid)
  local d = S.p[pid]
  if d == nil then return end
  local v = rollValue(pid)

  local pool = {}
  for i = 1, #CFG.FORTUNE_KINDS do pool[i] = CFG.FORTUNE_KINDS[i] end

  local want = CFG.FORTUNE_DRAW or #pool
  if want > #pool then want = #pool end

  local out = {}
  for _ = 1, want do
    local k = GetRandomInt(1, #pool)
    local kind = pool[k]
    table.remove(pool, k)
    out[#out + 1] = makeCard(pid, kind, v)
  end
  d.cards = out
end

-- Goi tu 2_wave.lua khi ha tinh anh / boss. Chay tren MOI may.
local function addRolls(pid, n)
  local d = S.p[pid]
  if d == nil or n == nil or n <= 0 then return end
  d.rolls = (d.rolls or 0) + n
  -- Chua co the nao thi rut ngay. RUT o day chu khong o cho mo khung:
  -- ham nay chay tren moi may, con mo khung la UI thuan (ADR 0012).
  if d.cards == nil then drawCards(pid) end

  -- MO KHUNG NGAY.
  --
  -- DA THU DOI SANG "mo luc don sach wave" (2026-09-20) ROI GO LAI
  -- TRONG CUNG NGAY. Ghi lai vi ly le nghe rat xuoi ma sai:
  --
  --   "Tinh anh chet GIUA wave, con 49 con dang danh -- chon the luc do
  --    khong phai lua chon, la mot thu phai gat di."
  --
  -- Gia dinh do CHUA DO, va no sai. Tinh anh co ELITE_EHP = 10, tuc day
  -- gap 10 lan mot con linh va sinh cung luc voi 50 con kia -- nen no
  -- LUON la con chet cuoi. Boss thi con hien nhien hon: boss dung mot
  -- minh, boss chet LA wave sach.
  --
  -- Trong onMobDeath, rewardAll() va onWaveCleared() cach nhau DUNG
  -- NAM DONG trong cung mot ham. Doi cho mo khung giua hai dong do la
  -- doi mot thu khong ai nhin thay.
  --
  -- Va no lam hong mot duong: Thanh Thu chet TRONG HANG, thuong luc
  -- giua hai wave -- khong co wave nao dang chay de ma "don sach". 12
  -- luot cua Thanh Long nam cho toi tan wave sau.
  --
  -- Bai hoc: dem SO LAN khong phai do su kho chiu. 168 luot mot van la
  -- that, nhung moi lan von da roi vao luc an toan roi.
  if API.fortuneFrameShow ~= nil then API.fortuneFrameShow(pid) end
end

-- Goi tu 2_wave.lua luc don sach wave, va tu phim R.
--
-- Tra ve true neu co mo khung -- ben goi dung no de biet co nen lam
-- viec khac hay khong.
local function showIfPending(pid)
  local d = S.p[pid]
  if d == nil or (d.rolls or 0) <= 0 then return false end
  if d.cards == nil then drawCards(pid) end
  if API.fortuneFrameShow == nil then return false end
  API.fortuneFrameShow(pid)
  return true
end

-- ---------- Nhan the ----------
-- Chay tren MOI may, tu kenh dong bo.

local function take(pid, i)
  local d = S.p[pid]
  if d == nil or d.cards == nil then return end
  if (d.rolls or 0) <= 0 then return end
  local card = d.cards[i]
  if card == nil then return end

  if card.kind == "iron" then
    d.iron = (d.iron or 0) + card.amount

  elseif card.kind == "stat" then
    -- Cong vao bang CONG DON rieng, khong dat thang chi so hero:
    -- heroRecompute la cho DUY NHAT duoc ghi chi so, va no ghi de moi
    -- lan chay. Dat thang o day la lan sau recompute xoa mat.
    d.rollStats = d.rollStats or { str = 0, agi = 0, int = 0 }
    d.rollStats[card.stat] = (d.rollStats[card.stat] or 0) + card.amount
    if API.heroRecompute ~= nil then API.heroRecompute(pid) end

  elseif card.kind == "gold" then
    API.addGold(pid, card.amount)

  elseif card.kind == "lumber" then
    -- Di qua addLumber chu khong SetPlayerState: do la mot trong HAI
    -- duong ghi hop le, va no cap nhat so cai cua canh cheat.
    API.addLumber(pid, card.amount)
  end

  API.msg(pid, API.t("fortune_took", CFG.C_JADE .. API.fortuneLabel(card) .. CFG.C_END))

  d.rolls = d.rolls - 1
  if d.rolls > 0 then
    drawCards(pid)
    if API.fortuneFrameRefresh ~= nil then API.fortuneFrameRefresh(pid) end
  else
    d.cards = nil
    if API.fortuneFrameHide ~= nil then API.fortuneFrameHide(pid) end
  end
  API.panelRefresh(pid)
end

-- ---------- Chu cho tung the ----------

local function labelOf(card)
  if card == nil then return "" end
  if card.kind == "iron" then
    return API.num(card.amount) .. " " .. API.t("cur_iron")
  elseif card.kind == "stat" then
    return "+" .. API.num(card.amount) .. " " .. API.t("stat_" .. card.stat)
  elseif card.kind == "lumber" then
    return "+" .. API.num(card.amount) .. " " .. API.t("cur_lumber")
  end
  return "+" .. API.num(card.amount) .. " " .. API.t("cur_gold")
end

-- Icon KHONG go duong dan tay nua.
--
-- Da doan sai ba lan: BTNRingViolet (o xanh la), BTNStrength (o xanh
-- la), BTNGoldmine (ra cai NHA chu khong phai dong tien). Duong dan
-- texture khong liet ke duoc tu ngoai -- game dong goi bang CASC.
--
-- Nen DOC tu chinh doi tuong cua game, giong cach 8_shop.lua lam:
--   BlzGetAbilityIcon(id)  icon that cua mot ability
--   BlzGetItemIconPath(it) icon that cua mot item vua tao
--
-- Gia tri ban dau chi la duong LUI: chung deu la duong dan DA CHUNG
-- MINH la ve ra hinh (dang dung o the Trang Bi), nen sai lam thi ra
-- icon khong hop nghia chu KHONG BAO GIO ra o xanh la nua.
local ICON = {
  iron    = [[ReplaceableTextures\CommandButtons\BTNStaffOfSanctuary.blp]],
  stat = [[ReplaceableTextures\CommandButtons\BTNSteelMelee.blp]],
  gold  = [[ReplaceableTextures\CommandButtons\BTNTalisman.blp]],
  -- Duong LUI da chung minh ve ra hinh (the Trang Bi dang dung).
  lumber = [[ReplaceableTextures\CommandButtons\BTNSteelArmor.blp]],
}

-- Do icon that luc vao map. Moi muc: { khoa, ma item de thu, ability
-- de lui ve }.
local function probeIcons()
  -- 1. Chi so: lay tu chinh ability Luyen The (A004). Chac chan co --
  --    no dang ve ra hinh o the Ky Nang.
  if BlzGetAbilityIcon ~= nil then
    local p = BlzGetAbilityIcon(FourCC("A004"))
    if p ~= nil and p ~= "" then ICON.stat = p end
  end

  -- 2. Vang va da: thu tao item roi doc icon that cua no.
  --    CreateItem tra nil khi ma khong ton tai -> giu duong lui va GHI
  --    VET, khong nuot im.
  if CreateItem ~= nil and BlzGetItemIconPath ~= nil then
    local probes = { { "gold", "gold" }, { "iron", "ingt" },
                     { "lumber", "lmbr" } }
    for i = 1, #probes do
      local field, code = probes[i][1], probes[i][2]
      local it = CreateItem(FourCC(code), 0.0, 0.0)
      if it == nil then
        API.trace("fortune: khong co item '" .. code .. "', giu icon lui cho " .. field)
      else
        local p = BlzGetItemIconPath(it)
        if p ~= nil and p ~= "" then ICON[field] = p end
        RemoveItem(it)
      end
    end
  end

  for k, v in pairs(ICON) do
    API.trace("fortune: icon " .. k .. " = " .. tostring(v))
  end
end

-- ---------- Giao dien ----------
--
-- KHONG con la mot the trong bang. Khung rieng, ba cot doc, mo NGAY khi
-- tinh anh/boss chet -- xem 4_ui/5_fortuneframe.lua.

local function hasRolls(pid)
  local d = S.p[pid]
  return d ~= nil and (d.rolls or 0) > 0 and d.cards ~= nil
end

local function cardsOf(pid)
  local d = S.p[pid]
  return (d ~= nil) and d.cards or nil
end

local function rollCount(pid)
  local d = S.p[pid]
  return (d ~= nil) and (d.rolls or 0) or 0
end

local function startFortune()
  probeIcons()
  API.syncOn(CFG.OP_FORTUNE, take)
  API.trace("fortune: san sang")
end

API.fortuneAddRolls = addRolls
API.fortuneShowPending = showIfPending
API.fortuneLabel     = labelOf
API.fortuneTake     = take
API.fortuneHasRolls  = hasRolls
API.fortuneCards      = cardsOf
API.fortuneRolls   = rollCount
API.fortuneIcon     = function(kind) return ICON[kind] end
API.startFortune    = startFortune
end
--#endregion 2_player/10_fortune.lua

--#region 2_player/11_pet.lua
do
-- ============================================================
--  2_player/11_pet.lua -- Pet di theo hero
--
--  BAN DAU: thuan trang tri. Khong danh, khong an don, khong chi so.
--  O Pet trong the Trang Bi (CFG.GEAR_PET_SLOT) da de san cho no tu
--  truoc; day moi la con vat that ngoai map.
--
--  BA THU PHAI CO, va deu co ly do:
--    Locust (Aloc)  khong chon duoc, khong bi nham muc tieu, khong va
--                   cham -- pet di xuyen qua quan chu khong chen duong
--    bat tu         Locust da chan phan lon, nhung don DIEN RONG (Chan
--                   Dia cua boss) van cham toi; chet mot cai la pet bien
--                   mat giua tran ma khong ai hieu vi sao
--    SuspendHeroXP  Hmkg la unit HERO. Khong khoa thi pet len cap, hien
--                   bang chon chieu, va an mat kinh nghiem cua nguoi choi
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- ---------- Tao ----------

local function remove(pid)
  local d = S.p[pid]
  if d == nil or d.pet == nil then return end
  RemoveUnit(d.pet)
  d.pet = nil
end

local function spawn(pid)
  local cfg = CFG.PET
  if cfg == nil then return nil end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return nil end

  -- Con da THU PHUC de len con mac dinh. Ha Thanh Thu nao thi pet thanh
  -- con do, va ghi de con dang co -- moi luc mot pet.
  local uid = d.petUnit or cfg.unit
  if uid == nil then
    -- Chua thu phuc con nao. Khong phai loi -- chi la chua co pet.
    return nil
  end

  -- Doi hero thi bo con cu di, neu khong moi lan doi la them mot con.
  remove(pid)

  local hx, hy = GetUnitX(d.hero), GetUnitY(d.hero)
  local x = API.polarX(hx, cfg.spawnOffset or 120.0, 225.0)
  local y = API.polarY(hy, cfg.spawnOffset or 120.0, 225.0)
  x, y = API.clampToMap(x, y)

  -- Chu so huu trung lap: xem chu thich CFG.PET.neutral. bj_PLAYER_-
  -- NEUTRAL_EXTRA la slot ma chinh du an nay da dung cho model hero o
  -- bang chon tuong -- duong da di roi, khong phai doan.
  local owner = Player(pid)
  if cfg.neutral then
    local slot = _G["bj_PLAYER_NEUTRAL_EXTRA"]
    if slot ~= nil then
      owner = Player(slot)
    else
      API.trace("pet: khong co bj_PLAYER_NEUTRAL_EXTRA -- pet se hien o " ..
                "thanh hero cua nguoi choi")
    end
  end

  local u = CreateUnit(owner, uid, x, y, GetUnitFacing(d.hero))
  if u == nil then
    API.trace("pet: CreateUnit tra ve nil -- kiem id trong CFG.PET")
    return nil
  end

  -- Locust: them NGAY sau khi tao. Them muon hon thi unit da kip nam
  -- trong danh sach chon duoc cua nguoi choi va Locust khong go ra.
  local locustId = cfg.locust
  if locustId ~= nil and UnitAddAbility ~= nil then
    if not UnitAddAbility(u, locustId) then
      API.trace("pet: KHONG them duoc Locust (" .. API.idToStr(locustId) ..
                ") -- pet se chon duoc")
    end
    -- Khoa lai de khong ai go ra duoc, va de no khong hien o bang chieu.
    if UnitMakeAbilityPermanent ~= nil then
      UnitMakeAbilityPermanent(u, true, locustId)
    end
  else
    API.trace("pet: thieu CFG.PET.locust hoac UnitAddAbility")
  end

  if SetUnitInvulnerable ~= nil then SetUnitInvulnerable(u, true) end
  if SuspendHeroXP ~= nil then SuspendHeroXP(u, true) end

  SetUnitScale(u, cfg.scale, cfg.scale, cfg.scale)

  -- Tra lai mau cua nguoi choi. Doi chu sang trung lap thi pet mang mau
  -- trung lap, va ba nguoi choi se co ba con pet giong het nhau -- khong
  -- ai biet con nao cua minh.
  if cfg.neutral and SetUnitColor ~= nil and GetPlayerColor ~= nil then
    SetUnitColor(u, GetPlayerColor(Player(pid)))
  end

  -- Khong cho no tu di danh: pet ban dau la trang tri, ma mot con tu
  -- lao vao quai thi nguoi choi se tuong no co tham gia danh.
  if SetUnitAcquireRange ~= nil then SetUnitAcquireRange(u, 0.0) end

  d.pet = u
  API.trace("pet: pid " .. pid .. " -> " .. API.idToStr(uid) ..
            " (scale " .. cfg.scale .. ")")
  return u
end

-- ---------- Di theo ----------
--
-- Ra lenh CHI KHI di qua xa. Ra lenh moi nhip thi lenh sau huy lenh
-- truoc, pet dung khong nhuc nhich -- loi kinh dien cua pet trong WC3.
local function follow()
  local cfg = CFG.PET
  if cfg == nil then return end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.pet ~= nil then
      if not API.alive(d.pet) or d.hero == nil or not API.alive(d.hero) then
        -- Hero chet thi pet dung yen cho, khong chay ve xac.
      else
        local px, py = GetUnitX(d.pet), GetUnitY(d.pet)
        local hx, hy = GetUnitX(d.hero), GetUnitY(d.hero)
        local dx, dy = hx - px, hy - py
        if dx * dx + dy * dy > cfg.near * cfg.near then
          -- Dung lai o RIA vong tron chu khong dam vao giua hero.
          local a = API.angleXY(hx, hy, px, py)
          IssuePointOrder(d.pet, "move",
                          API.polarX(hx, cfg.near * 0.6, a),
                          API.polarY(hy, cfg.near * 0.6, a))
        end
      end
    end
  end
end

-- ---------- Khoi dong ----------

-- Doi sang con KE TIEP trong so nhung con da thu phuc. Vong lai.
--
-- Chay tu syncOn nen co tren MOI may: pet la unit that, khong phai thu
-- cuc bo -- tao tren mot may thi chi may do thay.
local function cycle(pid)
  local d = S.p[pid]
  local list = CFG.SIDE_QUESTS or {}
  if d == nil or d.petOwn == nil or #list == 0 then return end

  -- Tu con DANG deo tro di, tim con tiep theo da thu phuc.
  local from = 0
  for i = 1, #list do
    if list[i].unit == d.petUnit then from = i end
  end
  for k = 1, #list do
    local i = ((from - 1 + k) % #list) + 1
    if d.petOwn[i] then
      d.petUnit = list[i].unit
      spawn(pid)
      API.panelRefresh(pid)
      return
    end
  end
end

-- Dong trong CFG.SIDE_QUESTS cua con DANG di theo. nil = chua co con nao.
--
-- Mot cho tra duy nhat cho ca ten lan chan dung. Truoc day chi co ten,
-- con chan dung thi the Trang Bi treo CFG.GEAR_PET_ICON co dinh -- nen
-- doi pet xong o van hien Chu Tuoc.
local function defOf(pid)
  local d = S.p[pid]
  if d == nil or d.petUnit == nil then return nil end
  for i = 1, #(CFG.SIDE_QUESTS or {}) do
    if CFG.SIDE_QUESTS[i].unit == d.petUnit then return CFG.SIDE_QUESTS[i] end
  end
  return nil
end

-- Ten con dang di theo, cho the Trang Bi. nil = chua co con nao.
local function label(pid)
  local q = defOf(pid)
  return (q ~= nil) and API.pick(q) or nil
end

-- Chan dung con dang di theo. nil = de cho goi tu quyet dinh duong lui
-- (CFG.GEAR_PET_ICON), chu KHONG tu tra duong lui o day: o goi con phan
-- biet "chua co pet" voi "co pet nhung thieu file anh".
local function iconOf(pid)
  local q = defOf(pid)
  return (q ~= nil) and q.icon or nil
end

local function ownedCount(pid)
  local d = S.p[pid]
  if d == nil or d.petOwn == nil then return 0 end
  local n = 0
  for i = 1, #(CFG.SIDE_QUESTS or {}) do
    if d.petOwn[i] then n = n + 1 end
  end
  return n
end

local function startPet()
  if CFG.PET == nil then
    API.trace("pet: CFG.PET khong co -- bo qua")
    return
  end

  -- LIEN MINH, dat mot lan luc khoi dong.
  --
  -- Pet thuoc ve mot phe trung lap de no khong hien o thanh hero cua
  -- nguoi choi. Nhung trung lap trong Warcraft KHONG mac dinh la than
  -- thien -- bj_PLAYER_NEUTRAL_EXTRA la phe THU DICH, va pet da danh
  -- nguoi choi that. Phai noi ro ra, ca hai chieu.
  local slot = _G["bj_PLAYER_NEUTRAL_EXTRA"]
  if CFG.PET.neutral and slot ~= nil and SetPlayerAllianceStateBJ ~= nil then
    local owner = Player(slot)
    for i = 1, #S.pids do
      local p = Player(S.pids[i])
      SetPlayerAllianceStateBJ(owner, p, bj_ALLIANCE_ALLIED_VISION)
      SetPlayerAllianceStateBJ(p, owner, bj_ALLIANCE_ALLIED_VISION)
    end

    -- VA VOI PHE DICH NUA -- day la cho thieu.
    --
    -- LOI DA SHIP: doan tren chi noi quan he voi NGUOI CHOI, nen pet va
    -- quai van la ke thu cua nhau. Hai hau qua, va ca hai deu nhin ra
    -- duoc ma khong ai doan duoc nguyen nhan:
    --
    --   quai NHAM VAO PET. Pet bat tu nen chung khong giet duoc, nhung
    --   chung dung lai va vung vao no -- pet thanh mot cai moc keo quai
    --   khong ai dinh dat o do.
    --
    --   pet DANH TRA. SetUnitAcquireRange(0) chan viec TU DI TIM muc
    --   tieu, no khong chan viec danh tra khi bi danh. Nen chi can mot
    --   con quai vung truoc la pet lao theo.
    --
    -- NEUTRAL chu khong ALLIED: hai phe thoi nham vao nhau, va khong
    -- ben nao chia tam nhin cho ben nao. Dung ALLIED_VISION o day thi
    -- nguoi choi -- von da lien minh-co-tam-nhin voi phe pet -- co the
    -- nhin xuyen sang ca ban do dich.
    local neutral = _G["bj_ALLIANCE_NEUTRAL"] or _G["bj_ALLIANCE_ALLIED"]
    if S.enemy ~= nil and neutral ~= nil then
      SetPlayerAllianceStateBJ(owner, S.enemy, neutral)
      SetPlayerAllianceStateBJ(S.enemy, owner, neutral)
    else
      API.trace("pet: KHONG dat duoc quan he voi phe dich -- pet se bi " ..
                "quai nham vao va se danh tra")
    end

    API.trace("pet: phe " .. slot .. " lien minh voi " .. #S.pids ..
              " nguoi choi, trung lap voi phe dich")
  end
  S.petTimer = CreateTimer()
  TimerStart(S.petTimer, CFG.PET.tick, true, follow)
  API.syncOn(CFG.OP_PET, function(pid) cycle(pid) end)
  API.trace("pet: san sang, nhip " .. CFG.PET.tick .. "s")
end

API.petCycle  = cycle
API.petLabel  = label
API.petIcon   = iconOf
API.petOwned  = ownedCount
API.petSpawn  = spawn
API.petRemove = remove
API.startPet  = startPet
end
--#endregion 2_player/11_pet.lua

--#region 2_player/12_houseup.lua
do
-- ============================================================
--  12_houseup.lua  --  Nang cap Nha Chinh, tra bang VANG
--
--  Mo bang bang phim ESC -> the VI -> Kien Co (cong Suc Manh).
--
--  DA THU rieng mot duong "bam chuot vao Nha Chinh thi mo the VI"
--  (EVENT_PLAYER_UNIT_SELECTED) roi BO: mot phim ESC da du, va mot cua
--  vao nua la them mot hang so co the vang mat o 1.31.1 cho khong duoc
--  gi. Cung dot do bo luon "Hoi Phuc" (trung viec voi
--  HOUSE_REGEN_PER_WAVE) va "Phan Sat" (mot trigger sat thuong toan cuc
--  cho mot hieu ung nho). Can lam lai thi xem git log file nay.
--
--  BA DIEU PHAI NHO KHI SUA FILE NAY:
--
--  1. CAP LA CUA CHUNG, khong phai cua tung nguoi. Nha chinh chi co
--     MOT, nen S.houseUp la mot bang duy nhat chu khong nam trong
--     S.p[pid]. Mot nguoi mua, ca doi huong -- cung ly do voi hai Phap
--     Khi "nhahp"/"nharegen".
--
--     Luu cap vao S.p[pid] thi hai nguoi cung mua se thanh hai bo cap
--     rieng, ma nha thi chi co mot -- cai nao thang la tuy thu tu goi.
--     Loi im lang, kinh dien.
--
--  2. KHONG tu dat mau nha. rescaleHouse() trong 2_wave.lua chay lai
--     MOI WAVE va tinh lai max tu dau. Goi BlzSetUnitMaxHP o day thi
--     wave sau xoa sach. Duong duy nhat dung la de rescaleHouse hoi
--     nguoc qua API.houseUpStr().
--
--  3. SO DIEM PHAI LEO THEO CANH GIOI (ADR 0024: cong thi leo, nhan
--     thi phang). Mau nha bam theo duong cong quai, nen mot con so diem
--     PHANG se thanh vo nghia o canh gioi 10. Nhan voi
--     CULT_STAT_STEP^(bac-1) y het cach Trang Bi cong diem.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Cap hien tai cua mot duong.
local function levelOf(code)
  if S.houseUp == nil then return 0 end
  return S.houseUp[code] or 0
end

-- Canh gioi CAO NHAT trong doi.
--
-- Nha la cua chung nen lay nguoi di xa nhat lam moc, khong lay trung
-- binh: trung binh thi them mot nguoi moi vao la nha YEU DI, va do la
-- mot luat khong ai doan duoc.
local function topRank()
  local r = 1
  if API.cultRank == nil then return r end
  for i = 1, #S.pids do
    local k = API.cultRank(S.pids[i]) or 1
    if k > r then r = k end
  end
  return r
end

-- Tong diem Suc Manh dang cong cho nha.
--
-- Doc-luc-dung: 2_wave.lua goi ham nay moi wave va luc mua, khong co
-- bang dieu phoi nao ca.
local function strTotal()
  local up = (CFG.HOUSE_UP or {})[1]
  if up == nil then return 0 end
  local lv = levelOf(up.code)
  if lv <= 0 then return 0 end
  local step = CFG.CULT_STAT_STEP or 1.30
  return math.floor(lv * (up.str or 0) * step ^ (topRank() - 1) + 0.5)
end

-- Gia de len cap TIEP THEO. Tra nil khi da kich tran -- nil o day co
-- nghia "khong mua duoc nua", khac han voi 0 ("mua duoc, mien phi").
local function priceOf(code)
  local lv = levelOf(code)
  if lv >= (CFG.HOUSE_UP_MAX or 10) then return nil end
  local p0 = CFG.HOUSE_UP_PRICE0 or 300
  local st = CFG.HOUSE_UP_STEP or 1.45
  return math.floor(p0 * st ^ lv + 0.5)
end

-- ---------- Bao nhieu mau mot diem Suc Manh ----------
--
-- DO tren chinh con nha chinh luc vao map, khong go hang so: nha da di
-- qua BlzSetUnitMaxHP luc tao, va khong co gi bao dam Warcraft con cho
-- Suc Manh doi max nua. Do mot lan thi biet chac.
--
-- Do xong TRA LAI nguyen trang. Thu tu: doc goc -> day len -> doc lai
-- -> dat ve. Neu max khong nhuc nhich thi khong do duoc, va luc do lui
-- ve CFG.HOUSE_UP_STR_HP -- co bao ra, khong nuot.
local function probeHpPerStr()
  if S.house == nil or GetHeroStr == nil or SetHeroStr == nil then return nil end
  local s0 = GetHeroStr(S.house, false)
  local h0 = GetUnitState(S.house, UNIT_STATE_MAX_LIFE)
  SetHeroStr(S.house, s0 + 100, true)
  local h1 = GetUnitState(S.house, UNIT_STATE_MAX_LIFE)
  SetHeroStr(S.house, s0, true)
  if h1 <= h0 then return nil end
  return (h1 - h0) / 100.0
end

local function hpPerStr()
  return S.houseStrHp or CFG.HOUSE_UP_STR_HP or 25.0
end

-- ---------- Mua ----------
--
-- Chay tren MOI may qua syncOn. Kiem lai dieu kien o day chu khong tin
-- cu bam: ben gui la cuc bo.
local function buy(pid, i)
  local up = (CFG.HOUSE_UP or {})[i]
  if up == nil then return end

  local price = priceOf(up.code)
  if price == nil then
    API.msg(pid, CFG.C_GREY .. API.t("hu_max", API.pick(up)) .. CFG.C_END)
    return
  end
  if not API.spendGold(pid, price) then
    API.msg(pid, CFG.C_RED .. API.t("no_gold") .. CFG.C_END ..
      API.t("need_have", API.num(price), API.num(API.getGold(pid))))
    API.panelRefresh(pid)
    return
  end

  if S.houseUp == nil then S.houseUp = {} end
  S.houseUp[up.code] = levelOf(up.code) + 1

  -- Mau doi NGAY, khong doi wave sau.
  --
  -- Mua giua mot wave dang bi don ma phai cho het wave moi thay gi la
  -- mua trong bong toi -- va dung luc do thi nguoi choi can no ngay.
  if API.waveRescaleHouse ~= nil then API.waveRescaleHouse() end

  -- Tin CHUNG: nha la cua ca doi nen ca doi phai biet no vua day len
  -- bao nhieu, va biet ai tra tien.
  API.say(pid, API.t("hu_bought", CFG.C_JADE .. API.pick(up) .. CFG.C_END,
                     levelOf(up.code), CFG.HOUSE_UP_MAX or 10,
                     API.num(strTotal())))
  API.panelRefreshAll()
  API.trace("houseup: " .. up.code .. " -> cap " .. levelOf(up.code) ..
            ", tong " .. strTotal() .. " Str (canh gioi " .. topRank() ..
            ", " .. string.format("%.1f", hpPerStr()) .. " mau/diem)" ..
            " -- pid " .. pid .. " tra " .. price .. " vang")
end

-- ---------- The trong bang ----------

local function tabItems(pid)
  local gold = API.getGold(pid)
  local out  = {}
  for i = 1, #(CFG.HOUSE_UP or {}) do
    local up    = CFG.HOUSE_UP[i]
    local lv    = levelOf(up.code)
    local max   = CFG.HOUSE_UP_MAX or 10
    local price = priceOf(up.code)

    -- Mo ta NOI GIA TRI DANG CO, khong noi "moi cap +40 diem". Nguoi
    -- choi can biet minh dang duoc bao nhieu, chu khong phai tu nhan
    -- trong dau. Cap 0 thi hien 0 -- van la mot cau tra loi.
    local it = {
      icon   = up.icon,
      name   = API.pick(up),
      -- desc_vi/desc_en la DU LIEU trong bang, khong phai khoa i18n --
      -- cung quy uoc voi CFG.HEROES (xem 2_heroframe.lua:258).
      desc   = string.format(
                 (API.lang() == "en" and up.desc_en) or up.desc_vi or "%s",
                 CFG.C_JADE .. API.num(strTotal()) .. CFG.C_END),
      status = CFG.C_GREY .. lv .. "/" .. max .. CFG.C_END,
    }

    if price == nil then
      it.status = CFG.C_GOLD .. lv .. "/" .. max .. CFG.C_END
      -- Noi vao 'desc' chu KHONG vao 'note': than kieu "list" chi ve
      -- icon/name/status/desc/btn -- 'note' la cua kieu "focus" va
      -- kieu "grid". Dat vao note thi o kich tran se trong khong co nut
      -- lan khong co chu.
      it.desc = it.desc .. "   " .. CFG.C_GOLD ..
                API.t("hu_note_max") .. CFG.C_END
    else
      it.btn   = API.t("btn_upgrade") .. "  " .. API.num(price) ..
                 " " .. API.t("cur_gold")
      it.btnOn = (gold >= price)
    end
    out[i] = it
  end
  return out
end

local function tabItemAction(pid, i)
  API.syncSend(pid, CFG.OP_HOUSE_UP, i)
end

-- ---------- Khoi dong ----------

local function startHouseUp()
  S.houseUp = {}

  S.houseStrHp = probeHpPerStr()
  if S.houseStrHp == nil then
    API.trace("houseup: KHONG do duoc mau moi diem Str tren nha chinh " ..
              "(BlzSetUnitMaxHP co the da khoa max) -- lui ve " ..
              (CFG.HOUSE_UP_STR_HP or 25.0))
  end

  API.panelAddTab({
    name       = API.t("panel_house"),
    kind       = "list",
    rows       = #(CFG.HOUSE_UP or {}),
    items      = tabItems,
    itemAction = tabItemAction,
    empty      = API.t("hu_empty"),
  })

  API.syncOn(CFG.OP_HOUSE_UP, buy)

  API.trace("houseup: " .. #(CFG.HOUSE_UP or {}) .. " duong, tran cap " ..
            (CFG.HOUSE_UP_MAX or 10) .. ", gia dau " ..
            (CFG.HOUSE_UP_PRICE0 or 300) .. " x " ..
            (CFG.HOUSE_UP_STEP or 1.45) .. "^n, " ..
            string.format("%.1f", hpPerStr()) .. " mau/diem Str")
end

API.houseUpStr   = strTotal
API.houseUpStrHp = hpPerStr
API.houseUpLevel = levelOf
API.startHouseUp = startHouseUp
end
--#endregion 2_player/12_houseup.lua

--#region 2_player/13_cheatguard.lua
do
-- ============================================================
--  13_cheatguard.lua  --  Bat cheat co san cua Warcraft III
--
--  KHONG CHAN DUOC, CHI PHAT HIEN DUOC. Cheat cua Warcraft
--  (greedisgood, whosyourdaddy...) do CHINH ENGINE xu ly, khong di qua
--  trigger nao cua map. Khong co native nao tat chung.
--
--  Nen he nay khong chan DAU VAO -- no do HAU QUA roi THU HOI. Hai
--  duong do duoc:
--
--    1. SO CAI TIEN. Vang va Go song tren THANH TAI NGUYEN cua
--       Warcraft (PLAYER_STATE_RESOURCE_*), va greedisgood bom thang
--       vao do. Map thi chi ghi qua addGold/addLumber -- HAI cho duy
--       nhat goi SetPlayerState trong ca cay. Nen: moi lan map ghi,
--       ghi luon con so do vao so cai. Lech = co ke thu ba ghi vao.
--
--       Linh Khi va Da KHONG can canh: chung song trong S.p[pid],
--       cheat khong voi toi.
--
--    2. BAT TU. whosyourdaddy dat unit bat tu. Map khong bao gio dat
--       hero bat tu, nen hero bat tu = cheat.
--
--  KHONG BAO NHAM la yeu cau so mot. Lenh -debug day ca bon dong tien
--  len 999.999 -- nhung no goi API.addGold nen so cai tu khop. Bat cu
--  ai them mot duong cap tien MOI phai di qua addGold/addLumber, neu
--  khong he nay se to oan nguoi choi.
--
--  PHAN UNG MAC DINH LA THU HOI ("revert"). Chan dau vao thi khong
--  the, nhung hau qua thi thu hoi duoc: so cai giu con so DUNG, nen dat
--  lai thanh tai nguyen ve con so do la xoa sach phan an cap.
--  greedisgood van "chay", chi la vo dung sau nua giay.
--
--  Day la CHO THU BA duoc goi SetPlayerState, ngoai addGold/addLumber.
--  Ngoai le nay an toan vi no chi dat ve DUNG con so so cai dang giu --
--  khong tao ra mot nguon ghi moi, chi xoa mot nguon ghi la.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Map vua ghi mot con so len thanh tai nguyen. Nho lai.
--
-- Goi tu addGold/addLumber trong 1_player.lua, NGAY SAU SetPlayerState.
-- Goi truoc thi so cai giu con so cu va lan kiem ngay sau se to oan.
local function note(pid, kind, value)
  if S.ledger == nil then S.ledger = {} end
  if S.ledger[pid] == nil then S.ledger[pid] = {} end
  S.ledger[pid][kind] = value
end

local function said(pid, kind)
  local d = S.p[pid]
  if d == nil then return true end
  if d.cheatSaid == nil then d.cheatSaid = {} end
  if d.cheatSaid[kind] then return true end
  d.cheatSaid[kind] = true
  return false
end

-- Bao mot lan cho moi KIEU cheat, khong bao moi nhip.
--
-- Mot nguoi go greedisgood roi de yen thi lech ton tai mai mai -- bao
-- moi 2 giay la bien phat hien thanh tieng on, va tieng on thi nguoi ta
-- tat di chu khong sua.
local function flag(pid, kind, detail)
  if said(pid, kind) then return end

  local d = S.p[pid]
  if d ~= nil then d.cheated = true end
  S.cheatSeen = true

  API.trace("cheat: pid " .. pid .. " -- " .. kind .. " -- " .. detail)

  local act = CFG.CHEAT_ACTION or "revert"
  if act == "off" then return end

  -- Bao cho CA BAN DO, khong bao rieng.
  --
  -- Mot minh nguoi go thi bao rieng la vo nghia -- ho biet ho vua go gi.
  -- Gia tri cua dong nay nam o cho NGUOI KHAC doc duoc.
  API.say(pid, CFG.C_RED .. API.t("cheat_seen") .. CFG.C_END)
end

-- ---------- Do ----------

local function checkOne(pid)
  local d = S.p[pid]
  if d == nil or not d.active then return end

  local led = (S.ledger or {})[pid]
  if led == nil then return end
  local slack = CFG.CHEAT_SLACK or 1

  local revert = (CFG.CHEAT_ACTION or "revert") == "revert"

  -- Chi xu ly khi THUA ra. Thieu di thi nhan con so moi lam moc -- co
  -- the la mot duong tru tien nao do chua kip ghi so, va to oan vi
  -- THIEU tien la kieu sai te nhat.
  local function guard(kind, state)
    local cur = GetPlayerState(Player(pid), state)
    local book = led[kind]
    if book == nil then return end
    if cur > book + slack then
      flag(pid, kind, "so cai " .. book .. ", that " .. cur ..
                      (revert and " -- da thu hoi" or ""))
      if revert then
        -- Dat ve DUNG con so so cai. Khong goi addGold: addGold cong
        -- THEM va se ghi lai so cai, tuc lay con so an cap lam moc.
        SetPlayerState(Player(pid), state, book)
      else
        led[kind] = cur   -- khong thu hoi thi nhan moc moi
      end
    elseif cur < book then
      led[kind] = cur
    end
  end

  guard("gold",   PLAYER_STATE_RESOURCE_GOLD)
  guard("lumber", PLAYER_STATE_RESOURCE_LUMBER)

  -- BAT TU: map khong bao gio dat hero bat tu, nen hero bat tu la
  -- whosyourdaddy. Nha chinh thi CO the bat tu (CFG.HOUSE_INVULNERABLE)
  -- nen khong dung no lam dau hieu.
  local h = d.hero
  if h ~= nil and API.alive(h) and BlzIsUnitInvulnerable ~= nil then
    if BlzIsUnitInvulnerable(h) then
      flag(pid, "invuln", "hero bat tu ma map khong dat" ..
                          (revert and " -- da go" or ""))
      -- Go bat tu. whosyourdaddy con cho mot don giet ngay, va phan do
      -- KHONG go duoc -- nhung mat phan bat tu la nguoi choi van chet
      -- duoc, tuc van thua duoc.
      if revert and SetUnitInvulnerable ~= nil then
        SetUnitInvulnerable(h, false)
      end
    end
  end
end

local function tick()
  for i = 1, #S.pids do checkOne(S.pids[i]) end
end

-- Co the hoi tu cac he khac: "van nay da dinh cheat chua".
local function clean()
  return not S.cheatSeen
end

-- ---------- Khoi dong ----------

local function startCheatGuard()
  S.ledger, S.cheatSeen = {}, false
  if not CFG.CHEAT_WATCH then
    API.trace("cheat: CFG.CHEAT_WATCH = false -- khong canh")
    return
  end

  -- MOC DAU la con so DANG CO, khong phai 0.
  --
  -- Warcraft phat vang/go khoi dau theo thiet lap trong war3map.w3i,
  -- truoc khi mot dong Lua nao chay. Lay 0 lam moc thi ca doi bi to
  -- oan ngay giay dau.
  for i = 1, #S.pids do
    local pid = S.pids[i]
    note(pid, "gold",   GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD))
    note(pid, "lumber", GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER))
  end

  S.cheatTimer = CreateTimer()
  TimerStart(S.cheatTimer, CFG.CHEAT_TICK or 2.0, true, tick)

  API.trace("cheat: canh so cai vang/go + bat tu, moi " ..
            (CFG.CHEAT_TICK or 2.0) .. "s, phan ung '" ..
            tostring(CFG.CHEAT_ACTION or "revert") .. "'")
end

API.cheatNote      = note
API.cheatClean     = clean
API.startCheatGuard = startCheatGuard
end
--#endregion 2_player/13_cheatguard.lua

--#region 2_player/14_revive.lua
do
-- ============================================================
--  14_revive.lua  --  Hero chet roi song lai
--
--  VI SAO PHAI CO. Truoc file nay onAnyDeath() chi xu ly NHA CHINH va
--  QUAI -- khong mot dong nao cho hero. Quet ca cay nguon: duong song
--  lai duy nhat la Ankh 500 vang, hoac bi dong Hoi Sinh cua A006.
--
--  Nghia la chet o wave 30 ma khong co Ankh thi ngoi xem 70 wave con
--  lai. Trong map co-op ba nguoi, do la cho mot nguoi nghi choi giua
--  chung ma van phai ngoi do.
--
--  Te hon: measureParty() BO QUA hero chet, nen boss nho lai theo --
--  doi hai nguoi thang de hon doi ba nguoi co mot xac. Nghich ly, va
--  no am tham.
--
--  SONG LAI O NHA CHINH, KHONG PHAI CHO VUA CHET. Cho vua chet la cho
--  vua thua: song lai ngay giua bay quai la chet lan hai trong ba
--  giay. Ve nha thi doan duong quay lai chinh la phan gia phai tra.
--
--  KHONG CAN DONG BO. Su kien chet cua Warcraft ban tren MOI may voi
--  cung mot unit, nen moi may tu chay cung mot nhanh va ra cung ket
--  qua. Khac han callback frame (ADR 0012) -- cai do chi ban tren may
--  bam.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Tra ve pid neu unit nay la hero CUA MOT NGUOI CHOI, khong thi nil.
--
-- Kiem 'd.hero == u' chu khong chi kiem chu so huu: pet cung thuoc ve
-- nguoi choi o vai ban truoc, va thap canh thi luon thuoc ve ho.
local function heroPidOf(u)
  if u == nil then return nil end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero == u then return pid end
  end
  return nil
end

-- Cho song lai: quanh NHA CHINH, toa ra theo slot de ba nguoi khong
-- chong len nhau. Thieu nha thi lui ve dung cho cu.
local function revivePoint(pid, u)
  if S.house ~= nil and API.alive(S.house) and API.heroFanPoint ~= nil then
    return API.heroFanPoint(pid, GetUnitX(S.house), GetUnitY(S.house),
                            CFG.HERO_SPAWN_OFFSET or 500.0)
  end
  return GetUnitX(u), GetUnitY(u)
end

local function revive(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  d.reviving = nil

  local u = d.hero
  if API.alive(u) then return end          -- Ankh hay A006 da lo truoc

  local x, y = revivePoint(pid, u)
  if ReviveHero == nil then
    API.warn(pid, "Khong co ReviveHero -- hero khong song lai duoc.")
    return
  end
  ReviveHero(u, x, y, true)

  -- Day mau/mana ve day. ReviveHero cua Warcraft tra hero ve mot phan
  -- mau, ma song lai voi mot vach mau giua bay quai la chet lan hai.
  SetUnitState(u, UNIT_STATE_LIFE, GetUnitState(u, UNIT_STATE_MAX_LIFE))
  SetUnitState(u, UNIT_STATE_MANA, GetUnitState(u, UNIT_STATE_MAX_MANA))

  -- Canh bam vao unit. Unit khong bi xoa nen effect con nguyen, nhung
  -- goi lai cho chac: check() ton trong d.wingPick va khong deo lai
  -- neu dang dung bo.
  if API.wingCheck ~= nil then API.wingCheck(pid) end
  -- Chi so thi khong doi -- cung mot unit -- nhung mot lan tinh lai
  -- khong ton gi va no don sach moi thu co the da truot.
  if API.heroRecompute ~= nil then API.heroRecompute(pid) end
  if API.panelRefresh ~= nil then API.panelRefresh(pid) end

  API.say(pid, API.t("hero_revived"))
  API.trace("revive: pid " .. pid .. " song lai o " ..
            math.floor(x) .. "," .. math.floor(y))
end

-- Goi tu onAnyDeath() trong 5_boot/1_events.lua.
--
-- Tra ve true neu da nhan xu ly, de ben goi khong day tiep sang
-- onMobDeath -- hero khong phai quai, va onMobDeath cong tien thuong.
local function onHeroDeath(u)
  local pid = heroPidOf(u)
  if pid == nil then return false end

  local d = S.p[pid]
  local secs = CFG.HERO_REVIVE_SECONDS or 30.0
  if secs <= 0.0 then return true end      -- 0 = tat han he nay

  -- Mot cho hen duy nhat. Khong co co nay thi mot hero chet -> Ankh
  -- cuu -> chet lai se xep HAI cai hen, va cai thu nhat se "song lai"
  -- mot hero dang song.
  if d ~= nil then d.reviving = true end

  -- BAO CHO CA BAN DO. Bao rieng nguoi vua chet la vo nghia -- ho dang
  -- nhin man hinh xam. Gia tri nam o cho hai nguoi kia biet doi vua
  -- mat mot phan ba hoa luc trong 30 giay.
  API.say(pid, API.t("hero_died", math.floor(secs)))
  API.trace("revive: pid " .. pid .. " chet -- hen " .. secs .. "s")

  API.after(secs, function() revive(pid) end)
  return true
end

local function startRevive()
  if CFG.HERO_REVIVE_SECONDS == nil or CFG.HERO_REVIVE_SECONDS <= 0.0 then
    API.trace("revive: TAT (CFG.HERO_REVIVE_SECONDS = 0)")
    return
  end
  if ReviveHero == nil then
    API.warn(nil, "Khong co ReviveHero -- hero chet se nam luon.")
    return
  end
  API.trace("revive: hero song lai sau " .. CFG.HERO_REVIVE_SECONDS ..
            "s, o quanh nha chinh")
end

API.onHeroDeath  = onHeroDeath
API.startRevive  = startRevive
end
--#endregion 2_player/14_revive.lua

--#region 2_player/15_heroname.lua
do
-- ============================================================
--  15_heroname.lua  --  Hai dong chu tren bang hero
--
--  Warcraft ve bang hero bang DUNG hai dong, va ta chi doi duoc noi
--  dung, khong doi duoc bo cuc:
--
--      dong 1   ten rieng cua hero        (proper name)
--      dong 2   "Level <N> <ten unit>"    N va ten unit deu doi duoc
--
--  TRUOC FILE NAY CA HAI DONG DEU GHI "Mage" -- va dong hai ghi
--  "Level 1 Mage" VINH VIEN, vi hero trong map nay khong bao gio len
--  cap (CFG.LOCK_HERO_XP). Tuc dong quan trong thu hai cua bang noi
--  dung mot thu: mot he thong khong ton tai.
--
--  Gio:
--      dong 1   ten nhan vat              (CFG.HEROES[i].title)
--      dong 2   "Level 7 Hoa Than"        cap = bac Tu Vi, ten = canh gioi
--
--  VI SAO DAT CA CAP HERO chu khong chi doi ten unit: de nguyen cap 1
--  thi dong hai thanh "Level 1 Hoa Than" -- mot con so 1 dung canh chu
--  "bac 7", te hon ca truoc. Dat cap bang bac Tu Vi thi chu "Level"
--  thoi noi doi, va ca dong doc duoc ma khong con mot ky tu thua.
--
--  BA DIEU PHAI NHO:
--
--  1. LEN CAP THI WARCRAFT PHAT DIEM KY NANG. Map nay khong dung diem
--     do (ky nang mua bang Go), nen phai rut ngay -- neu khong nguoi
--     choi thay nut "+" nhap nhay va bam vao hoc nham ability goc.
--
--  2. KHONG HA CAP DUOC. SetHeroLevel cua Warcraft chi di len. Lenh
--     dev "-lc 3" sau khi da o bac 20 se khong ha cap xuong duoc, nen
--     dong hai giu so cu. Ghi vet chu khong im lang.
--
--  3. CAP KHONG CONG CHI SO GI. heroRecompute() ghi chi so bang so
--     TUYET DOI, nen phan Warcraft cong khi len cap bi ghi de ngay lan
--     tinh sau. Do la ly do dat cap o day an toan.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Ten nhan vat cua mot hero, tra tu CFG.HEROES theo unit type.
local function titleOf(uid)
  for i = 1, #(CFG.HEROES or {}) do
    if CFG.HEROES[i].id == uid then
      local h = CFG.HEROES[i]
      return h.title or h.name
    end
  end
  return nil
end

-- Goi sau khi pick hero, VA sau moi lan doi bac Tu Vi.
local function refresh(pid)
  if not CFG.HERO_NAME_SHOW_RANK then return end
  local d = S.p[pid]
  if d == nil or d.hero == nil or not API.alive(d.hero) then return end

  local h    = d.hero
  local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1

  -- Dong 2: ten unit = ten canh gioi.
  if BlzSetUnitName ~= nil and API.realmName ~= nil then
    BlzSetUnitName(h, API.realmName(rank))
  end

  -- Dong 1: ten nhan vat. Dat mot lan la du -- no khong doi theo bac --
  -- nhung dat lai moi lan cung khong ton gi, va no tu sua neu co he
  -- nao do lo ghi de.
  if BlzSetHeroProperName ~= nil then
    local t = titleOf(GetUnitTypeId(h))
    if t ~= nil then BlzSetHeroProperName(h, t) end
  end

  -- Cap = bac Tu Vi.
  if SetHeroLevel ~= nil and GetHeroLevel ~= nil then
    local cur = GetHeroLevel(h)
    if cur < rank then
      -- false = khong choi hoat anh len cap. Dot pha DA co hieu ung
      -- rieng (ResurrectTarget o 3_cultivation.lua); chong them mot
      -- cot sang vang nua la hai hieu ung danh nhau.
      SetHeroLevel(h, rank, false)
      -- Rut diem ky nang Warcraft vua phat. Khong rut thi nut "+" nhap
      -- nhay va nguoi choi bam vao hoc nham ability goc.
      if API.lockHero ~= nil then API.lockHero(h) end
    elseif cur > rank then
      -- SetHeroLevel KHONG ha cap duoc. Chi xay ra voi lenh dev "-lc".
      API.trace("heroname: pid " .. pid .. " cap " .. cur ..
                " > bac " .. rank .. " -- Warcraft khong ha cap duoc")
    end
  end
end

local function startHeroName()
  if not CFG.HERO_NAME_SHOW_RANK then
    API.trace("heroname: TAT (CFG.HERO_NAME_SHOW_RANK = false)")
    return
  end
  if BlzSetHeroProperName == nil then
    API.trace("heroname: KHONG co BlzSetHeroProperName -- dong 1 giu ten " ..
              "cua Object Editor")
  end
  API.trace("heroname: dong 1 = ten nhan vat, dong 2 = cap + canh gioi")
end

API.heroNameRefresh = refresh
API.startHeroName   = startHeroName
end
--#endregion 2_player/15_heroname.lua

--#region 3_battle/1_house.lua
do
-- ============================================================
--  1_house.lua  --  Nha chinh & phan giai vung
--
--  Dung nha chinh giua CFG.RGN_HOUSE, va phan giai san vung
--  CFG.RGN_ENEMY de sau nay cho quai ra. Chua sinh quai nao ca.
--
--  Nha chinh la HERO (Mountain King), khong phai cong trinh. Khac biet
--  phai xu ly: mau tinh theo suc manh nen phai khoa kinh nghiem, va
--  hero mac dinh co don danh nen phai tat di.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nha chinh dung mot slot rieng, khong thuoc ve rieng nguoi choi nao.
-- Quan he dong minh dat o 04_player.
local function houseOwner()
  return Player(CFG.HOUSE_SLOT)
end

-- Voi hero, mau toi da duoc suy ra tu suc manh. Dat thang bang
-- BlzSetUnitMaxHP van duoc, nhung se bi tinh lai neu hero len cap hoac
-- doi chi so -- vi vay CFG.HOUSE_SUSPEND_XP mac dinh bat.
local function setHouseHP(value)
  if S.house == nil or BlzSetUnitMaxHP == nil then return false end
  BlzSetUnitMaxHP(S.house, math.floor(value))
  SetUnitState(S.house, UNIT_STATE_LIFE, GetUnitState(S.house, UNIT_STATE_MAX_LIFE))
  return true
end

-- Tam nhin bang fog modifier, KHONG sua truong cua unit.
--
-- Truoc day dung BlzSetUnitRealField(UNIT_RF_SIGHT_RADIUS). Da bo:
-- kiem tra hang so ~= nil khong chan duoc truong hop hang so ton tai
-- nhung SAI KIEU -- goi setter real len mot truong integer la ghi sai
-- bo nho, ACCESS_VIOLATION. Nha chinh dung yen nen mot vung sang co
-- dinh la tuong duong hoan toan, va chi dung native cu chac chan.
local function setHouseSight(radius)
  for i = 1, #S.pids do
    local fm = CreateFogModifierRadius(Player(S.pids[i]), FOG_OF_WAR_VISIBLE,
                                       S.houseX, S.houseY, radius, true, false)
    FogModifierStart(fm)
  end
  return "fog modifier"
end

-- Khong cho nha chinh tu tim muc tieu.
--
-- Truoc day dung BlzSetUnitIntegerField(UNIT_IF_ATTACKS_ENABLED, 0) --
-- da bo vi cung ly do o tren. SetUnitAcquireRange la native cu, co tu
-- doi dau: ban kinh 0 thi unit khong bao gio tu nham ai. No van danh
-- neu bi RA LENH danh, nhung slot so huu nha khong co nguoi dieu khien
-- nen khong bao gio co lenh do.
local function disableAttacks()
  SetUnitAcquireRange(S.house, 0.0)
  return true
end

local function createHouse()
  local r, realName = API.findRegion(CFG.RGN_HOUSE)
  if r == nil then
    API.regionMissing("CFG.RGN_HOUSE", API.regionLabel(CFG.RGN_HOUSE))
    return nil
  end
  S.houseRgnName = realName

  local x, y = API.regionCenter(r)
  API.trace("house: CreateUnit slot " .. CFG.HOUSE_SLOT)
  S.house = CreateUnit(houseOwner(), CFG.HOUSE_UNIT, x, y, CFG.HOUSE_FACE)
  if S.house == nil then
    API.warn(nil, "CreateUnit that bai -- kiem tra CFG.HOUSE_UNIT.")
    return nil
  end
  S.houseX, S.houseY = x, y

  if CFG.HOUSE_SCALE ~= 1.0 then
    SetUnitScale(S.house, CFG.HOUSE_SCALE, CFG.HOUSE_SCALE, CFG.HOUSE_SCALE)
  end
  if BlzSetUnitName ~= nil then BlzSetUnitName(S.house, CFG.HOUSE_NAME) end

  -- Khoa kinh nghiem TRUOC khi dat mau, neu khong len cap se pha moc.
  API.trace("house: SuspendHeroXP")
  if CFG.HOUSE_SUSPEND_XP then SuspendHeroXP(S.house, true) end

  API.trace("house: setHP (BlzSetUnitMaxHP)")
  S.houseHpSet    = setHouseHP(CFG.HOUSE_HP)

  API.trace("house: setSight (fog modifier)")
  S.houseSightVia = setHouseSight(CFG.HOUSE_SIGHT)

  API.trace("house: disableAttacks (SetUnitAcquireRange)")
  if not CFG.HOUSE_CAN_ATTACK then
    S.houseNoAttack = disableAttacks()
  end

  API.trace("house: SetUnitInvulnerable")
  SetUnitInvulnerable(S.house, CFG.HOUSE_INVULNERABLE)

  -- Chot nha chinh tai cho. BA lop, vi khong lop nao mot minh du chac:
  --   SetUnitMoveSpeed(0)  Warcraft ep ve toc do toi thieu chu khong ve
  --                        0 han, nen day chi la lop giam thiet hai.
  --   "stop"               huy lenh di chuyen dang co san trong hang doi.
  --   PauseUnit(true)      chot han: unit khong nhan lenh nao nua.
  --
  -- PauseUnit KHONG lam no bat tu: unit bi chot van an sat thuong, van
  -- chet, van ban su kien chet -- nen duong thua van chay.
  if CFG.HOUSE_FROZEN then
    API.trace("house: FROZEN (move 0 + stop + PauseUnit)")
    if SetUnitMoveSpeed ~= nil then SetUnitMoveSpeed(S.house, 0.0) end
    if IssueImmediateOrder ~= nil then IssueImmediateOrder(S.house, "stop") end
    if PauseUnit ~= nil then PauseUnit(S.house, true) end
  end

  -- Go tui do. Xem CFG.HOUSE_REMOVE_ABILITIES.
  if UnitRemoveAbility ~= nil and CFG.HOUSE_REMOVE_ABILITIES ~= nil then
    local got = {}
    for i = 1, #CFG.HOUSE_REMOVE_ABILITIES do
      local aid = CFG.HOUSE_REMOVE_ABILITIES[i]
      if UnitRemoveAbility(S.house, aid) then
        got[#got + 1] = API.idToStr(aid)
      end
    end
    API.trace("house: go ability -- " ..
              ((#got > 0) and table.concat(got, " ") or "KHONG id nao trung"))
  end

  API.trace("house: XONG")
  return S.house
end

-- ---------- Nha chinh khong nhan do ----------
--
-- Lop thu hai, va la lop CHAC: no khong phu thuoc vao viec doan dung ma
-- ability tui do. Nha chinh vua nhat duoc mon nao thi tra ngay ra dat.
--
-- Tra ra dat chu khong xoa: mon do la cua nguoi choi, ho bo tien mua.
-- Lam mat no thi cai gia cua mot cu keo nham nang hon han cai loi.
local function onHousePickup()
  if S.house == nil then return end
  if GetTriggerUnit() ~= S.house then return end

  local it = GetManipulatedItem()
  if it == nil then return end

  -- Dat lai tai cho nha chinh. UnitRemoveItem tra mon ra khoi tui roi
  -- tha xuong ngay duoi chan unit, nen chi can goi no.
  if UnitRemoveItem ~= nil then
    UnitRemoveItem(S.house, it)
  elseif SetItemPosition ~= nil then
    SetItemPosition(it, GetUnitX(S.house), GetUnitY(S.house))
  end

  API.msg(nil, CFG.C_GREY .. API.t("house_no_items") .. CFG.C_END)
  API.trace("house: tu choi mon " ..
            ((GetItemName ~= nil) and GetItemName(it) or "?"))
end

-- Goi tu 08_events khi nha chinh chet. Day la dieu kien thua DUY NHAT.
local function onHouseDeath()
  if not S.running then return end
  if not CFG.HOUSE_DEATH_ENDS_GAME then return end
  API.endGame(false, CFG.HOUSE_NAME .. " da bi pha huy.")
end

-- Chua cho quai ra. Buoc nay chi xac nhan vung ton tai va nho lai.
local function resolveEnemyRegion()
  local r, realName = API.findRegion(CFG.RGN_ENEMY)
  if r == nil then
    API.regionMissing("CFG.RGN_ENEMY", API.regionLabel(CFG.RGN_ENEMY))
    return nil
  end
  S.enemyRgnName = realName

  S.enemyRect = r
  S.enemyX, S.enemyY = API.regionCenter(r)
  return r
end

-- Diem nay roi vao block nao cua luoi 5x5 -- de doi chieu vung ve tay
-- trong World Editor voi luoi logic.
local function blockLabel(x, y)
  if x == nil then return "-" end
  local col, row = API.blockAt(x, y)
  if col == nil then
    if API.inRiver(x, y) then return "duoi song" end
    return "ngoai luoi"
  end
  return "block #" .. API.blockIndex(col, row) .. " (" .. col .. "," .. row .. ")"
end

local function report()
  local rgns = API.listRegions()
  API.info(nil, CFG.C_GOLD .. "=== Vung & nha chinh ===" .. CFG.C_END)
  API.info(nil, "Vung WE thay duoc (" .. #rgns .. "): " .. table.concat(rgns, ", "))

  if S.house ~= nil then
    API.info(nil, "Nha chinh : " .. API.num(S.houseX) .. ", " .. API.num(S.houseY) ..
      "  -- " .. blockLabel(S.houseX, S.houseY) ..
      CFG.C_GREY .. "  [vung " .. tostring(S.houseRgnName) .. "]" .. CFG.C_END)
    API.info(nil, "  chu     : slot " .. CFG.HOUSE_SLOT ..
      ", dong minh voi " .. #S.pids .. " nguoi choi")
    API.info(nil, "  mau     : " .. API.num(GetUnitState(S.house, UNIT_STATE_MAX_LIFE)) ..
      (S.houseHpSet and "" or CFG.C_RED .. " (dat that bai: can 1.31+)" .. CFG.C_END))
    API.info(nil, "  tam nhin: " .. API.num(CFG.HOUSE_SIGHT) ..
      " qua " .. tostring(S.houseSightVia))
    API.info(nil, "  don danh: " ..
      (CFG.HOUSE_CAN_ATTACK and "con" or "khong tu nham (acquire range 0)"))
    API.info(nil, "  chet     : " ..
      (CFG.HOUSE_INVULNERABLE and (CFG.C_GOLD .. "bat tu, khong chet duoc" .. CFG.C_END)
       or (CFG.HOUSE_DEATH_ENDS_GAME and "thua ngay" or "khong sao")))
  end

  if S.enemyRect ~= nil then
    API.info(nil, "Vung dich : " .. API.num(S.enemyX) .. ", " .. API.num(S.enemyY) ..
      "  -- " .. blockLabel(S.enemyX, S.enemyY) ..
      CFG.C_GREY .. "  [vung " .. tostring(S.enemyRgnName) ..
      "]  (chua cho quai ra)" .. CFG.C_END)
  end
end

-- ---------- Cong dich chuyen: HeroMoveRegion -> nha chinh ----------
--
-- MOT CHIEU. Vung dich la nha chinh chu khong phai chinh vung nay, nen
-- khong co vong lap "vao roi lai bi day ve".
--
-- Su kien vao vung ban tren MOI may cung luc, nen viec doi vi tri o day
-- la dong bo san -- khong phai di qua kenh syncSend. Rieng keo camera
-- moi la viec cuc bo, va PanCameraToTimedForPlayer da nhan pid san.
-- Bao nhieu mon 'code' trong qua khoi dau. De cau thong bao doc duoc
-- so THAT thay vi go cung mot con so roi de no cu.
local function startCount(code)
  if CFG.START_ITEMS == nil then return 0 end
  for k = 1, #CFG.START_ITEMS do
    if CFG.START_ITEMS[k].code == code then
      return CFG.START_ITEMS[k].count or 0
    end
  end
  return 0
end

local function startHeroGate()
  local rMove, moveName = API.findRegion(CFG.RGN_HERO_MOVE)
  if rMove == nil then
    API.regionMissing("CFG.RGN_HERO_MOVE", API.regionLabel(CFG.RGN_HERO_MOVE))
    return
  end
  local rHouse = API.findRegion(CFG.RGN_HOUSE)
  if rHouse == nil then
    API.regionMissing("CFG.RGN_HOUSE", API.regionLabel(CFG.RGN_HOUSE))
    return
  end
  local hx, hy = API.regionCenter(rHouse)

  -- TriggerRegisterEnterRegion doi mot 'region', khong phai 'rect'.
  -- Vung cua World Editor la rect, nen phai boc lai mot lop.
  if CreateRegion == nil or RegionAddRect == nil
     or TriggerRegisterEnterRegion == nil then
    API.trace("gate: thieu CreateRegion/RegionAddRect/" ..
              "TriggerRegisterEnterRegion -- khong dat duoc cong")
    return
  end

  local rgn = CreateRegion()
  RegionAddRect(rgn, rMove)
  local t = CreateTrigger()
  TriggerRegisterEnterRegion(t, rgn, nil)
  TriggerAddAction(t, function()
    local u = GetTriggerUnit()
    if u == nil then return end
    -- CHI hero cua nguoi choi. Quai, pet va nha chinh cung di qua day
    -- duoc, ma dich chuyen chung thi tran dau loan het.
    local pid = (API.heroPidOf ~= nil) and API.heroPidOf(u) or nil
    if pid == nil then return end

    local x, y = API.heroFanPoint(pid, hx, hy, CFG.HERO_SPAWN_OFFSET)
    SetUnitPosition(u, x, y)

    -- Keo pet theo. Khong keo thi no chay bo ca ban do, va con duong do
    -- di qua bai quai.
    local d = S.p[pid]
    if d ~= nil and d.pet ~= nil and SetUnitPosition ~= nil then
      SetUnitPosition(d.pet, x, y)
    end

    if PanCameraToTimedForPlayer ~= nil then
      PanCameraToTimedForPlayer(Player(pid), x, y, 0.0)
    end

    -- Qua khoi dau -- CHI LAN DAU moi nguoi.
    --
    -- Cong nay nam ngay duoi cho hero hien ra: di ra di vao mat ba
    -- giay. Phat moi lan la mot cai may in luot quay va binh thuoc vo
    -- han, va luc do he Co Duyen mat het y nghia. Mot co duy nhat
    -- (d.gateGift) canh ca hai phan qua.
    if d ~= nil and not d.gateGift then
      d.gateGift = true

      if CFG.LUMBER_START ~= nil and CFG.LUMBER_START > 0
         and API.addLumber ~= nil then
        API.addLumber(pid, CFG.LUMBER_START)
      end

      -- Vang: dat THANH CFG.GOLD_START, khong cong them.
      --
      -- Warcraft da phat vang khoi dau theo war3map.w3i truoc khi mot
      -- dong Lua nao chay, va con so do khong doc duoc tu CFG. Cong
      -- them thi tong la "50 + mot con so khong ai biet". Bu phan lech
      -- thi dung 50 du w3i dat gi -- va GHI VET con so nen, de lan sau
      -- khong ai phai doan no nua.
      --
      -- Di qua addGold chu khong SetPlayerState: addGold la mot trong
      -- HAI duong ghi hop le, va no cap nhat so cai cua canh cheat.
      -- Ghi thang o day la tu to oan minh sau nua giay.
      if CFG.GOLD_START ~= nil and API.addGold ~= nil and API.getGold ~= nil then
        local base = API.getGold(pid)
        if base ~= CFG.GOLD_START then
          API.addGold(pid, CFG.GOLD_START - base)
        end
        API.trace("gate: pid " .. pid .. " vang nen " .. base ..
                  " -> dat thanh " .. CFG.GOLD_START)
      end

      local iron = CFG.IRON_START or 0
      if iron > 0 and API.addIron ~= nil then API.addIron(pid, iron) end

      -- Vat pham truoc, luot quay sau: neu tui day thi shopGive bao
      -- ngay, con nguoi choi van thay dong thuong quay o duoi.
      if CFG.START_ITEMS ~= nil and API.shopGive ~= nil then
        for k = 1, #CFG.START_ITEMS do
          local q = CFG.START_ITEMS[k]
          API.shopGive(pid, q.code, q.count)
        end
        -- DOC lai so that tu CFG chu khong go vao cau chu. Go vao chu
        -- thi doi CFG.TOWER_START tu 2 len 3 la cau thong bao noi doi
        -- -- va no noi doi IM LANG, khong ai kiem duoc.
        --
        -- Da Ren da ra khoi cau nay cung luc CFG.IRON_START ve 0
        -- (2026-09-19); cho do gio la vang va go.
        API.msg(pid, CFG.C_JADE .. API.t("gate_gift",
          startCount("hp"), startCount("mp"), startCount("tower"),
          CFG.GOLD_START or 0, CFG.LUMBER_START or 0) .. CFG.C_END)
      end

      local n = CFG.GATE_ROLL or 0
      if n > 0 and API.fortuneAddRolls ~= nil then
        API.fortuneAddRolls(pid, n)
        API.msg(pid, CFG.C_GOLD .. API.t("gate_roll", n) .. CFG.C_END)
      end
    end

    API.trace("gate: pid " .. pid .. " tu " .. moveName .. " -> nha chinh")
  end)
  S.heroGate = t
  API.trace("gate: " .. moveName .. " -> " .. (S.houseRgnName or "nha chinh"))
end

API.startHeroGate      = startHeroGate
API.blockLabel         = blockLabel
API.createHouse        = createHouse
API.onHouseDeath       = onHouseDeath
API.onHousePickup      = onHousePickup
API.resolveEnemyRegion = resolveEnemyRegion
API.setHouseHP         = setHouseHP
API.report             = report
end
--#endregion 3_battle/1_house.lua

--#region 3_battle/2_wave.lua
do
-- ============================================================
--  2_wave.lua  --  100 stage
--
--  Luat: docs/02-he-thong/dot-quai.md
--  Duong cong: docs/03-du-lieu/duong-cong-suc-manh.md
--
--  MOT bien stage duy nhat, 1..100. Canh gioi va tang deu SUY RA tu no
--  -- giu hai bien song song la chung se lech nhau.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- ---------- Chi so hoa stage ----------
-- Mot canh gioi = TIERS_PER_REALM tang + 1 boss. So 11 khong hard-code.
local function stagesPerRealm()
  return CFG.TIERS_PER_REALM + 1
end

local function totalStages()
  return #CFG.REALMS * stagesPerRealm()
end

-- Tra ve: canh gioi 1..20, tang 1..10, co phai boss khong
local function decode(stage)
  local per   = stagesPerRealm()
  local realm = math.floor((stage - 1) / per) + 1
  local k     = ((stage - 1) % per) + 1
  local isBoss = (k == per)
  local tier   = isBoss and CFG.TIERS_PER_REALM or k
  return realm, tier, isBoss
end

local function realmName(realm)
  return API.pick(CFG.REALMS[realm])
end

-- Tang cua mot stage, thanh chu: "So Ki", "Vien Man", hoac "BOSS".
--
-- Bon tang co TEN rieng (CFG.TIER_NAMES) chu khong danh so: "Truc Co So
-- Ki" doc ra nghia ngay, con "Truc Co Tang 3" thi phai nho tang 3 tren
-- tong bao nhieu.
--
-- Lui ve danh so neu bang ten thieu phan tu -- doi TIERS_PER_REALM ma
-- quen them ten thi van chay, chi la ten xau, chu khong no loi.
--
-- Chu o day di qua API.t/API.pick chu khong go thang: truoc day
-- stageLabel noi " tang " bang tieng Viet ngay ca khi CFG.LANG = "en",
-- nen ban tieng Anh hien ra "Mortal tang 4".
local function tierLabel(stage)
  local _, tier, isBoss = decode(stage)
  if isBoss then return API.t("stage_boss") end
  local name = CFG.TIER_NAMES and CFG.TIER_NAMES[tier] or nil
  if name ~= nil then return API.pick(name) end
  if tier >= CFG.TIERS_PER_REALM then return API.t("tier_perfection") end
  return API.t("tier_word") .. " " .. tier
end

-- Ten quai = canh gioi + TANG + hau to theo loai.
--
-- Co TANG trong ten vi khong co no thi ca 5 stage cua mot canh gioi ra
-- cung mot cai ten. Ma quai don lai qua nhieu wave (do duoc: stage 6
-- con 174 con song), nen tren map luc nao cung co vai the he cung luc
-- -- nhin vao mot con khong biet no thuoc dot nao, cung khong biet no
-- dang o dung gia tri thuong cua stage nao.
--
-- Boss khong can tang: no la lan do kiep DUY NHAT cua canh gioi do.
--
-- 20 canh gioi x 4 tang x 2 loai + 20 boss = 180 ten, sinh ra tu 20 ten
-- canh gioi + 4 ten tang + 3 hau to -- khong phai 180 unit type.
--
-- BlzSetUnitName doi ten TUNG con luc chay, nen doi tieng khong phai
-- dung toi Object Editor. Thieu native thi quai giu ten goc cua mau
-- lam no ("Footman", "Ghoul"...) -- 5_natives.lua do va bao truoc.
local function mobName(stage, kind)
  local realm = decode(stage)
  if kind == "boss" then
    return realmName(realm) .. " - " .. API.t("boss_suffix")
  end
  local suffix = (kind == "elite") and "elite_suffix" or "mob_suffix"
  return realmName(realm) .. " " .. tierLabel(stage) .. " - " .. API.t(suffix)
end

local function realmWorld(realm)
  local r = CFG.REALMS[realm]
  if r == nil then return 1 end
  return r.world
end

-- Chu hien cho nguoi choi: "Truc Co Tang 4" hoac "Truc Co Vien Man".
-- Cung mot nguon voi ten quai, nen dong bao wave va con quai tren map
-- khong the goi khac nhau.
local function stageLabel(stage)
  local realm = decode(stage)
  return realmName(realm) .. " " .. tierLabel(stage)
end

-- ---------- Duong cong ----------

-- He so Linh Can cua mot BAC, tinh thang tu bang chi so.
--
-- Goi qua API vi statAt nam trong 3_cultivation.lua. Tra ve 1.0 neu he do
-- chua san sang -- quai van sinh duoc, chi la khong bam theo.
local function cultPowerAt(rank)
  if API.cultStatAt == nil then return 1.0 end
  local b = CFG.CULT_DMG_BASE
  return (b + API.cultStatAt(rank)) / (b + API.cultStatAt(1))
end

-- EHP quai BAM THEO duong cong Linh Can -- xem CFG.MOB_EHP_FOLLOW_CULT.
--
-- Ca hai ve deu co cung thua so he so Linh Can nen no triet tieu, va ti
-- le "may phat mot con" phang theo dinh nghia. Mu cua MOB_EHP_GROWTH la
-- (TANG - 1), khong phai (stage - 1): phan tang truong theo canh gioi
-- da nam trong he so roi, dem hai lan la nhan doi do doc.
local function ehpOf(stage, realm)
  if CFG.MOB_EHP_FOLLOW_CULT then
    local _, tier = decode(stage)
    return CFG.MOB_EHP_BASE * cultPowerAt(realm)
         * CFG.MOB_EHP_GROWTH ^ (tier - 1)
  end
  return CFG.MOB_EHP_BASE
       * CFG.MOB_EHP_GROWTH ^ (stage - 1)
       * CFG.MOB_EHP_REALM_STEP ^ (realm - 1)
end

-- Sat thuong quai cung bam theo, nhung DOC HON: mau toi da cua hero len
-- theo Suc Manh, tuc len theo dung he so do. Giu nguyen duong cong cu
-- thi cuoi van quai go khong not hero.
--
-- MOB_DMG_FOLLOW_POW < 1 nen quai doc cham hon hero khoe len mot chut --
-- co y, de nguoi choi thay minh cung day len chu khong dam chan tai cho.
local function dmgOf(stage, realm)
  if CFG.MOB_EHP_FOLLOW_CULT then
    local _, tier = decode(stage)
    return CFG.MOB_DMG_BASE
         * cultPowerAt(realm) ^ (CFG.MOB_DMG_FOLLOW_POW or 1.0)
         * CFG.MOB_DMG_GROWTH ^ (tier - 1)
  end
  return CFG.MOB_DMG_BASE
       * CFG.MOB_DMG_GROWTH ^ (stage - 1)
       * CFG.MOB_DMG_REALM_STEP ^ (realm - 1)
end

local function armorOf(realm)
  return CFG.MOB_ARMOR_BASE + CFG.MOB_ARMOR_PER_REALM * (realm - 1)
end

-- Duong cong sinh ra EHP; MAU THAT suy nguoc ra tu giap. Cong giap o
-- dau thi chia mau o do. (ADR 0010)
local function hpFromEhp(ehp, armor)
  return ehp / (1 + CFG.ARMOR_DR_PER_POINT * armor)
end

-- So nguoi choi dang song, dem lai moi wave (ADR 0009).
local function playerCount()
  if not CFG.SCALE_RECOUNT_EACH_WAVE then return #S.pids end
  local n = API.activeCount()
  if n < 1 then n = 1 end
  return n
end

-- ---------- Sinh quai ----------

local function applyStats(u, ehp, dmg, armor)
  local hp = math.floor(hpFromEhp(ehp, armor) + 0.5)
  if hp < 1 then hp = 1 end

  if BlzSetUnitMaxHP ~= nil then
    BlzSetUnitMaxHP(u, hp)
    SetUnitState(u, UNIT_STATE_LIFE, GetUnitState(u, UNIT_STATE_MAX_LIFE))
  end
  if BlzSetUnitArmor ~= nil then
    BlzSetUnitArmor(u, armor)
  end
  if BlzSetUnitBaseDamage ~= nil then
    BlzSetUnitBaseDamage(u, math.floor(dmg + 0.5), 0)
  end
end

local function spawnPoint()
  if S.enemyX ~= nil then
    local jx = GetRandomReal(-CFG.SPAWN_JITTER, CFG.SPAWN_JITTER)
    local jy = GetRandomReal(-CFG.SPAWN_JITTER, CFG.SPAWN_JITTER)
    return API.clampToMap(S.enemyX + jx, S.enemyY + jy)
  end
  return API.blockCenter(3, 3)
end

local function sendToHouse(u)
  if S.houseX == nil then return end
  IssuePointOrder(u, "attack", S.houseX, S.houseY)
end

-- kind: "mob" | "elite" | "boss"
-- ex/ey: sinh o DUNG cho do thay vi o cua vao. Boss dung de goi thuoc
-- ha quanh minh, va thuoc ha phai di qua day de cung duong cong, cung
-- tien thuong, va cung duoc dem vao S.alive.
local function spawnOne(stage, realm, kind, ex, ey)
  -- Tra theo CANH GIOI, khong phai theo coi: quai doi hinh moi 5 stage
  -- thay vi moi 25. Thieu bac thi lui ve ma da chay that, chu khong
  -- tra nil va nuot ca wave.
  local uid = CFG.MOB_UNIT[realm] or CFG.MOB_UNIT_FALLBACK
  if uid == nil then return nil end

  local x, y = spawnPoint()
  if ex ~= nil and ey ~= nil then x, y = ex, ey end
  local face = API.angleXY(x, y, S.houseX or x, S.houseY or y)
  local u = CreateUnit(S.enemy, uid, x, y, face)
  if u == nil then
    S.wave.spawnFail = (S.wave.spawnFail or 0) + 1
    return nil
  end

  local P     = S.wave.players
  local ehp   = ehpOf(stage, realm) * (1 + CFG.SCALE_EHP_PER_PLAYER * (P - 1))
  local dmg   = dmgOf(stage, realm) * (1 + CFG.SCALE_DMG_PER_PLAYER * (P - 1))
  local armor = armorOf(realm)

  if kind == "elite" then
    ehp = ehp * CFG.ELITE_EHP
    dmg = dmg * CFG.ELITE_DMG
    SetUnitScale(u, CFG.ELITE_SCALE, CFG.ELITE_SCALE, CFG.ELITE_SCALE)
    SetUnitVertexColor(u, 255, 210, 120, 255)
  end

  applyStats(u, ehp, dmg, armor)
  if BlzSetUnitName ~= nil then BlzSetUnitName(u, mobName(stage, kind)) end
  S.mobs[u] = kind
  -- Ghi lai stage luc SINH, khong dung stage hien tai luc chet.
  -- Quai don lai qua nhieu wave (do duoc: stage 6 con 174 con song),
  -- nen tra theo stage hien tai la tu thuong them cho viec giet cham.
  S.mobStage[u] = stage
  -- Tu chinh gan SAU applyStats: no doi mau con quai, ma tinh anh cung
  -- doi mau -- de tu chinh thang thi ca dot doc ra mot mau duy nhat.
  if API.modifierApply ~= nil then API.modifierApply(u) end
  S.alive = S.alive + 1
  sendToHouse(u)
  return u
end

-- ---------- Kinh te ----------
--
-- Ba ham cu -- waveIncome(), bountyOf(), payBounty() -- da xoa het.
--
-- Chung ton tai de giai MOT bai toan: thu nhap la duong cong mu
-- 60 x 1.0319^(stage-1), chia cho 50 con, nen o stage 1 mot con dang
-- gia 0.72 Linh Khi. Lam tron xuong la ca wave dau duoc 0 dong; lam
-- tron len la thu nhap dau game vot 23%. Nen phai giu so thuc va cong
-- don phan le.
--
-- Thu nhap gio PHANG: mot con dung mot dong. Khong con phan le nao de
-- cong don, nen ca ba ham thanh thua. rewardAll() goi thang
-- API.addQi / addGold / addLumber.
--
-- He so x1.25 cua Phap Khi "Tu Linh Tran" mat theo, va do la dung: he
-- Phap Khi dang khoa (CFG.RELIC_LOCKED).

-- ---------- Mot wave ----------

-- Mau nha tinh lai moi wave theo sat thuong mot con linh o stage do.
-- Khong tinh lai thi den canh gioi 5 nha da thanh giay.
--
-- Giu nguyen TI LE mau dang co, roi hoi them REGEN_PER_WAVE -- neu dat
-- lai day mau moi wave thi lot bao nhieu cung khong sao.
local function rescaleHouse(stage, realm)
  if S.house == nil or BlzSetUnitMaxHP == nil then return end

  local oldMax = GetUnitState(S.house, UNIT_STATE_MAX_LIFE)
  local ratio  = 1.0
  if oldMax > 0 then
    ratio = GetUnitState(S.house, UNIT_STATE_LIFE) / oldMax
  end

  local P = S.wave.players
  local newMax = CFG.HOUSE_HP_HITS * dmgOf(stage, realm)
               * (1 + CFG.SCALE_DMG_PER_PLAYER * (P - 1))

  -- Hai Phap Khi cong vao nha chinh. Nha la cua CHUNG, nen chi can MOT
  -- nguoi mua la ca doi duoc -- do la ly do chung dat gia cao hon hai
  -- mon ca nhan o tren.
  local bonusMax, bonusRegen = 0.0, 0.0
  if API.relicAnyHas ~= nil then
    if API.relicAnyHas("nhahp")    then bonusMax   = 0.30 end
    if API.relicAnyHas("nharegen") then bonusRegen = 0.15 end
  end

  newMax = newMax * (1 + bonusMax)

  -- Nang cap nha chinh (the VI, tra bang vang) cong SUC MANH.
  --
  -- Dat Str THAT len unit roi moi dat max: nguoi choi bam vao nha thay
  -- con so do tren bang chi so, chu khong phai mot con so chi ton tai
  -- trong dau ta. Nhung max thi van do CONG THUC NAY quyet dinh --
  -- BlzSetUnitMaxHP goi SAU cung nen no thang, du Warcraft co tu tinh
  -- lai max theo Str hay khong. Mot nguon duy nhat, khong tranh chap.
  --
  -- Day la duong DUY NHAT dung: ham nay chay lai moi wave va tinh
  -- newMax tu dau, nen ai goi BlzSetUnitMaxHP ngoai day deu bi xoa o
  -- wave sau -- va xoa im lang.
  if API.houseUpStr ~= nil then
    local str = API.houseUpStr()
    if str > 0 then
      if SetHeroStr ~= nil and GetHeroStr ~= nil then
        local base = S.houseStrBase
        if base == nil then
          base = GetHeroStr(S.house, false)
          S.houseStrBase = base
        end
        SetHeroStr(S.house, base + str, true)
      end
      newMax = newMax + str * (API.houseUpStrHp and API.houseUpStrHp() or 25.0)
    end
  end

  newMax = math.floor(newMax + 0.5)
  if newMax < 1 then newMax = 1 end

  BlzSetUnitMaxHP(S.house, newMax)
  local heal = ratio + CFG.HOUSE_REGEN_PER_WAVE + bonusRegen
  if heal > 1.0 then heal = 1.0 end
  SetUnitState(S.house, UNIT_STATE_LIFE, newMax * heal)
end

-- Tinh lai NGAY, khong doi wave sau.
--
-- 12_houseup.lua goi cai nay luc mua Kien Co: mua giua mot wave dang bi
-- don ma phai cho het wave moi thay gi la mua trong bong toi, va dung
-- luc do thi nguoi choi can no NGAY.
--
-- Doc stage/realm tu S chu khong nhan tham so: ben goi khong co ly do
-- gi phai biet minh dang o stage may, va hai noi cung giu mot con so
-- thi som muon lech.
local function rescaleNow()
  local stage = S.stage
  if stage == nil then return end
  local realm = decode(stage)
  rescaleHouse(stage, realm)
end

local function spawnStage(stage)
  local realm, tier, isBoss = decode(stage)

  S.stage = stage
  S.wave.players = playerCount()
  S.wave.spawnFail = 0
  -- Stage boss KHONG co tu chinh: boss da co bang co che rieng
  -- (CFG.BOSS_MECH), chong them mot lop nua la khong ai doc ra cai gi
  -- dang giet minh. clear() tat ca thoi tiet.
  if API.modifierClear ~= nil then API.modifierClear() end
  rescaleHouse(stage, realm)

  if isBoss then
    -- Boss KHONG di qua spawnOne: no khong lay chi so tu duong cong ma
    -- DO suc manh that cua doi. Xem 3_boss.lua.
    local x, y = spawnPoint()
    local face = API.angleXY(x, y, S.houseX or x, S.houseY or y)
    local u = API.bossSpawn and API.bossSpawn(stage, realm, x, y, face) or nil
    if u ~= nil then
      S.mobs[u] = "boss"
      S.mobStage[u] = stage
      S.alive = S.alive + 1
      sendToHouse(u)
    else
      S.wave.spawnFail = (S.wave.spawnFail or 0) + 1
    end
    API.msg(nil, CFG.C_RED .. API.t("boss_coming", realmName(realm)) .. CFG.C_END)
  else
    -- BOC TRUOC KHI SINH: spawnOne() hoi tu chinh de gan len tung con.
    --
    -- Goi o day la mot rang buoc dong bo, khong phai tien tay: ham nay
    -- chay tu duong da dong bo nen GetRandomInt quay cung thu tu tren
    -- moi may. Boc trong callback cua frame la lech ban game (ADR 0012).
    if API.modifierPick ~= nil then API.modifierPick(stage) end

    for _ = 1, CFG.WAVE_MOB_COUNT do spawnOne(stage, realm, "mob") end
    for _ = 1, CFG.WAVE_ELITE_COUNT do spawnOne(stage, realm, "elite") end
    API.msg(nil, CFG.C_GOLD .. "[" .. stage .. "/" .. totalStages() .. "] " ..
      stageLabel(stage) .. CFG.C_END)
    if API.modifierAnnounce ~= nil then API.modifierAnnounce() end

    -- Ghi ro wave nay gom NHUNG GI, bang dung cai ten dang nam tren con
    -- quai. Mot wave co hai loai ma dong bao chi noi mot cau chung thi
    -- nguoi choi khong doi chieu duoc cai minh nhin thay voi cai vua doc.
    API.msg(nil, "   " .. CFG.C_GREY .. API.t("wave_comp",
      CFG.WAVE_MOB_COUNT,   mobName(stage, "mob"),
      CFG.WAVE_ELITE_COUNT, mobName(stage, "elite")) .. CFG.C_END)
  end

  if S.wave.spawnFail > 0 then
    API.warn(nil, "Khong sinh duoc " .. S.wave.spawnFail ..
      " con -- kiem tra CFG.MOB_UNIT.")
  end
  API.trace("stage " .. stage .. " (" .. stageLabel(stage) .. ") P=" ..
            S.wave.players .. " song=" .. S.alive)
end

-- Dong ho khong con la NHIP nua -- no chi con mot viec: hoan viec sinh
-- quai ra khoi su kien dang chay.
--
-- waveNow() duoc goi tu cu bam frame hoac tu lenh chat, tuc dang o BEN
-- TRONG mot su kien cua engine. Sinh 51 unit ngay tai do la dung cai bay
-- ADR 0005. Nen waveNow() hen timer 0.02 giay, va ham nay chay o nhip sau.
--
-- Moi dieu kien chan (con quai song, het stage) da kiem o waveNow/callState
-- TRUOC khi toi day.
local function onWaveTimer()
  -- Co mo o waveNow() ha xuong NGAY DAY: den day dot da that su bat
  -- dau, khong con gi de tranh nhau nua. Ha truoc ca phep kiem
  -- S.running, neu khong mot lan tu choi la co ket cung mai mai.
  S.waveCalling = false
  if not S.running then return end

  local nextStage = S.stage + 1
  if nextStage > totalStages() then
    API.endGame(true, API.t("win_final", realmName(#CFG.REALMS)))
    return
  end
  spawnStage(nextStage)
end

-- ---------- Nhip 2 giay: ra lenh lai ----------
-- Quai bi danh lac huong khong tu quay ve nha.

local function tick()
  if not S.running or S.houseX == nil then return end
  for u, _ in pairs(S.mobs) do
    if u ~= nil and API.alive(u) then sendToHouse(u) end
  end
  -- Boss dung chung nhip nay chu khong nuoi dong ho rieng: mot nhip thi
  -- khong co chuyen hai dong ho troi lech nhau.
  if API.bossTick ~= nil then API.bossTick() end
end

-- Goi dot ke tiep. Day la cho DUY NHAT dot moi duoc sinh ra -- khong con
-- dong ho nao tu keo dot vao nua.
--
-- Chay tren MOI may, tu kenh dong bo (nut tren bang tran dau) hoac tu
-- lenh chat.
--
-- Khong goi thang onWaveTimer(): sinh 51 unit ngay trong su kien dang
-- chay la cai bay ADR 0005. Hen 0.02 giay de no chay o nhip sau.
local function waveNow()
  if not S.running or S.waveTimer == nil then
    API.trace("waveNow: TU CHOI -- running=" .. tostring(S.running) ..
              " timer=" .. tostring(S.waveTimer ~= nil))
    return false
  end

  -- Con quai song thi khong goi duoc. Kiem O DAY chu khong chi o giao
  -- dien: nut co the bi bam dung luc con cuoi cung chua chet, va lenh
  -- chat thi khong qua giao dien bao gio.
  if CFG.WAVE_ONLY_WHEN_CLEAR and S.alive > 0 then
    API.msg(nil, CFG.C_GREY .. API.t("wave_hold", S.alive) .. CFG.C_END)
    API.trace("waveNow: TU CHOI -- con song " .. S.alive)
    return false
  end

  if S.alive >= CFG.WAVE_MAX_ALIVE then
    API.msg(nil, CFG.C_GREY .. API.t("wave_hold", S.alive) .. CFG.C_END)
    return false
  end

  if S.stage + 1 > totalStages() then return false end

  -- KHE 0.02 GIAY. Tu day den luc spawnStage() chay, S.alive van la 0,
  -- nen phep kiem "con quai song thi thoi" o tren VAN CHO QUA. Bam hai
  -- cai lien la ra hai dot -- da dinh: 100 con mot luc.
  --
  -- Co nay dong khe do lai. No o TRONG waveNow chu khong o giao dien:
  -- lenh chat -next va nguoi choi thu hai khong di qua giao dien nao.
  if S.waveCalling then
    API.trace("waveNow: TU CHOI -- dang goi mot dot roi")
    return false
  end
  S.waveCalling = true

  API.trace("waveNow: goi dot " .. (S.stage + 1) ..
            " (cho=" .. tostring(S.waitNext) .. ")")
  S.waitNext = nil
  S.waveHold = false
  PauseTimer(S.waveTimer)
  TimerStart(S.waveTimer, 0.02, false, onWaveTimer)
  return true
end

-- ---------- Phat thuong ----------
--
-- MOI phan thuong di qua day. Quai thuong, tinh anh, boss -- ca hai loai
-- tien -- deu chia deu cho MOI nguoi choi, khong phu thuoc ai ket lieu.
-- Xem ADR 0013.
--
-- Mot cho duy nhat, vi truoc day Linh Khi va Tinh Thach moi cai mot vong
-- lap rieng: thu them mot loai thuong nua la quen mot cho.
local function rewardAll(stage, kind)
  -- Ba loai quai, ba dong tien. So PHANG, khong theo stage:
  --
  --   linh thuong -> 1 Linh Khi + 1 Vang   (nhip giay)
  --   tinh anh    -> 2 Go                  (nhip wave)
  --   boss        -> 5 Go                  (nhip canh gioi)
  --
  -- Moi loai quai mo khoa dung mot he, nen ba he bi chan boi ba loai
  -- NOI DUNG khac nhau chu khong chi boi mot cai vi:
  --   Linh Khi -> Linh Can   Vang -> Shop   Go -> Ky Nang
  --
  -- Xem docs/02-he-thong/kinh-te.md
  -- Tu chinh "Trung Linh" nhan MOI phan thuong cua stage nay.
  --
  -- Nhan ca Go va luot Co Duyen chu khong chi tien: chot 2026-09-19 vi
  -- Go se co them cho tieu. Ky vong ca van: Go 260 -> ~292, luot quay
  -- 169 -> ~185.
  local mult = (API.modifierRewardMult ~= nil) and API.modifierRewardMult() or 1.0
  local qi, gold, lumber, cards = 0, 0, 0, 0
  if kind == "boss" then
    qi   = CFG.REWARD_BOSS_QI
    lumber   = CFG.REWARD_BOSS_LUMBER
    cards = CFG.FORTUNE_BOSS
  elseif kind == "elite" then
    qi   = CFG.REWARD_ELITE_QI
    lumber   = CFG.REWARD_ELITE_LUMBER
    cards = CFG.FORTUNE_ELITE
  else
    qi   = CFG.REWARD_MOB_QI
    gold = CFG.REWARD_MOB_GOLD
  end

  if mult ~= 1.0 then
    qi     = math.floor(qi     * mult + 0.5)
    gold   = math.floor(gold   * mult + 0.5)
    lumber = math.floor(lumber * mult + 0.5)
    cards  = math.floor(cards  * mult + 0.5)
  end

  for i = 1, #S.pids do
    local pid = S.pids[i]
    if S.p[pid] ~= nil and S.p[pid].active then
      if qi > 0 then API.addQi(pid, qi) end
      if gold > 0 then API.addGold(pid, gold) end
      -- Them luot quay CHAY TREN MOI MAY (ham nay di tu su kien quai
      -- chet), va no rut luon ba the -- do la cho duy nhat duoc goi
      -- GetRandomInt cho he quay. Xem dau 10_fortune.lua.
      if cards > 0 and API.fortuneAddRolls ~= nil then
        API.fortuneAddRolls(pid, cards)
      end
      if lumber > 0 then
        local n = lumber
        if kind == "elite" and API.relicHas ~= nil
           and API.relicHas(pid, "go") then n = n + 1 end
        API.addLumber(pid, n)
      end
    end
  end
  -- Ve lai bang khi mot dong tien nhay MOT CUC LON: Go tung diem mot,
  -- va Linh Khi cua tinh anh/boss (50/100) -- moi cai deu dang ke. Quai
  -- thuong nhay 1 moi con, ve lai moi con la 50 lan mot wave, de nhip
  -- refresh cua bang lo.
  if lumber > 0 then API.panelRefreshAll() end

  if kind == "boss" then
    API.msg(nil, CFG.C_JADE .. API.t("boss_down", realmName(realm), lumber) .. CFG.C_END)
  end
end

-- ---------- Nghi giua hai canh gioi ----------
--
-- Danh dau dang cho viec gi. 'what' doi NHAN cua nut goi dot tren bang
-- tran dau: "boss" -> TRIEU BOSS, "realm" -> SANG CANH GIOI SAU.
local function pauseWaves(what)
  S.waitNext = what
  if S.waveTimer ~= nil then PauseTimer(S.waveTimer) end
  API.trace("wave: cho '" .. what .. "' o stage " .. S.stage)
end

-- ---------- Wave vua sach ----------
--
-- Tach rieng khoi onMobDeath vi CO HAI duong toi day:
--   1. con cuoi cung chet  -> onMobDeath
--   2. phep DO LAI phat hien so dem da lech -> recount()
--
-- Duong 2 la thu bat buoc phai co. Neu mot con bien mat ma khong sinh su
-- kien chet, onMobDeath khong chay cho no, va neu HAI MOC nay chi nam
-- trong onMobDeath thi ca van se bo qua boss -- nut goi se hien "GOI DOT"
-- thay vi "TRIEU BOSS", va khong ai biet da mat mot tran boss.
local function onWaveCleared()
  if S.stage <= 0 or not S.running then return end
  if API.relicOnClear ~= nil then API.relicOnClear() end

  -- LUOI HUNG cho khung Co Duyen, khong phai cho mo chinh.
  --
  -- Cho mo chinh la addRolls() -- ngay luc tinh anh/boss/Thanh Thu
  -- chet. Dong nay chi bat mot truong hop: showFrame() thoat som khi
  -- build(pid) hong, va luc do luot nam lai ma khong co khung nao.
  -- Toi day thu dung lai khung mot lan nua.
  --
  -- Khong co luot thi showIfPending() tra false va khong lam gi, nen
  -- dong nay khong bao gio ban nham.
  --
  -- Dat TRUOC ba nhanh return ben duoi: ca ba deu la "wave da sach".
  if API.fortuneShowPending ~= nil then
    for i = 1, #S.pids do API.fortuneShowPending(S.pids[i]) end
  end

  local r, tier, wasBoss = decode(S.stage)

  -- MOC 1: vua ha boss -> cho goi sang canh gioi sau.
  if CFG.WAVE_REST and wasBoss and S.stage < totalStages() then
    pauseWaves("realm")
    API.msg(nil, CFG.C_GOLD ..
      API.t("wave_realmdone", realmName(r + 1)) .. CFG.C_END)
    return
  end

  -- MOC 2: vua don sach tang cuoi -> cho goi boss.
  if CFG.WAVE_REST and (not wasBoss) and tier >= CFG.TIERS_PER_REALM then
    pauseWaves("boss")
    API.msg(nil, CFG.C_GOLD ..
      API.t("wave_perfection", realmName(r)) .. CFG.C_END)
    return
  end

  API.msg(nil, CFG.C_JADE .. API.t("wave_cleared") .. CFG.C_END)
end

-- ---------- DO LAI so quai song ----------
--
-- LOI THAT (ADR 0018): S.alive ket tren 0 thi MOI loi thoat cung chet --
-- ca duong "don sach" lan nut goi tay, vi ca hai hoi cung con so do.
-- Ket la ket vinh vien, khong loi nao bao.
--
-- Nen cu CFG.WAVE_RECOUNT giay lai DO LAI thay vi tin con so dang giu.
--
-- DEM QUA S.mobs, KHONG quet map theo chu so huu.
--   S.mobs chi duoc ghi o duong sinh cua he wave, nen quai DAT SAN o cac
--   vung dat sau nay khong bao gio lot vao. Dem theo
--   GetOwningPlayer == S.enemy thi vo luon chung va S.alive khong bao gio
--   ve 0 -- dung cai bay ma phep do nay dinh chua.
--
-- Xoa khoa trong luc pairs() la HOP LE trong Lua (them khoa moi moi
-- khong duoc), nen don xac ngay tai cho duoc.
local function recount()
  if not S.running then return end
  local n, gone = 0, 0
  for u, _ in pairs(S.mobs) do
    if API.alive(u) then
      n = n + 1
    else
      S.mobs[u] = nil
      S.mobStage[u] = nil
      gone = gone + 1
    end
  end
  if gone == 0 and n == S.alive then return end

  local before = S.alive
  API.trace("wave: DO LAI -- S.alive " .. before .. " -> " .. n ..
            " (don " .. gone .. " con da bien mat khong sinh su kien chet)")
  S.alive = n

  -- Con cuoi cung bien mat ma khong ai bao: phai chay NOT phan "da don
  -- sach", neu khong ca van se bo qua boss trong im lang.
  if before > 0 and n == 0 then onWaveCleared() end
end

-- ---------- Goi tu 08_events khi mot con chet ----------

local function onMobDeath(u, killer)
  local kind = S.mobs[u]
  if kind == nil then return end

  S.mobs[u] = nil
  S.alive = S.alive - 1
  if S.alive < 0 then S.alive = 0 end
  -- Dem cho bang tong ket. Dem o DAY chu khong o onAnyDeath: cho nay
  -- da loc 'kind == nil' nen no chi dem quai cua he wave, khong dem
  -- thap canh, pet hay hero.
  S.killCount = (S.killCount or 0) + 1

  local stage = S.mobStage[u] or S.stage
  S.mobStage[u] = nil

  rewardAll(stage, kind)

  if S.alive == 0 then onWaveCleared() end
end

-- ---------- Khoi dong ----------

-- Nhan cua nut goi dot tren bang tran dau. Giao dien chi VE lai thu ham
-- nay tra ve -- no khong tu suy ra trang thai o dau ca, de nut va lenh
-- chat khong bao gio noi hai dieu khac nhau.
local function callState()
  local nextStage = S.stage + 1
  if not S.running then
    return { label = API.t("wave_btn_wait"), on = false }
  end
  if nextStage > totalStages() then
    return { label = API.t("wave_btn_done"), on = false }
  end
  if CFG.WAVE_ONLY_WHEN_CLEAR and S.alive > 0 then
    return { label = API.t("wave_btn_busy", S.alive), on = false }
  end
  if S.waitNext == "boss" then
    return { label = API.t("wave_btn_boss"), on = true }
  end
  if S.waitNext == "realm" then
    local r = decode(S.stage)
    return { label = API.t("wave_btn_realm", realmName(r + 1)), on = true }
  end
  if S.stage <= 0 then
    return { label = API.t("wave_btn_first"), on = true }
  end
  return { label = API.t("wave_btn_next", nextStage), on = true }
end

-- Tao thu 20 mau linh luc vao map, kiem hai thu, roi xoa di.
--
-- VI SAO PHAI DO. Mot ma unit bon ky tu go sai thi CreateUnit tra ve
-- nil va wave do khong sinh duoc con nao -- im lang, va chi lo ra o
-- canh gioi 14 sau bon muoi phut choi. Do o giay dau thi biet ngay.
--
-- VA KIEM BAY. Chu du an yeu cau khong co quai bay: quai bay thi hero
-- danh gan khong cham toi, duong di khong theo dia hinh, va Chan Dia
-- cua boss thanh vo nghia. Ban truoc coi Than dung Frost Wyrm va no
-- bay -- khong ai bat duoc vi khong co cho nao kiem.
--
-- Tao o goc ban do roi RemoveUnit ngay. Mot con hien ra nua giay o goc
-- thi khong ai thay; mot wave rong thi ai cung thay.
local function probeMobUnits()
  if CreateUnit == nil or CFG.MOB_UNIT == nil then return end
  local bad, flying = {}, {}
  for r = 1, #CFG.REALMS do
    local uid = CFG.MOB_UNIT[r]
    if uid == nil then
      bad[#bad + 1] = r
    else
      local u = CreateUnit(S.enemy, uid, 0.0, 0.0, 0.0)
      if u == nil then
        bad[#bad + 1] = r .. ":" .. API.idToStr(uid)
      else
        if IsUnitType ~= nil and _G["UNIT_TYPE_FLYING"] ~= nil
           and IsUnitType(u, UNIT_TYPE_FLYING) then
          flying[#flying + 1] = r .. ":" .. API.idToStr(uid)
        end
        RemoveUnit(u)
      end
    end
  end

  if #bad > 0 then
    API.warn(nil, "CFG.MOB_UNIT sai ma o canh gioi: " ..
             table.concat(bad, " ") .. " -- lui ve " ..
             API.idToStr(CFG.MOB_UNIT_FALLBACK or 0))
  end
  if #flying > 0 then
    API.warn(nil, "CFG.MOB_UNIT co quai BAY o canh gioi: " ..
             table.concat(flying, " ") .. " -- hero danh gan khong cham toi")
  end
  API.trace("wave: do " .. #CFG.REALMS .. " mau linh -- " .. #bad ..
            " ma sai, " .. #flying .. " con bay")
end

local function startWaves()
  probeMobUnits()
  S.stage = 0
  S.mobs  = {}
  S.mobStage = {}
  S.alive = 0
  S.wave  = { players = 1, spawnFail = 0 }

  -- Dong ho nay KHONG con dem nguoc gi. No chi duoc waveNow() hen 0.02
  -- giay mot lan de hoan viec sinh quai ra khoi su kien dang chay.
  -- Khong co TimerDialog: khong con con so nao chay tren man hinh.
  S.waveTimer = CreateTimer()
  API.msg(nil, CFG.C_GOLD .. API.t("wave_waiting") .. CFG.C_END)

  S.tickTimer = CreateTimer()
  TimerStart(S.tickTimer, CFG.WAVE_TICK, true, tick)

  -- Luoi do: xem chu thich recount().
  S.recountTimer = CreateTimer()
  TimerStart(S.recountTimer, CFG.WAVE_RECOUNT, true, recount)

  API.trace("wave: khoi dong, " .. totalStages() .. " stage")
end

local function stopWaves()
  if S.waveTimer ~= nil then PauseTimer(S.waveTimer) end
  if S.tickTimer ~= nil then PauseTimer(S.tickTimer) end
  if S.recountTimer ~= nil then PauseTimer(S.recountTimer) end
end

-- Lenh dev "-wave N": nhay thang toi stage N. Khong co no thi khong ai
-- kiem duoc stage 180.
local function jumpTo(stage)
  if stage < 1 then stage = 1 end
  if stage > totalStages() then stage = totalStages() end
  S.stage = stage - 1
  TimerStart(S.waveTimer, 0.5, false, onWaveTimer)
end

API.stagesPerRealm = stagesPerRealm
API.totalStages    = totalStages
API.decodeStage    = decode
API.realmName      = realmName
API.stageLabel     = stageLabel
API.tierLabel      = tierLabel
API.ehpOf          = ehpOf
API.dmgOf          = dmgOf
API.armorOf        = armorOf
API.mobName        = mobName
API.realmWorld       = realmWorld
-- Boss goi de sinh thuoc ha quanh minh, tai mot toa do cu the.
API.waveSpawnAt    = function(stage, realm, x, y)
  return spawnOne(stage, realm, "mob", x, y)
end
API.waveNow        = waveNow
API.waveWaiting    = function() return S.waitNext end
API.waveCallState  = callState
API.onMobDeath     = onMobDeath
API.waveRescaleHouse = rescaleNow
API.startWaves     = startWaves
API.stopWaves      = stopWaves
API.jumpToStage    = jumpTo
end
--#endregion 3_battle/2_wave.lua

--#region 3_battle/3_boss.lua
do
-- ============================================================
--  3_boss.lua  --  Boss: hero di bo, do theo suc manh THAT cua doi
--
--  KHAC HAN QUAI THUONG. Quai thuong bam theo duong cong Tu Vi (xem
--  CFG.MOB_EHP_FOLLOW_CULT). Boss thi DO doi ngay luc no xuat hien --
--  chi so, sat thuong, giap, mau -- roi suy ra mau va don danh cua no.
--
--  Vi sao phai do chu khong dung duong cong: duong cong gia dinh nguoi
--  choi len dung mot bac moi canh gioi. Ai cay them, ai bo lo, ai don
--  het the chi so o Co Duyen -- duong cong khong biet. Boss thi phai
--  biet, neu khong no hoac la bia thit hoac la buc tuong.
--
--  VA MOT LOI DO DUOC: 1 Agi = 1/3 giap, ma Tu Vi cong deu ca ba chi
--  so. Cuoi van hero co 8,070 giap -> giam 99.79% sat thuong. Dat sat
--  thuong boss bang mot con so tuyet doi thi no danh 2,036 chi con 4
--  mau. Nen boss tinh theo MAU HIEU DUNG: mau / (1 - giam).
--
--  Hai muoi con, moi canh gioi mot con, moi con mot file mo ta rieng:
--  docs/02-he-thong/boss/
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function damageReduction(armor)
  local k = CFG.ARMOR_DR_PER_POINT * armor
  if k <= 0 then return 0.0 end
  return k / (1.0 + k)
end

local function hasMech(b, name)
  return b ~= nil and b.mech ~= nil and b.mech[name] == true
end

local function mechNum(name, field)
  local t = CFG.BOSS_MECH and CFG.BOSS_MECH[name] or nil
  return (t ~= nil) and t[field] or 0.0
end

-- ---------- Do suc manh doi ----------
-- Tra ve: tong dps uoc luong, mau hieu dung TRUNG BINH mot hero, so hero

-- Tong % ma cac BI DONG cong vao moi don danh DON MUC TIEU.
--
-- VI SAO KHONG GOM "cleave": Chem Lan van sat thuong sang con BEN
-- CANH. Danh boss thi boss dung mot minh, nen no cong 0. Gom vao la
-- uoc luong cao len va boss thanh qua day mau cho Hart.
--
-- "burn" thi nguoc lai: no dot chinh muc tieu vua danh, nen no cong du
-- ca khi chi co mot con. Bang CFG.BOSS_DPS_PASSIVE_FX giu danh sach
-- nay, de them bi dong moi la khai them mot dong chu khong sua ham.
local function passivePct(pid)
  local list = CFG.BOSS_DPS_PASSIVE_FX
  if list == nil or API.skillList == nil then return 0.0 end
  local sks, sum = API.skillList(pid), 0.0
  for i = 1, #sks do
    for k = 1, #list do
      if sks[i].fx == list[k] then
        local lv = API.skillLevel(pid, sks[i].id, i)
        if lv > 0 then sum = sum + API.skillPct(sks[i], lv) end
      end
    end
  end
  return sum
end

-- ---------- Hao quang ----------
--
-- Gan mot trong nam aura co san cua Warcraft len boss. Ca nam deu la
-- PHAN TRAM nen tu bam theo suc boss, khong teo (ADR 0024).
--
-- BA CHO DE HONG IM LANG, va ca ba deu ghi vet:
--
--   1. MA ABILITY SAI. UnitAddAbility tra false -- khong nem loi, khong
--      bao gi. Nen do lan luot qua danh sach ung cu vien.
--
--   2. QUEN DAT BAC. Ability gan bang UnitAddAbility ra o BAC 0 va bac
--      0 khong co tac dung nao. Day la cai bay da ghi trong
--      docs/02-he-thong/ky-nang.md, va no khong hien ra o dau ca.
--
--   3. SAI LOAI DON DANH. Vampiric chi an don CAN CHIEN, Trueshot chi
--      an don TAM XA -- luat cua Warcraft. Gan nham thi aura ton tai,
--      icon hien, va khong lam gi het.
local function applyAura(u, d, realm)
  if d == nil or d.aura == nil or UnitAddAbility == nil then return nil end
  local a = (CFG.BOSS_AURA or {})[d.aura]
  if a == nil then
    API.trace("boss: aura '" .. tostring(d.aura) .. "' khong co trong CFG.BOSS_AURA")
    return nil
  end

  -- Loai don danh: DO, khong suy tu ten unit.
  local ranged = (IsUnitType ~= nil) and _G["UNIT_TYPE_RANGED_ATTACKER"] ~= nil
                 and IsUnitType(u, UNIT_TYPE_RANGED_ATTACKER) or false
  if a.need == "melee" and ranged then
    API.trace("boss: r" .. realm .. " aura '" .. d.aura ..
              "' can don CAN CHIEN ma con nay danh XA -- se khong an gi")
  elseif a.need == "ranged" and not ranged then
    API.trace("boss: r" .. realm .. " aura '" .. d.aura ..
              "' can don TAM XA ma con nay danh GAN -- se khong an gi")
  end

  local code = nil
  for i = 1, #(a.abils or {}) do
    local c = FourCC(a.abils[i])
    if UnitAddAbility(u, c) then code = c; break end
  end
  if code == nil then
    API.trace("boss: r" .. realm .. " KHONG gan duoc aura '" .. d.aura ..
              "' (" .. table.concat(a.abils or {}, " ") .. ")")
    return nil
  end

  -- BAC. Chia 20 canh gioi thanh CFG.BOSS_AURA_MAX_LEVEL khoang deu.
  -- Khong dat thi ability nam o bac 0 va khong lam gi -- kieu hong im
  -- lang nhat trong ca ba.
  local top = CFG.BOSS_AURA_MAX_LEVEL or 3
  local lv = math.floor((realm - 1) / (20.0 / top)) + 1
  if lv < 1 then lv = 1 elseif lv > top then lv = top end
  if SetUnitAbilityLevel ~= nil then SetUnitAbilityLevel(u, code, lv) end

  API.trace("boss: r" .. realm .. " aura '" .. d.aura .. "' bac " .. lv ..
            " (" .. (ranged and "danh xa" or "danh gan") .. ")")
  return a
end

local function measureParty()
  local dps, ehpAvg, n = 0.0, 0.0, 0
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h) then
      n = n + 1
      local pid = S.pids[i]
      local top = API.skillTopStat and API.skillTopStat(h) or 0
      local hit = CFG.BOSS_DPS_FACTOR * (CFG.CULT_DMG_BASE + top)

      -- NHAN CAC LOP % DON DANH, y het onDamaged() lam voi don THAT.
      --
      -- LO HONG DA CO: ham nay chi lay (DMG_BASE + chi so), trong khi
      -- don danh that con nhan them %Kiem va Phap Khi Hoa Vu. Nen cang
      -- mua Trang Bi thi uoc luong cang thap so voi that, tuc BOSS CANG
      -- DE -- nguoc han y do. Khong ai thay duoc vi boss van "co mau
      -- theo doi", chi la sai he so.
      local pct = 0.0
      if API.gearDmgPct ~= nil then pct = pct + API.gearDmgPct(pid) end
      if API.relicVal ~= nil then
        pct = pct + API.relicVal(pid, "hoavu", "dmgUp")
      end
      if pct > 0.0 then hit = hit * (1.0 + pct) end

      -- MOT DON, khong phai mot giay. Phai chia cho hoi chieu don danh
      -- that -- neu khong thi mau boss = 40 DON chu khong phai 40 giay,
      -- va boss chet trong chop mat.
      --
      -- BlzGetUnitAttackCooldown tra ve giay giua hai don, DA tinh ca
      -- buff toc danh. Vang mat thi lui ve hang so va BAO RA.
      local cd = nil
      local fn = _G["BlzGetUnitAttackCooldown"]
      if fn ~= nil then cd = fn(h, 0) end
      if cd == nil or cd <= 0.0 then
        if not S.warnedCooldown then
          S.warnedCooldown = true
          API.trace("boss: KHONG doc duoc BlzGetUnitAttackCooldown -- " ..
                    "lui ve " .. CFG.BOSS_ATTACKS_FALLBACK .. " don/giay")
        end
        cd = 1.0 / CFG.BOSS_ATTACKS_FALLBACK
      end

      -- Ky nang gop them. Uoc luong, chinh theo dong trace luc boss chet.
      --
      -- BOSS_SKILL_SHARE la phan CHU DONG (bam nut). Bi dong cong % vao
      -- moi don danh -- Thieu Thien cua Hvwd -- thi phai cong RIENG:
      -- no khong phai mot uoc luong chung, no la con so doc duoc.
      --
      -- Do duoc 2026-09-19: boss r16 chet sau 30s so voi thiet ke 40s,
      -- tuc san luong that gap 1.33 lan uoc luong. Hvwd luc do co Thieu
      -- Thien va khong co Trang Bi -- dung bang phan bi dong thieu o day.
      dps = dps + (hit / cd) * (1.0 + CFG.BOSS_SKILL_SHARE + passivePct(pid))

      local cut = damageReduction((BlzGetUnitArmor ~= nil) and BlzGetUnitArmor(h) or 0.0)
      -- Mau hieu dung: bao nhieu sat thuong THO moi ha duoc hero nay.
      ehpAvg = ehpAvg + GetUnitState(h, UNIT_STATE_MAX_LIFE) / (1.0 - cut)
    end
  end
  if n == 0 then return 0.0, 0.0, 0 end
  return dps, ehpAvg / n, n
end

-- ---------- Tra ban thiet ke ----------

local function def(realm)
  if CFG.BOSSES ~= nil then
    for i = 1, #CFG.BOSSES do
      if CFG.BOSSES[i].r == realm then return CFG.BOSSES[i] end
    end
  end
  return nil
end

-- ---------- Sinh boss ----------

local function spawn(stage, realm, x, y, face)
  local d = def(realm)
  local uid = (d ~= nil) and d.unit
              or CFG.BOSS_UNIT[API.realmWorld and API.realmWorld(realm) or 1]
  if uid == nil then return nil end

  local u = CreateUnit(S.enemy, uid, x, y, face)
  if u == nil then return nil end

  local dps, ehpAvg, n = measureParty()

  -- MAU: song duoc BOSS_SECONDS duoi hoa luc ca doi.
  -- Khong nhan them theo so nguoi choi -- dps o tren DA la tong cua ca
  -- doi. Nhan hai lan la phat nguoi choi vi ru duoc ban.
  local hp = dps * CFG.BOSS_SECONDS
  if hp < 1.0 then hp = 1.0 end

  -- SAT THUONG: ha mot hero dung yen trong BOSS_HITS_TO_KILL don. Con so nay
  -- la sat thuong THO -- nhin rat to, nhung sau giap no dung bang
  -- mau_that / BOSS_HITS_TO_KILL.
  local dmg = ehpAvg / CFG.BOSS_HITS_TO_KILL
  if dmg < 1.0 then dmg = 1.0 end

  if BlzSetUnitMaxHP ~= nil then
    BlzSetUnitMaxHP(u, math.floor(hp + 0.5))
    SetUnitState(u, UNIT_STATE_LIFE, GetUnitState(u, UNIT_STATE_MAX_LIFE))
  end
  if BlzSetUnitBaseDamage ~= nil then
    BlzSetUnitBaseDamage(u, math.floor(dmg + 0.5), 0)
  end
  -- Boss KHONG co giap: mau vua tinh DA la mau that can de tru.
  if BlzSetUnitArmor ~= nil then BlzSetUnitArmor(u, 0.0) end

  SetUnitScale(u, CFG.BOSS_SCALE, CFG.BOSS_SCALE, CFG.BOSS_SCALE)
  SetUnitVertexColor(u, 255, 120, 120, 255)
  -- Hero thi co kinh nghiem. Khoa lai, khong thi boss len cap giua tran
  -- va moi con so vua tinh o tren truot het.
  if SuspendHeroXP ~= nil then SuspendHeroXP(u, true) end
  if BlzSetUnitName ~= nil and d ~= nil then BlzSetUnitName(u, API.pick(d)) end

  local mechSet = {}
  if d ~= nil and d.mech ~= nil then
    for i = 1, #d.mech do mechSet[d.mech[i]] = true end
  end

  S.boss = {
    u = u, stage = stage, realm = realm, def = d, mech = mechSet,
    dmg = dmg, maxHp = hp, enraged = false, casting = false,
    age = 0.0,
    cdSlam = mechNum("slam", "cd"), cdCharge = mechNum("charge", "cd"),
    cdSummon = mechNum("summon", "cd"), cdShield = mechNum("shield", "cd"),
    shield = 0.0,
  }

  local aura = applyAura(u, d, realm)

  if d ~= nil then
    API.msg(nil, CFG.C_RED .. API.t("boss_arrived", API.pick(d)) .. CFG.C_END)
  end
  -- BAO HAO QUANG RA CHU. Khong bao thi no la mot he so vo hinh: nguoi
  -- choi thua ma khong biet vi sao. Cung ly le voi tu chinh -- mot lop
  -- co that nhung khong doc duoc thi khong dung de ra quyet dinh duoc.
  if aura ~= nil then
    local en = (API.lang() == "en")
    API.msg(nil, CFG.C_GOLD .. API.t("boss_aura", API.pick(aura)) ..
            CFG.C_END .. "  " .. CFG.C_GREY ..
            ((en and aura.desc_en) or aura.desc_vi or "") .. CFG.C_END)
  end
  API.trace("boss: r" .. realm .. " " .. API.idToStr(uid) .. " -- " .. n ..
            " hero, dps " .. math.floor(dps) .. " -> mau " .. math.floor(hp) ..
            ", don " .. math.floor(dmg))

  -- Chan Dia chi la co che neu hai cau hoi nay co cau tra lai DO DUOC:
  --
  --   1. Ai chay kip ra khoi vong? (toc do x cast so voi radius)
  --   2. Ai o lai thi song? (don chia cho mau hieu dung CUA CHINH HO)
  --
  -- Cau 2 quan trong hon cau 1. b.dmg tinh tren mau hieu dung TRUNG BINH
  -- ca doi, nen cung mot don Chan Dia se an vao tanker nhe hon va an vao
  -- thang mong nang hon -- dung y do: tanker o lai chiu, thang mong phai
  -- chay. Nhung "nhe hon" la bao nhieu thi phai do, khong doan.
  if hasMech(S.boss, "slam") then
    local cast = mechNum("slam", "cast")
    local r    = mechNum("slam", "radius")
    local hit  = dmg * mechNum("slam", "factor")
    for i = 1, #S.pids do
      local pid = S.pids[i]
      local dd  = S.p[pid]
      local h   = dd and dd.hero or nil
      if h ~= nil and API.alive(h) then
        local cut  = damageReduction((BlzGetUnitArmor ~= nil) and BlzGetUnitArmor(h) or 0.0)
        local ehp  = GetUnitState(h, UNIT_STATE_MAX_LIFE) / (1.0 - cut)
        local pct  = (ehp > 0.0) and (hit / ehp * 100.0) or 999.0
        local sp   = (GetUnitMoveSpeed ~= nil) and GetUnitMoveSpeed(h) or 0.0
        API.trace("boss: slam pid " .. pid .. " " ..
                  (API.heroNameOf and API.heroNameOf(GetUnitTypeId(h)) or "?") ..
                  " -- mat " .. math.floor(pct) .. "% mau" ..
                  (pct >= 100.0 and " (CHET NGAY)" or " (o lai duoc)") ..
                  " | chay " .. math.floor(sp * cast) .. "/" .. math.floor(r) ..
                  (sp * cast >= r and " (thoat kip)" or " (KHONG kip)"))
      end
    end
  end
  return u
end

-- ---------- Co che ----------

local function forEachEnemy(x, y, radius, f)
  local g = CreateGroup()
  GroupEnumUnitsInRange(g, x, y, radius, nil)
  local t = FirstOfGroup(g)
  while t ~= nil do
    GroupRemoveUnit(g, t)
    if API.alive(t) and IsUnitEnemy(t, S.enemy) then f(t) end
    t = FirstOfGroup(g)
  end
  DestroyGroup(g)
end

local function strike(b, tgt, dmg)
  UnitDamageTarget(b.u, tgt, dmg, true, false,
                   ATTACK_TYPE_NORMAL, DAMAGE_TYPE_NORMAL, WEAPON_TYPE_WHOKNOWS)
end

local function enrageMult(b)
  return b.enraged and mechNum("enrage", "dmg") or 1.0
end

-- Chan Dia: don BAO TRUOC, khong phai cuc sat thuong dinh ky.
--
-- Ban truoc: 2.5x sat thuong, ban kinh 420, no NGAY va tam no bam theo
-- boss. Nguoi choi khong co cach nao biet truoc, va boss di theo thi
-- chay cung khong thoat. Nhin tu ghe nguoi choi thi no khong phai mot
-- co che -- no chi la mau tru dan.
--
-- Ban nay:
--   . boss DUNG YEN cast 2 giay, mot vong tron hien ra -- thay duoc
--   . tam no CHOT o vi tri luc bat dau cast -- chay la thoat THAT
--   . boss bi khoa 2 giay -- doi lay mot cua so ranh de danh tra
--   . 10x mot don thuong = 10 / BOSS_HITS_TO_KILL = 83% mau hieu dung:
--     an tron mot phat thi gan chet chu KHONG chet; an hai phat lien
--     thi chet
--
-- KHONG nhan he so phat cuong. 10 x 1.6 = 133% tuc chet ngay tu mau
-- day, ma mot don CHET CHAC thi bao truoc cung vo nghia -- phat cuong
-- da the hien o don thuong roi.
--
-- Boss chet giua luc cast thi don huy: burst boss la mot cau tra loi
-- hop le cho co che nay.
local function slamRing(x, y, r)
  local n = math.floor(mechNum("slam", "marks"))
  if n < 4 then n = 4 end
  for i = 1, n do
    local a = 360.0 * i / n
    API.fx(CFG.FX_SLAM_MARK, API.polarX(x, r, a), API.polarY(y, r, a))
  end
end

local function groundSlam(b)
  local x, y  = GetUnitX(b.u), GetUnitY(b.u)
  local r     = mechNum("slam", "radius")
  local cast  = mechNum("slam", "cast")
  if cast <= 0.0 then cast = 0.1 end

  b.casting = true
  PauseUnit(b.u, true)
  API.fx(CFG.FX_HIT_BUFF, x, y)
  slamRing(x, y, r)
  API.msg(nil, CFG.C_RED .. API.t("boss_slam_cast") .. CFG.C_END)

  -- Ve lai vong tron vai lan: hieu ung WC3 dien mot lan roi tat, ve mot
  -- lan thi nguoi choi chi thay mot cai chop chu khong thay VONG.
  local pulses = 3
  for i = 1, pulses - 1 do
    API.after(cast * i / pulses, function()
      if b.casting then slamRing(x, y, r) end
    end)
  end

  API.after(cast, function()
    b.casting = false
    -- Bo khoa TRUOC khi kiem con song: xac dang bi PauseUnit thi khong
    -- ruc ra duoc, va con boss chet giua luc cast la truong hop thuong.
    if b.u ~= nil then PauseUnit(b.u, false) end
    if b.u == nil or not API.alive(b.u) then return end
    local dmg = b.dmg * mechNum("slam", "factor")
    API.fx(CFG.FX_SLAM_HIT, x, y)
    forEachEnemy(x, y, r, function(t) strike(b, t, dmg) end)
  end)
end

-- Lao toi hero XA NHAT, khong phai gan nhat: ep ke nup sau cung phai
-- tham gia. Dung gan thi da an don thuong roi.
local function charge(b)
  local bx, by = GetUnitX(b.u), GetUnitY(b.u)
  local far, dmax = nil, -1.0
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h) then
      local dist = API.distXY(bx, by, GetUnitX(h), GetUnitY(h))
      if dist > dmax then far, dmax = h, dist end
    end
  end
  if far == nil then return end
  SetUnitPosition(b.u, GetUnitX(far), GetUnitY(far))
  API.fx(CFG.FX_HIT_LINE, GetUnitX(far), GetUnitY(far))
  -- Truoc day chi co vet lao, khong mot chu nao. Vet thi troi qua trong
  -- nua giay, con nguoi choi bi lao trung thi khong hieu vua an gi.
  API.msg(nil, CFG.C_RED .. API.t("boss_charge") .. CFG.C_END)
  strike(b, far, b.dmg * mechNum("charge", "factor") * enrageMult(b))
end

local function summonAdds(b)
  local n = math.floor(mechNum("summon", "count"))
  if n <= 0 or API.waveSpawnAt == nil then return end
  for i = 1, n do
    local a = 360.0 * i / n
    -- Goi qua he wave de thuoc ha cung duong cong, cung tien thuong, va
    -- cung duoc dem vao S.alive -- neu khong, don sach wave xong ma con
    -- thuoc ha thi dong ho wave treo.
    API.waveSpawnAt(b.stage, b.realm,
                    API.polarX(GetUnitX(b.u), 220.0, a),
                    API.polarY(GetUnitY(b.u), 220.0, a))
  end
  API.msg(nil, CFG.C_GREY .. API.t("boss_summon") .. CFG.C_END)
end

local function shield(b)
  b.shield = b.shield + b.maxHp * mechNum("shield", "ratio")
  API.fx(CFG.FX_HIT_BUFF, GetUnitX(b.u), GetUnitY(b.u))
  API.msg(nil, CFG.C_GREY .. API.t("boss_shield") .. CFG.C_END)
end

-- ---------- Nhip 2 giay ----------

local function tick()
  local b = S.boss
  if b == nil or b.u == nil then return end
  if not API.alive(b.u) then
    -- VONG PHAN HOI. BOSS_SKILL_SHARE la uoc luong, khong do duoc tu
    -- ngoai; dong nay bien no thanh thu do duoc. Song ngan hon thiet ke
    -- thi nang SKILL_SHARE len, dai hon thi ha xuong.
    API.trace(string.format(
      "boss: r%d CHET sau %.1fs (thiet ke %.0fs) -- lech %+.0f%%",
      b.realm or 0, b.age or 0.0, CFG.BOSS_SECONDS,
      ((b.age or 0.0) / CFG.BOSS_SECONDS - 1.0) * 100.0))
    S.boss = nil
    return
  end
  b.age = (b.age or 0.0) + CFG.WAVE_TICK

  if hasMech(b, "enrage") and not b.enraged then
    if GetUnitState(b.u, UNIT_STATE_LIFE) / b.maxHp <= mechNum("enrage", "at") then
      b.enraged = true
      if BlzSetUnitBaseDamage ~= nil then
        BlzSetUnitBaseDamage(b.u, math.floor(b.dmg * mechNum("enrage", "dmg") + 0.5), 0)
      end
      SetUnitVertexColor(b.u, 255, 40, 40, 255)
      API.msg(nil, CFG.C_RED .. API.t("boss_enraged") .. CFG.C_END)
    end
  end

  -- Dang cast Chan Dia thi khong lam gi khac: lao di giua chung thi
  -- boss bien mat khoi vong tron no vua ve ra, va loi hua "dung o day
  -- se an don" thanh noi doi.
  if b.casting then return end

  local function beat(field, name, f)
    if not hasMech(b, name) then return end
    b[field] = b[field] - CFG.WAVE_TICK
    if b[field] <= 0.0 then b[field] = mechNum(name, "cd"); f(b) end
  end
  beat("cdSlam",   "slam",   groundSlam)
  beat("cdCharge", "charge",      charge)
  beat("cdSummon", "summon", summonAdds)
  beat("cdShield", "shield",    shield)
end

-- ---------- Su kien sat thuong rieng cua boss ----------
--
-- Boss tu giu trigger cua no thay vi nho 7_effect.lua: bon co che duoi
-- day chi song trong mot tran boss, tron chung vao he bi dong cua hero
-- thi ca hai ben deu kho doc.

-- ---------- Cho co che AM mot dau hieu ----------
--
-- Do duoc truoc khi sua: 3 trong 8 co che KHONG ve gi va KHONG bao gi
-- (lifesteal, reflect, shred). Hau qua: 8/20 boss co co che nguoi choi
-- khong the biet la co, va boss 17 (Thanh Nhan Vo Nga) khong lam gi
-- nhin thay duoc CA -- no la mot con danh thuong to xac.
--
-- Mia mai nhat la shred: no la co che quan trong nhat bang (tra loi cho
-- viec cuoi van hero co 8.070 giap = giam 99,79% sat thuong) ma lai cam
-- nhat.
--
-- Tiet luu theo THOI GIAN SONG cua boss chu khong theo so don: boss
-- danh vai don moi giay, ve moi don thi man hinh thanh mot dam khoi.
local function beat1s(b, key)
  local t = b.age or 0.0
  if (b[key] or -99.0) + 1.0 > t then return false end
  b[key] = t
  return true
end

-- Dong bao chi MOT lan moi tran: no tra loi cau "chuyen gi dang xay
-- ra", ma cau do chi can tra loi mot lan.
local function sayOnce(b, key, msg)
  if b[key] then return end
  b[key] = true
  API.msg(nil, msg)
end

local function onDamage()
  local b = S.boss
  if b == nil or b.u == nil then return end

  local tgt = (BlzGetEventDamageTarget ~= nil) and BlzGetEventDamageTarget()
              or GetTriggerUnit()
  local src = GetEventDamageSource()
  local dmg = GetEventDamage()
  if dmg <= 0.0 then return end

  -- BOSS AN DON
  if tgt == b.u then
    if b.shield > 0.0 and BlzSetEventDamage ~= nil then
      local absorb = (dmg < b.shield) and dmg or b.shield
      b.shield = b.shield - absorb
      dmg = dmg - absorb
      BlzSetEventDamage(dmg)
    end
    if hasMech(b, "reflect") and src ~= nil and src ~= b.u and dmg > 0.0 then
      -- Phan lai NGUON. Cu phan nay lai ban su kien nay lan nua, nhung
      -- lan do src == boss nen khong vao nhanh phan don -- khong de quy.
      UnitDamageTarget(b.u, src, dmg * mechNum("reflect", "ratio"), true, false,
                       ATTACK_TYPE_NORMAL, DAMAGE_TYPE_NORMAL, WEAPON_TYPE_WHOKNOWS)
      -- Ve tren KE DANH, khong tren boss: nguoi choi phai thay don cua
      -- MINH doi chieu, do moi la noi dung cua co che.
      if beat1s(b, "fxReflect") then
        API.fx(CFG.FX_HIT_CLEAVE, GetUnitX(src), GetUnitY(src))
      end
      sayOnce(b, "saidReflect", CFG.C_RED ..
              API.t("boss_reflect", math.floor(mechNum("reflect", "ratio") * 100 + 0.5)) ..
              CFG.C_END)
    end
    return
  end

  -- BOSS GAY DON
  if src == b.u then
    if hasMech(b, "lifesteal") then
      local hp = GetUnitState(b.u, UNIT_STATE_LIFE) + dmg * mechNum("lifesteal", "ratio")
      local mx  = GetUnitState(b.u, UNIT_STATE_MAX_LIFE)
      SetUnitState(b.u, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
      if beat1s(b, "fxSteal") then
        API.fx(CFG.FX_HIT_HEAL, GetUnitX(b.u), GetUnitY(b.u))
      end
      sayOnce(b, "saidSteal", CFG.C_RED ..
              API.t("boss_lifesteal", math.floor(mechNum("lifesteal", "ratio") * 100 + 0.5)) ..
              CFG.C_END)
    end
    -- XE GIAP: KHONG sua giap that. Giap la cua engine tu luc
    -- heroRecompute thoi so huu no (xem 7_effect.lua); gianh lai la
    -- lap lai dung cai loi da mat may ngay de go.
    --
    -- Thay vao do cong don mot he so KHUECH DAI sat thuong len chinh
    -- hero do: cung ket qua "cang danh lau cang de vo", ma khong ai
    -- phai so huu lai giap.
    if hasMech(b, "shred") and API.heroPidOf ~= nil then
      local pid = API.heroPidOf(tgt)
      if pid ~= nil and S.p[pid] ~= nil then
        local d = S.p[pid]
        -- Phap Khi "Bat Dong Minh Vuong": moi don xe giap chi con mot
        -- nua. Giam luc CONG DON chu khong luc doc ra -- giam luc doc
        -- thi con so bao cho nguoi choi va con so that se lech.
        local per = mechNum("shred", "perHit")
        if API.relicVal ~= nil then
          local half = API.relicVal(pid, "batdong", "halve")
          if half > 0.0 then per = per * (1.0 - half) end
        end
        d.bossShred = (d.bossShred or 0.0) + per
        if BlzSetEventDamage ~= nil then
          BlzSetEventDamage(dmg * (1.0 + d.bossShred))
        end
        -- Bao theo MOC 25%, khong bao moi don: con so phai nhay du to
        -- de doc ra "minh dang yeu dan", con tung 2% thi thanh tieng on.
        local step = math.floor(d.bossShred / 0.25)
        if step > (d.bossShredSaid or 0) then
          d.bossShredSaid = step
          API.msg(pid, CFG.C_RED ..
                  API.t("boss_shred", math.floor(d.bossShred * 100 + 0.5)) .. CFG.C_END)
        end
        if beat1s(b, "fxShred") then
          API.fx(CFG.FX_HIT_CLEAVE, GetUnitX(tgt), GetUnitY(tgt))
        end
      end
    end
  end
end

-- ---------- Do luc vao map ----------

local function probe()
  if CreateUnit == nil or CFG.BOSSES == nil then return end
  local bad = {}
  for i = 1, #CFG.BOSSES do
    local d = CFG.BOSSES[i]
    local u = CreateUnit(S.enemy, d.unit, 0.0, 0.0, 0.0)
    local tag = "r" .. d.r .. " " .. API.idToStr(d.unit)
    if u == nil then
      bad[#bad + 1] = tag .. " KHONG CO"
    else
      local flying  = (IsUnitType ~= nil) and IsUnitType(u, UNIT_TYPE_FLYING) or false
      local hero = (IsUnitType ~= nil) and IsUnitType(u, UNIT_TYPE_HERO) or false
      if flying then bad[#bad + 1] = tag .. " BIET BAY" end
      if not hero then bad[#bad + 1] = tag .. " khong phai HERO" end
      RemoveUnit(u)
    end
  end
  if #bad > 0 then
    API.warn(nil, "BOSS SAI: " .. table.concat(bad, " | "))
    API.trace("boss: SAI -- " .. table.concat(bad, " | "))
  else
    API.trace("boss: " .. #CFG.BOSSES .. " ban thiet ke hop le (hero, khong bay)")
  end
end

local function startBoss()
  S.boss = nil
  -- Phep do NAY TON: no tao 20 unit roi xoa ngay, moi lan vao map.
  --
  -- No kiem "boss co phai hero khong, co biet bay khong" -- dieu chi doi
  -- khi CFG.BOSSES doi, tuc luc DANG LAM MAP. Ban choi that thi bang do
  -- khong doi giua chung, nen chay lai moi van la tra gia cho mot cau
  -- tra loi da biet.
  --
  -- Danh doi, biet truoc: go nham mot ma boss o ban release thi khong
  -- bao luc vao map nua, ma doi toi canh gioi do moi lo ra. Chap nhan --
  -- doi lay khoi dong nhe hon cho moi van choi.
  if CFG.DEBUG then probe() end
  if BlzGetEventDamageTarget ~= nil then
    local t = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(t, EVENT_PLAYER_UNIT_DAMAGED)
    TriggerAddAction(t, onDamage)
  end
  API.trace("boss: san sang")
end

-- Dung chung cho engine rieng cua Thanh Thu (4_sidequest.lua). Ba ham
-- nay THUAN TUY: khong doc S.boss, khong giu trang thai -- nen chia se
-- duoc ma khong buoc hai he vao nhau.
API.bossMeasureParty = measureParty
API.bossForEachEnemy = forEachEnemy
API.bossSlamRing     = slamRing
API.bossMechNum      = mechNum

API.bossSpawn = spawn
API.bossTick  = tick
API.startBoss = startBoss
end
--#endregion 3_battle/3_boss.lua

--#region 3_battle/4_sidequest.lua
do
-- ============================================================
--  3_battle/4_sidequest.lua -- Bon Thanh Thu: boss pho ban
--
--  KHAC boss thuong o ba diem, va ca ba deu keo theo he qua:
--
--    dung san tu luc vao map  -> khong do doi duoc (luc do ca doi con
--                                o Pham Nhan), nen chi so suy tu CHINH
--                                CANH GIOI CUA
--    nguoi choi tim toi no    -> no khong duoc phep di dau ca
--    ha xong thu phuc         -> chet la doi pet va dua nguoi choi ve
--
--  VI SAO ENGINE RIENG, khong dung chung voi 3_boss.lua:
--
--  3_boss.lua bam vao S.boss -- MOT bien, sau cho doc thang. O day co
--  BON con dung cung luc, cong boss dot la nam. Doi S.boss thanh danh
--  sach la sua vao trai tim cua he dang ganh 20 boss chinh cua ca van:
--  onDamage phai duyet N con o cho nong nhat, co casting phai tach theo
--  tung con, va dong trace "CHET sau ...s" dung de do BOSS_SKILL_SHARE
--  se mat.
--
--  Doi lai: sua mot co che thi phai sua hai cho. Chap nhan, it nhat cho
--  toi khi Thanh Thu choi thu xong va biet giu lai bo co che nao.
--
--  Ba ham THUAN TUY thi van dung chung (API.bossForEachEnemy,
--  bossSlamRing, bossMechNum) -- chung khong doc trang thai nao.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function mechNum(name, field)
  return API.bossMechNum(name, field)
end

local function hasMech(b, name)
  return b ~= nil and b.mech ~= nil and b.mech[name] == true
end

local function strike(b, tgt, dmg)
  UnitDamageTarget(b.u, tgt, dmg, true, false,
                   ATTACK_TYPE_NORMAL, DAMAGE_TYPE_NORMAL, WEAPON_TYPE_WHOKNOWS)
end

local function enrageMult(b)
  return b.enraged and mechNum("enrage", "dmg") or 1.0
end

-- ---------- Chi so: DO DOI, luc NGUOI CHOI BUOC VAO ----------
--
-- LOI DA SHIP: ban dau suy tu canh gioi cua. Do duoc tu file vet (canh
-- gioi 16, mot hero): chi so that 30.105, phan tu canh gioi chi 511 --
-- tuc 1,7%. Trang bi va ky nang chiem 98,3%, gap 59 lan. Ket qua: con
-- dau qua dai, ba con sau vo trong mot nhip.
--
-- Gio dung CHINH measureParty() cua boss thuong, nhung goi LUC BUOC
-- VAO: luc sinh (vao map) ca doi con o canh gioi 1 va phep do vo nghia.
local function armStats(q)
  local dps, ehpAvg, n = API.bossMeasureParty()
  if n == 0 then return nil, nil, 0 end

  local hp = dps * (q.seconds or CFG.SIDE_QUEST_SECONDS or 60.0)
  -- ehpAvg la mau HIEU DUNG -- da chia cho (1 - giam tu giap). Khong
  -- chia thi cuoi van hero co 8.070 giap (giam 99,79%) va don cua boss
  -- cham toi chi con 4 mau.
  local dmg = ehpAvg / (q.hits or CFG.SIDE_QUEST_HITS or 14.0)
  if hp < 1.0 then hp = 1.0 end
  if dmg < 1.0 then dmg = 1.0 end
  return math.floor(hp + 0.5), math.floor(dmg + 0.5), n
end

-- ---------- Co che ----------

local function groundSlam(b)
  local x, y = GetUnitX(b.u), GetUnitY(b.u)
  local r    = mechNum("slam", "radius")
  local cast = mechNum("slam", "cast")
  if cast <= 0.0 then cast = 0.1 end

  b.casting = true
  PauseUnit(b.u, true)
  API.fx(CFG.FX_HIT_BUFF, x, y)
  API.bossSlamRing(x, y, r)
  API.msg(nil, CFG.C_RED .. API.t("boss_slam_cast") .. CFG.C_END)

  -- Ve lai vong tron vai lan: hieu ung WC3 dien mot lan roi tat, ve mot
  -- lan thi nguoi choi chi thay mot cai chop chu khong thay VONG.
  for i = 1, 2 do
    API.after(cast * i / 3.0, function()
      if b.casting then API.bossSlamRing(x, y, r) end
    end)
  end

  API.after(cast, function()
    b.casting = false
    -- Bo khoa TRUOC khi kiem con song: xac dang bi PauseUnit thi khong
    -- ruc ra duoc, va con boss chet giua luc cast la truong hop thuong.
    if b.u ~= nil then PauseUnit(b.u, false) end
    if b.u == nil or not API.alive(b.u) then return end
    local dmg = b.dmg * mechNum("slam", "factor")
    API.fx(CFG.FX_SLAM_HIT, x, y)
    API.bossForEachEnemy(x, y, r, function(t) strike(b, t, dmg) end)
  end)
end

-- Lao toi hero XA NHAT trong hang. Khac boss dot: chi tinh hero DANG O
-- TRONG PHO BAN -- lao toi mot nguoi dang o nha chinh thi con boss bay
-- nua ban do va pho ban tu giai tan.
local function charge(b)
  local bx, by = GetUnitX(b.u), GetUnitY(b.u)
  local reach = (CFG.SIDE_QUEST_LEASH or 1400.0)
  local far, dmax = nil, -1.0
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h) then
      local dist = API.distXY(bx, by, GetUnitX(h), GetUnitY(h))
      if dist <= reach and dist > dmax then far, dmax = h, dist end
    end
  end
  if far == nil then return end
  SetUnitPosition(b.u, GetUnitX(far), GetUnitY(far))
  API.fx(CFG.FX_HIT_LINE, GetUnitX(far), GetUnitY(far))
  API.msg(nil, CFG.C_RED .. API.t("boss_charge") .. CFG.C_END)
  strike(b, far, b.dmg * mechNum("charge", "factor") * enrageMult(b))
end

local function summonAdds(b)
  local n = math.floor(mechNum("summon", "count"))
  if n <= 0 or API.waveSpawnAt == nil then return end
  -- waveSpawnAt(stage, realm, x, y) -- BON tham so. Goi qua he wave de
  -- thuoc ha cung duong cong, cung tien thuong, va cung duoc dem vao
  -- S.alive; neu khong, don sach wave xong ma con thuoc ha thi dong ho
  -- wave treo.
  --
  -- Thanh Thu khong co "stage" cua rieng no. Suy tu canh gioi cua bang
  -- API.stagesPerRealm() chu khong go hang so -- doi so dot moi canh
  -- gioi thi cho nay tu theo.
  local realm = b.def.rank
  local per   = (API.stagesPerRealm ~= nil) and API.stagesPerRealm() or 5
  local stage = realm * per
  local x, y = GetUnitX(b.u), GetUnitY(b.u)
  for i = 1, n do
    local a = 360.0 * i / n
    API.waveSpawnAt(stage, realm,
                    API.polarX(x, 220.0, a), API.polarY(y, 220.0, a))
  end
  API.msg(nil, CFG.C_GREY .. API.t("boss_summon") .. CFG.C_END)
end

local function shieldUp(b)
  b.shield = b.shield + b.maxHp * mechNum("shield", "ratio")
  API.fx(CFG.FX_HIT_BUFF, GetUnitX(b.u), GetUnitY(b.u))
  API.msg(nil, CFG.C_GREY .. API.t("boss_shield") .. CFG.C_END)
end

-- ---------- Tiet luu dau hieu ----------
-- Cung ly do voi boss dot: ba co che lifesteal/reflect/shred chi co so,
-- khong ve gi -- nguoi choi khong the biet la no dang co.
local function beat1s(b, key)
  local t = b.age or 0.0
  if (b[key] or -99.0) + 1.0 > t then return false end
  b[key] = t
  return true
end

local function sayOnce(b, key, msg)
  if b[key] then return end
  b[key] = true
  API.msg(nil, msg)
end
-- ---------- Nap chi so luc buoc vao ----------
--
-- Goi tu onSideQuest() ngay sau khi dich chuyen. CHI nap khi con do dang
-- DAY MAU -- neu khong, nguoi thu hai buoc vao giua tran se hoi day mau
-- con boss va xoa het cong danh cua nguoi dau.
local function arm(i)
  local b = (S.side or {})[i]
  if b == nil or b.u == nil or not API.alive(b.u) then return end
  if b.armed and GetUnitState(b.u, UNIT_STATE_LIFE)
                 < GetUnitState(b.u, UNIT_STATE_MAX_LIFE) then
    return
  end

  local hp, dmg, n = armStats(b.def)
  if hp == nil then return end

  if BlzSetUnitMaxHP ~= nil then
    BlzSetUnitMaxHP(b.u, hp)
    SetUnitState(b.u, UNIT_STATE_LIFE, GetUnitState(b.u, UNIT_STATE_MAX_LIFE))
  end
  if BlzSetUnitBaseDamage ~= nil then BlzSetUnitBaseDamage(b.u, dmg, 0) end
  local was = b.maxHp or 0
  b.maxHp, b.dmg, b.armed, b.age = hp, dmg, true, 0.0
  b.enraged, b.shield = false, 0.0
  SetUnitVertexColor(b.u, 255, 255, 255, 255)

  -- CHI ghi vet khi con so DOI DANG KE. Ham nay chay moi nhip khi hang
  -- trong -- 4 con x 1 giay, ghi moi lan thi file vet phinh vo han va
  -- nuot mat nhung dong that su dang doc.
  --
  -- Nguong 10%: doi duoi muc do la doi vat va (mot hero hoi mau), tren
  -- muc do la doi that (len canh gioi, mua trang bi, them nguoi choi).
  if was <= 0 or math.abs(hp - was) > was * 0.10 then
    API.trace(string.format(
      "sidequest: %d %s NAP -- %d hero, mau %d (%.0fs hoa luc), don %d (%.0f don)",
      i, API.pick(b.def), n, hp,
      b.def.seconds or CFG.SIDE_QUEST_SECONDS or 60.0,
      dmg, b.def.hits or CFG.SIDE_QUEST_HITS or 14.0))
  end
end


-- ---------- Nhip ----------
--
-- CHI chay con nao CO NGUOI trong hang. Bon con danh vao phong trong tu
-- phut dau van dau thi chat day dong bao va man hinh day hieu ung, cho
-- mot tran khong ai xem.
local function anyHeroNear(b)
  local reach = (CFG.SIDE_QUEST_LEASH or 1400.0)
  local bx, by = GetUnitX(b.u), GetUnitY(b.u)
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h)
       and API.distXY(bx, by, GetUnitX(h), GetUnitY(h)) <= reach then
      return true
    end
  end
  return false
end

local function tickOne(b, dt)
  if b.u == nil or not API.alive(b.u) then return end

  -- Day xich: keo ve hang neu di qua xa. Dung khoang cach chu khong
  -- dung vung -- vung la hinh chu nhat hep, ma danh nhau thi hai ben xe
  -- dich lien tuc.
  local dx, dy = GetUnitX(b.u) - b.hx, GetUnitY(b.u) - b.hy
  local far = (CFG.SIDE_QUEST_LEASH or 1400.0)
  if dx * dx + dy * dy > far * far then
    IssuePointOrder(b.u, "move", b.hx, b.hy)
    return
  end

  if not anyHeroNear(b) then return end
  b.age = (b.age or 0.0) + dt

  if hasMech(b, "enrage") and not b.enraged then
    if GetUnitState(b.u, UNIT_STATE_LIFE) / b.maxHp <= mechNum("enrage", "at") then
      b.enraged = true
      if BlzSetUnitBaseDamage ~= nil then
        BlzSetUnitBaseDamage(b.u, math.floor(b.dmg * mechNum("enrage", "dmg") + 0.5), 0)
      end
      SetUnitVertexColor(b.u, 255, 40, 40, 255)
      API.msg(nil, CFG.C_RED .. API.t("boss_enraged") .. CFG.C_END)
    end
  end

  -- Dang cast Chan Dia thi khong lam gi khac: lao di giua chung thi no
  -- bien khoi vong tron vua ve ra, va loi hua "dung o day se an don"
  -- thanh noi doi.
  if b.casting then return end

  local function beat(field, name, f)
    if not hasMech(b, name) then return end
    b[field] = b[field] - dt
    if b[field] <= 0.0 then b[field] = mechNum(name, "cd"); f(b) end
  end
  beat("cdSlam",   "slam",   groundSlam)
  beat("cdCharge", "charge",      charge)
  beat("cdSummon", "summon", summonAdds)
  beat("cdShield", "shield",   shieldUp)
end

-- Bo ghim khi LAN THU DA BO DO.
--
-- Ghim chi so la dung (xem armPin), nhung ghim VINH VIEN thi sai: cham
-- vao con thu mot cai luc vua mo khoa roi bo di se dong bang no o suc
-- manh cua doi luc do, va quay lai sau mot tieng van gap dung con so ay.
--
-- Chi bo hai co; arm() lo phan con lai -- no tu hoi day mau, tat cuong,
-- xoa khien va dat lai b.age. Viet lai o day la hai noi cung khai mot
-- viec, roi mot ngay chi sua mot noi.
local function release(b)
  b.pinned = false
  b.armed  = false
end

local function tick()
  local dt = CFG.SIDE_QUEST_TICK or 1.0
  for i = 1, #(S.side or {}) do
    local b = S.side[i]
    if b ~= nil then
      -- NAP CHI SO KHI KHONG CO AI TRONG HANG.
      --
      -- LOI DA SHIP: truoc day chi nap luc bam Tien Hanh, nen tu luc vao
      -- map toi luc ai do buoc vao, ca bon con van la ban goc Hmkg --
      -- GIONG HET NHAU. Nguoi choi nhin vao thay bon con y het, va
      -- tuong he chi so khong chay.
      --
      -- Nap o day thi chung khac nhau ngay khi doi co hero dau tien, va
      -- tu cap nhat khi doi manh len -- khong phai doi buoc vao moi dung.
      --
      -- arm() tu tu choi neu con do dang bi danh do (mau < toi da), nen
      -- goi moi nhip khong xoa cong nguoi dang danh. Nhung van chan them
      -- o day: co nguoi trong hang la KHONG nap, du mau con day.
      --
      -- b.pinned: da co nguoi bam "Tien Hanh" mot lan roi thi THOI theo
      -- doi. Xem armPin() ben duoi.
      --
      -- b.idle dem giay LIEN TUC khong co ai trong hang. Du lau thi coi
      -- nhu lan thu da bo do: bo ghim, va nhip ngay sau do arm() se do
      -- lai tu dau. Dem o day chu khong trong tickOne vi tickOne thoat
      -- som khi khong co ai gan -- dung cho ta can dem.
      if anyHeroNear(b) then
        b.idle = 0.0
      else
        b.idle = (b.idle or 0.0) + dt
        if b.pinned and b.idle >= (CFG.SIDE_QUEST_RESET or 20.0) then
          release(b)
          API.trace("sidequest: " .. i .. " BO GHIM -- bo hoang " ..
                    math.floor(b.idle) .. "s")
        end
        if not b.pinned then arm(i) end
      end
      tickOne(b, dt)
    end
  end
end

-- ---------- Su kien sat thuong ----------

local function bossOf(u)
  for i = 1, #(S.side or {}) do
    local b = S.side[i]
    if b ~= nil and b.u == u then return b end
  end
  return nil
end

local function onDamage()
  local tgt = (BlzGetEventDamageTarget ~= nil) and BlzGetEventDamageTarget()
              or GetTriggerUnit()
  local src = GetEventDamageSource()
  local dmg = GetEventDamage()
  if dmg <= 0.0 then return end

  -- THANH THU AN DON
  local b = bossOf(tgt)
  if b ~= nil then
    if b.shield > 0.0 and BlzSetEventDamage ~= nil then
      local absorb = (dmg < b.shield) and dmg or b.shield
      b.shield = b.shield - absorb
      dmg = dmg - absorb
      BlzSetEventDamage(dmg)
    end
    if hasMech(b, "reflect") and src ~= nil and src ~= b.u and dmg > 0.0 then
      -- Phan lai NGUON. Cu phan nay lai ban su kien nay lan nua, nhung
      -- lan do src == boss nen khong vao nhanh phan don -- khong de quy.
      UnitDamageTarget(b.u, src, dmg * mechNum("reflect", "ratio"), true, false,
                       ATTACK_TYPE_NORMAL, DAMAGE_TYPE_NORMAL, WEAPON_TYPE_WHOKNOWS)
      if beat1s(b, "fxReflect") then
        API.fx(CFG.FX_HIT_CLEAVE, GetUnitX(src), GetUnitY(src))
      end
      sayOnce(b, "saidReflect", CFG.C_RED ..
        API.t("boss_reflect", math.floor(mechNum("reflect", "ratio") * 100 + 0.5))
        .. CFG.C_END)
    end
    return
  end

  -- THANH THU GAY DON
  b = bossOf(src)
  if b == nil then return end

  if hasMech(b, "lifesteal") then
    local hp = GetUnitState(b.u, UNIT_STATE_LIFE) + dmg * mechNum("lifesteal", "ratio")
    local mx = GetUnitState(b.u, UNIT_STATE_MAX_LIFE)
    SetUnitState(b.u, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
    if beat1s(b, "fxSteal") then
      API.fx(CFG.FX_HIT_HEAL, GetUnitX(b.u), GetUnitY(b.u))
    end
    sayOnce(b, "saidSteal", CFG.C_RED ..
      API.t("boss_lifesteal", math.floor(mechNum("lifesteal", "ratio") * 100 + 0.5))
      .. CFG.C_END)
  end

  -- XE GIAP: KHONG sua giap that -- giap la cua engine tu luc
  -- heroRecompute thoi so huu no. Cong don mot he so KHUECH DAI len
  -- chinh hero do: cung ket qua "cang danh lau cang de vo".
  if hasMech(b, "shred") and API.heroPidOf ~= nil then
    local pid = API.heroPidOf(tgt)
    if pid ~= nil and S.p[pid] ~= nil then
      local d = S.p[pid]
      d.bossShred = (d.bossShred or 0.0) + mechNum("shred", "perHit")
      if BlzSetEventDamage ~= nil then
        BlzSetEventDamage(dmg * (1.0 + d.bossShred))
      end
      local step = math.floor(d.bossShred / 0.25)
      if step > (d.bossShredSaid or 0) then
        d.bossShredSaid = step
        API.msg(pid, CFG.C_RED ..
          API.t("boss_shred", math.floor(d.bossShred * 100 + 0.5)) .. CFG.C_END)
      end
      if beat1s(b, "fxShred") then
        API.fx(CFG.FX_HIT_CLEAVE, GetUnitX(tgt), GetUnitY(tgt))
      end
    end
  end
end

-- ---------- Sinh ----------

local function spawnOne(i)
  local q = CFG.SIDE_QUESTS[i]
  if q == nil then return nil end

  local r = API.findRegion(q.lair)
  if r == nil then
    API.trace("sidequest: thieu vung hang " .. API.regionLabel(q.lair) ..
              " -- khong sinh duoc " .. API.pick(q))
    return nil
  end

  local x, y = API.regionCenter(r)
  local u = CreateUnit(S.enemy, q.unit, x, y, 270.0)
  if u == nil then
    API.trace("sidequest: CreateUnit nil cho " .. API.idToStr(q.unit))
    return nil
  end

  -- CHUA dat mau/don o day. Luc nay ca doi con o canh gioi 1 va chua co
  -- trang bi -- do bay gio thi con boss se yeu gap hang chuc lan so voi
  -- luc nguoi choi thuc su buoc vao. Chi so nap trong arm().
  --
  -- Khong cho giap, cung ly do voi boss dot: mau tinh ra DA la mau hieu
  -- dung can de tru, cho them giap la tru hai lan.
  if BlzSetUnitArmor ~= nil then BlzSetUnitArmor(u, 0.0) end
  -- Hero thi co kinh nghiem. Khoa lai, khong thi no len cap trong luc
  -- dung khong va moi con so vua tinh truot het.
  if SuspendHeroXP ~= nil then SuspendHeroXP(u, true) end
  -- TAM SAN: du de danh ai buoc vao hang, khong du de duoi ra ngoai.
  -- Dat 0 la sai -- tam san 0 nghia la no khong tu chon muc tieu, va
  -- nhieu kha nang cung khong danh tra. Tam san binh thuong CONG day
  -- xich o tickOne() thi dung du tam san hanh xu the nao.
  if SetUnitAcquireRange ~= nil then
    SetUnitAcquireRange(u, CFG.SIDE_QUEST_AGGRO or 800.0)
  end
  SetUnitScale(u, CFG.SIDE_QUEST_SCALE or 1.6,
                  CFG.SIDE_QUEST_SCALE or 1.6,
                  CFG.SIDE_QUEST_SCALE or 1.6)

  local mech = {}
  for k = 1, #(q.mech or {}) do mech[q.mech[k]] = true end

  S.side[i] = {
    u = u, idx = i, def = q, mech = mech,
    dmg = 0, maxHp = 0, armed = false, hx = x, hy = y,
    enraged = false, casting = false, shield = 0.0, age = 0.0,
    cdSlam   = mechNum("slam",   "cd"), cdCharge = mechNum("charge", "cd"),
    cdSummon = mechNum("summon", "cd"), cdShield = mechNum("shield", "cd"),
  }
  API.trace(string.format(
    "sidequest: %d %s o %s -- co che [%s], moc canh gioi %d, chua nap chi so",
    i, API.pick(q), API.regionLabel(q.lair),
    table.concat(q.mech or {}, " "), q.rank))
  return u
end


-- ---------- Ha xong ----------
--
-- Chay tren MOI may: su kien unit chet ban dong bo san, khong phai di
-- qua syncSend.
local function onDeath()
  local u = GetTriggerUnit()
  if u == nil then return end
  local b = bossOf(u)
  if b == nil then return end

  local q = b.def

  -- Lay toa do TRUOC khi buong b: phan thuong chia theo ai dang dung
  -- trong hang, ma biet ai dung trong hang thi phai biet hang o dau.
  -- Doc toa do cua xac van duoc -- unit chua bi Remove.
  local bx, by = GetUnitX(b.u), GetUnitY(b.u)
  local reach  = (CFG.SIDE_QUEST_LEASH or 1400.0)

  -- CO DA HA -- co cua CHUNG, khong nam trong S.p[pid]: con thu chi co
  -- mot, ha roi la ca doi ha roi. Phap Khi doc co nay de mo khoa.
  if S.sideDone == nil then S.sideDone = {} end
  S.sideDone[b.idx] = true
  if API.relicUnlocked ~= nil then API.relicUnlocked(b.idx) end

  S.side[b.idx] = nil
  API.trace(string.format("sidequest: %d %s CHET sau %.1fs (thiet ke %.0fs)",
    b.idx, API.pick(q), b.age or 0.0, CFG.SIDE_QUEST_SECONDS or 60.0))
  API.msg(nil, CFG.C_GOLD .. API.t("sq_tamed", API.pick(q)) .. CFG.C_END)

  -- PHAN THUONG: luot Co Duyen, chia theo MOC.
  --
  -- Chi cho ai CO MAT trong hang. Nguoi dang o nha chinh farm quai ma
  -- van an thuong thi mot nguoi danh ca doi cung giau -- va tran 240
  -- giay cua Thanh Long mat het y nghia.
  --
  -- Khong doi con song: chet TRONG hang van la da danh. Xac nam ngay
  -- do, nen phep do khoang cach van dung.
  local rolls = q.rolls or 0

  -- Doi pet sang con vua ha, va dua nguoi choi ve. Dua ve la PHAN THUONG
  -- cho viec thang, va no cung tranh phai ve them mot vung cua ra.
  for k = 1, #S.pids do
    local pid = S.pids[k]
    local d = S.p[pid]
    if d ~= nil and d.hero ~= nil then
      local near = API.distXY(bx, by, GetUnitX(d.hero),
                              GetUnitY(d.hero)) <= reach
      if rolls > 0 then
        if near and API.fortuneAddRolls ~= nil then
          API.fortuneAddRolls(pid, rolls)
          API.msg(pid, CFG.C_GOLD ..
            API.t("sq_reward", API.pick(q), rolls) .. CFG.C_END)
        elseif not near then
          -- Noi RO vi sao khong co gi. Im lang thi nguoi choi tuong he
          -- thuong hong, va lan sau van dung ngoai.
          API.msg(pid, CFG.C_GREY ..
            API.t("sq_noreward", API.pick(q)) .. CFG.C_END)
        end
      end

      if API.alive(d.hero) then
        -- SUU TAM, khong ghi de. Truoc day "d.petUnit = q.unit" lam
        -- ha con thu thu hai la mat con thu nhat -- bon chien loi pham
        -- ma chi giu duoc mot.
        --
        -- Co la CUA CHUNG (S.sideDone) nhung con DANG DI THEO la cua
        -- rieng tung nguoi: hai nguoi trong mot doi chon hai con khac
        -- nhau duoc.
        if d.petOwn == nil then d.petOwn = {} end
        d.petOwn[b.idx] = true
        d.petUnit = q.unit
        if API.petSpawn ~= nil then API.petSpawn(pid) end
        if API.goHome ~= nil then API.goHome(pid) end
      end
    end
  end
end

-- ---------- Nhac khi du dieu kien ----------
--
-- Bang nhiem vu nam sau mot phim va mot the -- nguoi choi khong mo no
-- moi phut de kiem. Khong nhac thi mot pho ban co the mo tu lau ma
-- khong ai biet.
--
-- Nho tung nguoi da duoc nhac con nao (d.sqSeen): nhac lai moi lan dot
-- pha thi tu dong vien thanh tieng on.
local function checkUnlock(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if d.sqSeen == nil then d.sqSeen = {} end

  local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
  for i = 1, #(CFG.SIDE_QUESTS or {}) do
    local q = CFG.SIDE_QUESTS[i]
    if rank >= q.rank and not d.sqSeen[i] then
      d.sqSeen[i] = true
      API.msg(pid, CFG.C_GOLD .. API.t("sq_unlocked", i, API.pick(q)) ..
                   CFG.C_END)
    end
  end
end

-- ---------- Khoi dong ----------

local function startSideQuest()
  S.side = {}
  if CFG.SIDE_QUESTS == nil then return end

  local td = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(td, EVENT_PLAYER_UNIT_DEATH)
  TriggerAddAction(td, onDeath)
  S.sideDeathTrig = td

  local tdm = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tdm, EVENT_PLAYER_UNIT_DAMAGED)
  TriggerAddAction(tdm, onDamage)
  S.sideDmgTrig = tdm

  local n = 0
  for i = 1, #CFG.SIDE_QUESTS do
    if spawnOne(i) ~= nil then n = n + 1 end
  end

  S.sideTimer = CreateTimer()
  TimerStart(S.sideTimer, CFG.SIDE_QUEST_TICK or 1.0, true, tick)
  API.trace("sidequest: sinh " .. n .. "/" .. #CFG.SIDE_QUESTS ..
            " Thanh Thu, day xich " .. (CFG.SIDE_QUEST_LEASH or 1400.0))
end

-- NAP ROI GHIM -- goi dung mot lan, luc nguoi choi bam "Tien Hanh".
--
-- Truoc do tick() van nap lai moi nhip khi hang trong, de bon con khac
-- nhau ngay tu dau van va lon len theo doi. Nhung tu giay nguoi choi
-- buoc vao, con so phai DUNG LAI.
--
-- LOI DA SHIP: khong ghim thi rut lui la vo nghia. Danh khong lai, chay
-- ve nha mua trang bi, quay lai -- con thu vua nap lai theo suc moi cua
-- ta, manh len dung bay nhieu. Khong co duong nao thang mot con minh
-- chua du suc, tru viec danh mot mach.
--
-- Ghim xong thi moc canh gioi moi co nghia that: con thu duoc do theo
-- suc cua doi DUNG LUC CAM KET, va mo trang bi sau do la loi cua nguoi
-- choi chu khong bi he thong doi lai.
local function armPin(i)
  arm(i)
  local b = (S.side or {})[i]
  if b ~= nil and b.armed then
    b.pinned = true
    API.trace("sidequest: " .. i .. " GHIM chi so (mau " ..
              (b.maxHp or 0) .. ", don " .. (b.dmg or 0) .. ")")
  end
end

API.startSideQuest = startSideQuest
API.sideQuestArm   = armPin
API.sideQuestCheck = checkUnlock
end
--#endregion 3_battle/4_sidequest.lua

--#region 3_battle/5_modifier.lua
do
-- ============================================================
--  5_modifier.lua  --  Tu chinh: moi stage thuong mot sua doi
--
--  Khong co he nay thi bon tang cua mot canh gioi chi cach nhau
--  x1.054 chi so -- nguoi choi bam dung ngan ay nut, bon lan, hai
--  muoi canh gioi. Xem docs/02-he-thong/dot-quai.md.
--
--  BON DIEU PHAI NHO KHI SUA FILE NAY:
--
--  1. BOC O DAU LA MOT RANG BUOC DONG BO. GetRandomInt phai chay tren
--     MOI MAY cung thu tu, neu khong hai ban game lech nhau. pick()
--     goi tu spawnStage() -- duong da dong bo. TUYET DOI khong boc
--     trong callback cua frame (ADR 0012).
--
--  2. KHONG dung giap de giam sat thuong. ADR 0010: duong cong sinh ra
--     EHP, mau that suy nguoc ra TU GIAP. So vao giap la lang le doi ca
--     duong cong do kho cua map. Hai tu chinh "giam 50%" vi the nhan o
--     SU KIEN SAT THUONG.
--
--  3. MA ABILITY THI DO, KHONG GO. UnitAddAbility tra false khi ma sai
--     va ham IM LANG khong lam gi -- dung cai bay CLAUDE.md canh bao.
--     probeAbility() thu lan luot roi TRACE ket qua.
--
--  4. Tu chinh ma nguoi choi khong biet thi khong phai co che, no la
--     do kho VO HINH -- va do kho vo hinh chi gay uc che. Moi stage
--     phai bao ten VA bao phai lam gi.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- ---------- Boc ----------

local function cur()
  return S.waveMod
end

-- Ma ability hut mau THAT SU dung duoc o ban nay.
--
-- Do mot lan tren con quai dau tien: gan thu, ai nhan thi giu ma do.
-- Khong ma nao nhan thi lui ve duong su kien sat thuong -- va BAO RA.
local function probeAbility(u, list)
  if UnitAddAbility == nil or list == nil then return nil end
  for i = 1, #list do
    local code = FourCC(list[i])
    if UnitAddAbility(u, code) then
      API.trace("modifier: hut mau dung ability '" .. list[i] .. "'")
      return code
    end
  end
  API.trace("modifier: KHONG ma ability hut mau nao gan duoc (" ..
            table.concat(list, " ") .. ") -- lui ve su kien sat thuong")
  return false
end

-- ---------- Thoi tiet ----------
--
-- Lop bao thu BA, canh dong chu (troi di) va mau quai (phai nhin vao
-- quai). Troi thi thay ma khong can nhin dau ca.
--
-- TAO MOT LAN LUC VAO MAP roi bat/tat, khong tao lai moi stage:
-- AddWeatherEffect moi lan la mot handle moi, va handle Warcraft thi
-- khong tu don. Mot ban do 100 stage se ro ri 100 cai.
--
-- Tat ca gan vao CUNG mot rect (bj_mapInitialPlayableArea -- da dung o
-- ba cho khac trong map nay). Nhieu hieu ung tren mot rect la binh
-- thuong; chi mot cai duoc BAT tai mot luc.
--
-- MA THOI TIET THI DO, KHONG GO. AddWeatherEffect tra nil khi ma sai
-- roi im lang -- thu lan luot danh sach ung vien, giu cai nao dung
-- duoc, va GHI VET ca hai truong hop.
local function makeWeather(m)
  if AddWeatherEffect == nil or m.weather == nil then return nil end
  local r = bj_mapInitialPlayableArea
  if r == nil then
    API.trace("modifier: khong co bj_mapInitialPlayableArea -- bo thoi tiet")
    return nil
  end
  for i = 1, #m.weather do
    local w = AddWeatherEffect(r, FourCC(m.weather[i]))
    if w ~= nil then
      if EnableWeatherEffect ~= nil then EnableWeatherEffect(w, false) end
      API.trace("modifier: thoi tiet " .. m.code .. " = '" .. m.weather[i] .. "'")
      return w
    end
  end
  API.trace("modifier: KHONG ma thoi tiet nao dung duoc cho " .. m.code ..
            " (" .. table.concat(m.weather, " ") .. ")")
  return nil
end

-- Bat dung mot cai, tat het phan con lai.
--
-- Tat TRUOC roi bat SAU: bat truoc thi co mot khung hinh hai kieu troi
-- chong nhau, va mua voi bao cat cung luc nhin ra loi ve.
local function setWeather(code)
  if S.modWeather == nil or EnableWeatherEffect == nil then return end
  for k, w in pairs(S.modWeather) do
    if k ~= code and w ~= nil then EnableWeatherEffect(w, false) end
  end
  local cw = (code ~= nil) and S.modWeather[code] or nil
  if cw ~= nil then EnableWeatherEffect(cw, true) end
end

-- Boc mot tu chinh cho stage. KHONG trung cai vua roi.
--
-- Hai stage lien tiep giong nhau thi nguoi choi tuong he hong -- va
-- voi bang 5 cai thi xac suat trung la 1/5, du cao de gap thuong xuyen.
local function pick(stage)
  local list = CFG.MODIFIERS
  if list == nil or #list == 0 then S.waveMod = nil; return end

  local prev = S.waveModCode
  local m
  if #list == 1 then
    m = list[1]
  else
    -- Boc lai toi khi khac cai truoc. Toi da vai vong vi #list >= 2.
    for _ = 1, 20 do
      m = list[GetRandomInt(1, #list)]
      if m.code ~= prev then break end
    end
  end

  S.waveMod     = m
  S.waveModCode = m.code
  S.waveModAbil = nil   -- do lai moi stage: ability chi gan cho stage nay
  setWeather(m.code)
end

-- Tat troi. Goi o stage boss: boss da co bang co che rieng, them mot
-- kieu troi nua la nguoi choi khong biet troi dang noi ve cai gi.
local function clear()
  S.waveMod, S.waveModCode = nil, nil
  setWeather(nil)
  -- Khung Tong Quan co mot dong doc tu day. Khong goi thi dong do giu
  -- ten tu chinh CU suot ca dot boss -- sai ma nhin rat that.
  if API.gameFrameRefresh ~= nil then API.gameFrameRefresh() end
end

-- ---------- Bao cho nguoi choi ----------
--
-- HAI kenh, vi chat troi con tu chinh keo dai ca dot:
--   dong chu  -> noi quai LAM GI va minh PHAI LAM GI
--   mau quai  -> nhin la biet, khong phai nho
local function announce()
  local m = cur()
  if m == nil then return end
  local en   = (API.lang() == "en")
  local desc = (en and m.desc_en) or m.desc_vi or ""
  local sky  = (en and m.sky_en) or m.sky_vi

  -- Goi TEN kieu troi ra, khong de nguoi choi tu doan.
  --
  -- Troi la lop bao thu ba, nhung mot so kieu (suong mu) rat mo nhat --
  -- neu khong noi thi nguoi choi khong biet co phai troi vua doi hay
  -- khong, va mot dau hieu khong chac chan thi khong dung duoc.
  local head = API.t("wave_mod", API.pick(m))
  if sky ~= nil then head = head .. API.t("wave_mod_sky", sky) end

  API.msg(nil, CFG.C_GOLD .. head .. CFG.C_END ..
               "  " .. CFG.C_GREY .. desc .. CFG.C_END)
  if API.gameFrameRefresh ~= nil then API.gameFrameRefresh() end
end

-- Tu chinh DANG chay, cho khung Tong Quan (phim R). Tra ve (ten, mo ta),
-- hoac nil khi dot nay khong co tu chinh nao.
--
-- VI SAO PHAI CO CHO TRA CUU, khong chi mot dong chat.
--
-- Dong chat bao dung mot lan, luc vao dot. Nhung TU CHINH KEO DAI CA
-- DOT, con dong chat thi troi mat sau vai giay. Nguoi choi vao giua
-- dot, hoac vua doc mot dong khac de len, thi khong con cho nao hoi --
-- va thu duy nhat con lai la mau quai voi kieu troi, ca hai deu phai
-- NHO moi doc duoc.
--
-- Do la lop thu tu, va la lop duy nhat TRA CUU DUOC:
--   dong chat  noi mot lan, roi mat
--   mau quai   luon o do, nhung phai nho no nghia gi
--   kieu troi  luon o do, nhung suong mu thi rat mo
--   dong nay   luon o do, va noi ro bang chu
local function labelNow()
  local m = cur()
  if m == nil then return nil end
  local en   = (API.lang() == "en")
  local sky  = (en and m.sky_en) or m.sky_vi
  local name = API.pick(m)
  if sky ~= nil then name = name .. " (" .. sky .. ")" end
  return name, (en and m.desc_en) or m.desc_vi or ""
end

-- Lenh dev "-sky N": bat MOT ma thoi tiet bat ky de NHIN.
--
-- Vi sao phai co lenh nay: khong co cach nao kiem ma thoi tiet bang
-- code. AddWeatherEffect nhan ca ma rac va tra ve handle binh thuong
-- -- 'WNcw' va 'WOlw' deu "dung duoc" theo phep do do, ma tren man
-- hinh khong hien gi. Phep do that la con mat.
--
-- Tao mot lan roi giu (S.skyProbe): goi nhieu lan ma tao moi lan thi
-- ro ri handle, va Warcraft khong tu don.
local function devSky(pid, text)
  local list = CFG.SKY_PROBE or {}
  local arg  = (text or ""):match("%-sky%s+(%S+)")

  if S.skyProbe == nil then S.skyProbe = {} end

  -- Tat het truoc, ke ca thoi tiet cua tu chinh: hai kieu troi chong
  -- nhau thi khong biet minh dang nhin cai nao.
  setWeather(nil)
  for _, w in pairs(S.skyProbe) do
    if w ~= nil and EnableWeatherEffect ~= nil then EnableWeatherEffect(w, false) end
  end
  if arg == "off" then
    API.info(pid, "-sky: tat het")
    return
  end

  local n = tonumber(arg)
  if n == nil or list[n] == nil then
    API.info(pid, "-sky N   (N = 1.." .. #list .. ")   |   -sky off")
    for i = 1, #list do
      API.info(pid, "   " .. i .. ". " .. list[i][1] .. "  " .. list[i][2])
    end
    return
  end

  local code = list[n][1]
  if S.skyProbe[code] == nil then
    local r = bj_mapInitialPlayableArea
    if AddWeatherEffect == nil or r == nil then
      API.info(pid, "-sky: khong co AddWeatherEffect")
      return
    end
    S.skyProbe[code] = AddWeatherEffect(r, FourCC(code))
  end
  local w = S.skyProbe[code]
  if w ~= nil and EnableWeatherEffect ~= nil then EnableWeatherEffect(w, true) end
  API.info(pid, "-sky " .. n .. " = '" .. code .. "'  " .. list[n][2])
  API.trace("sky: bat thu '" .. code .. "' (" .. list[n][2] .. ")")
end

-- Lenh dev "-mod N": ep tu chinh so N va bat troi cua no ngay.
--
-- Ly do co lenh nay: doi RNG boc trung mot tu chinh de xem kieu troi
-- cua no la cho mot minh trong may phut. Va khi mot kieu troi KHONG
-- hien ra, phai tra loi duoc cau "no khong chay, hay no chay ma mo qua"
-- -- lenh nay tra loi trong muoi giay.
local function devSet(pid, text)
  local n = tonumber((text or ""):match("%-mod%s+(%d+)"))
  local list = CFG.MODIFIERS or {}
  if n == nil or list[n] == nil then
    API.info(pid, "-mod N  (N = 1.." .. #list .. ")")
    for i = 1, #list do
      API.info(pid, "   " .. i .. ". " .. list[i].code ..
                    "  troi=" .. tostring((list[i].weather or {})[1]))
    end
    return
  end
  local m = list[n]
  S.waveMod, S.waveModCode, S.waveModAbil = m, m.code, nil
  setWeather(m.code)
  API.info(pid, "-mod " .. n .. " -> " .. m.code .. ", troi " ..
                tostring((m.weather or {})[1]))
end

-- ---------- Gan len mot con vua sinh ----------

local function apply(u)
  local m = cur()
  if m == nil or u == nil then return end

  local c = m.color
  if c ~= nil and SetUnitVertexColor ~= nil then
    SetUnitVertexColor(u, c[1], c[2], c[3], 255)
  end

  if m.kind == "ability" then
    -- Do MOT lan cho ca stage, roi dung ket qua do cho 49 con con lai.
    if S.waveModAbil == nil then
      S.waveModAbil = probeAbility(u, m.abils)
    elseif S.waveModAbil and UnitAddAbility ~= nil then
      UnitAddAbility(u, S.waveModAbil)
    end
  end
end

-- ---------- Giam sat thuong ----------
--
-- Chay o su kien sat thuong, KHONG o giap (xem dau file).
--
-- Phan biet phep/don danh y het cach Ao Choang lam trong 7_effect.lua:
-- moi ky nang hero deu danh ra DAMAGE_TYPE_MAGIC, don thuong thi
-- DAMAGE_TYPE_NORMAL. Thieu BlzGetEventDamageType thi coi la don danh
-- va GHI VET mot lan -- khong nuot.
local warnedType = false

local function onDamaged()
  local m = cur()
  if m == nil or m.kind ~= "damage" then return end
  if BlzSetEventDamage == nil then return end

  local tgt = GetTriggerUnit()
  if tgt == nil or S.mobs == nil or S.mobs[tgt] == nil then return end

  local dmg = GetEventDamage()
  if dmg <= 0.0 then return end

  local spell = false
  if BlzGetEventDamageType ~= nil then
    spell = (BlzGetEventDamageType() ~= DAMAGE_TYPE_NORMAL)
  elseif not warnedType then
    warnedType = true
    API.trace("modifier: THIEU BlzGetEventDamageType -- moi don deu tinh " ..
              "la don danh, tu chinh Chan Phep se khong an gi")
  end

  if spell ~= (m.spell == true) then return end

  -- Phap Khi "Luong Nghi Chau": tu chinh nay chi con cat mot nua.
  --
  -- Loc theo NGUOI GAY sat thuong, khong theo muc tieu: muc tieu la con
  -- quai, ma mon do la cua hero. Ai khong mua thi van an du 50%, nen
  -- hai nguoi trong mot doi co the danh khac nhau.
  local cut = m.cut or 0.0
  if API.relicVal ~= nil and API.heroPidOf ~= nil then
    local sp = API.heroPidOf(GetEventDamageSource())
    if sp ~= nil then
      local half = API.relicVal(sp, "luongnghi", "modCut")
      if half > 0.0 then cut = cut * (1.0 - half) end
    end
  end
  BlzSetEventDamage(dmg * (1.0 - cut))
end

-- ---------- Chet thi no ----------
--
-- Sat thuong tinh theo SAT THUONG CUA CHINH CON DO (BlzGetUnitBaseDamage)
-- chu khong phai mot con so phang: con so phang se thanh vo nghia o canh
-- gioi 15. Doc khong duoc thi bo qua chu khong bia.
local function onDeath()
  local m = cur()
  if m == nil or m.kind ~= "death" then return end

  local u = GetTriggerUnit()
  if u == nil or S.mobs == nil or S.mobs[u] == nil then return end
  if BlzGetUnitBaseDamage == nil or UnitDamageTarget == nil then return end

  local base = BlzGetUnitBaseDamage(u, 0)
  if base == nil or base <= 0 then return end
  local dmg = base * (m.factor or 1.0)
  local r   = m.radius or 300.0
  local x, y = GetUnitX(u), GetUnitY(u)

  if CFG.FX_SLAM_HIT ~= nil then API.fx(CFG.FX_SLAM_HIT, x, y) end

  -- Chi danh HERO nguoi choi. No lan sang chinh dong quai cua no thi
  -- tu chinh nay thanh mot mon qua cho nguoi choi.
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    local h = d and d.hero or nil
    if h ~= nil and API.alive(h)
       and API.distXY(x, y, GetUnitX(h), GetUnitY(h)) <= r then
      -- Phap Khi "Bat Dong Minh Vuong": vu no chi con mot nua.
      local one = dmg
      if API.relicVal ~= nil then
        local half = API.relicVal(S.pids[i], "batdong", "halve")
        if half > 0.0 then one = one * (1.0 - half) end
      end
      UnitDamageTarget(u, h, one, true, false,
                       ATTACK_TYPE_NORMAL, DAMAGE_TYPE_NORMAL, WEAPON_TYPE_WHOKNOWS)
    end
  end
end

-- ---------- Nhan thuong ----------

local function rewardMult()
  local m = cur()
  if m ~= nil and m.kind == "bounty" then return m.mult or 1.0 end
  return 1.0
end

-- ---------- Khoi dong ----------

local function startModifier()
  S.waveMod, S.waveModCode, S.waveModAbil = nil, nil, nil
  if CFG.MODIFIERS == nil or #CFG.MODIFIERS == 0 then
    API.trace("modifier: bang rong -- moi stage thuong se giong het nhau")
    return
  end

  S.modWeather = {}
  for i = 1, #CFG.MODIFIERS do
    local m = CFG.MODIFIERS[i]
    S.modWeather[m.code] = makeWeather(m)
  end

  local td = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(td, EVENT_PLAYER_UNIT_DAMAGED)
  TriggerAddAction(td, onDamaged)
  S.modDmgTrig = td

  local tk = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tk, EVENT_PLAYER_UNIT_DEATH)
  TriggerAddAction(tk, onDeath)
  S.modDeathTrig = tk

  API.trace("modifier: " .. #CFG.MODIFIERS .. " tu chinh, boc ngau nhien " ..
            "khong trung cai truoc")
end

API.modifierPick       = pick
API.modifierClear      = clear
API.modifierDevSet     = devSet
API.modifierDevSky     = devSky
API.modifierApply      = apply
API.modifierAnnounce   = announce
API.modifierLabel      = labelNow
API.modifierRewardMult = rewardMult
API.startModifier      = startModifier
end
--#endregion 3_battle/5_modifier.lua

--#region 4_ui/1_panel.lua
do
-- ============================================================
--  1_panel.lua  --  Bang nhan vat (phim R -- xem CFG.PANEL_KEY)
--
--  MOT khung, bon the. Moi he tu dang ky noi dung cua minh qua
--  API.panelAddTab -- khung khong biet gi ve Linh Can hay Ky Nang.
--
--  HAI KIEU THAN BANG, khong phai mot.
--
--  Ban truoc chi co mot kieu: bang tinh hang x o, moi the tu khai bao
--  cot cua no, va mot nut "+" rong 0.028 o mep phai. Bon he thi khong
--  cung hinh dang, nen ep ca bon vao bang tinh lam cai nao cung do:
--
--    Linh Can  la mot cai thang co DUNG MOT hanh dong (dot pha len bac
--              ke). Bang tinh hien 7 dong, ma 6 dong khong bam duoc --
--              thong tin tham khao chen cho dung mot viec lam duoc.
--    Ky Nang   la 7 mon nang cap doc lap. Nam cot chia 680px thi cot
--              "Bac" con 81px, va chu dai tran sang cot ben.
--    Trang Bi  6 mon, Phap Khi 5 mon -- cung hinh dang voi Ky Nang.
--
--  Nen: "list" (3/4 the) va "focus" (1/4 the). The khai bao DU LIEU,
--  bang lo BO CUC -- nguoc han ban truoc, noi the phai khai bao cot.
--
--  Nho vay them mot he moi khong phai dung them bang, cung khong phai
--  do be ngang cot: tra ve mot danh sach muc la xong.
--
--  Mo/dong va doi the la UI THUAN -> lam cuc bo duoc, khong can dong
--  bo. Chi HANH DONG (dot pha, nang cap, mua) moi phai qua
--  BlzSendSyncData, va do la viec cua tung he.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local TAB_H  = 0.026
local HEAD_H = 0.022    -- dong tien
-- KHONG CON NUT CLOSE. Dong bang ESC, hoac bam lai phim mo bang.
--
-- Nut cu nam o chan khung va bam khong an: thanh giao dien duoi cua
-- Warcraft phu khoang 0.12 duoi man hinh va an TREN frame cua ta, nen
-- no nuot cu bam truoc khi toi duoc nut. Frame bi che mot phan van
-- "nhin thay duoc" nen nhin thi khong ra loi.
--
-- Doi len dinh khung thi het loi, nhung mot phim ESC van gon hon mot
-- cai nut phai ram chuot toi -- va ESC la thu nguoi choi bam theo phan
-- xa de dong bat cu thu gi. Nen bo han nut, giu mot dong chu nho chi
-- cho biet bam gi.
local GAP    = 0.006
local LINE   = 0.016    -- khoang cach hai dong chu trong mot muc

-- Cao than bang o kieu "focus". Bang phai CAO BANG NHAU o moi the,
-- neu khong doi the mot cai la khung nhay -- nen lay max voi kieu list.
local FOCUS_H = 0.200

-- THU TU O DAY LA MOT RANG BUOC, khong phai so thich: nam ham duoi
-- phai dung TRUOC cellH()/gridH(). Lua khong thay local khai bao sau,
-- nen mot closure viet truoc se bat ICON/BTN_H thanh BIEN TOAN CUC --
-- tuc nil -- va no chi no luc CHAY.
--
-- Da dinh that: khoi "grid" nhap vao nam tren khoi nay, nen ICON() ben
-- trong cellH() la nil. Ket qua: build() nem loi giua chung, backdrop
-- da tao thi dang HIEN, chua kip dat kich thuoc va chua co con nao --
-- bam ESC ra mot cai hop rong co mac dinh, khong dong duoc, va khong
-- mot dong bao nao. Loi Lua trong callback cua Warcraft khong in ra dau.
-- Le trong THAT = le + vien trang tri cua backdrop. Moi thu ben trong
-- dung con so nay, nen doi backdrop chi phai sua mot cho.
local function PAD()   return CFG.PANEL_PAD + (CFG.PANEL_BORDER or 0.0) end
local function ROW()   return CFG.PANEL_ROW end
local function ICON()  return CFG.PANEL_ICON end
local function BTN_W() return CFG.PANEL_BTN_W end
local function BTN_H() return CFG.PANEL_BTN_H end

-- ---------- Than kieu "grid": o trang bi xep quanh hinh nguoi ----------
--
-- Doc tu the dang ky (tab.slots), khong go tay: doi CFG.GEAR_SLOTS la
-- bang tu co theo, y het cach MAX_ITEMS doc so dong tu the dai nhat.
local GRID_SLOTS = nil
-- { cot, dong } cua o TICK cua the luoi, hoac nil neu the khong co.
-- Doc tu the dang ky (tab.toggleSlot) y het GRID_SLOTS -- bang khong go
-- tay con so nao cua rieng he Trang Bi.
local GRID_TOGGLE = nil
local GRID_COLS, GRID_ROWS = 0, 0
local CELL_GAP = 0.008

-- Mot o = icon o tren, nut Upgrade ngay duoi.
local function cellH()  return ICON() + 0.004 + BTN_H() end
local function rowStep() return cellH() + CELL_GAP end

local function gridH()
  if GRID_ROWS <= 0 then return 0.0 end
  return GRID_ROWS * rowStep() - CELL_GAP
end

-- Bao nhieu dong phai dung san. Tinh tu the dai nhat da dang ky, chu
-- khong go tay: them mot he 9 muc thi bang tu no rong ra.
local MAX_ITEMS = 1

-- Than bang cao bang the CAO NHAT trong ba kieu. Bang phai cao bang
-- nhau o moi the, neu khong doi the mot cai la khung nhay.
local function bodyH()
  local h = MAX_ITEMS * ROW()
  if FOCUS_H > h then h = FOCUS_H end
  local g = gridH()
  if g > h then h = g end
  return h
end

local function panelH()
  return PAD() + TAB_H + GAP + HEAD_H + GAP + bodyH() + PAD()
end

local function tabTop()
  return PAD()
end

local function bodyTop()
  return tabTop() + TAB_H + GAP + HEAD_H + GAP
end

-- Be ngang phan chu cua mot muc: tru icon ben trai va nut ben phai.
local function textW()
  return CFG.PANEL_W - 2 * PAD() - ICON() - 0.008 - BTN_W() - 0.008
end

-- So La Ma cho nhan the: I. Linh Can, II. Ky Nang, ...
local ROMAN = { "I", "II", "III", "IV", "V", "VI", "VII", "VIII" }

local FRAME_OK = nil

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  FRAME_OK = (BlzGetOriginFrame ~= nil and BlzCreateFrameByType ~= nil
          and BlzFrameSetAbsPoint ~= nil and BlzFrameSetPoint ~= nil
          and BlzFrameSetSize ~= nil and BlzFrameSetTexture ~= nil
          and BlzFrameSetVisible ~= nil and BlzFrameSetText ~= nil
          and BlzTriggerRegisterFrameEvent ~= nil and BlzGetTriggerFrame ~= nil
          and ORIGIN_FRAME_GAME_UI ~= nil and FRAMEEVENT_CONTROL_CLICK ~= nil
          and FRAMEPOINT_CENTER ~= nil and FRAMEPOINT_TOPLEFT ~= nil)
  if not FRAME_OK then API.trace("panel: THIEU native frame") end
  return FRAME_OK
end

-- ---------- Dang ky the ----------
--
-- kind = "list":
--   items(pid) -> { { icon, name, desc, status, btn, btnOn }, ... }
--   itemAction(pid, i)
--   empty  -- chu hien khi items rong
--
-- kind = "focus":
--   info(pid) -> { title, sub, row = { {lbl, before, after}, ... },
--                  progress (0..1), note, btn, btnOn }
--   action(pid)
--
-- kind = "grid":
--   slots    -- { {cot, dong}, ... } mot cap cho moi o, dung thu tu items
--   items(pid) -> nhu "list", dung them:
--                   short  -- ten ngan, cho bang thong ke ben phai
--                   stat   -- mon nay dang cong gi
--   itemAction(pid, i)
--   statHead -- tieu de cot thong ke

local function addTab(tab)
  if tab.kind == nil then tab.kind = "list" end
  S.panel.tabs[#S.panel.tabs + 1] = tab
  return #S.panel.tabs
end

-- The chua lam: hien ro la chua lam thay vi de trong. Mot the trong
-- khien nguoi choi tuong giao dien hong.
local function placeholderTab(name, desc)
  return {
    name   = name,
    kind  = "list",
    items = function() return {} end,
    empty = CFG.C_GREY .. API.t("panel_empty") .. CFG.C_END .. "  " .. desc,
  }
end

-- ---------- Trang thai ----------

local function stateOf(pid)
  if S.panel.byPid[pid] == nil then
    S.panel.byPid[pid] = { panel = nil, money = nil, tabBtn = {},
                           item = {}, focus = nil,
                           tab = 1, shown = false }
  end
  return S.panel.byPid[pid]
end

-- ---------- Ve lai ----------

local function show(f, on)
  if f ~= nil then BlzFrameSetVisible(f, on) end
end

local function setEnabled(f, on)
  if f ~= nil and BlzFrameSetEnable ~= nil then BlzFrameSetEnable(f, on) end
end

-- ---------- Mot nut, ba trang thai ----------
--
-- CA BA kieu than (list / focus / grid) deu goi ham nay, nen Tu Vi,
-- Trang Bi va Ky Nang khong the noi khac nhau duoc.
--
-- Trang thai lay tu du lieu cua the:
--   it.btn == nil          -> khong co nut
--   it.btnOn ~= false      -> "on"
--   it.btnWhy == "locked"  -> "locked"   chua toi luot
--   con lai                -> "poor"     thieu tien
--
-- VI SAO TACH "poor" VOI "locked". Hai cai nay bao nguoi choi lam hai
-- viec TRAI NGUOC: thieu tien thi di cay quai, chua toi luot thi di dot
-- pha Tu Vi. Cho chung trong giong nhau la bat nguoi choi doan.
local function applyBtn(w, it)
  if w == nil or w.btn == nil then return end
  local has = (it ~= nil and it.btn ~= nil)
  show(w.btn, has)
  if not has then return end

  local state = "on"
  if it.btnOn == false then
    state = (it.btnWhy == "locked") and "locked" or "poor"
  end

  -- Chu: mau noi Y NGHIA, be day vien noi BAM DUOC HAY KHONG.
  local label = it.btn
  if state == "poor" then
    label = CFG.C_GREY .. label .. CFG.C_END
  elseif state == "locked" then
    label = CFG.C_GOLD .. label .. CFG.C_END
  end
  if w.btnTxt ~= nil then BlzFrameSetText(w.btnTxt, label) end

  -- MAU RUOT: tin hieu chinh, doc duoc mot minh khong can so sanh.
  if w.fill ~= nil and BlzFrameSetTexture ~= nil then
    local tex = (state == "poor")   and CFG.PANEL_BTN_FILL_POOR
             or (state == "locked") and CFG.PANEL_BTN_FILL_LOCKED
             or CFG.PANEL_BTN_FILL
    if tex ~= nil then BlzFrameSetTexture(w.fill, tex, 0, true) end
  end

  -- Be day vien = ruot thut vao bao nhieu. Chi con phan biet CO vien
  -- (on/poor) voi KHONG vien (locked) -- viec noi on khac poor da giao
  -- han cho mau ruot. Vien day tung la tin hieu chinh, va 8,6 px tren
  -- nut cao 47 px nhin ra mot cai khung chu khong phai cai nut.
  if w.fill ~= nil and w.w ~= nil then
    local d = (CFG.PANEL_BTN_BORDER or 0.0016)
            * ((state == "on")   and (CFG.PANEL_BTN_W_ON     or 1.0)
            or (state == "poor") and (CFG.PANEL_BTN_W_POOR   or 1.0)
            or (CFG.PANEL_BTN_W_LOCKED or 0.0))
    BlzFrameSetSize(w.fill, w.w - 2 * d, w.h - 2 * d)
    BlzFrameSetPoint(w.fill, FRAMEPOINT_TOPLEFT, w.btn,
                     FRAMEPOINT_TOPLEFT, d, -d)
  end

  setEnabled(w.btn, state == "on")
end

local function refreshList(st, pid, tab)
  local items = (tab.items and tab.items(pid)) or {}

  for i = 1, MAX_ITEMS do
    local it = items[i]
    local w  = st.item[i]
    if w ~= nil then
      local has = (it ~= nil)
      show(w.bg, has and (i % 2 == 0))
      show(w.name, has)
      show(w.state, has)
      show(w.sub, has)
      show(w.icon, has and it.icon ~= nil)
      show(w.btn, has and it.btn ~= nil)

      if has then
        if it.icon ~= nil then BlzFrameSetTexture(w.icon, it.icon, 0, true) end
        BlzFrameSetText(w.name,  CFG.C_GOLD .. (it.name or "?") .. CFG.C_END)
        BlzFrameSetText(w.state, it.status or "")
        BlzFrameSetText(w.sub,   CFG.C_GREY .. (it.desc or "") .. CFG.C_END)
        -- applyBtn lo het: chu, be day vien, va bat/tat.
        --
        -- Nut KHONG bien mat khi thieu tien -- van thay duoc gia, chi
        -- khong bam duoc. An han thi nguoi choi khong biet mon do ton
        -- bao nhieu de ma de danh.
        applyBtn(w, it)
      end
    end
  end

  -- Dong "chua co gi" cho the giu cho.
  show(st.empty, #items == 0)
  if #items == 0 and st.empty ~= nil then
    BlzFrameSetText(st.empty, tab.empty or "")
  end
end

local function refreshFocus(st, pid, tab)
  local f = st.focus
  if f == nil then return end
  local d = (tab.info and tab.info(pid)) or {}

  BlzFrameSetText(f.titleF, CFG.C_GOLD .. (d.title or "") .. CFG.C_END)
  BlzFrameSetText(f.sub,    CFG.C_JADE .. (d.sub or "") .. CFG.C_END)

  local row = d.row or {}
  for i = 1, #f.row do
    local r = f.row[i]
    local v = row[i]
    show(r.alt, v ~= nil)
    show(r.lbl, v ~= nil)
    show(r.before, v ~= nil)
    show(r.after, v ~= nil)
    if v ~= nil then
      BlzFrameSetText(r.lbl,  CFG.C_GREY .. (v[1] or "") .. CFG.C_END)
      BlzFrameSetText(r.before, v[2] or "")
      -- Mui ten nam trong cung frame voi gia tri sau, de khong phai do
      -- be ngang cua gia tri truoc moi biet dat mui ten o dau.
      BlzFrameSetText(r.after,   CFG.C_GREY .. "->  " .. CFG.C_END ..
                               CFG.C_JADE .. (v[3] or "") .. CFG.C_END)
    end
  end

  -- Dai tranh. The nao KHONG khai bao 'art' thi ca cum an di -- than
  -- kieu focus dung chung cho moi the, khong rieng Tu Vi.
  if f.art ~= nil then
    local art = d.art or {}
    for i = 1, #f.art do
      local a, v = f.art[i], art[i]
      local on = (v ~= nil and v.icon ~= nil)
      show(a.icon, on)
      show(a.name, on)
      if on then
        BlzFrameSetTexture(a.icon, v.icon, 0, true)
        BlzFrameSetText(a.name, (v.dim and CFG.C_GREY or CFG.C_JADE)
                                .. (v.name or "") .. CFG.C_END)
      end
    end
    -- Mui ten chi co nghia khi CO ca hai dau.
    show(f.artArrow, art[1] ~= nil and art[2] ~= nil)
    if f.artArrow ~= nil then
      BlzFrameSetText(f.artArrow, CFG.C_GREY .. "->" .. CFG.C_END)
    end
  end

  local p = d.progress or 0.0
  if p < 0.0 then p = 0.0 elseif p > 1.0 then p = 1.0 end
  local full = CFG.PANEL_W - 2 * PAD()
  -- NEN phai hien -- backdropFrame() tao ra o trang thai an, va truoc
  -- day khong ai bat no len. Ket qua: chi thay o vang cua phan da day,
  -- lo lung khong ro no la thanh gi. Mot thanh tien do khong co nen thi
  -- khong phai thanh tien do.
  show(f.barBg, true)
  -- Be ngang 0 lam frame hong; an han di thay vi dat kich thuoc 0.
  show(f.barFill, p > 0.01)
  if p > 0.01 then BlzFrameSetSize(f.barFill, full * p, 0.010) end

  BlzFrameSetText(f.note, CFG.C_GREY .. (d.note or "") .. CFG.C_END)

  show(f.btn, d.btn ~= nil)
  if d.btn ~= nil then
    applyBtn(f, d)
  end
end

-- Ve lai luoi trang bi. Hai nua: o ben trai, bang thong ke ben phai --
-- cung mot nguon du lieu (tab.items) nen khong the lech nhau.
local function refreshGrid(st, pid, tab)
  local g = st.grid
  if g == nil or g.root == nil then return end
  local items = (tab.items and tab.items(pid)) or {}

  -- O Pet luon hien. backdropFrame()/text() tao ra o trang thai AN, nen
  -- khong bat o day thi no khong bao gio lo mat.
  show(g.petEdge, true); show(g.petFill, true); show(g.petTxt, true)

  -- Cot giua: icon + ten hero + canh gioi Tu Vi dang o.
  show(g.doll, true); show(g.dollIcon, true)
  show(g.dollName, true); show(g.dollRank, true)
  if g.dollName ~= nil then
    local d   = S.p[pid]
    local uid = (d ~= nil and d.hero ~= nil) and GetUnitTypeId(d.hero) or nil
    local nm  = (uid ~= nil and API.heroNameOf ~= nil)
                and API.heroNameOf(uid) or "?"
    BlzFrameSetText(g.dollName, CFG.C_GOLD .. nm .. CFG.C_END)

    -- Canh gioi: doc qua API vi bang REALMS o 1_config, con bac thi o
    -- 3_cultivation. Thieu mot trong hai thi hien "?" chu khong no.
    local r  = (API.cultRank ~= nil) and API.cultRank(pid) or 1
    local rn = (CFG.REALMS ~= nil and CFG.REALMS[r] ~= nil)
               and API.pick(CFG.REALMS[r]) or "?"
    BlzFrameSetText(g.dollRank, CFG.C_JADE .. rn .. CFG.C_END)

    if g.dollIcon ~= nil and uid ~= nil and API.heroIndex ~= nil then
      local hi = API.heroIndex(uid)
      local hd = (hi ~= nil) and CFG.HEROES[hi] or nil
      if hd ~= nil and hd.icon ~= nil then
        BlzFrameSetTexture(g.dollIcon, hd.icon, 0, true)
      end
    end
  end

  if g.statHead ~= nil then
    BlzFrameSetText(g.statHead, CFG.C_GOLD .. (tab.statHead or "") .. CFG.C_END)
  end

  -- O tich: chu do THE tu sinh, bang khong biet no noi gi.
  if g.toggle ~= nil then
    local on = (tab.toggleText ~= nil)
    show(g.toggle.btn, on)
    if on and g.toggle.txt ~= nil then
      BlzFrameSetText(g.toggle.txt, tab.toggleText(pid))
    end
  end

  for i = 1, #g.cell do
    local it, c = items[i], g.cell[i]
    local has = (it ~= nil)
    local hasBtn = has and it.btn ~= nil
    local hasTag = has and it.tag ~= nil
    show(c.edge, has)
    show(c.icon, has and it.icon ~= nil)
    show(c.btn,  hasBtn)
    show(c.tagBg, hasTag); show(c.tag, hasTag)
    -- Co nut thi khong co chu, va nguoc lai -- hai thu dung CHUNG mot
    -- cho nen bat ca hai la chung de len nhau.
    show(c.note, has and not hasBtn)
    if has then
      if it.icon ~= nil then BlzFrameSetTexture(c.icon, it.icon, 0, true) end
      -- 'tag' da mang mau cua chinh no tu 5_gear.lua -- khong boc them
      -- mot lop mau o day (Warcraft khong co ngan xep mau: mot |r dong
      -- het ca hai).
      if hasTag and c.tag ~= nil then BlzFrameSetText(c.tag, it.tag) end
      if not hasBtn and c.note ~= nil then
        BlzFrameSetText(c.note, CFG.C_GREY .. (it.note or "") .. CFG.C_END)
      end
      if it.btn ~= nil then
        -- Cung quy uoc voi kieu "list": khong du tien thi chu XAM chu
        -- khong an nut -- an di la nguoi choi khong biet mon do ton bao
        -- nhieu de ma de danh.
        applyBtn(c, it)
      end
    end
  end

  for i = 1, #g.stat do
    local it, w = items[i], g.stat[i]
    local has = (it ~= nil)
    show(w.alt, has); show(w.lbl, has); show(w.val, has)
    if has then
      BlzFrameSetText(w.lbl, CFG.C_GREY .. (it.short or it.name or "?") .. CFG.C_END)
      -- 'stat' da mang mau cua chinh no tu 5_gear.lua. Boc them mot lop
      -- mau o day la loi mau LONG NHAU: Warcraft khong co ngan xep mau,
      -- mot |r dong het ca hai va phan con lai cua dong mat mau.
      BlzFrameSetText(w.val, it.stat or "")
    end
  end
end

local function refresh(pid)
  local st = stateOf(pid)
  if st.panel == nil then return end

  local tab = S.panel.tabs[st.tab]
  if tab == nil then return end

  -- Nhan the: the dang mo to vang, cac the khac xam.
  for i = 1, #S.panel.tabs do
    local t = st.tabBtn[i]
    if t ~= nil and t.txt ~= nil then
      local nm = (ROMAN[i] or i) .. ". " .. S.panel.tabs[i].name
      BlzFrameSetText(t.txt,
        (i == st.tab and CFG.C_GOLD or CFG.C_GREY) .. nm .. CFG.C_END)
    end
  end

  if st.money ~= nil then
    local money = {
      { API.t("panel_qi"), API.getQi(pid),  CFG.C_JADE },
      { API.t("panel_gold"),    API.getGold(pid),     CFG.C_GOLD },
      { API.t("panel_lumber"),      API.getLumber(pid),       CFG.C_GOLD },
      { API.t("panel_iron"),      API.getIron(pid),       CFG.C_GREY },
    }
    for i = 1, #money do
      local m = st.money[i]
      if m ~= nil then
        BlzFrameSetText(m.lbl, CFG.C_GREY .. money[i][1] .. CFG.C_END)
        BlzFrameSetText(m.amt,   money[i][3] .. API.num(money[i][2]) .. CFG.C_END)
      end
    end
  end

  local kind   = tab.kind or "list"
  local isList = (kind == "list")

  -- Dong cua kieu "list" dung san o MOI the, nen the khac phai tat het
  -- chung di truoc -- neu khong the Trang Bi se co bay dong ma cu nam
  -- de duoi luoi.
  if not isList then
    for i = 1, MAX_ITEMS do
      local w = st.item[i]
      if w ~= nil then
        show(w.bg, false); show(w.icon, false); show(w.name, false)
        show(w.state, false); show(w.sub, false); show(w.btn, false)
      end
    end
    show(st.empty, false)
  end
  if st.focus ~= nil then show(st.focus.root, kind == "focus") end
  if st.grid  ~= nil then show(st.grid.root,  kind == "grid")  end

  -- Than bang dung duoc chua? Neu khong, dung de bang cam nin -- do la
  -- kieu hong te nhat: nguoi choi mo bang ra thay mot khung trong ron
  -- va tuong MINH lam sai gi do.
  local bodyOk = true
  if kind == "focus" then
    bodyOk = (st.focus ~= nil and st.focus.root ~= nil)
  elseif kind == "grid" then
    bodyOk = (st.grid ~= nil and st.grid.root ~= nil)
  end

  if not bodyOk then
    if st.empty ~= nil then
      BlzFrameSetText(st.empty, CFG.C_RED .. API.t("panel_bodyfail") .. CFG.C_END)
      show(st.empty, true)
    end
    API.trace("panel: the '" .. tostring(tab.name) .. "' kieu " .. kind ..
              " KHONG co than -- hien dong bao thay vi de trong")
    return
  end

  if kind == "focus" then
    refreshFocus(st, pid, tab)
  elseif kind == "grid" then
    refreshGrid(st, pid, tab)
  else
    refreshList(st, pid, tab)
  end
end

-- ---------- Nhay mot muc trong bang ----------
--
-- Goi tu he nao vua lam xong mot viec (luyen trang bi, mua do). Phan
-- hoi phai o TREN CAI MUC VUA BAM: do la cho nguoi choi dang nhin, con
-- hero ngoai map thi dang bi chinh cai bang che khuat.
--
-- Chay tren MOI may, nhung frame cua pid nao thi chi may cua nguoi do
-- ve -- nen khong phai loc gi them.
--
-- Tim o CA HAI kieu than: luoi (Trang Bi) va danh sach (Shop, Phap Khi).
-- He goi khong phai biet minh dang o kieu nao.
local function panelFlash(pid, index, kind)
  local st = stateOf(pid)

  -- Hoi THE DANG MO la kieu gi, khong phai "bang nao ton tai".
  -- Ca hai than deu dung san tu luc dung bang, nen thu luoi truoc la
  -- dang o Shop cung nhay trung mot o Trang Bi -- sai o khong ai ngo.
  local tab = S.panel.tabs[st.tab]
  local kind = (tab ~= nil) and (tab.kind or "list") or "list"

  local c = nil
  if kind == "grid" then
    c = (st.grid ~= nil and st.grid.cell ~= nil) and st.grid.cell[index] or nil
  elseif kind == "list" then
    c = (st.item ~= nil) and st.item[index] or nil
  end
  if c == nil or c.flash == nil then return end

  local ok  = (kind ~= "fail")
  local tex = ok and CFG.PANEL_FLASH_OK or CFG.PANEL_FLASH_FAIL
  if BlzFrameSetTexture ~= nil then
    BlzFrameSetTexture(c.flash, tex, 0, true)
  end

  local pulses = (kind == "big")  and (CFG.PANEL_FLASH_BIG_PULSES  or 3)
              or (kind == "fail") and (CFG.PANEL_FLASH_FAIL_PULSES or 2)
              or (CFG.PANEL_FLASH_OK_PULSES or 1)
  local step = CFG.PANEL_FLASH_STEP or 0.16

  -- Moi nhip: hien nua dau, tat nua sau. Hen gio tuyet doi tu bay gio
  -- chu khong noi duoi nhau -- noi duoi thi mot nhip truot la lech het.
  for k = 0, pulses - 1 do
    API.after(k * step,           function() show(c.flash, true)  end)
    API.after(k * step + step / 2, function() show(c.flash, false) end)
  end
end

local function hide(pid)
  local st = stateOf(pid)
  if st.panel ~= nil then BlzFrameSetVisible(st.panel, false) end
  st.shown = false
end

-- ---------- Dung bang ----------

local function buildBody(pid)
  local st = stateOf(pid)
  if st.panel ~= nil then return true end

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local P, W = PAD(), CFG.PANEL_W
  local bg, how = API.backdrop(CFG.PANEL_BACKDROP, parent, pid, CFG.FRAME_BG)
  st.panel = bg
  if st.panel == nil then return false end
  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.PANEL_X, CFG.PANEL_Y)
  BlzFrameSetSize(st.panel, W, panelH())

  -- Mot dong chu neo TRAI (hoac PHAI) vao mot o co be ngang THAT.
  -- Khong dat kich thuoc thi Warcraft can giua chu quanh diem neo va
  -- chu dai tran deu hai ben -- do la loi "chu de len cot ben canh"
  -- cua ban truoc.
  local function text(name, parentF, dx, dy, w, scale, right, h)
    local t = BlzCreateFrameByType("TEXT", name, parentF, "", pid)
    if t == nil then return nil end
    local s = scale or 1.0
    -- CHIA cho ti le phong -- CA TOA DO lan kich thuoc.
    --
    -- Do duoc tu anh chup: BlzFrameSetScale(f, s) khong chi phong hinh
    -- cua f, no phong luon KHOANG CACH tu f toi diem neo cua cha. Mot
    -- frame dat cach cha (dx, dy) voi ti le s se duoc ve o (dx*s, dy*s).
    --
    -- Ban truoc chi bu kich thuoc, nen moi dong chu co ti le khac 1.0
    -- deu bi keo ve goc tren-trai cua cha, va keo cang nhieu khi cang xa
    -- goc. Do la ly do DUY NHAT khien ca bon the vo bo cuc cung mot lan:
    --   dong tien (0.85) -> nhan cot 2 de len so cot 1: "0Insight"
    --   mo ta muc (0.85) -> keo len ngang hang TEN va trat vao icon
    --   ten muc   (1.05) -> day sang phai, roi khoi cot cua no
    --
    -- Kiem lai bang phep cong: cot 3 dang le o 0.3653, do duoc 0.3653 x
    -- 0.85 = 0.3105 -- dung bang chenh lech nhin thay tren man hinh.
    BlzFrameSetPoint(t, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT,
                     dx / s, -(dy / s))
    -- Truyen h = can GIUA trong mot o cao h, thay vi bam mep tren cua
    -- mot o cao LINE. Can theo mep tren thi phai doan chieu cao chu de
    -- biet tam no o dau -- va doan sai la lech vai pixel, dung cai lam
    -- dong "1/10" khong thang voi nut ben canh.
    BlzFrameSetSize(t, w / s, (h or LINE) / s)
    local mid = (h ~= nil and TEXT_JUSTIFY_MIDDLE ~= nil)
                and TEXT_JUSTIFY_MIDDLE or TEXT_JUSTIFY_TOP
    if BlzFrameSetTextAlignment ~= nil and TEXT_JUSTIFY_TOP ~= nil then
      BlzFrameSetTextAlignment(t, mid,
        right and TEXT_JUSTIFY_RIGHT or TEXT_JUSTIFY_LEFT)
    end
    API.frameScale(t, scale)
    API.frameDead(t)   -- chu nam de len nut se NUOT cu bam
    return t
  end

  -- CHA la tham so, khong co dinh st.panel.
  --
  -- Truoc day ham nay va backdropFrame() luon gan vao st.panel, ke ca
  -- khi goi tu cum "focus". Ket qua: nut va thanh tien do la ANH EM cua
  -- f.root chu khong phai CON, nen tat f.root khong tat duoc chung --
  -- "BREAK THROUGH -> Qi Refining" hien tren CA BON the.
  local function button(name, label, dx, dy, w, h, parentF)
    parentF = parentF or st.panel
    local b = BlzCreateFrameByType("GLUEBUTTON", name, parentF,
                                   CFG.FRAME_BUTTON_TEMPLATE, pid)
    if b == nil then return nil end
    BlzFrameSetSize(b, w, h)
    BlzFrameSetPoint(b, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT, dx, -dy)
    -- VIEN cua nut: HAI O MAU DAC LONG NHAU, khong muon template.
    --
    -- O ngoai phu kin nut = duong vien. O trong thut vao moi be d = ruot.
    -- Ca hai la CON cua nut nen tu an/hien va tu di theo nut, va
    -- frameDead nen khong nuot cu bam. Tao TRUOC chu de chu nam tren.
    --
    -- Vi sao khong dung backdrop co san: xem CFG.PANEL_BTN_EDGE.
    local d = CFG.PANEL_BTN_BORDER or 0.0016
    local function o(name, dx2, dy2, w2, h2, tex)
      local f = BlzCreateFrameByType("BACKDROP", name, b, "", pid)
      if f == nil then return end
      BlzFrameSetSize(f, w2, h2)
      BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, b, FRAMEPOINT_TOPLEFT, dx2, -dy2)
      BlzFrameSetTexture(f, tex, 0, true)
      API.frameDead(f)
      return f
    end
    local edge = o(name .. "Edge", 0.0, 0.0, w, h, CFG.PANEL_BTN_EDGE)
    local fill = o(name .. "Fill", d, d, w - 2 * d, h - 2 * d, CFG.PANEL_BTN_FILL)

    local t = BlzCreateFrameByType("TEXT", name .. "Txt", b, "", pid)
    if t ~= nil then
      BlzFrameSetPoint(t, FRAMEPOINT_CENTER, b, FRAMEPOINT_CENTER, 0, 0)
      BlzFrameSetText(t, label)
      API.frameDead(t)
    end
    BlzTriggerRegisterFrameEvent(S.panel.trig, b, FRAMEEVENT_CONTROL_CLICK)
    -- Giu ca vien/ruot va kich thuoc: doi be day vien luc ve lai thi
    -- phai dat lai ruot, ma dat lai ruot thi phai biet nut to bao nhieu.
    return { btn = b, txt = t, fill = fill, w = w, h = h }
  end

  local function backdropFrame(name, dx, dy, w, h, tex, parentF)
    parentF = parentF or st.panel
    local f = BlzCreateFrameByType("BACKDROP", name, parentF, "", pid)
    if f == nil then return nil end
    BlzFrameSetSize(f, w, h)
    BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT, dx, -dy)
    if tex ~= nil then BlzFrameSetTexture(f, tex, 0, true) end
    BlzFrameSetVisible(f, false)
    API.frameDead(f)
    return f
  end

  -- Hang the
  local n  = #S.panel.tabs
  local tw = (W - 2 * P - (n - 1) * GAP) / n
  for i = 1, n do
    st.tabBtn[i] = button("CharTab" .. i, S.panel.tabs[i].name,
                          P + (i - 1) * (tw + GAP), tabTop(), tw, TAB_H)
  end

  -- Dong tien: BA COT rong bang nhau, nhan can TRAI, so can PHAI.
  --
  -- Ban truoc nhet ca ba cap vao MOT frame chu, ngan nhau bang bon dau
  -- cach. Chu Warcraft khong deu nen bon dau cach khong ra mot be ngang
  -- co dinh: ba cap khong bao gio thang hang, va moi lan so doi do dai
  -- thi hai cap sau truot sang ngang. Nhin la thay lech, va lech khac
  -- nhau moi lan mo bang.
  --
  -- Cot co diem dau CO DINH thi khong con gi truot duoc.
  local moneyY = tabTop() + TAB_H + GAP
                 + (HEAD_H - LINE * CFG.PANEL_SCALE_SUB) * 0.5
  -- Ba cot tien chi chiem 78% be ngang; 22% con lai de chu thich ESC.
  --
  -- Chu thich KHONG dat duoc o hang the: nam nut da chia kin be ngang
  -- roi, dat o goc phai la de thang len "V. Shop".
  local hintW  = (W - 2 * P) * 0.22
  local SO_TIEN = 4
  local colW   = (W - 2 * P - hintW) / SO_TIEN
  st.money = {}
  for i = 1, SO_TIEN do
    local x = P + (i - 1) * colW
    st.money[i] = {
      lbl = text("CharMoneyL" .. i, st.panel, x, moneyY, colW * 0.58,
                  CFG.PANEL_SCALE_SUB, false),
      amt   = text("CharMoneyV" .. i, st.panel, x + colW * 0.58, moneyY,
                  colW * 0.42 - 0.008, CFG.PANEL_SCALE_SUB, true),
    }
  end

  -- Chu nho cuoi dong tien, KHONG phai nut: chi cho biet bam gi de dong.
  -- text() da goi API.frameDead nen no khong nuot cu bam nao.
  st.hint = text("CharHint", st.panel, W - P - hintW, moneyY, hintW,
                 CFG.PANEL_SCALE_SUB, true)
  if st.hint ~= nil then
    BlzFrameSetText(st.hint, CFG.C_GREY ..
      ((CFG.PANEL_KEY == nil) and API.t("panel_close_esc")
                               or API.t("panel_close", CFG.PANEL_KEY)) ..
      CFG.C_END)
  end

  local top = bodyTop()

  -- ----- Than kieu "list": MAX_ITEMS muc dung san -----
  for i = 1, MAX_ITEMS do
    local y  = top + (i - 1) * ROW()
    local xt = P + ICON() + 0.008
    local w  = textW()

    local it = {}
    -- Lop nhay: phu ca dong, thuong xuyen AN. Tao TRUOC cac thu khac
    -- de no nam DUOI chu va icon -- nhay lam nen chu khong che mat noi
    -- dung. (Nguoc voi luoi: o luoi no phu len icon vi o do khong co
    -- chu nao de che.)
    it.flash = backdropFrame("CharFlash" .. i, P, y, W - 2 * P, ROW() - 0.004,
                             CFG.PANEL_FLASH_OK)

    it.bg    = backdropFrame("CharBg" .. i, P, y, W - 2 * P, ROW() - 0.004,
                             CFG.PANEL_GRID_TEX)
    it.icon  = backdropFrame("CharIcon" .. i, P, y + 0.006, ICON(), ICON(), nil)
    it.name  = text("CharName" .. i,  st.panel, xt, y + 0.006, w * 0.62,
                    CFG.PANEL_SCALE_NAME, false)
    -- Dong bac ("1/10"): o cao TRON DONG, can giua theo chieu doc. Nut
    -- ben phai cung can giua dong, nen hai cai chung mot tam -- khong
    -- con phu thuoc chieu cao chu.
    it.state = text("CharState" .. i, st.panel, xt + w * 0.62, y,
                    w * 0.38, CFG.PANEL_SCALE_NAME, true, ROW())
    it.sub   = text("CharSub" .. i,   st.panel, xt, y + 0.006 + LINE + 0.004, w,
                    CFG.PANEL_SCALE_SUB, false)

    local b = button("CharBtn" .. i, "", W - P - BTN_W(),
                     y + (ROW() - BTN_H()) * 0.5, BTN_W(), BTN_H())
    -- GIU CA BANG ma button() tra ve, khong chi btn/btnTxt.
    -- applyBtn() can them fill/w/h de doi BE DAY VIEN -- vut chung di
    -- thi ba trang thai nut trong y het nhau, va do la loi da ship:
    -- xay dung xong ca he ba muc ma tren man hinh khong doi gi.
    if b ~= nil then
      it.btn, it.btnTxt = b.btn, b.txt
      it.fill, it.w, it.h = b.fill, b.w, b.h
    end

    show(it.name, false); show(it.state, false); show(it.sub, false)
    show(it.btn, false)
    st.item[i] = it
  end

  st.empty = text("CharEmpty", st.panel, P, top + 0.010, W - 2 * P,
                  CFG.PANEL_SCALE_NAME, false)
  show(st.empty, false)

  -- ----- Than kieu "focus" -----
  do
    local f = { row = {} }
    local fh = bodyH()

    -- Frame goc CHI de bat/tat ca cum bang MOT loi goi -- no khong ve gi.
    --
    -- Ban truoc no la BACKDROP phu PANEL_GRID_TEX. PANEL_GRID_TEX la mot
    -- o mau DAC (TeamColor27, den): dung cho mot dong cao 0.044 thi ra
    -- vach ke, dung cho ca than bang thi ra MOT TAM DEN to bang nua
    -- khung. Ke vach la viec cua tung dong, khong phai cua ca khoi.
    --
    -- "FRAME" la kieu frame rong: co toa do, co con, khong co hinh. No
    -- khong phai control nen khong goi frameDead -- khong co hinh thi
    -- cung khong nuot duoc cu bam.
    f.root = BlzCreateFrameByType("FRAME", "CharFocus", st.panel, "", pid)
    if f.root == nil then
      -- Lui ve kieu cu: xau nhung con hien duoc. Mot the TRONG te hon
      -- mot the co tam den.
      API.trace("panel: khong tao duoc FRAME rong -- lui ve BACKDROP")
      f.root = BlzCreateFrameByType("BACKDROP", "CharFocus", st.panel, "", pid)
      if f.root ~= nil then
        BlzFrameSetTexture(f.root, CFG.PANEL_GRID_TEX, 0, true)
        -- KHONG goi frameDead o day. frameDead la
        -- BlzFrameSetEnable(f, false), va mot frame bi TAT thi CON cua
        -- no khong nhan duoc cu bam nao -- nut Dot Pha se ve ra day du
        -- ma bam chet lang. frameDead chi dung cho o TRANG TRI nam DE
        -- LEN nut, khong dung cho hop CHUA nut.
      end
    end
    if f.root ~= nil then
      BlzFrameSetSize(f.root, W - 2 * P, fh)
      BlzFrameSetPoint(f.root, FRAMEPOINT_TOPLEFT, st.panel,
                       FRAMEPOINT_TOPLEFT, P, -top)
      show(f.root, false)

      local fw = W - 2 * P
      f.titleF = text("CharFTitle", f.root, 0.004, 0.006, fw * 0.55,
                      CFG.PANEL_SCALE_HEAD, false)
      f.sub    = text("CharFSub",   f.root, fw * 0.45, 0.008, fw * 0.55 - 0.004,
                      CFG.PANEL_SCALE_NAME, true)

      -- Ba dong so lieu, moi dong mot vach ke rieng -- cung cach the
      -- kieu "list" ke dong chan, de hai kieu than trong nhu mot bang.
      for i = 1, 3 do
        local y = 0.044 + (i - 1) * 0.024
        f.row[i] = {
          alt    = (CFG.PANEL_GRID and i % 2 == 0)
                  and backdropFrame("CharFRow" .. i, 0.0, y - 0.004, fw, 0.022,
                                    CFG.PANEL_GRID_TEX, f.root) or nil,
          lbl  = text("CharFL" .. i, f.root, 0.010, y, fw * 0.34,
                       CFG.PANEL_SCALE_NAME, false),
          before = text("CharFA" .. i, f.root, fw * 0.36, y, fw * 0.22,
                       CFG.PANEL_SCALE_NAME, true),
          after   = text("CharFB" .. i, f.root, fw * 0.60, y, fw * 0.38 - 0.010,
                       CFG.PANEL_SCALE_NAME, false),
        }
      end

      -- Thanh tien do + nut + ghi chu dat theo DAY cua than bang, khong
      -- theo dinh. Than bang cao bang the dai nhat (7 ky nang = 0.336),
      -- nen neo theo dinh thi ca cum dinh o nua tren va nua duoi bo
      -- trong -- do la cai "vo bo cuc" cua the I.
      --
      -- Toa do theo F.ROOT, khong theo st.panel. f.root nam o (P, -top)
      -- nen diem panel (P + x, top + y) chinh la diem root (x, y).
      local noteY = fh - 0.022
      local btnH  = BTN_H() + 0.006
      local btnY  = noteY - btnH - 0.010
      local barY  = btnY - 0.020

      -- ---------- DAI TRANH: canh gioi dang o -> canh gioi ke ----------
      --
      -- Than bang cao bang the dai nhat (7 ky nang), ma the Tu Vi chi co
      -- ba dong -- nen giua ba dong va thanh tien do bo trong 46% than
      -- bang. Do la mang trong to nhat ca giao dien.
      --
      -- Dat "dang o -> ke tiep" chu khong mot anh don, vi ca ba dong
      -- tren deu la "truoc -> sau" (Power x1.00 -> x2.85). Hai buc tranh
      -- xep cung nhip do thi doc ra ngay, va con cho nguoi choi THAY
      -- cai minh sap mua chu khong chi doc ten no.
      local rowsBot = 0.044 + 3 * 0.024 + 0.010     -- day ba dong so lieu
      local artTop  = rowsBot + 0.012
      local artH    = (barY - 0.012) - artTop
      if artH > 0.040 then
        f.art = {}
        local nameH = 0.020
        local s1 = artH - nameH                     -- anh dang o
        local s2 = s1 * 0.70                        -- anh ke tiep
        local gap = 0.034                           -- cho mui ten
        local x1  = (fw - (s1 + gap + s2)) * 0.5
        local x2  = x1 + s1 + gap

        local function art(i, x, y, sz)
          local a = {}
          a.icon = backdropFrame("CharFArt" .. i, x, y, sz, sz, nil, f.root)
          -- CAN GIUA bang CENTER-toi-CENTER. text() co tham so thu 7 la
          -- 'right' chu KHONG co can giua -- truyen false thi no bam mep
          -- TRAI. Da dinh o chu "Pet" va o ten hinh nguoi; day la lan ba.
          a.name = BlzCreateFrameByType("TEXT", "CharFArtN" .. i,
                                        f.root, "", pid)
          if a.name ~= nil then
            BlzFrameSetPoint(a.name, FRAMEPOINT_CENTER, a.icon,
                             FRAMEPOINT_BOTTOM, 0.0, -0.011)
            API.frameScale(a.name, CFG.PANEL_SCALE_NAME)
            API.frameDead(a.name)
          end
          return a
        end

        f.art[1] = art(1, x1, artTop, s1)
        f.art[2] = art(2, x2, artTop + (s1 - s2) * 0.5, s2)

        f.artArrow = BlzCreateFrameByType("TEXT", "CharFArtArrow",
                                          f.root, "", pid)
        if f.artArrow ~= nil then
          BlzFrameSetPoint(f.artArrow, FRAMEPOINT_CENTER, f.art[1].icon,
                           FRAMEPOINT_RIGHT, gap * 0.5, 0.0)
          API.frameScale(f.artArrow, CFG.PANEL_SCALE_HEAD)
          API.frameDead(f.artArrow)
        end
      else
        API.trace("panel: dai tranh cao " .. artH .. " -- khong du cho, bo qua")
      end

      f.barBg = backdropFrame("CharFBarBg", 0.0, barY, fw, 0.010,
                              CFG.PANEL_BAR_BG, f.root)
      f.barFill = backdropFrame("CharFBarFill", 0.0, barY, fw * 0.5, 0.010,
                                CFG.PANEL_BAR_FILL, f.root)

      local b = button("CharFBtn", "", fw * 0.10, btnY,
                       fw * 0.80, btnH, f.root)
      -- GIU CA BANG ma button() tra ve, khong chi btn/btnTxt.
      -- applyBtn() can them fill/w/h de doi BE DAY VIEN -- vut chung di
      -- thi ba trang thai nut trong y het nhau, va do la loi da ship:
      -- xay dung xong ca he ba muc ma tren man hinh khong doi gi.
      if b ~= nil then
        f.btn, f.btnTxt = b.btn, b.txt
        f.fill, f.w, f.h = b.fill, b.w, b.h
      end

      f.note = text("CharFNote", f.root, 0.010, noteY, fw - 0.020,
                      CFG.PANEL_SCALE_SUB, false)
    end
    st.focus = f
  end

  -- ----- Than kieu "grid" -----
  if GRID_SLOTS ~= nil and GRID_ROWS > 0 then
    local g  = { cell = {}, stat = {} }
    local fw = W - 2 * P

    -- Chia doi be ngang: luoi o ben trai, bang thong ke ben phai. Bang
    -- rong 0.74 nen xep doc het thi thua ngang va thieu doc -- ma thieu
    -- doc thi CA BON the cung cao len theo (bodyH lay max).
    -- Luoi chiem bao nhieu phan be ngang. Nam cot thi moi cot hep lai,
    -- ma nut "FORGE  1" van phai vua -- nen phan cho luoi rong hon ban
    -- ba cot. Bang thong ke ben phai con thua cho.
    local dollW = fw * 0.70
    local colW  = dollW / GRID_COLS
    local btnW  = colW - 0.016
    if btnW > 0.132 then btnW = 0.132 end   -- du cho "TIEN GIAI  10"

    -- HOP CHUA cua luoi. Kieu "FRAME" la mot hop VO HINH, dung de gom
    -- con lai mot cho -- nhung khong phai ban Warcraft nao cung tao
    -- duoc no bang BlzCreateFrameByType.
    --
    -- Thieu cai hop nay thi CA THE trong ron: refresh() da tat het dong
    -- cua kieu "list" roi, ma luoi thi khong ve duoc. Nen phai co duong
    -- lui, va duong lui la "BACKDROP" -- kieu ma file nay dung khap noi
    -- nen chac chan tao duoc. No co ve ra mot o mau, nhung mot o mau
    -- lam nen thi van hon mot bang trong.
    g.root = BlzCreateFrameByType("FRAME", "CharGrid", st.panel, "", pid)
    if g.root == nil then
      -- Khong frameDead cai nay: xem chu thich o duong lui cua "focus".
      g.root = BlzCreateFrameByType("BACKDROP", "CharGrid", st.panel, "", pid)
      if g.root ~= nil and BlzFrameSetTexture ~= nil then
        BlzFrameSetTexture(g.root, CFG.PANEL_GRID_TEX or CFG.FRAME_BG, 0, true)
      end
      API.trace("panel: kieu FRAME khong tao duoc -- luoi trang bi lui ve BACKDROP" ..
                " (duoc=" .. tostring(g.root ~= nil) .. ")")
    end
    if g.root == nil then
      API.trace("panel: KHONG dung duoc hop chua nao cho luoi trang bi")
    else
      BlzFrameSetSize(g.root, fw, bodyH())
      BlzFrameSetPoint(g.root, FRAMEPOINT_TOPLEFT, st.panel,
                       FRAMEPOINT_TOPLEFT, P, -top)
      show(g.root, false)

      -- O PET: cho danh san, chua he nao dung toi.
      --
      -- Ve NHU MOT O THAT (vien + ruot) chu khong bo trong: mot cho
      -- trong giua luoi trong nhu loi ve, con mot o co vien va chu mo
      -- thi doc ra ngay la "cho nay se co thu gi".
      --
      -- Khong co nut. Khong bam duoc. Do la khac biet duy nhat.
      -- Ve Y HET mot o that: cung o vuong bang icon, cung cho trong cot.
      -- Khac dung mot thu -- khong co nut.
      --
      -- Ban truoc ve mot hop to bang ca o va nhet chu vao, nen no khong
      -- thang hang voi day icon ben canh. Lay LAI dung phep tinh cua o
      -- thuong (ix = cx + (colW - ICON()) * 0.5) thi khong the lech.
      --
      -- Chu can giua bang CENTER-toi-CENTER, giong cach button() can
      -- nhan cua no. Can bang toa do thi phai biet be ngang chu, ma
      -- Warcraft khong co native nao do duoc be ngang mot chuoi -- ban
      -- truoc doan, va chu dat han sang mep phai.
      -- ---------- COT GIUA: LY LICH HERO ----------
      --
      -- Ban truoc cho nay la bong nguoi (CFG.GEAR_SILHOUETTE). Doi vi
      -- moi o da co icon that roi -- bong nguoi chi noi lai dieu icon
      -- da noi. Doi lai, cot giua gio TRA LOI MOT CAU HOI CO THAT.
      --
      -- Dieu kien Tien Hoa la cultRank >= tier + 1. Muon biet "vi sao
      -- Khien cua toi chua len canh gioi duoc" thi phai nho Tu Vi minh
      -- dang o dau -- truoc day phai doi sang the I de xem. Dat ngay
      -- giua luoi thi nut "CHO Kim Dan" ben canh doc ra nghia ngay.
      --
      -- Icon lay tu CFG.HEROES -- ba duong DA CHUNG MINH ve ra hinh,
      -- dang dung o bang chon tuong. Khong them anh, khong them muc
      -- trong war3map.imp, khong co cua doan sai duong dan.
      local dollCol = CFG.GEAR_DOLL_COL
      if dollCol ~= nil and GRID_ROWS >= 4 then
        local dx = (dollCol - 1) * colW + 0.006
        local dw = colW - 0.012
        local dh = 3 * rowStep() - CELL_GAP      -- ba hang tren
        g.doll = backdropFrame("CharDollBg", dx, 0.0, dw, dh,
                               CFG.PANEL_GRID_TEX, g.root)

        -- Icon KHONG lap day cot: 64x64 phong len 0.1375 la 3.9 lan,
        -- nhin ra be. 0.090 la 2.5 lan -- doi mot phan dien tich lay do
        -- net, va phan thua de chu ganh.
        local iw = CFG.GEAR_DOLL_ICON or 0.090
        local blockH = iw + 0.008 + 0.016 + 0.004 + 0.016
        local top = (dh - blockH) * 0.5
        g.dollIcon = backdropFrame("CharDollIcon",
                                   dx + (dw - iw) * 0.5, top, iw, iw,
                                   nil, g.root)
        -- CAN GIUA bang CENTER-toi-CENTER, khong dung text().
        --
        -- text() co tham so thu 7 la 'right' (can phai) chu KHONG co
        -- can giua -- truyen false thi no bam mep TRAI. Da dinh mot lan
        -- o chu "Pet", va lai dinh o day.
        --
        -- Neo vao khung nen g.doll roi day xuong bang offset: can bang
        -- toa do thi phai biet be ngang chuoi, ma Warcraft khong co
        -- native nao do duoc.
        local function mid(name, dy, scale)
          local t = BlzCreateFrameByType("TEXT", name, g.root, "", pid)
          if t == nil then return nil end
          BlzFrameSetPoint(t, FRAMEPOINT_CENTER, g.doll,
                           FRAMEPOINT_CENTER, 0.0, -(dy - dh * 0.5))
          API.frameScale(t, scale)
          API.frameDead(t)
          return t
        end
        g.dollName = mid("CharDollName", top + iw + 0.008 + 0.008,
                         CFG.PANEL_SCALE_NAME)
        g.dollRank = mid("CharDollRank", top + iw + 0.008 + 0.020 + 0.008,
                         CFG.PANEL_SCALE_SUB)
      end

      -- ---------- O PET ----------
      -- Ve Y HET mot o that: cung o vuong bang icon, cung cho trong cot.
      -- Khac dung mot thu -- khong co nut.
      local pet = CFG.GEAR_PET_SLOT
      if pet ~= nil then
        local pd  = CFG.PANEL_BTN_BORDER or 0.0016
        local pcx = (pet[1] - 1) * colW
        local pcy = (pet[2] - 1) * rowStep()
        local pix = pcx + (colW - ICON()) * 0.5
        g.petEdge = backdropFrame("CharGridPetEdge", pix - pd, pcy - pd,
                                  ICON() + 2 * pd, ICON() + 2 * pd,
                                  CFG.PANEL_BTN_EDGE, g.root)
        g.petFill = backdropFrame("CharGridPetFill", pix, pcy,
                                  ICON(), ICON(),
                                  CFG.PANEL_GRID_TEX, g.root)
        if g.petFill ~= nil then
          g.petTxt = BlzCreateFrameByType("TEXT", "CharGridPetTxt",
                                          g.root, "", pid)
          if g.petTxt ~= nil then
            BlzFrameSetPoint(g.petTxt, FRAMEPOINT_CENTER, g.petFill,
                             FRAMEPOINT_CENTER, 0.0, 0.0)
            BlzFrameSetText(g.petTxt,
                            CFG.C_GREY .. API.t("gear_pet") .. CFG.C_END)
            BlzFrameSetVisible(g.petTxt, false)
            API.frameDead(g.petTxt)
          end
        end
      end

      -- ---------- O TICH "luyen gop / luyen le" ----------
      -- Ngoi o khe NUT cua o Pet, tuc dung hang voi tam nut kia. No doi
      -- nhan cua CA TAM nut cung luc, nen phai nam trong dam nut do chu
      -- khong nep ra ria.
      --
      -- Trang thai cua no la UI CUC BO, khong dong bo: xem tabToggle o
      -- 5_gear.lua.
      if GRID_TOGGLE ~= nil then
        local tcx = (GRID_TOGGLE[1] - 1) * colW
        local tcy = (GRID_TOGGLE[2] - 1) * rowStep() + ICON() + 0.004
        g.toggle = button("CharGridToggle", "",
                          tcx + (colW - btnW) * 0.5, tcy,
                          btnW, BTN_H(), g.root)
      end

      local d = CFG.PANEL_BTN_BORDER or 0.0016
      for i = 1, #GRID_SLOTS do
        local col, row = GRID_SLOTS[i][1], GRID_SLOTS[i][2]
        local cx = (col - 1) * colW
        local cy = (row - 1) * rowStep()
        local ix = cx + (colW - ICON()) * 0.5
        local c  = {}

        -- Vien quanh icon, cung cach nut tu ve vien: hai o mau long nhau.
        c.edge = backdropFrame("CharGridEdge" .. i, ix - d, cy - d,
                               ICON() + 2 * d, ICON() + 2 * d,
                               CFG.PANEL_BTN_EDGE, g.root)
        c.icon = backdropFrame("CharGridIcon" .. i, ix, cy,
                               ICON(), ICON(), nil, g.root)

        local by = cy + ICON() + 0.004
        local b = button("CharGridBtn" .. i, "", cx + (colW - btnW) * 0.5,
                         by, btnW, BTN_H(), g.root)
        -- GIU CA BANG ma button() tra ve, khong chi btn/btnTxt.
        -- applyBtn() can them fill/w/h de doi BE DAY VIEN -- vut chung di
        -- thi ba trang thai nut trong y het nhau, va do la loi da ship:
        -- xay dung xong ca he ba muc ma tren man hinh khong doi gi.
        if b ~= nil then
          c.btn, c.btnTxt = b.btn, b.txt
          c.fill, c.w, c.h = b.fill, b.w, b.h
        end

        -- Dong chu DUNG CHO NUT khi mon nay khong bam duoc gi.
        --
        -- O trong khong loi giai thich thi nguoi choi tuong giao dien
        -- hong -- kieu "list" cu da co cho nay (it.desc), luoi o thi
        -- khong, nen phai lam lai.
        c.note = text("CharGridNote" .. i, g.root, cx, by + 0.004, colW,
                      CFG.PANEL_SCALE_SUB, false)

        -- NHAN CAP tren icon: mon nay dang o cap may.
        --
        -- LOI DA SHIP: ca luoi chi co icon va NUT, ma nut ghi GIA
        -- ("FORGE Hoan Hao  15") chu khong ghi TRANG THAI. Tam o trong y
        -- het nhau, nen nguoi choi khong doc ra mon nao da luyen toi dau
        -- -- phai suy nguoc tu con so tien, hoac liec sang bang ben phai
        -- ma bang do thi de sot.
        --
        -- PHU LEN icon chu khong them mot hang: them hang thi cellH() to
        -- ra, ma bodyH() lay max nen CA BON the cung cao len theo -- va
        -- bang thi vua bi che la nhieu mang den qua.
        --
        -- Noi dung nhan do 5_gear.lua quyet dinh ("33/100"). O day chi
        -- lo CHO DAT: icon rong 0.036 (~74px), o scale 0.70 vua khoang
        -- 10 ky tu -- du cho mot phan so, khong du cho mot ten cap.
        local tagH = 0.010
        local ty   = cy + ICON() - tagH
        c.tagBg = backdropFrame("CharGridTagBg" .. i, ix, ty,
                                ICON(), tagH, CFG.PANEL_GRID_TEX, g.root)
        if c.tagBg ~= nil then
          -- CAN GIUA bang CENTER-toi-CENTER: text() khong can giua duoc
          -- (tham so thu 7 la 'right'), va Warcraft khong co native nao
          -- do be ngang chuoi de tu tinh. Cung cach mid() lam o cot giua.
          local t = BlzCreateFrameByType("TEXT", "CharGridTag" .. i,
                                         g.root, "", pid)
          if t ~= nil then
            BlzFrameSetPoint(t, FRAMEPOINT_CENTER, c.tagBg,
                             FRAMEPOINT_CENTER, 0.0, 0.0)
            API.frameScale(t, 0.70)
            API.frameDead(t)
            c.tag = t
          end
        end

        -- LOP NHAY: phu len icon, thuong xuyen AN. Tao SAU icon de no
        -- nam TREN -- thu tu tao chinh la thu tu ve. Tao sau ca nhan cap
        -- nen luc nhay no phu kin ca nhan, dung y muon.
        c.flash = backdropFrame("CharGridFlash" .. i, ix - d, cy - d,
                                ICON() + 2 * d, ICON() + 2 * d,
                                CFG.PANEL_FLASH_OK, g.root)

        show(c.edge, false); show(c.icon, false)
        show(c.btn, false); show(c.note, false)
        show(c.tagBg, false); show(c.tag, false)
        g.cell[i] = c
      end

      -- Bang thong ke ben phai: mot dong moi mon.
      local sx = dollW + 0.014
      local sw = fw - sx
      g.statHead = text("CharGridSH", g.root, sx, 0.0, sw,
                        CFG.PANEL_SCALE_NAME, false)
      for i = 1, #GRID_SLOTS do
        local y = 0.026 + (i - 1) * 0.020
        g.stat[i] = {
          alt = (CFG.PANEL_GRID and i % 2 == 0)
                and backdropFrame("CharGridSA" .. i, sx - 0.004, y - 0.003,
                                  sw, 0.019, CFG.PANEL_GRID_TEX, g.root) or nil,
          -- 60/40 VA SO CAN TRAI.
          --
          -- Ban truoc 42/58 va so can PHAI: so bi ep sat mep phai cua o
          -- 204px trong khi no chi dai 55px -- ra mot khoang trong 150px
          -- giua ten va chi so cua chinh no.
          --
          -- Do lai voi chu DAI NHAT that su ("Necklace - Exalted" 164px
          -- + "-25.0% attack damage taken" 237px = 402px) thi ca hai
          -- KHONG vua trong 352px du chia the nao -- nen chuoi bonus da
          -- rut ngan o 6_i18n.lua. Cau day du van con cho o it.desc cua
          -- kieu than "list", noi rong ca bang.
          lbl = text("CharGridSL" .. i, g.root, sx, y, sw * 0.58,
                     CFG.PANEL_SCALE_STAT, false),
          val = text("CharGridSV" .. i, g.root, sx + sw * 0.58, y,
                     sw * 0.42, CFG.PANEL_SCALE_STAT, false),
        }
      end
    end
    st.grid = g
  end

  BlzFrameSetVisible(st.panel, false)
  API.trace("panel: dung bang pid " .. pid .. " (" .. n .. " the, " ..
            MAX_ITEMS .. " dong, luoi " .. GRID_COLS .. "x" .. GRID_ROWS ..
            ", nen = " .. tostring(how) .. ")")
  return true
end

-- Boc pcall quanh buildBody(): loi Lua trong callback cua Warcraft khong in ra
-- dau ca, nen khong boc thi mot dong sai o giua bien thanh "bam phim ra
-- cai hop rong" -- khong manh moi nao.
--
-- Hong thi DON RAC. Backdrop da tao la da HIEN; de lai thi nguoi choi
-- co mot cai hop khong dong duoc, va moi lan bam lai them mot cai.
local function build(pid)
  local ok, res = pcall(buildBody, pid)
  if ok and res ~= false then return res end

  API.trace("panel: DUNG BANG LOI -- " .. tostring(res))
  API.warn(pid, "panel: dung bang loi, xem file vet.")

  local st = stateOf(pid)
  if st ~= nil and st.panel ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.panel)
  end
  if st ~= nil then st.panel = nil end
  return false
end

local function setShown(pid, want)
  if not framesAvailable() then
    API.msg(pid, CFG.C_RED .. API.t("panel_noframe") .. CFG.C_END)
    return
  end
  if not build(pid) then return end

  -- HAI BANG LOAI TRU NHAU: chong len nhau thi ESC phai doan dong cai
  -- nao, ma cau hoi do khong co dap an dung.
  if want and API.gameFrameHide ~= nil then API.gameFrameHide(pid) end

  local st = stateOf(pid)
  st.shown = want
  refresh(pid)

  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    if st.shown then
      -- Don khung chat khi MO bang.
      --
      -- Frame tu tao deu la con cua ORIGIN_FRAME_GAME_UI, ma khung chat
      -- cua Warcraft ve DE LEN lop do -- khong co cach nao dua backdrop
      -- len tren no, nen "lam overlay day hon" khong giai duoc gi.
      --
      -- ClearTextMessages() la native CHI dung giao dien, khong doi
      -- trang thai nao -- goi trong nhanh cuc bo nay la an toan.
      if ClearTextMessages ~= nil then ClearTextMessages() end
    end
    BlzFrameSetVisible(st.panel, st.shown)
  end
end

local function toggle(pid)
  setShown(pid, not stateOf(pid).shown)
end

local function openTab(pid, index)
  local st = stateOf(pid)
  if S.panel.tabs[index] == nil then return end
  st.tab = index
  setShown(pid, true)
end

-- ---------- Su kien ----------

-- Tra ban phim ve cho game sau moi cu bam.
--
-- LOI THAT: bam vao mot the roi bam ESC thi bang khong dong. Bam ra
-- ngoai mot cai roi ESC thi lai duoc.
--
-- Nguyen nhan: GLUEBUTTON GIU TIEU DIEM ban phim sau khi duoc bam. Frame
-- dang giu tieu diem nuot het phim, nen ca
-- BlzTriggerRegisterPlayerKeyEvent lan EVENT_PLAYER_END_CINEMATIC deu
-- khong no. Bam ra cho khac la mat tieu diem, nen ESC lai chay -- dung
-- kieu "luc duoc luc khong" ma anh chup khong the hien.
--
-- Tat roi bat lai la cach tra tieu diem o ban 1.31. Nut nao gui duoc cu
-- bam thi von da dang bat, nen bat lai luon dung trang thai; va cac
-- duong ben duoi deu goi refresh() ngay sau do, refresh dat lai trang
-- thai bat/tat theo du tien hay khong.
local function releaseFocus(f)
  if f == nil or BlzFrameSetEnable == nil then return end
  BlzFrameSetEnable(f, false)
  BlzFrameSetEnable(f, true)
end

local function onClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end
  releaseFocus(f)

  for pid, st in pairs(S.panel.byPid) do
    if GetLocalPlayer() == Player(pid) then
      local tab = S.panel.tabs[st.tab]

      if st.focus ~= nil and f == st.focus.btn then
        if tab ~= nil and tab.action ~= nil then tab.action(pid) end
        return
      end

      for i = 1, #st.tabBtn do
        if st.tabBtn[i] ~= nil and f == st.tabBtn[i].btn then
          st.tab = i
          refresh(pid)
          return
        end
      end

      if st.grid ~= nil and st.grid.toggle ~= nil
         and f == st.grid.toggle.btn then
        if tab ~= nil and tab.toggleAction ~= nil then tab.toggleAction(pid) end
        refresh(pid)
        return
      end

      if st.grid ~= nil then
        for i = 1, #st.grid.cell do
          local c = st.grid.cell[i]
          if c ~= nil and f == c.btn then
            if tab ~= nil and tab.itemAction ~= nil then tab.itemAction(pid, i) end
            return
          end
        end
      end

      for i = 1, MAX_ITEMS do
        local w = st.item[i]
        if w ~= nil and f == w.btn then
          if tab ~= nil and tab.itemAction ~= nil then tab.itemAction(pid, i) end
          return
        end
      end
    end
  end
end

-- Phim E. Su kien phim la cuc bo, nhung mo/dong bang cung la UI thuan
-- nen khong can dong bo.
-- Phim mo bang. Doi E -> R: E da thanh phim tat cua Bat Hoai (ky nang
-- chu dong thu ba), va mot phim khong the vua bam skill vua mo bang.
-- ESC dong bang. HAI duong dang ky, khong mot:
--
--   OSKEY_ESCAPE                  co tu 1.31, nhung la duong moi
--   EVENT_PLAYER_END_CINEMATIC    duong co dien: Warcraft ban su kien
--                                 nay moi lan ai do bam ESC
--
-- Dang ky ca hai roi de hide() tu chan lan thu hai -- re hon nhieu so
-- voi viec doan xem ban nay nhan duong nao, va do chinh la kieu doan da
-- lam hong he dong bo mot lan (ADR 0012).
local function bindEsc()
  local n = 0
  local t = CreateTrigger()

  local esc = _G["OSKEY_ESCAPE"]
  if BlzTriggerRegisterPlayerKeyEvent ~= nil and esc ~= nil then
    for i = 1, #S.pids do
      BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), esc, 0, true)
    end
    n = n + 1
  end

  if TriggerRegisterPlayerEvent ~= nil and EVENT_PLAYER_END_CINEMATIC ~= nil then
    for i = 1, #S.pids do
      TriggerRegisterPlayerEvent(t, Player(S.pids[i]), EVENT_PLAYER_END_CINEMATIC)
    end
    n = n + 1
  end

  -- Khong con phim chu thi ESC phai BAT/TAT, neu khong thi khong con
  -- duong nao MO bang ngoai lenh chat "-c".
  --
  -- Con phim chu thi ESC chi TAT: luc do bam ESC de huy chon quan ma
  -- bang bat len la mot cai bay nho dat dung cho ai cung bam theo phan
  -- xa.
  local canToggle = (CFG.PANEL_KEY == nil)

  -- CHAN LAN NO THU HAI.
  --
  -- Hai duong dang ky o tren nam tren CUNG MOT trigger, nen mot lan bam
  -- ESC no HAI lan. Hoi ESC con la chi-tat thi vo hai: lan hai goi
  -- hide() tren mot bang da dong. Tu luc no thanh bat/tat thi lan hai
  -- HUY lan mot -- bang mo ra roi dong ngay trong cung mot khung hinh,
  -- nhin y het nhu ESC khong lam gi ca.
  --
  -- Do do duoc: file vet ghi "ESC dang ky qua 2 duong".
  --
  -- Van giu ca hai duong dang ky chu khong bo bot mot: khong ai biet
  -- ban sau con du ca hai khong, va chan trung o day re hon la doan.
  local escLock = {}
  TriggerAddAction(t, function()
    local pid = GetPlayerId(GetTriggerPlayer())
    if escLock[pid] then return end
    -- HAI KHUNG MODAL, ESC khong dong duoc cai nao, va cung khong mo
    -- bang nhan vat de len tren chung. Phai xong viec moi di tiep.
    --
    -- Bang chon hero tung KHONG co mat o day: bam ESC luc dang chon
    -- hero la bang nhan vat mo de len, con bang chon hero nam ket phia
    -- sau -- khong bam duoc ma cung khong dong duoc.
    if API.heroFrameShown ~= nil and API.heroFrameShown(pid) then return end
    if API.fortuneFrameShown ~= nil and API.fortuneFrameShown(pid) then return end
    escLock[pid] = true
    API.after(CFG.PANEL_ESC_LOCK or 0.25, function() escLock[pid] = nil end)

    -- BON TANG, va thu tu hoi CHINH LA thu tu uu tien:
    --   chon hero -> da chan o tren, ESC khong lam gi
    --   Co Duyen  -> da chan o tren, ESC khong lam gi
    --   bang R    -> dong no, dung
    --   bang ESC  -> dong no, dung
    --   khong gi  -> mo bang ESC
    --
    -- Hoi bang R TRUOC bang nay. Dao lai thi mo R roi bam ESC se di vao
    -- nhanh "bang nay dang dong -> mo no ra", va bang R nam li.
    if API.gameFrameShown ~= nil and API.gameFrameShown(pid) then
      API.gameFrameHide(pid)
      return
    end

    if stateOf(pid).shown then hide(pid)
    elseif canToggle then toggle(pid) end
  end)

  API.trace("panel: ESC dang ky qua " .. n .. " duong")
  return n > 0
end

local function bindKey()
  local name = CFG.PANEL_KEY
  if name == nil then
    API.trace("panel: khong gan phim chu (CFG.PANEL_KEY = nil), chi ESC")
    return false
  end
  local key = _G["OSKEY_" .. name]
  if BlzTriggerRegisterPlayerKeyEvent == nil or key == nil then
    API.trace("panel: KHONG co BlzTriggerRegisterPlayerKeyEvent/OSKEY_" ..
              name .. " -- chi con -c")
    return false
  end
  local t = CreateTrigger()
  for i = 1, #S.pids do
    BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), key, 0, true)
  end
  TriggerAddAction(t, function() toggle(GetPlayerId(GetTriggerPlayer())) end)
  API.trace("panel: da gan phim " .. name)
  return true
end

local function startPanel()
  -- So dong dung san = the dai nhat. Tinh o day chu khong go tay: them
  -- mot he 9 muc thi bang tu rong ra, khong phai nho sua hang so.
  for i = 1, #S.panel.tabs do
    local t = S.panel.tabs[i]
    if t.rows ~= nil and t.rows > MAX_ITEMS then MAX_ITEMS = t.rows end

    -- Kich thuoc luoi suy TU bang o cua the, khong go tay.
    if t.kind == "grid" and t.slots ~= nil then
      GRID_SLOTS = t.slots
      GRID_TOGGLE = t.toggleSlot
      if t.toggleSlot ~= nil then
        if t.toggleSlot[1] > GRID_COLS then GRID_COLS = t.toggleSlot[1] end
        if t.toggleSlot[2] > GRID_ROWS then GRID_ROWS = t.toggleSlot[2] end
      end
      for k = 1, #t.slots do
        local col, row = t.slots[k][1], t.slots[k][2]
        if col > GRID_COLS then GRID_COLS = col end
        if row > GRID_ROWS then GRID_ROWS = row end
      end
    end
  end

  S.panel.trig = CreateTrigger()
  TriggerAddAction(S.panel.trig, onClick)
  S.keyBound = bindKey()
  bindEsc()
  API.trace("panel: san sang, " .. #S.panel.tabs .. " the, " .. MAX_ITEMS ..
            " dong, phimE=" .. tostring(S.keyBound))
end

-- Ve lai bang cua MOI nguoi. Khong goi refresh(nil) duoc: stateOf se
-- gan S.panel.byPid[nil] va Lua no loi "table index is nil".
local function refreshAll()
  for i = 1, #S.pids do refresh(S.pids[i]) end
end

API.panelRefreshAll  = refreshAll
API.panelAddTab      = addTab
API.panelPlaceholder = placeholderTab
API.panelRefresh     = refresh
API.panelToggle      = toggle
API.panelHide        = hide
API.panelFlash       = panelFlash
API.panelGearFlash   = panelFlash   -- ten cu, giu cho 5_gear.lua
-- Ten cac the, theo dung thu tu va so La Ma dang hien.
--
-- De trang F9 doc duoc thay vi go tay mot danh sach roi de no cu -- do
-- la luat rieng cua 7_quest.lua ("noi dung SUY TU CFG"). Them mot the
-- moi la trang F9 tu co.
local function tabNames()
  local out = {}
  for i = 1, #S.panel.tabs do
    out[i] = (ROMAN[i] or i) .. ". " .. (S.panel.tabs[i].name or "?")
  end
  return out
end

API.panelTabNames    = tabNames
API.panelOpenTab     = openTab
API.startPanel       = startPanel
end
--#endregion 4_ui/1_panel.lua

--#region 4_ui/2_heroframe.lua
do
-- ============================================================
--  2_heroframe.lua  --  Bang chon hero: MOT COT MOI HERO
--
--  Dung khi CFG.HERO_PICK_MODE = "frame". Ba cot doc dat canh nhau,
--  moi cot mot hero, va MOT nut SELECT chung o duoi -- cung khuon voi
--  khung Co Duyen (5_fortuneframe.lua), khac o cho phai CHON roi moi
--  XAC NHAN.
--
--  NUT CHON NAM TRONG TUNG COT, khong phai mot nut chung o duoi.
--
--  Chon hero la viec KHONG LAM LAI DUOC (CFG.HERO_UNIQUE), nen the
--  khong duoc phep dinh chi vi mot cu cham. Nhung cach chua KHONG phai
--  la "chon truoc, xac nhan sau":
--
--  Trang thai "dang chon" song duoc bao lau thi do la bay nhieu thoi
--  gian de MAT no. Nguoi choi khac lay mot hero -> applyHeroPick goi
--  refreshOthers -> pickerShow -> buildPanel dung lai ca bang, va
--  destroyPanel xoa sach lua chon. Dang dua tay bam thi the nhay cho.
--  Khong sai -- applyHeroPick van chan dung -- nhung nguoi choi thay
--  "tu nhien mat", va do la loi giao dien that.
--
--  Nut rieng trong tung cot thi khong co trang thai nao de mat, ma van
--  chong duoc bam nham: phai trung dung cai nut chu khong phai cham vao
--  the la dinh.
--
--  So cot DOC TU danh sach hero con trong, khong go cung. Bang co ba
--  hero thi ba cot; them hero thu tu la bang tu chia lai.
--
--  DAY LA MODAL. Chua chon xong thi ESC khong mo duoc gi khac de len
--  tren -- cung luat voi khung Co Duyen, va bindEsc() trong 1_panel.lua
--  hoi API.heroFrameShown(pid) truoc tien. Truoc day no khong hoi, nen
--  bam ESC luc dang chon hero la bang nhan vat mo de len va bang chon
--  hero nam ket phia sau.
--
--  Cung hai rang buoc nhu 3_skillframe, va vi cung mot ly do:
--
--  1. Su kien bam frame CHI no tren may nguoi bam. Nen bam khong doi
--     trang thai -- no gui mot mau tin qua API.syncSend (3_sync.lua),
--     va moi may goi API.applyHeroPick khi nhan duoc. Lech may la bi da
--     ra khoi tran, khong phai loi hien thi.
--
--  2. Moi nguoi mot bang rieng. Lenh/timer chay tren moi may, nen mot
--     bang dung chung se bi nguoi thu hai huy mat.
--
--  Thieu native frame thi tu lui ve popup chu, khong sap.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local FRAME_OK = nil

local function checkNatives(list)
  local missing = {}
  for i = 1, #list do
    if _G[list[i]] == nil then missing[#missing + 1] = list[i] end
  end
  return missing
end

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  local missing = checkNatives({
    "BlzGetOriginFrame", "BlzCreateFrameByType", "BlzFrameSetPoint",
    "BlzFrameSetSize", "BlzFrameSetVisible", "BlzFrameSetTexture",
    "BlzTriggerRegisterFrameEvent", "BlzGetTriggerFrame",
  })
  FRAME_OK = (#missing == 0)
  if not FRAME_OK then
    API.trace("herocard: thieu native -- " .. table.concat(missing, " "))
  end
  return FRAME_OK
end

-- ---------- Hinh hoc ----------
--
-- Moi con so SUY RA tu co icon va co chu, khong go tay. Doi
-- CFG.CARD_SCALE_DESC mot cai ma phai sua bon hang so roi rac la kieu
-- loi bang phim E da dinh mot lan.

-- Doc tu CFG chu khong go o day: ba con so nay la num de chinh bo cuc,
-- va moi con so chinh duoc phai nam mot cho.
local function W()      return CFG.CARD_W end
local function GAP()    return CFG.CARD_GAP end
local function ICON_H() return CFG.CARD_ICON end
local BTN_H   = 0.026   -- nut CHON trong moi cot
local HEAD_H  = 0.030   -- dong tieu de
local DESC_N  = 3       -- so gach mo ta ve duoc trong mot cot

-- Le trong THAT = le + vien trang tri cua backdrop.
--
-- EscMenuBackdrop ve mot duong vien go day an vao mep trong. Dat chu o
-- dung PAD la no nam DE LEN vien do -- dung loi ma bang nhan vat
-- (PANEL_BORDER), the chon hero cu (CARD_BORDER) va khung Co Duyen da
-- dinh, moi cai mot lan.
local function P()
  return CFG.CARD_PAD + (CFG.CARD_BORDER or 0.0)
end

local function colW(n)
  if n < 1 then n = 1 end
  return (W() - 2 * P() - (n - 1) * GAP()) / n
end

-- Cao phan NOI DUNG cua mot cot: icon + ten + vai + DESC_N gach.
local function bodyH()
  local line = CFG.CARD_LINE
  return CFG.CARD_PAD + ICON_H() + 0.010      -- icon
       + line * CFG.CARD_SCALE_NAME + 0.004   -- ten
       + line + 0.006                         -- vai
       + DESC_N * (line + 0.003)              -- ba gach
end

-- Ca cot = noi dung + nut CHON o duoi.
local function colH()
  return bodyH() + 0.006 + BTN_H + CFG.CARD_PAD
end

local function frameH()
  return P() + HEAD_H + GAP() + colH() + P()
end

local function stateOf(pid)
  local hf = S.hframe
  if hf.byPid[pid] == nil then
    hf.byPid[pid] = { panel = nil, col = {}, map = {}, shown = false }
  end
  return hf.byPid[pid]
end

local function destroyPanel(pid)
  local st = stateOf(pid)
  if st.panel ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.panel)
  end
  st.panel = nil
  st.col   = {}
  st.map   = {}
  st.shown = false
end

local function hideFrame(pid)
  local st = stateOf(pid)
  if st.panel ~= nil and BlzFrameSetVisible ~= nil then
    BlzFrameSetVisible(st.panel, false)
  end
  st.shown = false
end

-- Bang nhan vat hoi ham nay truoc khi xu ly ESC.
local function isShown(pid)
  local hf = S.hframe
  if hf == nil or hf.byPid == nil then return false end
  local st = hf.byPid[pid]
  return st ~= nil and st.shown == true
end

-- ---------- Mot dong chu ----------

-- Neo TRAI vao mot o co be ngang THAT.
--
-- Phai dat be ngang: text frame khong co kich thuoc thi Warcraft can
-- giua no quanh diem neo, va chu dai thi tran deu ca hai ben. Co o roi
-- thi BlzFrameSetTextAlignment moi ep duoc.
--
-- CHIA cho ti le phong, CA TOA DO lan kich thuoc -- BlzFrameSetScale
-- phong luon khoang cach tu frame toi diem neo cua cha, nen frame dat
-- cach cha x se duoc ve o x * scale.
local function textLine(pid, parent, name, x, y, w, scale, center)
  local f = BlzCreateFrameByType("TEXT", name, parent, "", pid)
  if f == nil then return nil end
  local s = scale or 1.0
  BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, parent, FRAMEPOINT_TOPLEFT,
                   x / s, -(y / s))
  BlzFrameSetSize(f, w / s, CFG.CARD_LINE / s)
  if BlzFrameSetTextAlignment ~= nil
     and TEXT_JUSTIFY_TOP ~= nil and TEXT_JUSTIFY_CENTER ~= nil
     and TEXT_JUSTIFY_LEFT ~= nil then
    BlzFrameSetTextAlignment(f, TEXT_JUSTIFY_TOP,
      center and TEXT_JUSTIFY_CENTER or TEXT_JUSTIFY_LEFT)
  end
  API.frameScale(f, scale)
  API.frameDead(f)
  return f
end

-- ---------- Mot cot ----------
--
--        [icon]
--         Hart
--    Warrior - Tanker
--     Don quai dong
--     Chiu don khoe
--    Yeu truoc boss      <- gach cuoi luon la DIEM YEU, to do
local function buildCol(pid, parent, hero, x, cw)
  local c = {}
  local H = colH()
  local d = CFG.PANEL_BTN_BORDER or 0.0016

  -- COT KHONG PHAI LA NUT nua -- chi la mot cai khung. Bam vao than the
  -- khong lam gi ca; chi cai nut o duoi moi an. Do la phan chong bam
  -- nham, va no re hon han mot buoc xac nhan rieng.
  --
  -- Vien + ruot: hai o mau dac long nhau. Backdrop 9 o (EscMenuBackdrop)
  -- co goc khong co lai theo frame nen khong dung duoc cho o nho. Chi
  -- hai texture TeamColor04/27 la DA CHUNG MINH ve ra hinh.
  local function plate(name, parentF, dx, dy, w2, h2, tex)
    local f = BlzCreateFrameByType("BACKDROP", name, parentF, "", pid)
    if f == nil then return nil end
    BlzFrameSetSize(f, w2, h2)
    BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT,
                     dx, -dy)
    BlzFrameSetTexture(f, tex, 0, true)
    API.frameDead(f)
    return f
  end

  c.root = plate("HeroColEdge", parent, x, P() + HEAD_H + GAP(), cw, H,
                 CFG.PANEL_BTN_EDGE)
  if c.root == nil then return nil end
  plate("HeroColFill", c.root, d, d, cw - 2 * d, H - 2 * d,
        CFG.PANEL_BTN_FILL)

  if hero.icon ~= nil then
    local ic = BlzCreateFrameByType("BACKDROP", "HeroColIcon", c.root, "", pid)
    if ic ~= nil then
      BlzFrameSetSize(ic, ICON_H(), ICON_H())
      BlzFrameSetPoint(ic, FRAMEPOINT_TOP, c.root, FRAMEPOINT_TOP,
                       0.0, -CFG.CARD_PAD)
      BlzFrameSetTexture(ic, hero.icon, 0, true)
      API.frameDead(ic)
    end
  end

  if BlzFrameSetText == nil then return c end

  local line = CFG.CARD_LINE
  local tw   = cw - 2 * 0.004
  local y    = CFG.CARD_PAD + ICON_H() + 0.010

  local nm = textLine(pid, c.root, "HeroColName", 0.004, y, tw,
                      CFG.CARD_SCALE_NAME, true)
  BlzFrameSetText(nm, CFG.C_GOLD .. hero.name .. CFG.C_END)
  y = y + line * CFG.CARD_SCALE_NAME + 0.004

  if hero.role ~= nil then
    local r = textLine(pid, c.root, "HeroColRole", 0.004, y, tw,
                       CFG.CARD_SCALE_DESC, true)
    BlzFrameSetText(r, CFG.C_GREY .. hero.role .. CFG.C_END)
  end
  y = y + line + 0.006

  -- MOT GACH MOT DONG. Cot hep nen noi ba gach lam mot dong la tran ra
  -- ngoai -- text frame cua Warcraft KHONG tu xuong dong, chu thua chi
  -- de len cot ben canh.
  --
  -- Gach cuoi luon la diem yeu nen to do: do la thu duy nhat lam nguoi
  -- choi phai nghi xem nen chon con nao.
  local list = (API.lang() == "en" and hero.desc_en) or hero.desc_vi
  if list ~= nil then
    for i = 1, DESC_N do
      local txt = list[i]
      if txt ~= nil then
        local color = (i == #list) and CFG.C_RED or CFG.C_JADE
        local f = textLine(pid, c.root, "HeroColDesc" .. i, 0.004, y, tw,
                           CFG.CARD_SCALE_DESC, true)
        BlzFrameSetText(f, color .. txt .. CFG.C_END)
      end
      y = y + line + 0.003
    end
  end

  -- ---------- Nut CHON cua rieng cot nay ----------
  --
  -- NEO VAO BANG, KHONG vao c.root. c.root la mot o trang tri, ma moi o
  -- trang tri deu di qua frameDead() -- tuc BlzFrameSetEnable(f, false).
  -- Nut nam trong mot frame da bi TAT thi khong nhan duoc cu bam nao:
  -- nhin thi day du, bam thi chet lang.
  --
  -- Da dinh that o ban truoc: ba cot ve ra dep, nut CHON khong an.
  local bw = cw - 2 * CFG.CARD_PAD
  c.btn = BlzCreateFrameByType("GLUEBUTTON", "HeroColBtn", parent,
                               CFG.CARD_BUTTON_TEMPLATE, pid)
  if c.btn == nil then return c end
  BlzFrameSetSize(c.btn, bw, BTN_H)
  BlzFrameSetPoint(c.btn, FRAMEPOINT_TOPLEFT, parent, FRAMEPOINT_TOPLEFT,
                   x + CFG.CARD_PAD,
                   -(P() + HEAD_H + GAP() + bodyH() + 0.006))

  plate("HeroBtnEdge", c.btn, 0.0, 0.0, bw, BTN_H, CFG.PANEL_BTN_EDGE)
  plate("HeroBtnFill", c.btn, d, d, bw - 2 * d, BTN_H - 2 * d,
        CFG.PANEL_BTN_FILL)

  local bt = textLine(pid, c.btn, "HeroColBtnTxt", 0.004,
                      (BTN_H - line) * 0.5, bw - 0.008,
                      CFG.CARD_SCALE_NAME, true)
  if bt ~= nil then
    BlzFrameSetText(bt, CFG.C_GOLD .. API.t("pick_select") .. CFG.C_END)
  end

  return c
end



-- ---------- Ca bang ----------

-- Chay tren MOI may. Bang dung giong het nhau khap noi; chi khac o chuyen
-- hien cho ai -- do la UI, khong phai trang thai game, nen dung
-- GetLocalPlayer o day la an toan.
local function buildPanel(pid, list)
  local st = stateOf(pid)
  destroyPanel(pid)
  st.list = list

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local n  = #list
  local cw = colW(n)

  local bg, how = API.backdrop(CFG.CARD_BACKDROP, parent, pid, CFG.FRAME_BG)
  st.panel = bg
  if st.panel == nil then return false end

  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.CARD_X, CFG.CARD_Y)
  BlzFrameSetSize(st.panel, W(), frameH())

  if BlzFrameSetText ~= nil then
    local t = textLine(pid, st.panel, "HeroPanelTitle", P(), P(),
                       W() - 2 * P(), CFG.CARD_SCALE_TITLE, true)
    if t ~= nil then
      BlzFrameSetText(t, CFG.C_GOLD .. API.t("pick_title") .. CFG.C_END)
    end
  end

  local made = 0
  for i = 1, n do
    local c = buildCol(pid, st.panel, list[i], P() + (i - 1) * (cw + GAP()), cw)
    if c ~= nil and c.btn ~= nil then
      BlzTriggerRegisterFrameEvent(S.hframe.trig, c.btn, FRAMEEVENT_CONTROL_CLICK)
      -- Ghi SO THU TU trong CFG.HEROES, khong phai id: kenh dong bo chi
      -- tai duoc so nho. Xem src/1_core/3_sync.lua.
      st.map[c.btn] = { pid = pid, idx = API.heroIndex(list[i].id) }
      st.col[i] = c
      made = made + 1
    end
  end

  API.trace("herocard: pid " .. pid .. " -- tao " .. made .. "/" .. n ..
            " cot, nen = " .. tostring(how))
  if made == 0 then
    API.warn(nil, "herocard: khong tao duoc cot nao -- thu doi " ..
      "CFG.CARD_BUTTON_TEMPLATE.")
    destroyPanel(pid)
    return false
  end

  st.shown = true
  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.panel, true)
  end
  return true
end

local function showFrame(pid)
  if not framesAvailable() then
    API.info(pid, CFG.C_GOLD .. "Bang chon hero khong ve duoc -- lui ve popup chu."
      .. CFG.C_END)
    return API.showPicker(pid)
  end

  local d = S.p[pid]
  if d == nil or not d.active then return false end
  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    hideFrame(pid)
    return false
  end

  local list = API.heroesAvailable()
  if #list == 0 then
    hideFrame(pid)
    API.msg(pid, CFG.C_RED .. API.t("pick_none") .. CFG.C_END)
    return false
  end

  return buildPanel(pid, list)
end

-- ---------- Bam ----------
--
-- CHI chay tren may nguoi bam.
local function onCardClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end

  -- Tra tieu diem ban phim NGAY. GLUEBUTTON giu tieu diem sau khi bam,
  -- va frame giu tieu diem thi nuot het phim.
  if BlzFrameSetEnable ~= nil then
    BlzFrameSetEnable(f, false); BlzFrameSetEnable(f, true)
  end

  for pid, st in pairs(S.hframe.byPid) do
    if GetLocalPlayer() == Player(pid) and st.shown then
      local pick = st.map[f]
      if pick ~= nil and pick.idx ~= nil then
        -- Khong doi gi o day. Chi bao cho moi may biet -- va
        -- applyHeroPick ben kia van kiem lai mot lan nua, vi hai nguoi
        -- co the bam cung mot con trong cung mot nhip.
        API.syncSend(pid, CFG.OP_HERO, pick.idx)
        return
      end
    end
  end
end

-- Chay tren MOI may, tu kenh dong bo. Day la cho duy nhat duoc phep doi
-- trang thai game.
local function onPicked(pid, idx)
  local h = CFG.HEROES[idx]
  if h == nil then return end
  API.applyHeroPick(pid, h.id)
end

local function startHeroFrame()
  S.hframe = { trig = nil, syncTrig = nil, byPid = {} }
  if CFG.HERO_PICK_MODE ~= "frame" then return end
  if not framesAvailable() then
    API.warn(nil, "Khong ve duoc bang chon hero tren ban nay -- " ..
      "se dung popup chu.")
    return
  end

  S.hframe.trig = CreateTrigger()
  TriggerAddAction(S.hframe.trig, onCardClick)

  API.syncOn(CFG.OP_HERO, onPicked)
  API.trace("herocard: trigger san sang, dong bo=" .. API.syncMode())
end

API.showHeroFrame  = showFrame
API.hideHeroFrame  = hideFrame
API.heroFrameShown = isShown
API.startHeroFrame = startHeroFrame
end
--#endregion 4_ui/2_heroframe.lua

--#region 4_ui/3_skillframe.lua
do
-- ============================================================
--  3_skillframe.lua  --  Giao dien chon ky nang tu ve
--
--  Dung khi CFG.SKILL_MODE = "frame". Ve bang icon bang
--  BlzCreateFrameByType -- khong can file .fdf/.toc, khong phai import
--  gi trong World Editor.
--
--  HAI DIEU QUYET DINH TOAN BO THIET KE FILE NAY:
--
--  1. Frame la giao dien THUAN CLIENT, nam ngoai mo phong. Su kien bam
--     CHI no tren may nguoi bam. Doi trang thai game ngay trong do thi
--     may do re nhanh khoi hai may kia -- Warcraft III chay lockstep,
--     lech la da nguoi choi ra.
--
--     Nen: bam -> chi gui mot mau tin qua API.syncSend. Moi may, ke ca
--     may nguoi bam, nhan duoc roi MOI doi trang thai. Cung mot thay
--     doi, cung mot thu tu, khong lech. Kenh do 3_sync.lua lo.
--
--     (Popup dialog o 07_heropick khong dinh loi nay: dialog la UI cap
--     game, cu bam di qua duong lenh dong bo san.)
--
--  2. Moi nguoi choi phai co BANG RIENG. Lenh chat chay tren moi may,
--     nen mot bang dung chung se bi nguoi thu hai huy mat khi ho cung
--     go -sp.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local FRAME_OK = nil   -- nil = chua kiem tra

local function checkNatives(list)
  local missing = {}
  for i = 1, #list do
    if list[i][2] == nil then missing[#missing + 1] = list[i][1] end
  end
  return missing
end

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  local missing = checkNatives({
    { "BlzGetOriginFrame",           BlzGetOriginFrame },
    { "BlzCreateFrameByType",        BlzCreateFrameByType },
    { "BlzFrameSetAbsPoint",         BlzFrameSetAbsPoint },
    { "BlzFrameSetPoint",            BlzFrameSetPoint },
    { "BlzFrameSetAllPoints",        BlzFrameSetAllPoints },
    { "BlzFrameSetSize",             BlzFrameSetSize },
    { "BlzFrameSetTexture",          BlzFrameSetTexture },
    { "BlzFrameSetVisible",          BlzFrameSetVisible },
    { "BlzTriggerRegisterFrameEvent", BlzTriggerRegisterFrameEvent },
    { "BlzGetTriggerFrame",          BlzGetTriggerFrame },
    { "ORIGIN_FRAME_GAME_UI",        ORIGIN_FRAME_GAME_UI },
    { "FRAMEEVENT_CONTROL_CLICK",    FRAMEEVENT_CONTROL_CLICK },
    { "FRAMEPOINT_CENTER",           FRAMEPOINT_CENTER },
    { "FRAMEPOINT_LEFT",             FRAMEPOINT_LEFT },
  })
  FRAME_OK = (#missing == 0)
  if FRAME_OK then
    API.trace("frame: du native")
  else
    API.trace("frame: THIEU " .. table.concat(missing, " "))
    API.warn(nil, "Giao dien tu ve khong chay duoc -- thieu: " ..
      table.concat(missing, ", "))
  end
  return FRAME_OK
end

local function iconOf(choice)
  if choice.icon ~= nil then return choice.icon end
  if BlzGetAbilityIcon ~= nil then
    local p = BlzGetAbilityIcon(choice.id)
    if p ~= nil and p ~= "" then return p end
  end
  return nil
end

-- ---------- Bang rieng tung nguoi ----------

local function slotOf(pid)
  local sf = S.sframe
  if sf.byPid[pid] == nil then
    sf.byPid[pid] = { panel = nil, map = {}, slot = nil }
  end
  return sf.byPid[pid]
end

local function destroyPanel(pid)
  local st = slotOf(pid)
  if st.panel ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.panel)
  end
  st.panel = nil
  st.map = {}
end

local function hidePanel(pid)
  local st = slotOf(pid)
  if st.panel ~= nil then BlzFrameSetVisible(st.panel, false) end
end

local function nextSlotIndex(pid)
  local d = S.p[pid]
  local slots = API.slotsFor(pid)
  for i = 1, #slots do
    if d.slots[i] == nil then return i, slots end
  end
  return nil, slots
end

-- Chay tren MOI may. Bang duoc tao giong het nhau o khap noi; chi khac
-- o chuyen hien cho ai -- va do la UI, khong phai trang thai game, nen
-- dung GetLocalPlayer o day la an toan.
local function buildPanel(pid, slotIndex)
  local st = slotOf(pid)
  local slot = API.slotsFor(pid)[slotIndex]
  destroyPanel(pid)

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then
    API.warn(nil, "frame: khong lay duoc GAME_UI.")
    return false
  end

  st.panel = BlzCreateFrameByType("BACKDROP", "SkillPanel", parent, "", pid)
  if st.panel == nil then
    API.warn(nil, "frame: BlzCreateFrameByType tra ve nil.")
    return false
  end
  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.FRAME_X, CFG.FRAME_Y)
  BlzFrameSetSize(st.panel, CFG.FRAME_W, CFG.FRAME_H)
  BlzFrameSetTexture(st.panel, CFG.FRAME_BG, 0, true)

  if BlzFrameSetText ~= nil then
    local title = BlzCreateFrameByType("TEXT", "SkillTitle", st.panel, "", pid)
    if title ~= nil then
      BlzFrameSetPoint(title, FRAMEPOINT_CENTER, st.panel, FRAMEPOINT_CENTER,
                       0.0, CFG.FRAME_H * 0.36)
      BlzFrameSetText(title, slot.name or API.t("skill_slot_n", slotIndex))
      API.frameDead(title)
    end
  end

  local n = #slot.choices
  local step = CFG.FRAME_ICON + CFG.FRAME_GAP
  local startX = (CFG.FRAME_W - (n * CFG.FRAME_ICON + (n - 1) * CFG.FRAME_GAP)) * 0.5

  st.map = {}
  local made = 0
  for i = 1, n do
    local choice = slot.choices[i]
    local btn = BlzCreateFrameByType("GLUEBUTTON", "SkillBtn", st.panel,
                                     CFG.FRAME_BUTTON_TEMPLATE, pid)
    if btn ~= nil then
      BlzFrameSetSize(btn, CFG.FRAME_ICON, CFG.FRAME_ICON)
      BlzFrameSetPoint(btn, FRAMEPOINT_LEFT, st.panel, FRAMEPOINT_LEFT,
                       startX + (i - 1) * step, -CFG.FRAME_H * 0.08)

      local path = iconOf(choice)
      if path ~= nil then
        local ic = BlzCreateFrameByType("BACKDROP", "SkillIcon", btn, "", pid)
        if ic ~= nil then
          BlzFrameSetAllPoints(ic, btn)
          BlzFrameSetTexture(ic, path, 0, true)
          API.frameDead(ic)
        end
      end

      if BlzFrameSetTooltip == nil and BlzFrameSetText ~= nil then
        local lbl = BlzCreateFrameByType("TEXT", "SkillLbl", st.panel, "", pid)
        if lbl ~= nil then
          BlzFrameSetPoint(lbl, FRAMEPOINT_CENTER, btn, FRAMEPOINT_CENTER,
                           0.0, -CFG.FRAME_ICON * 0.75)
          BlzFrameSetText(lbl, choice.name)
          API.frameDead(lbl)
        end
      end

      BlzTriggerRegisterFrameEvent(S.sframe.trig, btn, FRAMEEVENT_CONTROL_CLICK)
      -- Ghi SO THU TU cua lua chon, khong phai id ability: kenh dong bo
      -- chi tai duoc so nho. Xem src/1_core/3_sync.lua.
      st.map[btn] = { pid = pid, slot = slotIndex, ci = i }
      made = made + 1
    end
  end

  API.trace("frame: pid " .. pid .. " slot " .. slotIndex ..
            " -- tao " .. made .. "/" .. n .. " nut")
  if made == 0 then
    API.warn(nil, "frame: khong tao duoc nut nao -- thu doi " ..
      "CFG.FRAME_BUTTON_TEMPLATE.")
    destroyPanel(pid)
    return false
  end

  st.slot = slotIndex
  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.panel, true)
  end
  return true
end

local function showFrame(pid)
  if not framesAvailable() then
    API.info(pid, CFG.C_GOLD .. "Lui ve popup chu." .. CFG.C_END)
    API.showSkillPicker(pid)
    return false
  end

  local d = S.p[pid]
  if d == nil or d.hero == nil then
    API.msg(pid, CFG.C_RED .. API.t("skill_nohero") .. CFG.C_END)
    return false
  end

  local si, slots = nextSlotIndex(pid)
  if #slots == 0 then
    API.msg(pid, CFG.C_RED .. API.t("skill_notree") .. CFG.C_END)
    return false
  end
  if si == nil then
    hidePanel(pid)
    API.msg(pid, CFG.C_GOLD .. API.t("skill_full", #slots) .. CFG.C_END)
    return false
  end

  return buildPanel(pid, si)
end

-- ---------- Ap dung lua chon ----------
-- Chay tren MOI may, tu su kien dong bo. Day la cho duy nhat duoc phep
-- doi trang thai game.
local function applyChoice(pid, slotIndex, aid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if slotIndex == nil or aid == nil then return end

  -- Bam hai lan truoc khi tin dong bo ve: lan thu hai bi chan o day.
  if d.slots[slotIndex] ~= nil then return end

  if not UnitAddAbility(d.hero, aid) then
    API.warn(pid, "Khong gan duoc ability " .. API.idToStr(aid) ..
      " -- id sai, hoac unit khong nhan duoc ability nay.")
    return
  end
  SetUnitAbilityLevel(d.hero, aid, 1)
  d.slots[slotIndex] = aid

  hidePanel(pid)
  local slots = API.slotsFor(pid)
  API.msg(nil, CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END ..
    " da hoc " .. CFG.C_JADE .. (slots[slotIndex].name or "?") .. CFG.C_END .. ".")

  if CFG.SKILL_PICK_CHAIN then showFrame(pid) end
end

-- ---------- Bam nut: CHI chay tren may nguoi bam ----------
local function onFrameClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end

  -- Nut cua nguoi nao thi chi nguoi do thay va bam duoc, nhung van tra
  -- lai cho chac -- xu ly cuc bo thi khong duoc phep doan.
  local hit = nil
  for pid, st in pairs(S.sframe.byPid) do
    if st.map[f] ~= nil then hit = st.map[f]; break end
  end
  if hit == nil then return end
  if GetLocalPlayer() ~= Player(hit.pid) then return end

  -- Khong doi gi o day. Chi bao cho moi may biet.
  API.syncSend(hit.pid, CFG.OP_SKILL, hit.slot * 100 + hit.ci)
end

-- Chay tren MOI may khi co ai gui tin.
local function onPicked(pid, arg)
  local slotIndex = math.floor(arg / 100)
  local ci        = arg - slotIndex * 100

  -- Cay skill lay tu hero dang cam, giong nhau tren moi may.
  local slot = API.slotsFor(pid)[slotIndex]
  if slot == nil or slot.choices[ci] == nil then return end

  applyChoice(pid, slotIndex, slot.choices[ci].id)
end

local function startSkillFrame()
  S.sframe = { trig = nil, syncTrig = nil, byPid = {} }
  if CFG.SKILL_MODE ~= "frame" then return end
  if not framesAvailable() then return end

  S.sframe.trig = CreateTrigger()
  TriggerAddAction(S.sframe.trig, onFrameClick)

  API.syncOn(CFG.OP_SKILL, onPicked)
  API.trace("frame: trigger san sang, dong bo=" .. API.syncMode())
end

API.showSkillFrame  = showFrame
API.startSkillFrame = startSkillFrame
API.framesAvailable = framesAvailable
end
--#endregion 4_ui/3_skillframe.lua

--#region 4_ui/4_fct.lua
do
-- ============================================================
--  4_fct.lua  --  Chu bay: sat thuong gay ra / nhan vao / linh khi
--
--  CAI BAY LON NHAT: Warcraft III chi cho khoang 100 text tag ton tai
--  cung luc. Mot wave co 50 con; ve mot chu moi don danh la trong vai
--  giay dat tran, va tu do KHONG CON chu nao hien nua -- ke ca chu quan
--  trong nhu "nha chinh sap chet".
--
--  Nen o day khong ve tung don. Sat thuong duoc CONG DON theo muc tieu
--  trong CFG.FCT_FLUSH giay, roi moi ve MOT chu -- va moi lan ve cung
--  chi ve toi da CFG.FCT_MAX_TAGS cai, uu tien con dau nhat.
--
--  Chu bay la UI thuan nen hien theo tung nguoi bang GetLocalPlayer --
--  an toan, khong dung toi trang thai game.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local EVT_OK = nil

local function eventsAvailable()
  if EVT_OK ~= nil then return EVT_OK end
  EVT_OK = (EVENT_PLAYER_UNIT_DAMAGED ~= nil and GetEventDamage ~= nil
        and GetEventDamageSource ~= nil and CreateTextTag ~= nil)
  if not EVT_OK then API.trace("fct: THIEU su kien sat thuong") end
  return EVT_OK
end

-- 1234 -> "1.2K", 1234567 -> "1.2M". Cuoi game sat thuong len hang van,
-- chu dai che mat man hinh.
local function short(n)
  n = math.floor(n + 0.5)
  if n >= 1000000 then return string.format("%.1fM", n / 1000000) end
  if n >= 1000    then return string.format("%.1fK", n / 1000) end
  return tostring(n)
end

-- Ve mot chu bay. pid = nil thi ai cung thay.
local function tag(x, y, text, r, g, b, pid, rise)
  local tt = CreateTextTag()
  if tt == nil then return end

  SetTextTagText(tt, text, CFG.FCT_SIZE)
  SetTextTagPos(tt, x, y, CFG.FCT_HEIGHT)
  SetTextTagColor(tt, r, g, b, 255)
  SetTextTagVelocity(tt, 0.0, (rise or CFG.FCT_RISE))
  SetTextTagPermanent(tt, false)
  SetTextTagLifespan(tt, CFG.FCT_LIFE)
  SetTextTagFadepoint(tt, CFG.FCT_LIFE * 0.5)

  if pid ~= nil then
    SetTextTagVisibility(tt, GetLocalPlayer() == Player(pid))
  end
end

-- ---------- Cong don ----------

local function keyOf(u) return u end

local function addPending(u, pid, amount, kind)
  local f = S.fct
  local k = keyOf(u)
  local e = f.pending[k]
  if e == nil then
    e = { u = u, pid = pid, dealt = 0.0, taken = 0.0 }
    f.pending[k] = e
    f.count = f.count + 1
  end
  if kind == "dealt" then e.dealt = e.dealt + amount
  else                    e.taken = e.taken + amount end
end

-- Ve toi da MAX_TAGS moi lan, uu tien con dau nhat. Phan con lai bi bo
-- -- co y: chu bay la phan hoi, khong phai so ke toan.
local function flush()
  local f = S.fct
  if f.count == 0 then return end

  local list = {}
  for _, e in pairs(f.pending) do list[#list + 1] = e end
  table.sort(list, function(a, b)
    return (a.dealt + a.taken) > (b.dealt + b.taken)
  end)

  local n = #list
  if n > CFG.FCT_MAX_TAGS then n = CFG.FCT_MAX_TAGS end

  for i = 1, n do
    local e = list[i]
    if e.u ~= nil and API.alive(e.u) then
      local x, y = GetUnitX(e.u), GetUnitY(e.u)
      if e.dealt > 0 then
        tag(x, y, short(e.dealt), 255, 230, 120, e.pid)
      end
      if e.taken > 0 then
        tag(x, y, "-" .. short(e.taken), 255, 90, 90, e.pid)
      end
    end
  end

  f.pending = {}
  f.count = 0
end

-- ---------- Su kien ----------

local function onDamage()
  if not CFG.FCT_ENABLED then return end

  local amount = GetEventDamage()
  if amount == nil or amount < CFG.FCT_MIN then return end

  local target = GetTriggerUnit()
  local source = GetEventDamageSource()
  if target == nil then return end

  -- NHA CHINH: ai cung thay (pid = nil).
  --
  -- Truoc day ham nay chi ve cho hero cua nguoi choi, nen ca tran danh
  -- quanh nha chinh dien ra khong mot con so nao -- thu quan trong nhat
  -- cua van lai la thu duy nhat khong co phan hoi.
  --
  -- Khong gan cho mot pid nao: nha chinh do la ca ba nguoi cung thua,
  -- nen mot nguoi thay so con hai nguoi kia khong thay la sai.
  if S.house ~= nil then
    if target == S.house then
      addPending(target, nil, amount, "taken")
      return
    end
    if source == S.house then
      addPending(target, nil, amount, "dealt")
      return
    end
  end

  -- Sat thuong hero cua nguoi choi NHAN VAO: ve tren dau hero, mau do.
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero == target then
      addPending(target, pid, amount, "taken")
      return
    end
  end

  -- Sat thuong hero GAY RA: ve tren dau muc tieu, mau vang.
  if source == nil then return end
  local spid = GetPlayerId(GetOwningPlayer(source))
  local sd = S.p[spid]
  if sd ~= nil and sd.hero == source then
    addPending(target, spid, amount, "dealt")
  end
end

-- Goi tu 04_player moi khi cong linh khi.
local function onQi(pid, amount)
  if not CFG.FCT_ENABLED or not CFG.FCT_SHOW_GOLD then return end
  if amount == nil or amount <= 0 then return end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  d.fctGold = (d.fctGold or 0) + amount
end

-- Linh khi cong don rieng: 50 con moi wave, ve tung dong la ngap man hinh.
local function flushGold()
  if not CFG.FCT_ENABLED or not CFG.FCT_SHOW_GOLD then return end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero ~= nil and (d.fctGold or 0) > 0 then
      if API.alive(d.hero) then
        tag(GetUnitX(d.hero), GetUnitY(d.hero), "+" .. short(d.fctGold),
            255, 215, 0, pid, CFG.FCT_RISE * 0.6)
      end
      d.fctGold = 0
    end
  end
end

local function startFct()
  S.fct = { pending = {}, count = 0 }
  if not CFG.FCT_ENABLED then return end
  if not eventsAvailable() then
    API.warn(nil, "Khong bat duoc su kien sat thuong -- tat chu bay.")
    return
  end

  local t = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(t, EVENT_PLAYER_UNIT_DAMAGED)
  TriggerAddAction(t, onDamage)

  S.fctTimer = CreateTimer()
  TimerStart(S.fctTimer, CFG.FCT_FLUSH, true, function()
    flush()
    flushGold()
  end)

  API.trace("fct: san sang, gom moi " .. CFG.FCT_FLUSH .. "s, toi da " ..
            CFG.FCT_MAX_TAGS .. " chu/lan")
end

API.fctOnQi = onQi
API.fctTag       = tag
API.startFct     = startFct
end
--#endregion 4_ui/4_fct.lua

--#region 4_ui/5_fortuneframe.lua
do
-- ============================================================
--  5_fortuneframe.lua  --  Khung Co Duyen: MOT COT MOI THE
--
--  Mo NGAY khi tinh anh/boss chet, khong phai mot the trong bang.
--  Cac cot dat canh nhau, moi cot mot the va MOT NUT SELECT ngay duoi.
--
--  VI SAO NUT RIENG, khong bam ca cot nhu truoc: chon the Co Duyen la
--  KHONG HOAN TAC duoc -- bam nham mot cai la mat ca luot. Ba cot sat
--  nhau va phu kin ca khung thi khong co cho nao de "bam hut"; mot nut
--  nho o duoi thi phai co y moi trung. Cung ly do voi bang chon hero.
--
--  SO COT DOC TU CFG.FORTUNE_DRAW, khong go cung. Be ngang khung giu
--  nguyen, cot tu chia lai -- them hay bot the khong phai sua file nay.
--
--  KHONG DONG BANG ESC. Phai chon mot the moi di tiep. Do la ly do
--  bindEsc() trong 1_panel.lua hoi API.fortuneFrameShown(pid) truoc khi
--  lam gi: neu khung nay dang mo thi ESC khong dong ma cung khong mo
--  bang nhan vat.
--
--  Khung nay khong sinh ngau nhien: the da duoc rut o 10_fortune.lua, tu
--  su kien quai chet, tren MOI may. O day chi VE lai thu da co.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local W      = 0.46     -- be ngang ca khung
local PAD    = 0.018
local GAP    = 0.010
local HEAD_H = 0.030    -- dong tieu de
-- The + nut = dung bang chieu cao cot cu (0.185), nen khung KHONG doi
-- kich thuoc: 0.153 + 0.006 + 0.026 = 0.185.
local COT_H  = 0.153    -- cao phan THE (trang tri)
local BTN_H  = 0.026    -- cao nut SELECT
local BTN_GAP = 0.006   -- khe giua the va nut
local BTN_PAD = 0.006   -- nut hep hon the moi ben bay nhieu
local ICON_H = 0.052

-- Le trong THAT = le + vien trang tri cua backdrop.
--
-- EscMenuBackdrop ve mot duong vien go day an vao mep trong. Dat tieu de
-- o dung PAD la no nam DE LEN vien do -- dung loi ma bang nhan vat
-- (CFG.PANEL_BORDER) va the chon hero (CFG.CARD_BORDER) da dinh, moi
-- cai mot lan.
local function P()
  return PAD + (CFG.PANEL_BORDER or 0.0)
end

-- So the mot luot. Doc moi lan chu khong nho: build() chay sau khi CFG
-- da nap xong, va giu mot ban sao cuc bo la mot cho nua co the lech.
local function nCol()
  -- SO THE RUT RA, khong phai so loai co san. Tu 2026-09-20 co BA loai
  -- ma chi rut HAI -- ve ba cot thi mot cot luon rong.
  local n = CFG.FORTUNE_DRAW or 0
  local avail = CFG.FORTUNE_KINDS and #CFG.FORTUNE_KINDS or 0
  if n <= 0 or n > avail then n = avail end
  return (n > 0) and n or 1
end

local function colW()
  local n = nCol()
  return (W - 2 * P() - (n - 1) * GAP) / n
end

local function frameH()
  return P() + HEAD_H + GAP + COT_H + BTN_GAP + BTN_H + P()
end

local function stateOf(pid)
  if S.fortuneUI == nil then S.fortuneUI = {} end
  if S.fortuneUI[pid] == nil then
    S.fortuneUI[pid] = { root = nil, col = {}, shown = false }
  end
  return S.fortuneUI[pid]
end

local function show(f, on)
  if f ~= nil then BlzFrameSetVisible(f, on) end
end

-- ---------- Dung khung ----------

local function build(pid)
  local st = stateOf(pid)
  if st.root ~= nil then return true end
  if BlzGetOriginFrame == nil or BlzCreateFrameByType == nil then return false end

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local bg = API.backdrop(CFG.PANEL_BACKDROP, parent, pid, CFG.FRAME_BG)
  if bg == nil then return false end
  st.root = bg
  BlzFrameSetAbsPoint(bg, FRAMEPOINT_CENTER, CFG.FORTUNE_X, CFG.FORTUNE_Y)
  BlzFrameSetSize(bg, W, frameH())

  -- Chu: chia ti le phong ca toa do lan kich thuoc -- cung bai hoc voi
  -- text() cua bang nhan vat, BlzFrameSetScale phong luon khoang cach
  -- toi diem neo cua cha.
  local function label(name, parent, dx, dy, w, scale, center)
    local t = BlzCreateFrameByType("TEXT", name, parent, "", pid)
    if t == nil then return nil end
    local s = scale or 1.0
    BlzFrameSetPoint(t, FRAMEPOINT_TOPLEFT, parent, FRAMEPOINT_TOPLEFT,
                     dx / s, -(dy / s))
    BlzFrameSetSize(t, w / s, 0.016 / s)
    if BlzFrameSetTextAlignment ~= nil then
      BlzFrameSetTextAlignment(t, TEXT_JUSTIFY_TOP,
        center and TEXT_JUSTIFY_CENTER or TEXT_JUSTIFY_LEFT)
    end
    API.frameScale(t, s)
    API.frameDead(t)
    return t
  end

  st.titleF = label("QuayTitle", bg, P(), P(), W - 2 * P(),
                  CFG.PANEL_SCALE_HEAD, true)

  local cw   = colW()
  local topY = P() + HEAD_H + GAP

  for i = 1, nCol() do
    local x = P() + (i - 1) * (cw + GAP)
    local c = {}

    local d = CFG.PANEL_BTN_BORDER or 0.0016

    -- ----- THE: chi trang tri, KHONG bam duoc -----
    c.card = BlzCreateFrameByType("BACKDROP", "QuayCot" .. i, bg, "", pid)
    if c.card == nil then return false end
    BlzFrameSetSize(c.card, cw, COT_H)
    BlzFrameSetPoint(c.card, FRAMEPOINT_TOPLEFT, bg, FRAMEPOINT_TOPLEFT,
                     x, -topY)
    BlzFrameSetTexture(c.card, CFG.PANEL_BTN_EDGE, 0, true)
    API.frameDead(c.card)

    -- Ruot thut vao mot vien, cung cach bang nhan vat ve nut: hai o mau
    -- dac long nhau. Backdrop 9 o (EscMenuBackdrop) co goc khong co lai
    -- theo frame nen khong dung duoc cho o nho.
    local fill = BlzCreateFrameByType("BACKDROP", "QuayFill" .. i, c.card, "", pid)
    if fill ~= nil then
      BlzFrameSetSize(fill, cw - 2 * d, COT_H - 2 * d)
      BlzFrameSetPoint(fill, FRAMEPOINT_TOPLEFT, c.card, FRAMEPOINT_TOPLEFT, d, -d)
      BlzFrameSetTexture(fill, CFG.PANEL_BTN_FILL, 0, true)
      API.frameDead(fill)
    end

    c.icon = BlzCreateFrameByType("BACKDROP", "QuayIcon" .. i, c.card, "", pid)
    if c.icon ~= nil then
      BlzFrameSetSize(c.icon, ICON_H, ICON_H)
      BlzFrameSetPoint(c.icon, FRAMEPOINT_TOP, c.card, FRAMEPOINT_TOP,
                       0.0, -0.014)
      API.frameDead(c.icon)
    end

    c.name = label("QuayTen" .. i, c.card, 0.004, 0.014 + ICON_H + 0.010,
                cw - 0.008, CFG.PANEL_SCALE_NAME, true)
    c.desc = label("QuayMota" .. i, c.card, 0.004, 0.014 + ICON_H + 0.034,
                 cw - 0.008, CFG.PANEL_SCALE_SUB, true)

    -- ----- NUT SELECT rieng cua cot nay -----
    --
    -- NEO VAO BANG (bg), KHONG vao c.card. c.card da di qua frameDead()
    -- -- tuc BlzFrameSetEnable(f, false) -- va nut nam trong mot frame
    -- da TAT thi khong nhan duoc cu bam nao: nhin thi day du, bam thi
    -- chet lang. Bang chon hero da dinh dung loi nay mot lan.
    local bw = cw - 2 * BTN_PAD
    c.btn = BlzCreateFrameByType("GLUEBUTTON", "QuaySel" .. i, bg,
                                 CFG.FRAME_BUTTON_TEMPLATE, pid)
    if c.btn == nil then return false end
    BlzFrameSetSize(c.btn, bw, BTN_H)
    BlzFrameSetPoint(c.btn, FRAMEPOINT_TOPLEFT, bg, FRAMEPOINT_TOPLEFT,
                     x + BTN_PAD, -(topY + COT_H + BTN_GAP))
    BlzTriggerRegisterFrameEvent(S.fortuneTrig, c.btn, FRAMEEVENT_CONTROL_CLICK)

    local function plate(name, dx, dy, w2, h2, tex)
      local f = BlzCreateFrameByType("BACKDROP", name, c.btn, "", pid)
      if f == nil then return end
      BlzFrameSetSize(f, w2, h2)
      BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, c.btn, FRAMEPOINT_TOPLEFT, dx, -dy)
      BlzFrameSetTexture(f, tex, 0, true)
      API.frameDead(f)
    end
    plate("QuaySelEdge" .. i, 0.0, 0.0, bw, BTN_H, CFG.PANEL_BTN_EDGE)
    plate("QuaySelFill" .. i, d, d, bw - 2 * d, BTN_H - 2 * d, CFG.PANEL_BTN_FILL)

    local bt = label("QuaySelTxt" .. i, c.btn, 0.004, (BTN_H - 0.016) * 0.5,
                     bw - 0.008, CFG.PANEL_SCALE_NAME, true)
    if bt ~= nil then
      BlzFrameSetText(bt, CFG.C_GOLD .. API.t("pick_select") .. CFG.C_END)
    end

    st.col[i] = c
  end

  BlzFrameSetVisible(bg, false)
  API.trace("fortuneframe: dung khung pid " .. pid)
  return true
end

-- ---------- Ve lai ----------

local function refresh(pid)
  local st = stateOf(pid)
  if st.root == nil then return end
  local card = API.fortuneCards(pid)
  if card == nil then return end

  BlzFrameSetText(st.titleF, CFG.C_GOLD .. API.t("fortune_title") .. CFG.C_END ..
    "   " .. CFG.C_GREY .. API.t("fortune_left", API.num(API.fortuneRolls(pid))) ..
    CFG.C_END)

  -- Duyet theo SO THE THAT su rut duoc, khong theo so cot: hai so nay
  -- chi lech neu ai do doi CFG giua chung -- nhung lech la mot cot giu
  -- chu cu cua luot truoc, kieu sai im lang.
  for i = 1, #st.col do
    local c = st.col[i]
    local t = card[i]
    if c ~= nil and t ~= nil then
      if c.icon ~= nil then
        BlzFrameSetTexture(c.icon, API.fortuneIcon(t.kind) or "", 0, true)
      end
      BlzFrameSetText(c.name,  CFG.C_GOLD .. API.fortuneLabel(t) .. CFG.C_END)
      BlzFrameSetText(c.desc, CFG.C_GREY .. API.t("fortune_card_" .. t.kind) ..
                              CFG.C_END)
    end
  end
end

-- ---------- Hieu ung chia bai ----------
--
-- Truoc day doi the giua hai luot la mot cu NHAY: chu va icon doi tai
-- cho trong cung mot khung hinh, khong co gi bao la vua sang luot moi.
-- Co 12 luot lien tiep (Thanh Long) thi no thanh mot cai bang nhay
-- loan.
--
-- Chia tung cot mot, cach nhau FORTUNE_DEAL_STEP giay. Chi dung
-- BlzFrameSetVisible -- khong dung alpha hay scale: hai thu do khong
-- chac co o moi ban, ma mot hieu ung trang tri thi khong dang de lam
-- hong khung.
--
-- KHONG dong bo. No khong doi mot chut trang thai nao, va moi may co
-- khung rieng -- nen chay cuc bo la dung.
local function dealIn(pid)
  local st = stateOf(pid)
  if st.root == nil then return end
  local step = CFG.FORTUNE_DEAL_STEP or 0.10
  if step <= 0.0 or API.after == nil then return end

  for i = 1, #st.col do
    local c = st.col[i]
    if c ~= nil then
      -- An ca cot LAN nut: de lai cai nut khong thi no lo lung mot
      -- minh, nhin ra loi ve chu khong ra hieu ung.
      show(c.card, false); show(c.btn, false)
      API.after(step * i, function()
        -- Kiem lai LUC DEN GIO: nguoi choi co the da dong khung, va
        -- bat lai mot cai the le giua man hinh la mot loi nhin thay
        -- duoc.
        if not st.shown then return end
        show(c.card, true); show(c.btn, true)
      end)
    end
  end
end

-- ---------- Bat / tat ----------

local function setVisible(pid, want)
  local st = stateOf(pid)
  if st.root == nil then return end
  st.shown = want
  BlzFrameSetVisible(st.root, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.root, want)
  end
end

local function showFrame(pid)
  if not API.fortuneHasRolls(pid) then return end
  if not build(pid) then return end

  -- DONG BANG NHAN VAT TRUOC.
  --
  -- LOI DA SHIP: dang mo ESC ma tinh anh hoac boss chet thi khung Co
  -- Duyen bat len DE LEN bang -- hai khung cung neo vao
  -- ORIGIN_FRAME_GAME_UI, khong cai nao biet cai nao. Nguoi choi thay
  -- chu chong chit va khong bam duoc gi cho ra hon.
  --
  -- Khung nay la cai bat len KHONG XIN PHEP (tu su kien quai chet), nen
  -- no la ben phai nhuong duong -- chu khong phai bat bang di kiem xem
  -- co khung nao sap bat hay khong.
  if API.panelHide ~= nil then API.panelHide(pid) end

  refresh(pid)
  setVisible(pid, true)
  dealIn(pid)
end

local function hideFrame(pid)
  setVisible(pid, false)
end

local function refreshFrame(pid)
  refresh(pid)
  dealIn(pid)
end

-- Bang nhan vat hoi ham nay truoc khi xu ly ESC.
local function isShown(pid)
  local st = S.fortuneUI and S.fortuneUI[pid] or nil
  return st ~= nil and st.shown == true
end

-- ---------- Bam ----------

local function onClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end
  for pid, st in pairs(S.fortuneUI or {}) do
    if GetLocalPlayer() == Player(pid) and st.shown then
      for i = 1, #st.col do
        if st.col[i] ~= nil and f == st.col[i].btn then
          -- Nha tieu diem ban phim, neu khong frame giu phim va ESC
          -- khong toi duoc trigger nua -- cung loi da dinh o bang.
          if BlzFrameSetEnable ~= nil then
            BlzFrameSetEnable(f, false); BlzFrameSetEnable(f, true)
          end
          API.syncSend(pid, CFG.OP_FORTUNE, i)
          return
        end
      end
    end
  end
end

local function startFortuneFrame()
  S.fortuneUI   = {}
  S.fortuneTrig = CreateTrigger()
  TriggerAddAction(S.fortuneTrig, onClick)
  API.trace("fortuneframe: san sang")
end

API.fortuneFrameShow    = showFrame
API.fortuneFrameHide    = hideFrame
API.fortuneFrameRefresh = refreshFrame
API.fortuneFrameShown  = isShown
API.startFortuneFrame   = startFortuneFrame
end
--#endregion 4_ui/5_fortuneframe.lua

--#region 4_ui/6_gameframe.lua
do
-- ============================================================
--  6_gameframe.lua  --  Bang tran dau: phim R
--
--  Bang THU HAI. Bang nhan vat (ESC) tra loi "nhan vat toi the nao";
--  bang nay tra loi "tran dau dang the nao".
--
--  HAI THE:
--    I.  Tong Quan     dot may/100, canh gioi, quai con song, NUT GOI DOT
--    II. Nhiem Vu Phu  de trong -- 25 block danh cho phan nay (ADR 0014)
--
--  BA LUAT PHAI GIU, ca ba deu da tung cat du an nay mot lan:
--
--  1. KHONG tu dang ky phim ESC. bindEsc() trong 1_panel.lua la chu so
--     huu ESC duy nhat; no hoi API.gameFrameShown() roi tu quyet dinh.
--     Hai bo dang ky ESC tren cung mot trigger la MOT cu bam no HAI lan
--     -- do la ly do CFG.PANEL_ESC_LOCK ton tai.
--
--  2. PHAI tra tieu diem ban phim sau moi cu bam. GLUEBUTTON giu tieu
--     diem va nuot het phim, nen bam nut goi dot xong thi ESC chet. Tat
--     roi bat lai frame la cach tra o ban 1.31.
--
--  3. GetLocalPlayer CHI dung cho viec HIEN/AN. Moi thay doi trang thai
--     di qua kenh dong bo -- bam nut chi gui CFG.OP_WAVE_CALL, con viec
--     goi dot that su chay tren MOI may.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local W      = 0.46
local PAD    = 0.018
local GAP    = 0.008
local TAB_H  = 0.026
local LINE   = 0.021
local BTN_H  = 0.032
-- 5 tu 2026-09-19: them dong TU CHINH. Moi hinh hoc khac suy ra tu day
-- (chieu cao khung, vi tri hai nut duoi), nen doi mot so nay la du.
local ROWS   = 5        -- so dong chu cua the Tong Quan

local TAB_OVERVIEW = 1
local TAB_QUESTS   = 2

-- Mot hang nhiem vu phu: chu ben trai, nut ben phai.
-- 4 hang x 0.030 = 0.120, vua trong bodyH() = 0.124. The I va the II
-- dung chung than bang nen KHONG duoc cao hon no.
-- 1 dong dau (LINE) + 4 hang x QROW = 0.021 + 0.100 = 0.121, vua trong
-- bodyH() = 0.124. The I va the II dung chung than bang nen KHONG duoc
-- cao hon no.
local QROW   = 0.025
local QBTN_H = 0.021

-- Le trong THAT = le + vien trang tri cua backdrop. Cung bai hoc voi
-- bang nhan vat va khung Co Duyen: dat chu o dung PAD la no nam DE LEN
-- vien go cua EscMenuBackdrop.
local function P()
  return PAD + (CFG.PANEL_BORDER or 0.0)
end

local function bodyH()
  return ROWS * LINE + GAP + BTN_H
end

local function frameH()
  return P() + TAB_H + GAP + bodyH() + P()
end

local function stateOf(pid)
  if S.gameUI == nil then S.gameUI = {} end
  if S.gameUI[pid] == nil then
    S.gameUI[pid] = { root = nil, tab = TAB_OVERVIEW, row = {}, tabBtn = {},
                      shown = false }
  end
  return S.gameUI[pid]
end

local function show(f, on)
  if f ~= nil then BlzFrameSetVisible(f, on) end
end

-- ---------- Dung khung ----------

local function buildBody(pid)
  local st = stateOf(pid)
  if st.root ~= nil then return true end
  if BlzGetOriginFrame == nil or BlzCreateFrameByType == nil then return false end

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local bg = API.backdrop(CFG.PANEL_BACKDROP, parent, pid, CFG.FRAME_BG)
  if bg == nil then return false end
  st.root = bg
  BlzFrameSetAbsPoint(bg, FRAMEPOINT_CENTER, CFG.GAME_X, CFG.GAME_Y)
  BlzFrameSetSize(bg, W, frameH())

  -- Chu: CHIA ca toa do lan kich thuoc cho ti le phong.
  -- BlzFrameSetScale phong luon KHOANG CACH toi diem neo cua cha, nen
  -- khong chia thi moi dong co ti le khac 1.0 deu bi keo ve goc tren
  -- trai -- dung loi da lam vo bo cuc bang nhan vat mot lan.
  local function label(name, parentF, dx, dy, w, scale, center)
    local t = BlzCreateFrameByType("TEXT", name, parentF, "", pid)
    if t == nil then return nil end
    local s = scale or 1.0
    BlzFrameSetPoint(t, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT,
                     dx / s, -(dy / s))
    BlzFrameSetSize(t, w / s, LINE / s)
    if BlzFrameSetTextAlignment ~= nil then
      BlzFrameSetTextAlignment(t, TEXT_JUSTIFY_TOP,
        center and TEXT_JUSTIFY_CENTER or TEXT_JUSTIFY_LEFT)
    end
    API.frameScale(t, s)
    API.frameDead(t)
    return t
  end

  local function button(name, x, y, w, h)
    local b = BlzCreateFrameByType("GLUEBUTTON", name, bg,
                                   CFG.FRAME_BUTTON_TEMPLATE, pid)
    if b == nil then return nil end
    BlzFrameSetSize(b, w, h)
    BlzFrameSetPoint(b, FRAMEPOINT_TOPLEFT, bg, FRAMEPOINT_TOPLEFT, x, -y)
    BlzTriggerRegisterFrameEvent(S.gameTrig, b, FRAMEEVENT_CONTROL_CLICK)

    -- Vien + ruot: hai o mau dac long nhau. Backdrop 9 o co goc khong co
    -- lai theo frame nen khong dung duoc cho nut nho.
    local d = CFG.PANEL_BTN_BORDER or 0.0016
    local function fill(nm, dx, dy, w2, h2, tex)
      local f = BlzCreateFrameByType("BACKDROP", nm, b, "", pid)
      if f == nil then return end
      BlzFrameSetSize(f, w2, h2)
      BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, b, FRAMEPOINT_TOPLEFT, dx, -dy)
      BlzFrameSetTexture(f, tex, 0, true)
      API.frameDead(f)
    end
    fill(name .. "E", 0.0, 0.0, w, h, CFG.PANEL_BTN_EDGE)
    fill(name .. "F", d, d, w - 2 * d, h - 2 * d, CFG.PANEL_BTN_FILL)

    local txt = label(name .. "T", b, 0.0, (h - 0.012) * 0.5, w,
                      CFG.PANEL_SCALE_NAME, true)
    return { btn = b, txt = txt }
  end

  -- ----- Hai nhan the -----
  local tw = (W - 2 * P() - GAP) * 0.5
  for i = 1, 2 do
    st.tabBtn[i] = button("GameTab" .. i, P() + (i - 1) * (tw + GAP), P(),
                          tw, TAB_H)
  end

  -- ----- Than the I -----
  local top = P() + TAB_H + GAP
  for i = 1, ROWS do
    st.row[i] = label("GameRow" .. i, bg, P(), top + (i - 1) * LINE,
                      W - 2 * P(), CFG.PANEL_SCALE_NAME, false)
  end

  -- Hang duoi chia doi: GOI DOT ben trai, VE NHA ben phai.
  --
  -- VE NHA nam o the TONG QUAN chu khong o the Nhiem Vu Phu, du no sinh
  -- ra cho phan pho ban: the Tong Quan la the mo mac dinh, nen dat o day
  -- moi dung nghia "dung duoc moi luc".
  local cw = W - 2 * P()
  st.call = button("GameCall", P(), top + ROWS * LINE + GAP,
                   cw * 0.62, BTN_H)
  st.home = button("GameHome", P() + cw * 0.64, top + ROWS * LINE + GAP,
                   cw * 0.36, BTN_H)

  -- ----- Than the II: nhiem vu phu -----
  --
  -- Dung SAN ca bon hang. Dung theo so luong luc chay thi doi
  -- CFG.SIDE_QUESTS la phai dung lai khung -- ma khung chi dung mot lan.
  -- DONG DAU: Tu Vi HIEN TAI cua nguoi choi.
  --
  -- Thieu dong nay thi nut chi noi "can Nguyen Anh" ma khong noi minh
  -- dang o dau -- nguoi choi biet DICH nhung khong biet minh cach no
  -- bao xa, va the la khong biet bao gio moi lam duoc.
  st.quests = label("GameQuests", bg, P(), top, W - 2 * P(),
                    CFG.PANEL_SCALE_NAME, false)

  st.quest = {}
  local qw = W - 2 * P()
  for i = 1, #(CFG.SIDE_QUESTS or {}) do
    local qy = top + LINE + (i - 1) * QROW
    st.quest[i] = {
      lbl = label("GameQName" .. i, bg, P(), qy + 0.005, qw * 0.58,
                  CFG.PANEL_SCALE_NAME, false),
      btn = button("GameQBtn" .. i, P() + qw * 0.60, qy, qw * 0.40, QBTN_H),
    }
  end

  BlzFrameSetVisible(bg, false)
  API.trace("gameframe: dung khung pid " .. pid)
  return true
end

-- Boc pcall quanh buildBody(): loi Lua trong callback cua Warcraft khong in ra
-- dau ca, nen khong boc thi mot dong sai o giua bien thanh "bam phim ra
-- cai hop rong" -- khong manh moi nao.
--
-- Hong thi DON RAC. Backdrop da tao la da HIEN; de lai thi nguoi choi
-- co mot cai hop khong dong duoc, va moi lan bam lai them mot cai.
local function build(pid)
  local ok, res = pcall(buildBody, pid)
  if ok and res ~= false then return res end

  API.trace("gameframe: DUNG BANG LOI -- " .. tostring(res))
  API.warn(pid, "gameframe: dung bang loi, xem file vet.")

  local st = stateOf(pid)
  if st ~= nil and st.root ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.root)
  end
  if st ~= nil then st.root = nil end
  return false
end

-- ---------- Ve lai ----------

-- ---------- Nhiem vu phu ----------

local function realmName(r)
  local t = CFG.REALMS and CFG.REALMS[r]
  return (t ~= nil) and API.pick(t) or tostring(r)
end

-- BA ly do khoa, va moi ly do phai NOI RA duoc. Mot nut xam khong giai
-- thich thi nguoi choi tuong giao dien hong -- cung bai hoc voi nut
-- "CHO Kim Dan" o the Trang Bi.
local function questState(pid, i)
  local q = (CFG.SIDE_QUESTS or {})[i]
  if q == nil then return nil, nil end
  local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
  if rank < q.rank then return "rank", q end
  if API.findRegion(q.arrive) == nil then return "norgn", q end
  return "ok", q
end

local function fillQuests(pid, st)
  for i = 1, #(st.quest or {}) do
    local w = st.quest[i]
    local why, q = questState(pid, i)
    local on = (q ~= nil)
    show(w.lbl, on)
    if w.btn ~= nil then show(w.btn.btn, on) end
    if on then
      -- Canh gioi yeu cau nam o NHAN, luon hien -- ke ca khi da mo
      -- khoa. Chi hien luc khoa thi nguoi choi khong the lap ke hoach:
      -- muon biet con sau can gi phai doi toi luc bi chan moi biet.
      BlzFrameSetText(w.lbl, (why == "ok" and CFG.C_GOLD or CFG.C_GREY)
        .. API.t("sq_title", i, API.pick(q), realmName(q.rank)) .. CFG.C_END)
      if w.btn ~= nil and w.btn.txt ~= nil then
        local txt
        if why == "ok" then
          txt = API.t("sq_go")
        elseif why == "norgn" then
          -- Day la loi cua NGUOI LAM MAP, khong phai cua nguoi choi --
          -- nen to mau do chu khong xam.
          txt = CFG.C_RED .. API.t("sq_norgn") .. CFG.C_END
        else
          txt = CFG.C_GREY .. API.t("sq_locked") .. CFG.C_END
        end
        BlzFrameSetText(w.btn.txt, txt)
        if BlzFrameSetEnable ~= nil then
          BlzFrameSetEnable(w.btn.btn, why == "ok")
        end
      end
    end
  end
end

local function refresh(pid)
  local st = stateOf(pid)
  if st.root == nil then return end

  for i = 1, 2 do
    local b = st.tabBtn[i]
    if b ~= nil and b.txt ~= nil then
      local nm = (i == TAB_OVERVIEW) and API.t("game_tab_overview")
                                      or API.t("game_tab_quests")
      BlzFrameSetText(b.txt,
        (i == st.tab and CFG.C_GOLD or CFG.C_GREY) .. nm .. CFG.C_END)
    end
  end

  local isOverview = (st.tab == TAB_OVERVIEW)
  for i = 1, ROWS do show(st.row[i], isOverview) end
  if st.call ~= nil then show(st.call.btn, isOverview) end
  if st.home ~= nil then
    show(st.home.btn, isOverview)
    if st.home.txt ~= nil then
      BlzFrameSetText(st.home.txt, API.t("sq_home"))
    end
  end
  show(st.quests, not isOverview)

  -- Bon hang nhiem vu. Chi hien o the II.
  for i = 1, #(st.quest or {}) do
    local q = st.quest[i]
    show(q.lbl, not isOverview)
    if q.btn ~= nil then show(q.btn.btn, not isOverview) end
  end
  if not isOverview then fillQuests(pid, st) end

  if not isOverview then
    show(st.quests, true)
    if #(CFG.SIDE_QUESTS or {}) == 0 then
      BlzFrameSetText(st.quests, CFG.C_GREY .. API.t("game_quests_soon") .. CFG.C_END)
    else
      local cur = (API.cultRank ~= nil) and API.cultRank(pid) or 1
      BlzFrameSetText(st.quests, CFG.C_GREY .. API.t("sq_head") .. " " ..
        CFG.C_GOLD .. realmName(cur) .. CFG.C_END ..
        CFG.C_GREY .. string.format("  (%d/%d)", cur, #(CFG.REALMS or {})) ..
        CFG.C_END)
    end
    return
  end

  -- Moi con so o day doc tu he wave, khong tu tinh lai. Hai cho cung
  -- tinh mot thu thi som muon cung lech.
  local stage = S.stage or 0
  local total = API.totalStages and API.totalStages() or 0
  local r, tier, isBoss = 1, 0, false
  if API.decodeStage ~= nil and stage > 0 then
    r, tier, isBoss = API.decodeStage(stage)
  end

  BlzFrameSetText(st.row[1], CFG.C_GOLD ..
    API.t("game_stage", stage, total) .. CFG.C_END)

  if stage > 0 and API.realmName ~= nil and API.tierLabel ~= nil then
    BlzFrameSetText(st.row[2], API.t("game_realm",
      API.realmName(r), API.tierLabel(stage)))
  else
    BlzFrameSetText(st.row[2], "")
  end

  -- Con may dot nua toi boss. Boss luon la stage cuoi cua canh gioi.
  if stage > 0 and API.stagesPerRealm ~= nil then
    local per  = API.stagesPerRealm()
    local left = per - tier
    if isBoss or left <= 0 then
      BlzFrameSetText(st.row[3], CFG.C_JADE .. API.t("game_atboss") .. CFG.C_END)
    else
      BlzFrameSetText(st.row[3],
        API.t("game_toboss", left, API.realmName(r)))
    end
  else
    BlzFrameSetText(st.row[3], "")
  end

  BlzFrameSetText(st.row[4], CFG.C_GREY ..
    API.t("game_alive", S.alive or 0) .. CFG.C_END)

  -- TU CHINH dang chay. Dong chat luc vao dot troi mat sau vai giay, ma
  -- tu chinh keo dai CA DOT -- nen no phai co mot cho tra cuu duoc.
  -- Xem labelNow() trong 5_modifier.lua.
  if API.modifierLabel ~= nil then
    local name, desc = API.modifierLabel()
    if name ~= nil then
      BlzFrameSetText(st.row[5], CFG.C_GOLD .. name .. CFG.C_END ..
        "  " .. CFG.C_GREY .. (desc or "") .. CFG.C_END)
    else
      BlzFrameSetText(st.row[5], "")
    end
  else
    BlzFrameSetText(st.row[5], "")
  end

  if st.call ~= nil and API.waveCallState ~= nil then
    local c = API.waveCallState()
    -- Chu XAM khi khong bam duoc. Vien va ruot la o mau tu ve nen
    -- BlzFrameSetEnable khong doi mau chung -- khong lam gi thi nut bam
    -- duoc va nut mo trong y het nhau.
    BlzFrameSetText(st.call.txt,
      c.on and (CFG.C_GOLD .. c.label .. CFG.C_END)
            or (CFG.C_GREY .. c.label .. CFG.C_END))
    if BlzFrameSetEnable ~= nil then BlzFrameSetEnable(st.call.btn, c.on) end
  end
end

-- ---------- Bat / tat ----------

local function setVisible(pid, want)
  local st = stateOf(pid)
  if st.root == nil then return end
  st.shown = want
  BlzFrameSetVisible(st.root, false)
  if GetLocalPlayer() == Player(pid) then
    if want then
      -- Don khung chat khi MO bang.
      --
      -- Frame tu tao deu la con cua ORIGIN_FRAME_GAME_UI, ma khung chat
      -- cua Warcraft ve DE LEN lop do -- khong co cach nao dua backdrop
      -- len tren no, nen "lam overlay day hon" khong giai duoc gi.
      --
      -- ClearTextMessages() la native CHI dung giao dien, khong doi
      -- trang thai nao -- goi trong nhanh cuc bo nay la an toan.
      if ClearTextMessages ~= nil then ClearTextMessages() end
    end
    BlzFrameSetVisible(st.root, want)
  end
end

local function isShown(pid)
  local st = S.gameUI and S.gameUI[pid] or nil
  return st ~= nil and st.shown == true
end

local function hideFrame(pid)
  setVisible(pid, false)
end

local function showFrame(pid)
  -- Co Duyen o tren cung: dang phai chon the thi khong mo gi khac.
  if API.fortuneFrameShown ~= nil and API.fortuneFrameShown(pid) then return end
  if not build(pid) then
    API.msg(pid, CFG.C_RED .. API.t("panel_noframe") .. CFG.C_END)
    return
  end
  -- HAI BANG LOAI TRU NHAU. Dong bang nhan vat truoc khi mo bang nay,
  -- neu khong hai backdrop de len nhau va ESC khong biet dong cai nao.
  if API.panelHide ~= nil then API.panelHide(pid) end
  refresh(pid)
  setVisible(pid, true)
end

-- R chi lam MOT viec: bat/tat bang tran dau.
--
-- DA TUNG cho no mo khung Co Duyen khi con luot, roi go lai
-- (2026-09-20). Ly le luc do: "khung chi bat len tu addRolls(), nen
-- neu no dong ma con luot thi nguoi choi ket luot".
--
-- Trang thai do KHONG XAY RA DUOC. fortuneFrameHide() duoc goi o dung
-- MOT cho -- trong take(), khi luot ve 0 -- va ESC cung khong dong
-- khung Co Duyen. Tuc "con luot ma khung dong" khong co duong nao toi.
--
-- Nen nhanh do vua la ma chet, vua CUOP phim R: con luot thi bam R
-- khong mo duoc bang tran dau nua.
--
-- Bai hoc: mot duong cuu ho cho trang thai khong ton tai khong phai la
-- vo hai -- no chiem mat mot phim.
local function toggle(pid)
  if isShown(pid) then hideFrame(pid) else showFrame(pid) end
end

local function refreshAll()
  for i = 1, #S.pids do
    if isShown(S.pids[i]) then refresh(S.pids[i]) end
  end
end

-- ---------- Bam ----------

local function onClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end

  -- Tra tieu diem ban phim NGAY. GLUEBUTTON giu tieu diem sau khi bam,
  -- va frame giu tieu diem nuot het phim -- khong tra thi bam nut xong
  -- la ESC chet, kieu loi "luc duoc luc khong".
  if BlzFrameSetEnable ~= nil then
    BlzFrameSetEnable(f, false); BlzFrameSetEnable(f, true)
  end

  for pid, st in pairs(S.gameUI or {}) do
    if GetLocalPlayer() == Player(pid) and st.shown then
      for i = 1, 2 do
        if st.tabBtn[i] ~= nil and f == st.tabBtn[i].btn then
          st.tab = i
          refresh(pid)
          return
        end
      end
      for i = 1, #(st.quest or {}) do
        local w = st.quest[i]
        if w.btn ~= nil and f == w.btn.btn then
          -- Bam nut la viec CUC BO (frame click chi no o may nguoi bam),
          -- ma dich chuyen la doi trang thai -- nen chi GUI y dinh. Ben
          -- nhan chay tren moi may va kiem lai du dieu kien.
          API.syncSend(pid, CFG.OP_SIDEQUEST, i)
          return
        end
      end

      if st.home ~= nil and f == st.home.btn then
        API.syncSend(pid, CFG.OP_GO_HOME, 0)
        return
      end

      if st.call ~= nil and f == st.call.btn then
        -- Chi GUI y dinh. Viec goi dot that chay tren moi may, tu
        -- ham nhan cua kenh dong bo.
        API.syncSend(pid, CFG.OP_WAVE_CALL, 0)
        return
      end
    end
  end
end

-- ---------- Nhan tu kenh dong bo ----------
-- Chay tren MOI may. Ai bam cung duoc -- ba nguoi la dong minh, va bao
-- ra chat ai vua goi la du: voi ba nguoi choi chung thi ap luc xa hoi xu
-- ly viec nay tot hon mot co che "ca ba san sang", ma moi co che la mot
-- cho co the treo.

local function onCall(pid, _)
  if API.waveNow == nil then return end
  if not API.waveNow() then
    refreshAll()
    return
  end
  API.msg(nil, CFG.C_GREY ..
    API.t("wave_called", GetPlayerName(Player(pid))) .. CFG.C_END)

  -- DONG khung o MOI may, khong rieng may nguoi bam.
  --
  -- Hai ly do, ly do sau moi la ly do that:
  --   . bang nay tra loi "tran dau dang the nao" -- goi dot xong thi
  --     cau tra loi nam o ngoai bai chien, khong nam trong bang
  --   . con mo la con bam duoc, ma khe giua "nhan loi goi" va "quai
  --     hien ra" du dai de lot mot cu bam nua
  --
  -- Day la lop thu hai. Lop thu nhat la co S.waveCalling trong
  -- waveNow() -- giao dien mot minh khong du, vi -next khong di qua no.
  for i = 1, #S.pids do hideFrame(S.pids[i]) end
end

-- ---------- Phim R ----------

local function bindKey()
  local name = CFG.GAME_KEY
  if name == nil then
    API.trace("gameframe: CFG.GAME_KEY = nil -- khong co phim mo bang")
    return false
  end
  -- Tra hang so luc GAN phim chu khong nho san: khong phu thuoc thu tu
  -- nap chunk. Cung cach bindKey() cua bang nhan vat lam.
  local key = _G["OSKEY_" .. name]
  if key == nil or BlzTriggerRegisterPlayerKeyEvent == nil then
    API.trace("gameframe: khong gan duoc phim " .. tostring(name))
    return false
  end
  local t = CreateTrigger()
  for i = 1, #S.pids do
    BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), key, 0, true)
  end
  TriggerAddAction(t, function() toggle(GetPlayerId(GetTriggerPlayer())) end)
  API.trace("gameframe: da gan phim " .. name)
  return true
end

-- ---------- Nhan tu kenh dong bo: dich chuyen toi vung nhiem vu ----------
--
-- Chay tren MOI may. KIEM LAI du dieu kien o day chu khong tin cu bam:
-- ben gui la cuc bo, mot may go trang thai van phai khong lam gi duoc.
local function onSideQuest(pid, i)
  local why, q = questState(pid, i)
  if q == nil then return end

  if why == "rank" then
    local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
    API.msg(pid, CFG.C_RED .. API.t("sq_need", realmName(q.rank),
                                    realmName(rank)) .. CFG.C_END)
    return
  end
  if why == "norgn" then
    local nm = API.regionLabel(q.arrive)
    API.msg(pid, CFG.C_RED .. API.t("sq_missing", nm) .. CFG.C_END)
    API.trace("sidequest: thieu vung " .. nm .. " -- chay `python w3region.py gen`")
    return
  end

  local d = S.p[pid]
  if d == nil or d.hero == nil or not API.alive(d.hero) then return end

  local r = API.findRegion(q.arrive)
  local cx, cy = API.regionCenter(r)
  local x, y = API.heroFanPoint(pid, cx, cy, CFG.HERO_SPAWN_OFFSET)
  SetUnitPosition(d.hero, x, y)
  -- Pet di theo, nhu o cong dich chuyen ve nha chinh.
  if d.pet ~= nil then SetUnitPosition(d.pet, x, y) end
  if PanCameraToTimedForPlayer ~= nil then
    PanCameraToTimedForPlayer(Player(pid), x, y, 0.0)
  end

  -- Nap chi so cho con boss NGAY LUC NAY: do doi o day moi dung, luc
  -- sinh (vao map) ca doi con o canh gioi 1.
  if API.sideQuestArm ~= nil then API.sideQuestArm(i) end

  API.say(pid, API.t("sq_entered",
    CFG.C_JADE .. API.pick(q) .. CFG.C_END))
  API.trace("sidequest: pid " .. pid .. " -> nhiem vu " .. i)
end

-- Dua hero (va pet) ve nha chinh. Dung chung duong voi cong
-- HeroMoveRegion o 1_house.lua -- mot cong thuc xoe quanh diem, nen
-- khoang cach giua cac hero luon giong nhau du ve bang duong nao.
local function onGoHome(pid, _)
  local d = S.p[pid]
  if d == nil or d.hero == nil or not API.alive(d.hero) then return end
  local r = API.findRegion(CFG.RGN_HOUSE)
  if r == nil then
    API.regionMissing("CFG.RGN_HOUSE", API.regionLabel(CFG.RGN_HOUSE))
    return
  end
  local cx, cy = API.regionCenter(r)
  local x, y = API.heroFanPoint(pid, cx, cy, CFG.HERO_SPAWN_OFFSET)
  SetUnitPosition(d.hero, x, y)
  if d.pet ~= nil then SetUnitPosition(d.pet, x, y) end
  if PanCameraToTimedForPlayer ~= nil then
    PanCameraToTimedForPlayer(Player(pid), x, y, 0.0)
  end

  -- Bao CA DOI. Ai dang o dau la thong tin chung: mot nguoi ve nha giua
  -- luot boss thi ca doi nen biet minh dang thieu mot tay.
  API.say(pid, API.t("sq_wenthome"))
  API.trace("gohome: pid " .. pid)
end

local function startGameFrame()
  S.gameUI   = {}
  S.gameTrig = CreateTrigger()
  TriggerAddAction(S.gameTrig, onClick)
  API.syncOn(CFG.OP_WAVE_CALL, onCall)
  API.syncOn(CFG.OP_SIDEQUEST, onSideQuest)
  API.syncOn(CFG.OP_GO_HOME,   onGoHome)
  bindKey()
  API.trace("gameframe: san sang")
end

API.goHome           = onGoHome
API.gameFrameShow    = showFrame
API.gameFrameHide    = hideFrame
API.gameFrameShown   = isShown
API.gameFrameToggle  = toggle
API.gameFrameRefresh = refreshAll
API.startGameFrame   = startGameFrame
end
--#endregion 4_ui/6_gameframe.lua

--#region 4_ui/7_quest.lua
do
-- ============================================================
--  4_ui/7_quest.lua -- Trang huong dan o menu Nhiem Vu (F9)
--
--  F9 la cho DUY NHAT Warcraft cho minh dat mot trang chu ma khong
--  ton cho tren man hinh. Khong phai vao World Editor: CreateQuest va
--  ho hang cua no deu la native, goi luc vao map la xong.
--
--  Noi dung SUY TU CFG chu khong go tay. Doi CFG.GAME_KEY tu "R" sang
--  chu khac ma trang nay van ghi "R" thi no thanh mot trang noi doi --
--  te hon la khong co trang nao.
-- ============================================================

-- KHONG khai bao lai S/CFG/API o day.
--
-- build.py boc moi file trong mot khoi do...end RIENG, va dat
--     local CFG, S, API
-- o khoi NGOAI. Chung la LOCAL, khong phai bien toan cuc -- nen _G.API
-- la nil. Viet "local API = _G.API" thi che mat cai that bang nil, va
-- dong "API.startQuest = ..." o cuoi file se nem loi NGAY LUC CHUNK
-- NAP. Chunk chet luc nap = map khong khoi tao duoc, va Warcraft bao
-- "There was an error reading the map file" -- khong mot dau vet nao
-- chi vao Lua. Da mat mot buoi de tim ra.
--
-- Cu phap van hop le nen build.py khong bat duoc. Dung bang cach khong
-- khai bao gi ca, y het 27 file kia.

-- Ten phim mo bang nhan vat. CFG.PANEL_KEY = nil nghia la khong gan
-- phim chu nao, chi ESC bat/tat -- xem chu thich o 1_config.lua.
local function panelKeyName()
  return (CFG.PANEL_KEY ~= nil) and (CFG.PANEL_KEY .. " / ESC") or "ESC"
end

-- "1-6" chu khong phai "1, 2, 3, 4, 5, 6": bang nao lien mach thi viet
-- gon, dut doan thi liet ke du. Doc THANG tu CFG.ITEM_KEYS.
local function itemKeyName()
  local k = CFG.ITEM_KEYS
  if k == nil or #k == 0 then return nil end
  if #k == 1 then return k[1] end
  local run = true
  for i = 2, #k do
    if tonumber(k[i]) == nil or tonumber(k[i]) ~= tonumber(k[1]) + i - 1 then
      run = false
      break
    end
  end
  if run then return k[1] .. "-" .. k[#k] end
  return table.concat(k, " ")
end

local function describe()
  local L = {}
  local function add(s) L[#L + 1] = s end
  local function key(k, text) add(CFG.C_GOLD .. k .. CFG.C_END .. "  " .. text) end

  add(API.t("quest_intro"))
  add("")

  -- ----- Phim -----
  key(panelKeyName(), API.t("quest_key_panel"))

  -- Liet ke the DOC TU BANG, khong go tay. Them mot the moi (VI. Nha
  -- Chinh chang han) la dong nay tu dai ra -- go tay thi no thanh mot
  -- trang noi doi, te hon la khong co trang nao.
  if API.panelTabNames ~= nil then
    local t = API.panelTabNames()
    if #t > 0 then
      add("      " .. CFG.C_GREY .. table.concat(t, "  ") .. CFG.C_END)
    end
  end

  if CFG.GAME_KEY ~= nil then
    key(CFG.GAME_KEY, API.t("quest_key_game"))
  end
  local ik = itemKeyName()
  if ik ~= nil then key(ik, API.t("quest_key_item")) end
  key("F9", API.t("quest_key_f9"))

  -- ----- Lenh go -----
  add("")
  key("-zoom", API.t("quest_zoom",
      API.num(math.floor((CFG.ZOOM_MIN or 900.0) + 0.5)),
      API.num(math.floor((CFG.ZOOM_MAX or 4500.0) + 0.5))))

  -- ----- Tu chinh -----
  --
  -- Day moi la phan dang doc nhat cua trang. Phim tat thi bam vai lan
  -- la thuoc; con "vi sao dam quai nay mau tim" thi khong doan ra duoc,
  -- va khong biet thi ca he tu chinh thanh do kho vo hinh.
  if CFG.MODIFIERS ~= nil and #CFG.MODIFIERS > 0 then
    add("")
    add(CFG.C_GOLD .. API.t("quest_mod_head") .. CFG.C_END)
    add(CFG.C_GREY .. API.t("quest_mod_intro") .. CFG.C_END)
    local en = (API.lang() == "en")
    for i = 1, #CFG.MODIFIERS do
      local m   = CFG.MODIFIERS[i]
      local sky = (en and m.sky_en) or m.sky_vi
      local d   = (en and m.desc_en) or m.desc_vi or ""
      add("   " .. CFG.C_JADE .. API.pick(m) .. CFG.C_END ..
          (sky ~= nil and (CFG.C_GREY .. "  (" .. sky .. ")" .. CFG.C_END) or "") ..
          "  " .. d)
    end
  end

  return table.concat(L, "\n")
end

-- ---------- Tao trang ----------
--
-- Moi native deu chot nil rieng. Thieu CreateQuest thi khong co gi de
-- lam, nhung thieu QuestSetIconPath thi van nen ra trang -- mat cai
-- icon con hon mat ca trang chu.
local function startQuest()
  if CreateQuest == nil then
    API.trace("quest: KHONG co CreateQuest -- bo qua trang F9")
    return
  end

  local q = CreateQuest()
  if q == nil then
    API.trace("quest: CreateQuest tra ve nil")
    return
  end

  local miss = {}
  local function call(name, ...)
    local fn = _G[name]
    if fn == nil then
      miss[#miss + 1] = name
      return
    end
    fn(...)
  end

  call("QuestSetTitle", q, API.t("quest_title"))
  call("QuestSetDescription", q, describe())
  -- required = true de no nam o muc tren cung. Day khong phai nhiem vu
  -- that, nhung no la thu dau tien nguoi choi can doc.
  call("QuestSetRequired", q, true)
  call("QuestSetDiscovered", q, true)
  call("QuestSetCompleted", q, false)
  -- KHONG dat icon. QuestSetIconPath doi mot duong dan texture, ma moi
  -- lan DOAN duong dan trong du an nay deu doan sai (xem BTNRingViolet).
  -- Trang khong icon van doc duoc; icon sai thi ra o xanh la.

  -- Nhap nut F9 mot cai luc vao map: khong nhap thi khong ai bam F9,
  -- va mot trang chu khong ai mo thi bang khong viet.
  call("FlashQuestDialogButton")

  S.quest = q
  if #miss > 0 then
    API.trace("quest: THIEU native " .. table.concat(miss, " "))
  else
    API.trace("quest: trang F9 da tao")
  end
end

API.startQuest = startQuest
end
--#endregion 4_ui/7_quest.lua

--#region 4_ui/8_camera.lua
do
-- ============================================================
--  8_camera.lua  --  Tam nhin camera, lenh "-zoom"
--
--  BA DIEU PHAI NHO:
--
--  1. CAMERA LA CUC BO, va do la LY DO no an toan. SetCameraField chi
--     doi camera cua may dang chay -- khong mot chut trang thai game
--     nao doi theo, nen khong co cua desync. Nguoc lai cung dung: goi
--     thang ma khong loc nguoi choi thi CA DOI bi zoom theo.
--
--     Dung SetCameraFieldForPlayer neu ban nay co; khong thi loc bang
--     GetLocalPlayer(). Ca hai duong deu an toan vi cung khong doi
--     trang thai.
--
--  2. ZOOM RA XA THI PHAI NOI FARZ. Warcraft cat canh o mot khoang
--     nhat dinh (far-Z); keo TARGET_DISTANCE ra 4000 ma de nguyen farz
--     thi dia hinh phia xa BIEN MAT thay vi hien ra. Trieu chung nhin
--     ra "map bi thung", de tuong la loi terrain.
--
--  3. CHAN TREN CHAN DUOI. Go "-zoom 999999" thi camera bay ra ngoai
--     vu tru va nguoi choi khong co duong ve tru khoi dong lai game.
--     Clamp, va bao ro da clamp.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function clampDist(v)
  local lo = CFG.ZOOM_MIN or 900.0
  local hi = CFG.ZOOM_MAX or 4500.0
  if v < lo then return lo end
  if v > hi then return hi end
  return v
end

-- Dat tam nhin cho MOT nguoi choi.
local function setZoom(pid, dist, secs)
  if SetCameraField == nil and SetCameraFieldForPlayer == nil then
    API.trace("camera: khong co SetCameraField -- lenh -zoom vo hieu")
    return nil
  end
  local d = clampDist(dist)
  local t = secs or CFG.ZOOM_TIME or 0.0

  local forPlayer = _G["SetCameraFieldForPlayer"]
  if forPlayer ~= nil then
    forPlayer(Player(pid), CAMERA_FIELD_TARGET_DISTANCE, d, t)
    if CFG.ZOOM_FARZ ~= nil and CAMERA_FIELD_FARZ ~= nil then
      forPlayer(Player(pid), CAMERA_FIELD_FARZ, CFG.ZOOM_FARZ, t)
    end
  elseif GetLocalPlayer() == Player(pid) then
    -- Nhanh nay chi chay tren may cua chinh nguoi do. KHONG doi trang
    -- thai game nao nen khong lech ban.
    SetCameraField(CAMERA_FIELD_TARGET_DISTANCE, d, t)
    if CFG.ZOOM_FARZ ~= nil and CAMERA_FIELD_FARZ ~= nil then
      SetCameraField(CAMERA_FIELD_FARZ, CFG.ZOOM_FARZ, t)
    end
  end

  if S.p[pid] ~= nil then S.p[pid].zoom = d end
  return d
end

-- "-zoom"      -> ve mac dinh
-- "-zoom 3000" -> dat 3000
--
-- Khong tham so KHONG phai la "khong lam gi": nguoi choi go "-zoom" khi
-- da zoom lung tung va muon ve cho cu. Do la cong dung chinh cua no.
local function onZoom(pid, text)
  local arg = (text or ""):match("%-zoom%s+([%d%.]+)")
  local want = tonumber(arg) or CFG.ZOOM_DEFAULT or 1650.0

  local got = setZoom(pid, want)
  if got == nil then return end

  API.msg(pid, CFG.C_JADE .. API.t("zoom_set", API.num(math.floor(got + 0.5)))
               .. CFG.C_END)
  -- Bao RO khi da bi chan, neu khong nguoi choi go 9000 thay 4500 roi
  -- tuong lenh hong.
  if math.abs(got - want) > 0.5 then
    API.msg(pid, CFG.C_GREY .. API.t("zoom_clamp",
      API.num(math.floor((CFG.ZOOM_MIN or 900.0) + 0.5)),
      API.num(math.floor((CFG.ZOOM_MAX or 4500.0) + 0.5))) .. CFG.C_END)
  end
end

local function startCamera()
  local t = CreateTrigger()
  for i = 1, #S.pids do
    -- false = khop TIEN TO, de "-zoom 3000" cung no. Voi true thi chi
    -- dung chuoi "-zoom" moi khop va lenh co tham so chet lang.
    TriggerRegisterPlayerChatEvent(t, Player(S.pids[i]), "-zoom", false)
  end
  TriggerAddAction(t, function()
    onZoom(GetPlayerId(GetTriggerPlayer()), GetEventPlayerChatString())
  end)
  S.zoomTrig = t

  -- AP NGAY cho moi nguoi, khong doi ai go lenh.
  --
  -- secs = 0: luc vao map ma cho camera TRUOT toi tam nhin moi thi
  -- nguoi choi thay man hinh tu dong lui ra, doc nhu loi. Nhay thang
  -- la dung -- chua ai kip nhin thi chua co gi de truot.
  local d = CFG.ZOOM_DEFAULT or 1650.0
  for i = 1, #S.pids do setZoom(S.pids[i], d, 0.0) end

  API.trace("camera: lenh -zoom san sang (mac dinh " ..
            (CFG.ZOOM_DEFAULT or 1650.0) .. ", chan " ..
            (CFG.ZOOM_MIN or 900.0) .. ".." .. (CFG.ZOOM_MAX or 4500.0) ..
            "), da ap cho " .. #S.pids .. " nguoi")
end

API.cameraZoom  = setZoom
API.startCamera = startCamera
end
--#endregion 4_ui/8_camera.lua

--#region 4_ui/9_wing.lua
do
-- ============================================================
--  9_wing.lua  --  Canh: huy hieu canh gioi, deo tren lung hero
--
--  Moi bo mo o mot moc canh gioi (CFG.WINGS[i].rank). Khong co chi so,
--  khong doi can bang -- no chi de NGUOI KHAC NHIN THAY anh da di toi
--  dau. Truoc do canh gioi chi doc duoc trong bang phim ESC.
--
--  BON DIEU PHAI NHO:
--
--  1. PHAI GAN TREN MOI MAY. Day la khac biet voi camera:
--     SetCameraField chi doi may dang chay nen goi cuc bo la dung, con
--     AddSpecialEffectTarget tao ra mot EFFECT THAT. Goi tren mot may
--     thi chi may do thay canh -- ma ca gia tri cua canh nam o cho
--     nguoi khac nhin thay. wear() vi the phai di tu duong da dong bo
--     (dot pha, hoac syncOn cua nut doi canh), KHONG tu callback frame.
--
--  2. DOI HERO LA RO RI. Effect bam vao unit. Hero bi xoa ma khong
--     DestroyEffect thi handle treo lai. Phai go o CHO DOI HERO, khong
--     chi o cho deo bo moi.
--
--  3. PHAI QUET LAI, KHONG CHI BAT SU KIEN. Nguoi choi co the nhay
--     canh gioi bang "-lc 15", hoac dot pha nhieu bac trong mot lan.
--     check() quet ca bang moi lan goi thay vi chi so voi bac vua qua.
--
--  4. DIEM GAN LA THUOC TINH CUA MODEL. Xem models/wings/note.txt:
--     goi Ethereal phai gan "origin", goi khac gan "chest" thi vot len
--     tren dau. Tung bo khai rieng truong 'attach'.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function defAt(i)
  return (CFG.WINGS or {})[i]
end

local function rankOf(pid)
  return (API.cultRank ~= nil) and API.cultRank(pid) or 1
end

-- Bo canh CAO NHAT ma canh gioi nay voi toi. nil = chua co bo nao.
--
-- Duyet xuoi va giu cai cuoi cung dat: bang xep theo do choi tang dan
-- nen cai sau luon "xin" hon cai truoc.
local function bestFor(pid)
  local r, best = rankOf(pid), nil
  for i = 1, #(CFG.WINGS or {}) do
    if r >= (CFG.WINGS[i].rank or 99) then best = i end
  end
  return best
end

local function owns(pid, i)
  local w = defAt(i)
  return w ~= nil and rankOf(pid) >= (w.rank or 99)
end

-- ---------- Deo / go ----------

local function clear(pid)
  local d = S.p[pid]
  if d == nil or d.wingFx == nil then return end
  if DestroyEffect ~= nil then DestroyEffect(d.wingFx) end
  -- Gan TACH ra chu khong "d.a, d.b = nil, nil": fieldpair.py chi nhan
  -- ra dang gan mot bien. Mot canh bao gia lam ca bo kiem mat tin.
  d.wingFx   = nil
  d.wingWorn = nil
end

-- point = nil thi lay 'attach' cua bo do, roi moi den mac dinh chung.
local function wear(pid, i, point)
  local w = defAt(i)
  local d = S.p[pid]
  if w == nil or d == nil or d.hero == nil then return false end
  if AddSpecialEffectTarget == nil then
    API.trace("wing: khong co AddSpecialEffectTarget")
    return false
  end

  clear(pid)

  local at = point or w.attach or CFG.WING_ATTACH or "origin"
  local fx = AddSpecialEffectTarget(w.path, d.hero, at)
  if fx == nil then
    API.trace("wing: AddSpecialEffectTarget tra nil -- '" .. w.path ..
              "' @ '" .. at .. "'")
    return false
  end
  if CFG.WING_SCALE ~= nil and BlzSetSpecialEffectScale ~= nil then
    BlzSetSpecialEffectScale(fx, CFG.WING_SCALE)
  end

  d.wingFx   = fx
  d.wingWorn = i
  API.trace("wing: pid " .. pid .. " deo #" .. i .. " '" .. w.code ..
            "' @ '" .. at .. "'")
  return true
end

-- ---------- Moc canh gioi ----------
--
-- Goi sau moi lan dot pha, VA sau khi pick hero (hero moi thi chua co
-- canh nao tren nguoi du canh gioi da cao).
local function check(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  local best = bestFor(pid)
  if best == nil then return end

  -- BAO khi vua cham mot moc MOI. d.wingTop nho moc cao nhat da bao,
  -- de dot pha nhieu bac mot lan khong ra ba dong lien tiep.
  if (d.wingTop or 0) < best then
    d.wingTop = best
    local w = defAt(best)
    -- Tin CHUNG: ca gia tri cua canh la nguoi khac nhin thay. Bao rieng
    -- cho nguoi vua dot pha la vo nghia -- ho dang nhin thang vao no.
    API.msg(nil, CFG.C_GOLD ..
      API.t("wing_earned", GetPlayerName(Player(pid)), API.pick(w)) ..
      CFG.C_END)
  end

  -- Chua tu chon bo nao thi luon deo bo cao nhat. Da tu chon roi thi
  -- TON TRONG lua chon do -- tru khi bo dang deo khong con hop le.
  local want = d.wingPick
  if want == nil or not owns(pid, want) then want = best end
  if d.wingWorn ~= want then wear(pid, want) end
end

-- Doi sang bo KE TIEP trong so nhung bo da mo. Vong lai tu dau.
--
-- Chay tu syncOn nen co tren moi may -- nguoi khac thay canh doi theo.
local function cycle(pid)
  local d = S.p[pid]
  local n = #(CFG.WINGS or {})
  if d == nil or n == 0 then return end
  local from = d.wingWorn or 0
  for k = 1, n do
    local i = ((from - 1 + k) % n) + 1
    if owns(pid, i) then
      d.wingPick = i
      wear(pid, i)
      API.panelRefresh(pid)
      return
    end
  end
end

-- ---------- The Trang Bi hoi ----------

local function label(pid)
  local d = S.p[pid]
  local i = d and d.wingWorn or nil
  if i == nil then return nil end
  return API.pick(defAt(i))
end

-- Anh cua bo DANG DEO, cho o Canh o the Trang Bi.
--
-- nil = chua deo bo nao; cho goi tu quyet dinh duong lui
-- (CFG.GEAR_WING_ICON). Khong tra duong lui o day: o goi con phan biet
-- "chua mo bo nao" voi "da deo nhung thieu file anh".
local function iconOf(pid)
  local d = S.p[pid]
  local i = d and d.wingWorn or nil
  if i == nil then return nil end
  local w = defAt(i)
  return (w ~= nil) and w.icon or nil
end

local function nextRank(pid)
  local r = rankOf(pid)
  for i = 1, #(CFG.WINGS or {}) do
    local need = CFG.WINGS[i].rank or 99
    if r < need then return need end
  end
  return nil
end

local function ownedCount(pid)
  local n = 0
  for i = 1, #(CFG.WINGS or {}) do
    if owns(pid, i) then n = n + 1 end
  end
  return n
end

local function startWing()
  if CFG.WINGS == nil or #CFG.WINGS == 0 then
    API.trace("wing: bang rong")
    return
  end
  API.syncOn(CFG.OP_WING, function(pid) cycle(pid) end)

  if CFG.DEV_COMMANDS then
    local t = CreateTrigger()
    for i = 1, #S.pids do
      -- false = khop TIEN TO, de "-wing 3 origin" cung no.
      TriggerRegisterPlayerChatEvent(t, Player(S.pids[i]), "-wing", false)
    end
    TriggerAddAction(t, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local text = GetEventPlayerChatString()
      -- Lay TRON phan con lai lam ten diem, khong phai mot tu: nua so
      -- diem gan cua Warcraft co dau cach ("hand left", "foot right"),
      -- nen "%S*" lam nua bang khong go duoc va tuong la deu hong.
      local arg, pt = (text or ""):match("%-wing%s+(%S+)%s*(.*)")
      if pt ~= nil then pt = pt:gsub("^%s+", ""):gsub("%s+$", "") end
      if arg == "off" then clear(pid); API.info(pid, "-wing: da go"); return end
      local n = tonumber(arg)
      if n == nil or defAt(n) == nil then
        API.info(pid, "-wing N [diem] | -wing off")
        for i = 1, #CFG.WINGS do
          API.info(pid, "   " .. i .. ". " .. CFG.WINGS[i].code ..
                        "  canh gioi " .. (CFG.WINGS[i].rank or 0) ..
                        "  @" .. (CFG.WINGS[i].attach or "origin"))
        end
        return
      end
      if pt == "" then pt = nil end
      wear(pid, n, pt)
    end)
    S.wingTrig = t
  end

  API.trace("wing: " .. #CFG.WINGS .. " bo, moc canh gioi " ..
            table.concat((function()
              local t2 = {}
              for i = 1, #CFG.WINGS do t2[i] = CFG.WINGS[i].rank or 0 end
              return t2
            end)(), " "))
end

API.wingCheck   = check
API.wingClear   = clear
API.wingCycle   = cycle
API.wingIcon    = iconOf
API.wingLabel   = label
API.wingNext    = nextRank
API.wingOwned   = ownedCount
API.startWing   = startWing
end
--#endregion 4_ui/9_wing.lua

--#region 4_ui/10_summary.lua
do
-- ============================================================
--  10_summary.lua  --  Bang tong ket luc het van
--
--  VI SAO CO. Ha boss stage 100 xong truoc day chi co MOT dong chu roi
--  CustomVictoryBJ. Mot tram wave doi lay mot hop thoai.
--
--  Va ban THUA con can hon ban thang: nguoi choi muon biet minh di
--  duoc toi dau, chu khong chi biet la thua.
--
--  CHI DOC, KHONG DEM THEM. Moi con so o day suy tu trang thai da co
--  san (S.stage, bac Tu Vi, so Thanh Thu, so Phap Khi...) tru DUNG HAI
--  cai phai dem: thoi gian va so quai. Them mot bo dem la them mot cho
--  co the lech voi su that.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function clock()
  if S.t0 == nil or TimerGetElapsed == nil then return nil end
  return TimerGetElapsed(S.t0)
end

-- "1g 23p" / "23p 45g". Bo giay khi da qua mot gio: o do giay la nhieu
-- chu so ma khong ai doc.
local function hms(sec)
  if sec == nil then return "--" end
  local h = math.floor(sec / 3600.0)
  local m = math.floor((sec - h * 3600.0) / 60.0)
  local s = math.floor(sec - h * 3600.0 - m * 60.0)
  if h > 0 then return h .. "g " .. m .. "p" end
  return m .. "p " .. s .. "g"
end

-- Tong bac trang bi cua mot nguoi. Doc qua API.gearLevel chu khong mo
-- bang: 5_gear.lua so huu cach tinh do.
local function gearTotal(pid)
  if API.gearLevel == nil or CFG.GEAR == nil then return 0 end
  local n = 0
  for i = 1, #CFG.GEAR do n = n + (API.gearLevel(pid, i) or 0) end
  return n
end

local function relicCount(pid)
  if API.relicHas == nil or CFG.RELIC == nil then return 0 end
  local n = 0
  for i = 1, #CFG.RELIC do
    if API.relicHas(pid, CFG.RELIC[i].code) then n = n + 1 end
  end
  return n
end

local function skillTotal(pid)
  if API.skillList == nil then return 0 end
  local list, n = API.skillList(pid), 0
  for i = 1, #list do
    n = n + (API.skillLevel(pid, list[i].id, i) or 0)
  end
  return n
end

-- ---------- Ve bang ----------
--
-- Di qua API.info: day la BAN BAO CAO, khong mau, nhieu dong. Rieng
-- hai dong dau (THANG/THUA va ly do) la chu cua NGUOI CHOI nen chung
-- di qua API.msg va qua i18n.
local function show(win, reason)
  API.msg(nil, " ")
  local head = win and API.t("end_win") or API.t("end_lose")
  API.msg(nil, (win and CFG.C_GOLD or CFG.C_RED) .. head .. CFG.C_END ..
               "  " .. reason)

  local stage = S.stage or 0
  local total = (API.totalStages ~= nil) and API.totalStages() or 0
  API.info(nil, API.t("end_stage", stage, total) ..
                "   " .. API.t("end_time", hms(clock())) ..
                "   " .. API.t("end_kills", API.num(S.killCount or 0)))

  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero ~= nil then
      local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
      local realm = (API.realmName ~= nil) and API.realmName(rank) or rank
      -- KHONG hien so canh: so bo canh mo duoc SUY RA tu canh gioi
      -- (CFG.WINGS[i].rank), nen no la cot thua -- noi lai dung cai
      -- ma cot dau da noi.
      API.info(nil, "  " .. GetPlayerName(Player(pid)) .. "  --  " ..
        realm ..
        "  |  " .. API.t("end_skill", skillTotal(pid)) ..
        "  |  " .. API.t("end_gear",  gearTotal(pid)) ..
        "  |  " .. API.t("end_relic", relicCount(pid)) ..
        "  |  " .. API.t("end_beast",
                         (API.petOwned ~= nil) and API.petOwned(pid) or 0))
    end
  end

  API.trace("summary: stage " .. stage .. "/" .. total ..
            ", " .. math.floor(clock() or 0) .. "s, " ..
            (S.killCount or 0) .. " quai")
end

local function startSummary()
  -- Mot dong ho chay suot van, chi de DOC. TimerGetElapsed tren mot
  -- timer chu khong cong don bang tay: cong don bang tay thi moi cho
  -- quen goi la mot cho lech.
  S.t0 = CreateTimer()
  TimerStart(S.t0, 999999.0, false, nil)
  S.killCount = 0
  API.trace("summary: san sang")
end

API.summaryShow  = show
API.startSummary = startSummary
end
--#endregion 4_ui/10_summary.lua

--#region 4_ui/11_board.lua
do
-- ============================================================
--  11_board.lua  --  Multiboard: bon thu KHONG nam tren thanh tai nguyen
--
--  VI SAO CAN. Map nay co BON dong tien, ma thanh tai nguyen cua
--  Warcraft chi co HAI o:
--
--    Vang, Go              thanh tai nguyen  -- luon thay
--    Linh Khi, Da          S.p[pid]          -- chi thay khi bam ESC
--    luot Co Duyen         chat              -- troi mat
--
--  Tuc HAI TRONG BON dong tien vo hinh, va mot trong hai la LINH KHI --
--  thu mua Tu Vi, truc tien trinh chinh. Cau "du 500 chua?" la cau
--  nguoi choi hoi lien tuc, ma phai bam ESC moi tra loi duoc.
--
--  VI SAO MULTIBOARD CHU KHONG PHAI MOT KHUNG TU VE. Day la thu duy
--  nhat LUON HIEN ma khong can BlzFrame: no la UI goc cua Warcraft, co
--  chac tren 1.31.1, nguoi choi thu nho duoc, va no khong dam voi bon
--  khung tu ve cua map (chung deu neo giua man hinh).
--
--  MOI HANG LA MOT NGUOI CHOI, khong phai chi minh. Do la cho bien no
--  tu mot cai HUD thanh mot cong cu CO-OP: nhin mot cai biet ai sap
--  dot pha, ai dang ngheo, ai con luot quay chua tieu.
--
--  DONG BO: noi dung multiboard la trang thai TOAN CUC. Moi may phai
--  ghi cung mot thu -- tuyet doi khong ghi trong nhanh GetLocalPlayer
--  (ADR 0012). Ham nay chay tu mot dong ho chung nen moi may tu chay
--  cung so lan.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Be ngang TUNG COT, tinh theo be ngang man hinh.
--
-- LOI DA SHIP: ban dau chi dat be ngang cho HANG TIEU DE. Multiboard
-- cua Warcraft giu be ngang theo TUNG O chu khong theo cot -- nen hang
-- tieu de gian theo so cua ta con hang du lieu giu mac dinh, va hai
-- hang le nhau tren man hinh.
--
-- Khong co ham nao dat "be ngang cua mot cot". Phai dat cho MOI o, va
-- do la ly do put() luon tra bang nay chu khong nhan tham so.
local COLW = { 0.085, 0.075, 0.055, 0.042, 0.042 }
local COLS = #COLW

local function fmtNum(n)
  return API.num(math.floor((n or 0) + 0.5))
end

-- Ghi mot o. Gop lai mot cho vi moi o deu phai lam BON viec giong nhau
-- (lay item, dat kieu, dat chu + be ngang, giai phong handle) -- quen
-- cai cuoi thi ro ri mot handle moi lan ve lai, va ta ve moi nua giay.
local function put(mb, row, col, text)
  local it = MultiboardGetItem(mb, row - 1, col - 1)
  if it == nil then return end
  MultiboardSetItemStyle(it, true, false)
  MultiboardSetItemValue(it, text)
  MultiboardSetItemWidth(it, COLW[col] or 0.05)
  MultiboardReleaseItem(it)
end

local function header(mb)
  put(mb, 1, 1, CFG.C_GOLD .. API.t("board_player") .. CFG.C_END)
  put(mb, 1, 2, CFG.C_GOLD .. API.t("board_realm")  .. CFG.C_END)
  put(mb, 1, 3, CFG.C_GOLD .. API.t("panel_qi")     .. CFG.C_END)
  put(mb, 1, 4, CFG.C_GOLD .. API.t("cur_iron")     .. CFG.C_END)
  put(mb, 1, 5, CFG.C_GOLD .. API.t("board_roll")   .. CFG.C_END)
end

local function refresh()
  local mb = S.board
  if mb == nil then return end

  -- Tieu de mang so dot. No la thu duy nhat cua BAN DAU (khong theo
  -- tung nguoi), va truoc day chi doc duoc khi bam R.
  local total = (API.totalStages ~= nil) and API.totalStages() or 0
  MultiboardSetTitleText(mb, API.t("board_title", S.stage or 0, total))

  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d   = S.p[pid]
    local row = i + 1

    put(mb, row, 1, GetPlayerName(Player(pid)))

    if d == nil or d.hero == nil then
      -- Chua chon hero: de trong chu khong ghi so 0. So 0 doc ra la
      -- "co ma het", con trong doc ra la "chua bat dau" -- hai thu khac
      -- nhau, va nguoi cung doi can phan biet duoc.
      put(mb, row, 2, CFG.C_GREY .. "--" .. CFG.C_END)
      put(mb, row, 3, "")
      put(mb, row, 4, "")
      put(mb, row, 5, "")
    else
      local rank = (API.cultRank ~= nil) and API.cultRank(pid) or 1
      local name = (API.realmName ~= nil) and API.realmName(rank) or tostring(rank)
      put(mb, row, 2, name)
      put(mb, row, 3, CFG.C_JADE .. fmtNum(API.getQi(pid)) .. CFG.C_END)
      put(mb, row, 4, fmtNum(API.getIron(pid)))

      -- Luot quay: to len khi CON luot, xam khi het. Mot con so 0 nam
      -- im thi mat bo qua; mot con so vang thi no tu goi.
      local n = (API.fortuneRolls ~= nil) and API.fortuneRolls(pid) or 0
      put(mb, row, 5, (n > 0) and (CFG.C_GOLD .. n .. CFG.C_END)
                               or (CFG.C_GREY .. "0" .. CFG.C_END))
    end
  end
end

local function startBoard()
  if not CFG.BOARD_SHOW then
    API.trace("board: TAT (CFG.BOARD_SHOW = false)")
    return
  end
  if CreateMultiboard == nil then
    API.trace("board: KHONG co CreateMultiboard -- Linh Khi va Da chi " ..
              "doc duoc trong bang ESC")
    return
  end

  local mb = CreateMultiboard()
  if mb == nil then
    API.trace("board: CreateMultiboard tra ve nil")
    return
  end
  S.board = mb

  -- Mot hang tieu de + mot hang moi nguoi choi.
  MultiboardSetRowCount(mb, #S.pids + 1)
  MultiboardSetColumnCount(mb, COLS)
  header(mb)
  refresh()
  MultiboardDisplay(mb, true)

  S.boardTimer = CreateTimer()
  TimerStart(S.boardTimer, CFG.BOARD_TICK or 0.5, true, refresh)

  API.trace("board: " .. (#S.pids + 1) .. " hang x " .. COLS ..
            " cot, nhip " .. (CFG.BOARD_TICK or 0.5) .. "s")
end

API.boardRefresh = refresh
API.startBoard   = startBoard
end
--#endregion 4_ui/11_board.lua

--#region 5_boot/1_events.lua
do
-- ============================================================
--  1_events.lua  --  Trigger
--
--  Hai viec: nha chinh chet, va chan nguoi choi chon nha chinh.
--  Su kien popup chon hero do 07_heropick tu dang ky lay.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function onAnyDeath()
  local u = GetTriggerUnit()
  if u == nil then return end
  if u == S.house then
    API.onHouseDeath()
    return
  end
  -- Hero cua nguoi choi: hen gio song lai, va KHONG day sang
  -- onMobDeath -- ham do cong tien thuong cho ke giet.
  if API.onHeroDeath ~= nil and API.onHeroDeath(u) then return end
  API.onMobDeath(u, GetKillingUnit())
end

-- Nha chinh la muc tieu phai giu, khong phai quan de dieu khien. Lot
-- vao Ctrl+A roi lo ra lenh cho no la hong ca van.
--
-- Warcraft III khong co cach danh dau mot unit la "khong chon duoc" ma
-- van cho ke dich danh -- ability Locust lam no vo hinh voi ca hai phia,
-- ma nha chet la thua nen khong dung duoc. Nen phai bo chon thu cong.
local function onSelect()
  if CFG.HOUSE_SELECTABLE then return end
  if S.house == nil or GetTriggerUnit() ~= S.house then return end

  local p = GetTriggerPlayer()
  -- Hoan sang tick sau: doi trang thai ngay trong su kien cua engine la
  -- cong thuc gay loi, xem ADR 0005.
  API.after(0.0, function()
    if S.house ~= nil then SelectUnitRemoveForPlayer(S.house, p) end
  end)
end

-- Lenh thu: "-sp" phat mot diem ky nang cho hero cua nguoi go.
--
-- Tra loi TRONG MOI TRUONG HOP. Lenh thu im lang la thu vo dung nhat:
-- khong biet no that bai hay khong duoc dang ky.
local function onChat()
  local pid = GetPlayerId(GetTriggerPlayer())
  local d = S.p[pid]

  -- Lenh dang ky khop TIEN TO, nen "-spawn" cung roi vao day. Kiem lai
  -- chuoi day du roi hay lam gi -- neu khong thi moi lenh moi bat dau
  -- bang "-sp" deu bi lenh nay nuot.
  local raw = GetEventPlayerChatString()
  if raw ~= nil and raw:match("^%s*%-sp%s*$") == nil then return end

  if d == nil then
    API.warn(pid, "-sp: ban khong nam trong danh sach nguoi choi.")
    return
  end
  if d.hero == nil then
    API.warn(pid, "-sp: ban chua chon hero.")
    return
  end
  if CFG.SKILL_MODE == "learn" then
    if API.grantSkillPoints(d.hero, 1) then
      API.info(pid, CFG.C_GOLD .. "-sp: +1 diem ky nang." .. CFG.C_END ..
        " Bam nut + tren hero de chon.")
      API.info(pid, CFG.C_GREY .. "Khong thay nut + nghia la Techtree - Hero" ..
        " Abilities cua hero con rong." .. CFG.C_END)
    else
      API.warn(pid, "-sp: UnitModifySkillPoints tu choi.")
    end

  elseif CFG.SKILL_MODE == "pick" then
    API.showSkillPicker(pid)

  elseif CFG.SKILL_MODE == "frame" then
    API.showSkillFrame(pid)

  else
    API.warn(pid, "-sp: SKILL_MODE dang la \"" ..
      tostring(CFG.SKILL_MODE) .. "\" -- doi sang \"learn\", \"pick\" hoac \"frame\".")
  end
end

-- Lenh dev "-wave N": nhay thang toi stage N.
-- Khong co no thi khong ai kiem duoc stage 180 -- doi 2 tieng de xem
-- mot con so khong phai la cach lam viec.
local function onWaveCmd()
  local pid = GetPlayerId(GetTriggerPlayer())
  local raw = GetEventPlayerChatString()
  if raw == nil then return end

  local n = tonumber(raw:match("^%s*%-wave%s+(%d+)"))
  if n == nil then
    API.warn(pid, "Dung: -wave <so tu 1 den " ..
      API.totalStages() .. ">")
    return
  end
  API.jumpToStage(n)
  API.info(pid, CFG.C_GOLD .. "Nhay toi stage " .. n .. "." .. CFG.C_END)
end

-- "-lc" mo bang Linh Can, "-lc up" dot pha thang khong can bang.
local function onCultCmd()
  API.cultChat(GetPlayerId(GetTriggerPlayer()), GetEventPlayerChatString())
end

-- Lenh dev cho tien: "-go 300" Go, "-vang 5000" Vang.
-- Khong co no thi muon thu bac Tu Vi 15 phai cay 155 wave.
--
-- "-lk" DA BO. No lech dung MOT ky tu voi "-lc" (mo the Tu Vi), va hai
-- lenh do lam hai viec khac han nhau -- go nham la cong tien thay vi mo
-- bang. Muon Linh Khi thi dung "-debug", no day het ca bon dong tien.
local function onMoneyCmd()
  local pid = GetPlayerId(GetTriggerPlayer())
  local raw = GetEventPlayerChatString()
  if raw == nil then return end

  local n = tonumber(raw:match("^%s*%-go%s+(%d+)"))
  if n ~= nil then
    API.addLumber(pid, n)
    API.info(pid, CFG.C_GREY .. "[dev] +" .. API.num(n) .. " go -> " ..
      API.num(API.getLumber(pid)) .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  n = tonumber(raw:match("^%s*%-vang%s+(%d+)"))
  if n ~= nil then
    API.addGold(pid, n)
    API.info(pid, CFG.C_GREY .. "[dev] +" .. API.num(n) .. " vang -> " ..
      API.num(API.getGold(pid)) .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  API.warn(pid, "Dung: -go <so> | -vang <so>")
end


-- "-debug": day CA BON dong tien len CFG.DEBUG_MONEY.
--
-- Chi chay khi CFG.DEBUG bat -- KHAC voi nhom lenh dev o tren (chung
-- theo CFG.DEV_COMMANDS). Hai cong tac tach nhau la co y: tat bao cao
-- chi tiet van go duoc lenh dev, va nguoc lai. Lenh nay dua het tien
-- cho nguoi choi nen no thuoc ve cong tac "dang soi ky", khong phai
-- cong tac "dang go lenh".
local function onDebugCmd()
  local pid = GetPlayerId(GetTriggerPlayer())

  -- Khop chat: "-debug" hoac "-debug   ", KHONG an "-debugxyz".
  local raw = GetEventPlayerChatString()
  if raw == nil or raw:match("^%s*%-debug%s*$") == nil then return end

  -- Cong tac tat thi NOI RA. Khong lam gi ma cung khong bao la kieu
  -- hong te nhat: nguoi go tuong lenh hong, di sua nham cho khac.
  if not CFG.DEBUG then
    API.warn(pid, "-debug can CFG.DEBUG = true" .. CFG.C_END ..
      CFG.C_GREY .. "  (sua o dau src/1_core/1_config.lua roi chay lai build.py)")
    API.trace("-debug: TU CHOI -- CFG.DEBUG = false")
    return
  end

  local n = CFG.DEBUG_MONEY or 999999

  API.addQi(pid, n)
  API.addGold(pid, n)
  API.addLumber(pid, n)
  if API.addIron ~= nil then API.addIron(pid, n) end

  API.info(pid, CFG.C_GOLD .. "[debug] +" .. API.num(n) ..
    " moi loai" .. CFG.C_END .. CFG.C_GREY ..
    "  (Linh Khi " .. API.num(API.getQi(pid)) ..
    " | Vang " .. API.num(API.getGold(pid)) ..
    " | Go " .. API.num(API.getLumber(pid)) ..
    " | Da " .. API.num((API.getIron ~= nil) and API.getIron(pid) or 0) ..
    ")" .. CFG.C_END)
  API.panelRefresh(pid)
  API.trace("debug: pid " .. pid .. " +" .. n .. " ca bon dong tien")
end

local function registerEvents()
  local tDeath = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tDeath, EVENT_PLAYER_UNIT_DEATH)
  TriggerAddAction(tDeath, onAnyDeath)

  if not CFG.HOUSE_SELECTABLE then
    local tSelect = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerUnitEvent(tSelect, Player(S.pids[i]),
                                     EVENT_PLAYER_UNIT_SELECTED, nil)
    end
    TriggerAddAction(tSelect, onSelect)
  end

  -- Nha chinh la hero, ma hero Warcraft co san sau o tui: keo mot binh
  -- mau tha vao no la binh do bien mat vao tui nha chinh. Tra ngay ra
  -- dat -- xem onHousePickup() trong 3_battle/1_house.lua.
  if EVENT_PLAYER_UNIT_PICKUP_ITEM ~= nil and API.onHousePickup ~= nil then
    local tPickup = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(tPickup, EVENT_PLAYER_UNIT_PICKUP_ITEM)
    TriggerAddAction(tPickup, API.onHousePickup)
  else
    API.trace("house: KHONG co EVENT_PLAYER_UNIT_PICKUP_ITEM -- " ..
              "nha chinh van co the nuot do")
  end

  if CFG.DEV_COMMANDS then
    local tChat = CreateTrigger()
    for i = 1, #S.pids do
      -- exactMatch = false: "-sp " thua dau cach van an
      TriggerRegisterPlayerChatEvent(tChat, Player(S.pids[i]), "-sp", false)
    end
    TriggerAddAction(tChat, onChat)

    local tWave = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tWave, Player(S.pids[i]), "-wave", false)
    end
    TriggerAddAction(tWave, onWaveCmd)
  end

  if CFG.DEV_COMMANDS then
    local tMoney = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tMoney, Player(S.pids[i]), "-go", false)
      TriggerRegisterPlayerChatEvent(tMoney, Player(S.pids[i]), "-vang", false)
    end
    TriggerAddAction(tMoney, onMoneyCmd)
  end

  -- "-debug" theo CFG.DEBUG, khong theo CFG.DEV_COMMANDS.
  --
  -- LUON DANG KY, con CHAY hay khong thi hoi CFG.DEBUG o trong ham.
  --
  -- Ban truoc boc ca cum trong "if CFG.DEBUG then": cong tac tat thi
  -- trigger khong ton tai, go lenh ra khong co gi, va khong mot dong
  -- nao noi vi sao. Dung cai kieu "nuot loi" ma CLAUDE.md cam.
  --
  -- Khop TIEN TO chu khong khop chinh xac: "-debug " thua mot dau cach
  -- van phai an -- bai hoc da ghi san o lenh "-sp". Phan chan
  -- "-debugxyz" chuyen vao ham, bang mot phep khop chat.
  local tDebug = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tDebug, Player(S.pids[i]), "-debug", false)
  end
  TriggerAddAction(tDebug, onDebugCmd)
  API.trace("lenh -debug: " ..
            (CFG.DEBUG and "BAT" or "TAT (CFG.DEBUG = false)"))

  -- Loi choi, khong phai lenh dev -- luon dang ky.
  local tCult = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tCult, Player(S.pids[i]), "-lc", false)
  end
  TriggerAddAction(tCult, onCultCmd)

  -- "-next" goi dot ke tiep. LUON dang ky, khong theo DEV_COMMANDS.
  --
  -- Duong CHINH la nut tren bang tran dau (phim R). Lenh nay giu lai lam
  -- DUONG LUI: framesAvailable() co the tra false (thieu native frame),
  -- va luc do khong con cach nao khoi dong van -- bang nhan vat da phai
  -- in "Khong ve duoc bang -- dung lenh chat" vi dung ly do do.
  --
  -- Khong phai lenh cheat: no doi da don sach quai moi goi duoc, nen
  -- khong bo qua duoc phan nao ca.
  do
    local tNext = CreateTrigger()
    for i = 1, #S.pids do
      -- false = khop TIEN TO. Voi true thi go du mot dau cach thua la
      -- khong khop, va khong khop thi im lang hoan toan.
      TriggerRegisterPlayerChatEvent(tNext, Player(S.pids[i]), "-next", false)
    end
    TriggerAddAction(tNext, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      API.trace("-next: pid " .. pid .. ", song=" .. S.alive ..
                ", stage=" .. S.stage)
      -- Chi goi som duoc khi da don sach. Cho phep goi som luc con quai
      -- la cho nguoi choi bo qua phan kho cua wave nay va nhan tien cua
      -- wave sau -- pha dung cai duong cong dang giu ca van.
      if S.alive > 0 then
        API.msg(pid, CFG.C_RED .. API.t("wave_notclear", S.alive) .. CFG.C_END)
        return
      end
      -- Dang o cua so nghi thi -next la thu DUY NHAT di tiep duoc, nen
      -- bao ro ai la nguoi bam.
      local waiting = API.waveWaiting()
      if API.waveNow() then
        -- Dung CHUNG khoa voi nut goi dot trong 6_gameframe.lua: hai
        -- duong lam cung mot viec thi phai noi cung mot cau.
        API.msg(nil, CFG.C_GREY ..
          API.t("wave_called", GetPlayerName(Player(pid))) ..
          (waiting ~= nil and (" (" .. waiting .. ")") or "") .. CFG.C_END)
      end
    end)
  end

  -- "-icon <ma>": tao mot item roi in TEN va DUONG DAN ICON THAT cua no.
  --
  -- Day la cach duy nhat biet mot duong dan icon co that: game dong goi
  -- bang CASC nen khong liet ke tu ngoai duoc, ma go nham thi Warcraft
  -- ve o XANH LA chu khong bao loi. Doan ba lan, sai ba lan.
  --
  -- Dung de di tim icon cho CFG.GEAR: "-icon ciri", "-icon hval"...
  -- thay cai nao hop nghia thi chep duong dan vao bang.
  if CFG.DEV_COMMANDS then
    local tIcon = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tIcon, Player(S.pids[i]), "-icon", false)
    end
    TriggerAddAction(tIcon, function()
      local pid  = GetPlayerId(GetTriggerPlayer())
      local code = GetEventPlayerChatString():match("^%s*%-icon%s+(%S%S%S%S)")
      if code == nil then
        API.warn(pid, "Dung: -icon <4 ky tu>, vi du -icon bspd")
        return
      end
      if CreateItem == nil then
        API.warn(pid, "-icon: ban nay khong co CreateItem.")
        return
      end
      local it = CreateItem(FourCC(code), 0.0, 0.0)
      if it == nil then
        API.warn(pid, "-icon " .. code .. ": khong co item nay.")
        API.trace("icon " .. code .. ": KHONG CO")
        return
      end
      local name = (GetItemName ~= nil) and GetItemName(it) or "?"
      local path = (BlzGetItemIconPath ~= nil) and BlzGetItemIconPath(it) or "?"
      API.msg(pid, CFG.C_GOLD .. code .. CFG.C_END .. "  " .. name)
      API.msg(pid, CFG.C_GREY .. "   " .. tostring(path) .. CFG.C_END)
      API.trace("icon " .. code .. " = " .. name .. " | " .. tostring(path))
      RemoveItem(it)
    end)
  end

  -- "-fx <duong dan>": ve thu mot model ngay duoi chan hero.
  --
  -- Model go sai duong dan thi Warcraft KHONG ve gi va KHONG bao loi --
  -- im hon ca icon, vi icon con ra o xanh la de thay. Khong co cach nao
  -- BIET mot duong dan model co that ngoai viec ve thu.
  --
  --   -fx Abilities\Spells\Human\Avatar\AvatarCaster.mdl
  --
  -- Thay hien ra gi thi chep duong dan vao CFG.FX_SLAM_* / FX_HIT_*.
  if CFG.DEV_COMMANDS then
    local tFx = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tFx, Player(S.pids[i]), "-fx", false)
    end
    TriggerAddAction(tFx, function()
      local pid  = GetPlayerId(GetTriggerPlayer())
      local path = GetEventPlayerChatString():match("^%s*%-fx%s+(.+)$")
      if path == nil then
        API.msg(pid, CFG.C_RED ..
          "Dung: -fx <duong dan .mdl>" .. CFG.C_END)
        return
      end
      path = path:gsub("%s+$", "")
      local d = S.p[pid]
      local h = d and d.hero or nil
      if h == nil then
        API.warn(pid, "-fx: ban chua co hero.")
        return
      end
      API.fx(path, GetUnitX(h), GetUnitY(h))
      -- Khong the biet no CO ve ra hay khong: AddSpecialEffect tra ve
      -- mot handle du duong dan sai. Nen phai NHIN, va dong nay chi de
      -- doi chieu xem vua thu cai nao.
      API.msg(pid, CFG.C_GREY .. "[fx] " .. path ..
        CFG.C_END .. CFG.C_GOLD .. "  -- nhin xem co gi hien khong" ..
        CFG.C_END)
      API.trace("fx thu: " .. path)
    end)
  end

  -- "-spawn": tao thang mot con H001 bang CreateUnit, canh hero.
  --
  -- De so sanh voi con dat san trong World Editor: cung loai unit, cung
  -- man hinh, mot con do WE dat, mot con do code tao. Neu chi con do code
  -- tao bi den thi loi nam o cach tao, khong phai o file model.
  if CFG.DEV_COMMANDS then
    local tSpawn = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tSpawn, Player(S.pids[i]), "-spawn", false)
    end
    TriggerAddAction(tSpawn, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local d = S.p[pid]
      local x, y = S.houseX or 0.0, S.houseY or 0.0
      if d ~= nil and d.hero ~= nil then
        x, y = GetUnitX(d.hero) + 200.0, GetUnitY(d.hero)
      end
      local uid = CFG.HEROES[1] and CFG.HEROES[1].id
      local u = CreateUnit(Player(pid), uid, x, y, 270.0)
      API.info(pid, CFG.C_GREY .. "[dev] CreateUnit " .. API.idToStr(uid) ..
        (u ~= nil and " -> ok" or " -> NIL") .. CFG.C_END)
      API.trace("-spawn: " .. API.idToStr(uid) ..
                (u ~= nil and " tao duoc" or " TAO THAT BAI"))
    end)
  end

  -- "-sync" bao duong dong bo nao dang chay va ping co ve khong. Luon
  -- dang ky: khi bang khong an thi day la cho dau tien phai nhin.
  local tSync = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tSync, Player(S.pids[i]), "-sync", true)
  end
  TriggerAddAction(tSync, function()
    API.syncChat(GetPlayerId(GetTriggerPlayer()))
  end)

  -- "-nat" liet ke native ban nay co. Luon dang ky: khi mot he im lang
  -- khong chay, day la cho thu hai phai nhin sau file vet.
  local tNat = CreateTrigger()
  for i = 1, #S.pids do
    -- false = khop TIEN TO. Voi true thi "-nat dam" khong khop gi ca va
    -- trigger khong no -- go lenh xong im lang, tuong la khong co ket qua.
    TriggerRegisterPlayerChatEvent(tNat, Player(S.pids[i]), "-nat", false)
  end
  TriggerAddAction(tNat, function()
    API.nativeChat(GetPlayerId(GetTriggerPlayer()), GetEventPlayerChatString())
  end)

  -- "-mod N" ep mot tu chinh de XEM kieu troi cua no ngay, thay vi doi
  -- RNG boc trung. Cung la cach tra loi "troi khong chay hay chay ma mo".
  if CFG.DEV_COMMANDS then
    local tMod = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tMod, Player(S.pids[i]), "-mod", false)
    end
    TriggerAddAction(tMod, function()
      if API.modifierDevSet ~= nil then
        API.modifierDevSet(GetPlayerId(GetTriggerPlayer()),
                           GetEventPlayerChatString())
      end
    end)
  end

  -- "-sky N" bat MOT ma thoi tiet de nhin. Xem chu thich devSky().
  if CFG.DEV_COMMANDS then
    local tSky = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tSky, Player(S.pids[i]), "-sky", false)
    end
    TriggerAddAction(tSky, function()
      if API.modifierDevSky ~= nil then
        API.modifierDevSky(GetPlayerId(GetTriggerPlayer()),
                           GetEventPlayerChatString())
      end
    end)
  end

  -- "-reg" DO hoi mau that cua hero. Lenh dev: no ha mau hero xuong nua
  -- va doi chi so trong luc do, khong phai thu de go giua tran.
  if CFG.DEV_COMMANDS then
    local tReg = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tReg, Player(S.pids[i]), "-reg", false)
    end
    TriggerAddAction(tReg, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local raw = GetEventPlayerChatString() or ""
      -- "-reg" mau | "-reg mana" mana | "-reg 5" / "-reg mana 5" doi so giay
      local kind = raw:find("mana", 1, true) and "mana" or "hp"
      API.nativeRegen(pid, tonumber(raw:match("(%d+)")), kind)
    end)
  end

  -- Ba lenh dev de thu he QUAY ma khong phai cay quai.
  --
  -- "-don"     giet sach quai dang song. Day la cai dang gia nhat: no
  --            di qua DUNG duong that -- su kien chet -> rewardAll ->
  --            cong tien + luot quay -> wave sau ra. Thu bang -quay thi
  --            chi thu duoc cai bang, con -don thu ca day chuyen.
  -- "-quay N"  cong thang N luot quay.
  -- "-da N"    cong thang N da Huyen Thiet.
  if CFG.DEV_COMMANDS then
    local tDev = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tDev, Player(S.pids[i]), "-don", false)
      TriggerRegisterPlayerChatEvent(tDev, Player(S.pids[i]), "-quay", false)
      TriggerRegisterPlayerChatEvent(tDev, Player(S.pids[i]), "-da", false)
    end
    TriggerAddAction(tDev, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local raw = GetEventPlayerChatString() or ""
      local n   = tonumber(raw:match("(%d+)"))

      if raw:match("^%s*%-don") ~= nil then
        -- Gom ra danh sach TRUOC khi giet: onMobDeath xoa khoi S.mobs
        -- ngay giua chung, ma sua mot bang dang duyet bang pairs() la
        -- hanh vi khong xac dinh trong Lua.
        local ds = {}
        for u, _ in pairs(S.mobs) do ds[#ds + 1] = u end
        local d = 0
        for i2 = 1, #ds do
          if API.alive(ds[i2]) then KillUnit(ds[i2]); d = d + 1 end
        end
        API.info(pid, CFG.C_GREY .. "[dev] da giet " .. d .. " con." .. CFG.C_END)
        return
      end

      if raw:match("^%s*%-quay") ~= nil then
        n = n or 10
        if API.fortuneAddRolls ~= nil then API.fortuneAddRolls(pid, n) end
        API.info(pid, CFG.C_GREY .. "[dev] +" .. n .. " luot quay." .. CFG.C_END)
        API.panelRefresh(pid)
        return
      end

      if raw:match("^%s*%-da") ~= nil then
        n = n or 100
        local d = S.p[pid]
        if d ~= nil then API.addIron(pid, n) end
        API.info(pid, CFG.C_GREY .. "[dev] +" .. n .. " da." .. CFG.C_END)
        API.panelRefresh(pid)
        return
      end
    end)
  end

  -- "-vung" in ban do phan vung 25 block va ping minimap theo mau.
  --
  -- Luon dang ky, khong theo DEV_COMMANDS: chua he nao gan vao block,
  -- nen day la cach DUY NHAT nhin thay bang CFG.BLOCKS co dung nhu dinh
  -- khong -- va de doi chieu voi vung Blk.. trong World Editor.
  local tRegion = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tRegion, Player(S.pids[i]), "-vung", true)
  end
  TriggerAddAction(tRegion, function()
    local pid = GetPlayerId(GetTriggerPlayer())
    API.info(pid, CFG.C_GOLD .. "=== Phan vung 25 block ===" .. CFG.C_END)

    local missing = 0
    -- In tu hang TREN xuong, dung chieu nguoi choi nhin ban do.
    for row = S.grid.rows, 1, -1 do
      local line = ""
      for col = 1, S.grid.cols do
        local idx = API.blockIndex(col, row)
        local d   = API.blockRoleDef(idx)
        if API.blockRegion(idx) == nil then missing = missing + 1 end
        line = line .. string.format("%-14s", idx .. " " .. API.pick(d))
      end
      API.msg(pid, line)
    end

    -- Ping tam moi block, mau theo vai tro.
    API.forEachBlock(function(col, row, idx, x0, y0, x1, y1)
      local m = API.blockRoleDef(idx).color
      PingMinimapEx((x0 + x1) * 0.5, (y0 + y1) * 0.5, 6.0,
                    m[1], m[2], m[3], false)
    end)

    if missing > 0 then
      API.warn(pid, "Thieu " .. missing .. " vung " ..
        CFG.BLOCK_RGN_PREFIX .. ".. trong World Editor." .. CFG.C_END ..
        CFG.C_GREY .. " Chay: python w3region.py gen")
    end
    API.msg(pid, CFG.C_GREY ..
      "Chua he nao gan vao block -- day moi la ban do." .. CFG.C_END)
  end)

  -- "-c" mo bang nhan vat, duong lui neu phim E khong gan duoc.
  local tPanel = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tPanel, Player(S.pids[i]), "-c", true)
  end
  TriggerAddAction(tPanel, function()
    API.panelToggle(GetPlayerId(GetTriggerPlayer()))
  end)

  API.dbg("Trigger da dang ky.")
end

API.registerEvents = registerEvents
end
--#endregion 5_boot/1_events.lua

--#region 5_boot/2_init.lua
do
-- ============================================================
--  2_init.lua  --  Khoi dong & moc vao main() cua map
--
--  File nay phai la file cuoi cung: build.py dong khoi do...end ngay
--  sau day.
-- ============================================================

-- In so do luoi ra chat. Day la cach kiem tra buoc 1: doi chieu con so
-- o day voi thuoc do trong World Editor.
local function reportGrid()
  local g = S.grid
  API.info(nil, CFG.C_GOLD .. "=== Luoi " .. g.cols .. "x" .. g.rows ..
    " (" .. (g.cols * g.rows) .. " o) ===" .. CFG.C_END)
  API.info(nil, "Vung choi duoc : " .. g.tilesW .. " x " .. g.tilesH .. " o dia hinh"
    .. "  (" .. API.num(g.playMaxX - g.playMinX) .. " x "
    .. API.num(g.playMaxY - g.playMinY) .. " don vi)")
  API.info(nil, "Moi block      : " .. g.blockTilesW .. " x " .. g.blockTilesH .. " o"
    .. "  (" .. API.num(g.blockW) .. " x " .. API.num(g.blockH) .. " don vi)")
  API.info(nil, "Long song      : " .. g.riverTiles .. " o  ("
    .. API.num(g.river) .. " don vi)")
  API.info(nil, "Le hai ben     : " .. g.marginTilesX .. " o ngang, "
    .. g.marginTilesY .. " o doc")
  API.info(nil, "Goc luoi (1,1) : " .. API.num(g.originX) .. ", " .. API.num(g.originY))
end

-- Ping minimap tam moi block de nhin thay luoi ngay khi vao map.
-- Ket thuc van. Doi 3 giay cho nguoi choi doc duoc ly do truoc khi
-- man hinh ket qua che mat.
local function endGame(win, reason)
  if not S.running then return end
  S.running = false
  API.stopWaves()

  -- Bang tong ket thay cho mot dong chu.
  --
  -- Hai dong cu di qua API.info / API.warn -- KENH CHAN DOAN cho nguoi
  -- LAM MAP -- va la chuoi cung khong qua i18n. Tuc chu quan trong
  -- nhat cua ca map nam sai kenh va chi co mot thu tieng.
  if API.summaryShow ~= nil then
    API.summaryShow(win, reason)
  else
    API.msg(nil, (win and CFG.C_GOLD or CFG.C_RED) ..
            (win and API.t("end_win") or API.t("end_lose")) ..
            CFG.C_END .. "  " .. reason)
  end

  -- Doi lau hon truoc day (3s): bang tong ket co nhieu dong, va hop
  -- thoai cua Warcraft nuot man hinh ngay khi no hien.
  API.after(CFG.END_SUMMARY_SECONDS or 10.0, function()
    for i = 1, #S.pids do
      local p = Player(S.pids[i])
      if win then
        CustomVictoryBJ(p, reason, true, true)
      else
        CustomDefeatBJ(p, reason)
      end
    end
  end)
end

-- Chay sau khi map da nap xong (goi tu timer 0 giay ben duoi).
local function bootstrap()
  if S.running then return end

  API.trace("bootstrap: bat dau")
  -- In ca DAU THOI GIAN build, khong chi so hieu. CFG.VERSION go tay
  -- nen hai ban build khac nhau van cung mot so -- va luc do "go lenh
  -- moi ma khong thay gi" khong phan biet duoc voi "dang chay ban cu".
  API.info(nil, CFG.C_GOLD .. "[build " .. CFG.VERSION ..
          (CFG.BUILD and ("  " .. CFG.BUILD) or "") ..
          "] code da chay." .. CFG.C_END)

  -- Mo suong mu. Khong bao gi: day la cach map nay chay binh thuong,
  -- khong phai mot cong tac dev dang bat. Bao moi van mot dong "[dev]"
  -- chi lam nguoi choi tuong minh dang o ban chua xong.
  if CFG.REVEAL_MAP then
    FogEnable(false)
    FogMaskEnable(false)
  end

  local n = API.initPlayers()
  API.trace("initPlayers: " .. n .. " nguoi choi")

  -- Kenh dong bo phai san sang TRUOC moi he khac: cac he dang ky tin
  -- nhan cua minh trong ham start cua chung.
  API.startSync()
  API.langCheck()

  -- Do xem ban nay co nhung native nao. Khong doi gi, chi ghi vet --
  -- nhung moi lan doan thay vi do, du an nay deu doan sai (ADR 0012).
  API.startNatives()

  API.buildGrid()
  API.trace("buildGrid: xong")

  -- Nha chinh dung sau khi co luoi, de bao cao duoc no nam o block nao.
  API.createHouse()
  API.trace("createHouse: tra ve")

  API.resolveEnemyRegion()
  API.trace("resolveEnemyRegion: xong")

  -- Phai chay TRUOC khi nguoi choi kip chon hero.
  --
  -- HAI CACH, vi chua biet cach nao an:
  --   1. Preload() thang duong dan file   <- cach chinh
  --   2. tao mot con moi loai hero roi xoa ngay
  --
  -- PreloadStart/PreloadEnd moi la cap nap THAT. PreloadGenStart/
  -- PreloadGenEnd la de SINH file preload -- lan trong do thi Preload()
  -- chi ghi ten vao file chu khong nap gi ca. Bo ghi vet cua du an nay
  -- dung dung ho PreloadGen*, nen phai goi dung cap o day.
  if CFG.PRELOAD ~= nil and Preload ~= nil then
    if PreloadStart ~= nil then PreloadStart() end
    for i = 1, #CFG.PRELOAD do Preload(CFG.PRELOAD[i]) end
    if PreloadEnd ~= nil then PreloadEnd(0.5) end
    API.trace("preload: da goi Preload cho " .. #CFG.PRELOAD .. " file")
  end

  API.preloadHeroes()

  API.startHeroLock()
  API.startCheatGuard()     -- canh cheat co san cua Warcraft
  API.startRevive()         -- hero chet roi song lai o nha chinh
  API.startSummary()        -- dong ho + bo dem cho bang tong ket
  API.startHeroName()       -- hai dong chu tren bang hero
  API.trace("startHeroLock: xong")

  -- Cac he dang ky the TRUOC, roi bang moi dung -- bang can biet co
  -- bao nhieu the de chia be ngang.
  -- Thu tu dang ky = thu tu the trong bang. Nam he -- xem
  -- docs/02-he-thong/kinh-te.md
  API.startCult()   -- I.   Linh Khi
  API.startSkills()    -- II.  Go
  API.startGear()   -- III. Da Huyen Thiet
  API.startRelic()   -- IV.  (tam khoa)
  API.startShop()      -- V.   Vang
  API.startHouseUp()   -- VI.  Vang -- nang cap nha chinh
  API.startFortune()      -- Co Duyen (khung rieng, khong phai the)
  API.startUseItem()
  API.startPet()            -- pet di theo hero
  API.startHeroGate()       -- HeroMoveRegion -> nha chinh
  API.startSideQuest()      -- bon Thanh Thu dung san trong hang
  API.startPanel()

  API.startSkillFx()
  API.startFct()
  API.startBoss()
  API.startModifier()      -- tu chinh cua tung stage thuong
  API.startWaves()
  API.startHeroFrame()
  API.startSkillFrame()
  API.startFortuneFrame()
  API.startGameFrame()      -- bang tran dau, phim R
  API.startCamera()         -- lenh -zoom
  API.startWing()           -- canh theo moc canh gioi
  API.startQuest()          -- trang huong dan phim tat o F9
  API.startBoard()          -- multiboard: Linh Khi, Da, luot quay
  API.startSkillPicking()
  API.startPicking()
  API.trace("startPicking: tra ve")

  API.registerEvents()
  API.trace("registerEvents: xong")

  S.running = true
  API.trace("BOOTSTRAP HOAN TAT")

  if CFG.DEBUG then
    -- KHONG ping 25 block o day nua. Lenh "-vung" da ping ca 25 o, va
    -- con to mau theo vai tro -- ban o day vua thua vua ban minimap
    -- ngay giay dau tien, luc nguoi choi con chua chon hero.
    --
    -- Muon xem luoi thi go "-vung".
    reportGrid()
    API.report()
    API.heroPickReport()
    API.dbg(n .. " nguoi choi vao map.")
  end
end

API.endGame    = endGame
API.reportGrid = reportGrid
API.bootstrap  = bootstrap

-- ---------- Moc vao vong doi cua map ----------
-- Khoi code nay chay luc nap chunk, truoc khi main() duoc goi. Ta boc
-- InitGlobals (main() goi no ngay sau InitBlizzard), roi hen timer 0 giay
-- de bootstrap chay khi map thuc su san sang.
-- Vet nay chay luc NAP CHUNK, truoc ca main(). No phan biet duoc hai
-- truong hop rat khac nhau:
--   co dong nay, khong co "bootstrap" -> chunk nap duoc nhung moc hong
--   khong co dong nao ca              -> map khong he chua code nay
API.trace("chunk: da nap, dang moc InitGlobals")

do
  local function run()
    TimerStart(CreateTimer(), 0.00, false, function()
      DestroyTimer(GetExpiredTimer())
      bootstrap()   -- tu chan neu da chay roi (S.running)
    end)
  end

  -- HAI DUONG, chu khong mot.
  --
  -- Khi code duoc nhet vao war3map.wct (o custom script cua World
  -- Editor), World Editor quyet dinh dat no o dau trong war3map.lua --
  -- va no co the dat TRUOC "function InitGlobals()". Luc do
  -- prevInitGlobals bat duoc nil, roi dinh nghia that cua InitGlobals
  -- de len ban thay the cua ta: moc mat, khong bao gi.
  --
  -- Nen ngoai moc do con hen thang mot timer ngay luc nap chunk. Cai
  -- nao toi truoc thi chay, bootstrap tu chan lan thu hai.
  local prevInitGlobals = InitGlobals
  InitGlobals = function()
    if prevInitGlobals ~= nil then prevInitGlobals() end
    run()
  end

  run()
end
end
--#endregion 5_boot/2_init.lua

